// ══════════════════════════════════════════════════════════════════════════
// PZ — 독 毒 신설 셋 · 폭마 그림 둘                            (2026-08-23)
//
// ── 왜 별도 파일인가 ──────────────────────────────────────────────────────
// `vfx.js` 는 50,207줄이고 **이 사이클에 다른 손이 같이 쓰고 있다.** 같은 날
// 그 파일에서 정규식 하나가 31,000줄을 날린 사고가 났다. ⇒ 새 그림은 여기에
// 만들고 `vfx.js` 는 **읽기만** 한다. 페이지는 `vfx.js` **뒤에** 이 파일을
// 부르므로 `FX`·`TONE`·`tile`·`PK*` 같은 전역이 전부 보인다.
//
// ⚠️ **최상위 이름을 전부 `PZ` 로 격리한다.** 50,000줄 뒤에 실리는 파일이라
//   최상위 `const` 가 하나만 겹쳐도 스크립트가 통째로 죽는다.
//   (확인: `PZ` 는 vfx/nav/char-page/chapter/rock/progress-data/두 페이지 스크립트에서 0건)
//
// ── 무엇을 만드나 셋 ──────────────────────────────────────────────────────
//   ① **독 묻은 표창** — 독의 **첫 일반 계열**. 3안
//   ② **독가스**       — 녹염을 「불」이 아니라 「가스」로 다시. **마법 계열**. 3안
//   ③ **폭마**        — 뇌+독 특수 속성의 그림. 2안 (시안에만 — 엔진 편입 없음)
//
// ── ⚠️ 게이트가 이 파일을 안 돈다 (실측) ──────────────────────────────────
// `tools/mockup_lint.js` 의 런타임 검사와 `tools/mockup_smoke.js` 는 둘 다
// **`docs/vfx/vfx.js` 하나만** 읽는다. 그래서 이 파일의 예외는 게이트가 못 본다.
//   ⇒ 자체 검증: `cat docs/vfx/vfx.js docs/vfx/vfx-poison.js > /tmp/z.js &&
//                 node tools/mockup_smoke.js /tmp/z.js`
//   ⇒ 그리고 린트 ⑪(제목의 「N종」 ↔ 실제 칸 수)이 이 파일의 칸을 **0으로** 세므로
//     새로 만든 `<h2>` 에는 **「N종」을 쓰지 않는다**(「3안」으로 적었다).
//
// ── 지키는 규약 (사용자가 반려해 온 것들) ─────────────────────────────────
//   ① **가는 획 여럿 = 거미줄** — 낙광 여덟이 전부 이걸로 떨어졌다.
//      ⇒ 주 채널 하나를 굵게, 곁가지는 적고 가늘게.
//   ② **평평하고 단순한 것 금지** — 색 사다리 · 너덜너덜한 가장자리 ·
//      크기 편차 · 안쪽 결이 있어야 한다.
//   ③ **불씨 · 가산 빛번짐 · 잔상** 세 층 — 화염방사(G4)가 통과한 근거다.
//      셋 다 여기 그대로 쓴다(독은 「불씨」가 **가라앉는 알갱이**로 번역된다).
//   ④ **빈 곳이 있으면 안 된다** — 봉투를 겹쳐 채운다.
//   ⑤ **판정 안내선을 그리지 않는다**(2026-08-23 사용자: 「당연히 지워야 되는 거 알지?」).
//   ⑥ **말한 개수만큼만** 만든다 — 표창 3 · 가스 3 · 마 2.
// ══════════════════════════════════════════════════════════════════════════

// ── 팔레트 — **새 색을 한 톨도 안 짓는다** ────────────────────────────────
// 독은 `TONE.toxin`(129° 초록), 금속은 `TONE.gold`(무속성 **회백** — 「아직 색이
// 없는 것」이라 「독이 묻기 전의 쇠」에 정확히 맞는다), 마는 `TONE.numb`(320° 자홍).
// 녹염·자염은 `PKT` 의 값을 그대로 읽는다(사용자가 고르기 화면에서 고른 색).
const PZTOX = "toxin";                 // 독 毒     #123D1C / #57D96B / #E6FFEA
const PZMET = "gold";                  // 회백 쇠   #2B2B33 / #9A9AA8 / #DCDCE8
const PZNUM = "numb";                  // 폭마     #3A0A2E / #E040A0 / #FFD9F0

// ══════════════════════════════════════════════════════════════════════════
// ① 독 묻은 표창 — **독의 첫 「일반 계열」**
// ══════════════════════════════════════════════════════════════════════════
//
// ── 왜 이것이 급한가 ──────────────────────────────────────────────────────
// `characterFieldable`(`lib/data/characters.dart:299`)이 요구하는 문이 둘인데
// (**일반 계열 ≥1** · 내 속성 ≥3) 독은 첫째를 못 넘어 **상점에서 잠겨 있다.**
// 독 여섯(`latch`·`split`·`halt`·`brand`·`spore`·`wardtoxin`)이 전부 보조·마법·
// 방어라 총구가 빈다. 원인은 광선검이 독의 유일한 일반이었는데 2026-08-21 에
// **염으로 갔기** 때문이다(`skill_element.dart` 의 「✂ 정정」).
// ⚠️ 그 광선검은 2026-08-23 에 **게임에서 아예 빠졌다** — 돌아올 자리가 아니다.
//
// ── 왜 「박힌다」인가 — **일반 계열 열셋 중 비어 있는 칸이 그것 하나다** ────
//   bolt   파동이 **밀려 나간다**(관통)      smg    갈래로 **연사**
//   scatter 부채로 **퍼진다**                flamer 원뿔을 **채운다**(지속)
//   sunpo  판·**과부하**                     frost* 결정이 **솟는다**
//   orbit  **돈다**                          seeker **쫓아간다**
//   discus **나갔다 돌아온다**               shotgun **가서 터진다**
// ⇒ 열하나 중 **맞은 뒤에 화면에 남는 것이 하나도 없다.** 표창은 나가서 **멈춘다** —
//   꽂힌 채 남아 거기서 독이 샌다. 그 자리가 비어 있고, 독의 동사와 정확히 맞는다
//   (`skill_element.dart` 독 절: 「독은 **붙어서 퍼진다**」 —
//    넷이 전부 「깔아 두고 나중에 값이 난다」).
//
// ⚠️ **바람원반(`discus`)과 제일 가깝다** — 둘 다 던지는 것이다. 갈리는 자리를
//   한 줄로 못 박는다: **원반은 돌아오고(닫힌 고리) 표창은 안 돌아온다(꽂힌다).**
//   원반이 남기는 것은 **궤적**이고 표창이 남기는 것은 **물건**이다.
// ⚠️ **회수는 회염(`FLret`)이, 부채 뿌리기는 산탄(`scatter`)이 이미 갖고 있다.**
//   그래서 여러 자루가 나갈 때도 **동시 부채로 안 편다** — 차례로 던진다.
//
// ⭐ **삼엽 날은 지어낸 모양이 아니다.** 독의 몸 표식이 이미 「날 셋이 도는
//   삼엽」이다(`vfx.js` 의 `EVSET`: `toxin:[["leaf",3,.50,.56]]`). 표창의 날을
//   같은 폴리곤(`EVP.leaf`)으로 그리면 **속성의 몸과 무기가 한 벌**이 된다.

/// 표창의 실루엣 — **뒤로 젖혀진 날 n 장.** 끝이 뾰족하고 뒷날이 깊게 파인다.
/// ⚠️⚠️ **`EVP.leaf` 로 날을 그렸다가 반려 조건에 걸렸다**(첫 렌더 판정):
///   그 폴리곤은 끝이 둥근 **꽃잎**이라 셋을 두르면 **꽃송이**가 된다 —
///   화면에서 「표창」이 아니라 「초록 알갱이」로 읽혔다. 표창의 정체는
///   **뾰족함**이라 실루엣부터 뾰족해야 한다.
/// ⭐ 대신 **날 수 셋**은 그대로 독에서 온다 — 독의 몸 표식이 「날 셋이 도는
///   삼엽」이고(`EVSET`: `toxin:[["leaf",3,.50,.56]]`), **묻은 독**을 칠할 때
///   그 `EVP.leaf` 를 쓴다. 쇠는 뾰족하고 **묻은 것이 잎 모양**이다.
/// [swp] 뒤로 젖혀진 정도(0 = 곧은 별, 1 = 낫처럼 휨).
function PZbladePoly(rOut,rIn,n,rot,swp){
  const P=[],u=TAU/n;
  for(let i=0;i<n;i++){
    const a=rot+i*u;
    const at=(k,r)=>P.push([Math.cos(a+k*u)*r,Math.sin(a+k*u)*r]);
    at(0        , rIn      );      // 날 뿌리 — 허브에서 나온다
    at(.22*swp  , rOut*.66 );      // 앞날 배 — 살짝 부푼다
    at(.44*swp  , rOut*.95 );
    at(.52*swp  , rOut     );      // **끝** — 뾰족하다
    at(.58*swp  , rOut*.62 );      // 뒷날 — 급하게 파인다
    at(.74*swp  , rIn *.70 );
    at(1                   , rIn *.52);   // 골 — 다음 날의 뿌리로 이어진다
  }
  return P;
}
/// ⭐⭐ **빛 표창 — 날 하나.** (2026-08-23 사용자: 「표창의 디자인을 **좀 더 빛의
/// 형태로** 바꿔줘 **'빛표창인데 독이 묻은 느낌'**」)
///
/// ⚠️⚠️ **순서가 뒤집혔다.** 앞 판은 「회백 쇠 + 독 얼룩」이라 화면에서 **쇠붙이**로
///   읽혔다. 지금은 **날 자체가 빛**이고 독은 **묻은 것**이다 —
///   「독 물건에 빛이 조금」이 아니라 **「빛 물건에 독이 조금」**.
/// ⚠️ 붓은 `vfx.js` 의 것을 **그대로 쓴다**(사본 금지): [gAdd] · [gHalo] · [gStroke].
///   그 둘이 심에 **흰색**을 박으므로 「속이 밝고 가장자리로 풀린다」가 공짜다.
/// ⚠️ **색을 갈랐다** — 날은 `TONE.toxin` 의 **앞날 `#E6FFEA` (130° · L95)**,
///   묻은 독은 같은 팔레트의 **`#123D1C` (134° · L16)**. 색상은 4° 차이인데
///   **밝기가 79 포인트** 벌어져 있어 「빛 ↔ 묻은 것」으로 갈린다.
///   ⚠️ 날에 `#57D96B`(129° L59)를 쓰면 다시 「독 물건」이 된다 — 쓰지 마라.
/// [px] 0 = 갓 던진 빛 · 1 = **빛이 식고 독만 남았다**(꽂힌 뒤에 그리로 간다).
function PZblade1(c,x,y,R,rot,al,SC,px){
  const TX=toneOf(PZTOX),p=px||0,lit=1-p*.72;
  const P=PZbladePoly(R,R*.34,1,rot,1).map(v=>[x+v[0],y+v[1]]);
  const tip=[x+Math.cos(rot+.52*TAU)*R,y+Math.sin(rot+.52*TAU)*R];
  const mid=[x+Math.cos(rot+.30*TAU)*R*.62,y+Math.sin(rot+.30*TAU)*R*.62];
  // ⓐ **빛의 몸** — 가산 한 겹. 면적이 넓어 알파가 낮아야 한다.
  gAdd(c,g=>{
    fillPoly(g,P,A("#E6FFEA",.15*al*lit));
    // ⓑ **빛의 척추** — [gStroke] 가 네 번 덧그어 속을 희게 만든다.
    gStroke(g,[[x,y],mid,tip],R*.30,PZTOX,.85*al*lit);
    // ⓒ **끝** — 작은 후광 하나. 크게 하면 원반(`discus`)의 고리처럼 보인다.
    gHalo(g,tip[0],tip[1],R*.30,PZTOX,.55*al*lit);});
  // ⓓ **묻은 독** — 가산이 아니다. **뒷날과 끝에만** 묻어 있다.
  //   ⚠️ 날 전체를 칠하지 마라 — 그러면 「독으로 만든 날」이라 앞 판으로 되돌아간다.
  c.lineCap="round";c.lineJoin="round";
  c.strokeStyle=A(TX[0],(.55+.40*p)*al);c.lineWidth=Math.max(1,R*.16);
  c.beginPath();c.moveTo(P[4][0],P[4][1]);
  c.lineTo(P[5][0],P[5][1]);c.lineTo(P[6][0],P[6][1]);c.stroke();
  const dr=R*(.16+.10*p);
  if(dr>.3)fillPoly(c,PKrag(tip[0],tip[1],dr,rot*7.3,7,.36,rot),A(TX[0],(.70+.30*p)*al));
  // ⓔ **다 식으면 독만 남는다** — 꽂혀 있는 동안 이쪽으로 간다.
  if(p>.02)fillPoly(c,P.map(v=>[x+(v[0]-x)*.82,y+(v[1]-y)*.82]),A(TX[0],.52*p*al));
}
/// 표창 한 자루 — 빛 날 [n] 장 + 허브. [sq] 는 세로 눌림(바퀴처럼 세워 돌 때).
function PZstar(c,x,y,R,rot,n,al,sq,SC,px){
  const q=Math.max(.14,sq===undefined?1:sq),p=px||0,lit=1-p*.72;
  const TX=toneOf(PZTOX);
  c.save();c.translate(x,y);c.scale(1,q);
  for(let i=0;i<n;i++)PZblade1(c,0,0,R,rot+i*TAU/n,al,SC,p);
  c.restore();
  // 허브 — **제일 밝은 점.** 빛으로 된 물건이라 가운데가 흰 심이다.
  gAdd(c,g=>{
    gHalo(g,x,y,R*(.78+.10*Math.sin(rot*2)),PZTOX,.62*al*lit);
    gHalo(g,x,y,R*.30,PZTOX,.85*al*lit);});
  // 허브에도 독이 조금 — 홈에 고인 것.
  if(R*.13>.3)fillPoly(c,PKrag(x,y,R*.13,3.1,7,.30,rot*.5),A(TX[0],(.45+.45*p)*al));
  void SC;
}

/// 새는 독 — 꽂힌 자리에서 **아래로 떨어지는 방울.** 불티가 위로 오르는 것과
/// 정반대다(`pvMark` 의 burn ↔ poison 이 같은 문법으로 갈려 있다).
function PZdrip(c,t,x,y,r,n,al,SC,seed){
  const TX=toneOf(PZTOX);
  for(let d=0;d<n;d++){
    const ph=((t*.72+d*(1/n)+seed*.37)%1);
    const dy=(ph*ph*.85+ph*.20)*30*SC;
    // ⚠️ 방울을 **키웠다**(2.9 → 4.6). 첫 렌더에서 「새는 것」이 안 보였다 —
    //   꽂힌 뒤에 값이 나는 스킬인데 새는 것이 안 보이면 박힌 이유가 사라진다.
    const rr=(4.6-2.3*ph)*SC*(.7+.6*hash(seed+d*3.1));
    if(rr<=.2)continue;
    const px=x+(hash(seed+d*7.7)-.5)*r*.9+Math.sin(t*1.6+d)*1.2*SC;
    const py=y+r*.42+dy;
    const a=al*Math.min(1,ph*7)*(1-ph)*(1-ph)*1.6;
    if(a<=.01)continue;
    fillPoly(c,PKrag(px,py,rr,seed+d*2.3,7,.34,seed+t*2.1),A(TX[0],a*.95));
    fillPoly(c,PKrag(px,py-rr*.14,rr*.56,seed+d*5.1,7,.28,seed-t*1.7),A(TX[1],a));
  }
}

// ── 성장 — L1~L5 ─────────────────────────────────────────────────────────
// ⚠️ 이 저장소 규약: **무기당 순수 수치 레벨은 최대 1개**이고 나머지는
//   「표식 1 + 격상 1」이다. 표창은 **발수**(수치) · **꽂혀 있는 시간**(표식) ·
//   **부러진 조각**(격상)으로 떨어진다.
const PZdN  = [1, 2, 2, 3, 4];                    // 발수
const PZdDW = [1.30, 1.30, 2.10, 2.10, 2.10];     // 꽂혀 있는 시간(초)
/// 적 배치 — `mgInit` 이 칸 크기에 비례시킨다(238 기준).
/// ⚠️ **넷뿐이고 넓게 벌렸다.** 처음에 다섯을 촘촘히 세웠더니 꽂힌 표창끼리
///   겹쳐 「초록 덩어리 여럿」으로 보였다(첫 렌더 판정) — 이 스킬은 **꽂힌 물건
///   하나하나가 보여야** 값이 사는데 그게 죽었다.
const PZdFOE = [[-74, -42, 17], [42, -78, 17], [80, 22, 16], [-48, 36, 16]];

/// 표창 셋이 같이 쓰는 몸. 갈리는 것은 [O] 넷뿐이다 —
///   `blades` 날 수 · `axis` 회전축 · `stick` 박힌 표시 · `leak` 새는 방식.
function PZdartRun(c,t,dt,W,H,st,O){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZdFOE);stepFoes(st.F,dt);
  const N=PZdN[LV-1],DW=PZdDW[LV-1];
  // ⚠️ 나는 구간을 .42 → **.60** 으로 늘렸다 — 첫 렌더에서 주기의 13% 뿐이라
  //   정지 화면에 **던지는 장면이 거의 안 잡혔다**. 던지는 물건인데 던지는 것이
  //   안 보이면 「꽂혀 있는 초록 덩어리」로만 읽힌다.
  const FLY=.60,GAP=.32,PER=FLY+DW+GAP;
  // ⚠️ **한 스케줄에서 다 파생한다** — 주기 끝(u=PER)과 처음(u=0)이 같은 상태라야
  //   루프에 이음매가 안 생긴다. 마지막 GAP 동안은 아무것도 안 그린다.
  if(!st.dq||st.dq.length!==N){
    st.dq=[];
    for(let i=0;i<N;i++)
      st.dq.push({i,u:(i*PER/N)%PER,fi:i%PZdFOE.length,ax:0,ay:0,hit:0,seed:i*7.31+1.7});
  }
  for(const q of st.dq){
    const pu=q.u;q.u=(q.u+dt)%PER;
    if(q.u<pu){                        // 새 주기 — 표적과 **박히는 자리**를 새로 뽑는다
      q.fi=(q.fi+N)%st.F.length;q.hit=0;
      // ⚠️ 박히는 자리는 **날아온 쪽**이다 — 아무 데나 꽂으면 「붙였다」로 보인다.
      //   몸에서 적을 본 방향의 **반대편 가장자리**(=가까운 면)에 흔들림을 준다.
      const g=st.F[q.fi];
      const base=Math.atan2(g.oy,g.ox)+Math.PI;
      const a=base+(hash(q.seed+q.fi*2.7)-.5)*1.5;
      q.ax=Math.cos(a)*1.02;q.ay=Math.sin(a)*1.02;}
    const f=st.F[q.fi];
    if(!q.hit&&q.u>=FLY){              // 박히는 순간
      q.hit=1;
      const dx=f.ox,dy=f.oy,d=Math.hypot(dx,dy)||1;
      // ⚠️ 넉백이 **작다** — 꽂히는 것은 미는 것이 아니다(산탄과 갈리는 자리).
      hitFoe(st,f,cx,cy,dx/d,dy/d,2.2*SC,PZTOX);
      f.pv=Math.min(3,(f.pv||0)+1.1);
      emit(st,cx+f.ox+f.kx,cy+f.oy+f.ky,5,
        {k:PZTOX,sp:64,r:2.2,life:.46,g:80,spikeP:.25});}
    // 꽂혀 있는 내내 **계속 샌다** — 이 스킬이 파는 것은 한 방이 아니라 시간이다.
    if(q.u>=FLY&&q.u<FLY+DW)f.pv=Math.min(3,(f.pv||0)+dt*.62);
  }
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.30;
  stepP(st,dt);

  // ── 그리기 ──────────────────────────────────────────────────────────────
  // ⚠️ **잠긴 몫은 적보다 먼저** 그린다(안 나). 적의 몸이 그대로 마스크가 되어
  //   「반쯤 잠겼다」가 공짜로 나온다 — `pvMark` 의 앞뒤 층과 같은 수법이다.
  if(O.stick==="half")
    for(const q of st.dq)PZdartStuck(c,t,cx,cy,SC,st,q,FLY,DW,O,0);
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);
  for(const q of st.dq)PZdartFly(c,t,cx,cy,SC,st,q,FLY,O);
  for(const q of st.dq)PZdartStuck(c,t,cx,cy,SC,st,q,FLY,DW,O,1);
  drawP(c,st);hero(c,t,cx,cy);
}

/// 나는 동안 — **휜 길 · 잔상 · 뒤로 흘리는 독 방울.**
/// ⚠️ 길을 직선으로 두면 「선 하나」라 심심하고, 무엇보다 **돌아오는 원반**과
///   구별이 안 된다. 살짝 휘어 던지되 **고리를 안 닫는다** — 그것이 갈리는 자리다.
function PZdartFly(c,t,cx,cy,SC,st,q,FLY,O){
  if(q.u>=FLY)return;
  const u=q.u/FLY,f=st.F[q.fi];
  const tx=cx+f.ox+f.kx+f.r*q.ax,ty=cy+f.oy+f.ky+f.r*q.ay;
  const bend=O.bend===undefined?.16:O.bend;
  const mx=(cx+tx)/2-(ty-cy)*bend,my=(cy+ty)/2+(tx-cx)*bend;
  const at=(v)=>{const w=1-v;
    return[w*w*cx+2*w*v*mx+v*v*tx,w*w*cy+2*w*v*my+v*v*ty];};
  const R=(O.R||11)*SC;
  const ang=Math.atan2(ty-cy,tx-cx);
  const spin=t*(O.spin||14)+q.seed*3.1;
  // ⓐ **잔상** — 지나간 자리가 한 박자 늦게 지워진다. 두 겹이면 충분하다.
  for(let s=2;s>=1;s--){
    const uu=u-s*.055;if(uu<=0)continue;
    const p=at(uu);
    PZdartBody(c,p[0],p[1],R*(1-s*.10),spin-s*.9,ang,O,(.30-s*.09),SC,0);}
  // ⓑ 흘리는 독 — **뒤로 처지고 가라앉는다.** 불씨가 위로 뜨는 것의 반대다.
  const TX=toneOf(PZTOX);
  for(let d=0;d<3;d++){
    const uu=u-.13-d*.10;if(uu<=0)continue;
    const p=at(uu);
    const a=(1-d*.28)*Math.min(1,u*5)*.75;
    const rr=(2.4-d*.5)*SC;if(rr<=.2)continue;
    fillPoly(c,PKrag(p[0]+(hash(q.seed+d)-.5)*3*SC,p[1]+(u-uu)*26*SC,rr,
      q.seed+d*3.7,7,.36,q.seed+t*2.6),A(TX[0],a*.8));
    fillPoly(c,PKrag(p[0],p[1]+(u-uu)*26*SC,rr*.55,q.seed+d*5.3,7,.30,
      q.seed-t*2.2),A(TX[1],a));}
  // ⓒ 본체
  const p=at(u);
  PZdartBody(c,p[0],p[1],R,spin,ang,O,1,SC,0);
}

/// 몸 하나 — 회전축이 [O.axis] 로 갈린다.
///   `flat`  화면 평면에서 **팽이처럼** 돈다 — 날 셋이 늘 다 보인다
///   `wheel` 진행축을 중심으로 **바퀴처럼** 선다 — 옆에서 보면 납작해진다
function PZdartBody(c,x,y,R,spin,ang,O,al,SC,px){
  if(O.axis==="wheel"){
    c.save();c.translate(x,y);c.rotate(ang);
    PZstar(c,0,0,R,spin,O.blades,al,.16+.84*Math.abs(Math.cos(spin*.5)),SC,px);
    c.restore();
  }else PZstar(c,x,y,R,spin,O.blades,al,1,SC,px);
}

/// 꽂혀 있는 동안 — **이 스킬의 정체가 여기 있다.** 열셋 중 아무도 안 남기는
/// 「맞은 뒤의 물건」이 화면에 서 있다.
/// [layer] 0 = 적보다 먼저(잠긴 몫) · 1 = 적보다 나중(드러난 몫).
function PZdartStuck(c,t,cx,cy,SC,st,q,FLY,DW,O,layer){
  if(q.u<FLY||q.u>=FLY+DW)return;
  const su=(q.u-FLY)/DW;
  const f=st.F[q.fi];
  const x=cx+f.ox+f.kx+f.r*q.ax,y=cy+f.oy+f.ky+f.r*q.ay;
  const R=(O.R||11)*SC;
  // 들어갈 때 살짝 박히고(0.06 안), 끝에서 옅어진다.
  const bite=Math.min(1,su/.06);
  const fade=Math.min(1,(1-su)*4.2)*bite;
  if(fade<=.01)return;
  const TX=toneOf(PZTOX);
  const ang=Math.atan2(y-cy,x-cx);

  if(layer===0){
    // 잠긴 몫 — **온전한 표창을 통째로** 그린다. 적의 몸이 절반을 먹는다.
    // ⚠️ **꽂힌 뒤에는 빛이 식고 독이 진해진다**(`px=su`) — 「깔아 두고 나중에
    //   값이 난다」는 독의 동사가 여기서 그림이 된다.
    PZstar(c,x,y,R*.96,ang+.5,O.blades,.92*fade,1,SC,su);
    return;}

  // ── 드러난 몫 ───────────────────────────────────────────────────────────
  if(O.stick==="out"){
    // (가) **튀어나온 채 멈춘다** — 아주 느리게만 돈다. 굳은 물건이라 안 바쁘다.
    PZstar(c,x,y,R*1.02,t*.55+q.seed,O.blades,fade,1,SC,su);
  }else if(O.stick==="half"){
    // (나) **반쯤 잠겼다** — 밖으로는 **빛 날 하나와 허브 반쪽**만 남는다.
    //   ⚠️ 빛은 `su` 만큼 식고 독은 그만큼 진해진다.
    const rr=ang-.55;                        // 밖을 향해 선 날 하나
    PZblade1(c,x,y,R,rr,fade,SC,su);
    gAdd(c,g=>gHalo(g,x,y,R*.42,PZTOX,.50*fade*(1-su*.72)));
    if(R*.15>.3)fillPoly(c,PKrag(x,y,R*.15,4.3,7,.28,rr),
      A(TX[0],(.55+.40*su)*fade));
  }else{
    // (다) **안 멈춘다** — 몸 안에서 계속 돌며 갈아 넣는다. 점점 느려진다.
    const w=t*(9.5-6.5*su)+q.seed*3.1;
    PZstar(c,x,y,R*(1.02-.10*su),w,O.blades,fade,1,SC,su);
  }

  // ── 거기서 퍼지는 독 — 안마다 다르다 ────────────────────────────────────
  if(O.leak==="drip"){
    PZdrip(c,t,x,y,f.r,4,fade,SC,q.seed);
  }else if(O.leak==="wash"){
    // 몸을 **타고 번진다** — 면이라 「스며들었다」로 읽힌다.
    const g0=jagPoly(cx+f.ox+f.kx,cy+f.oy+f.ky,f.r*(1.02+.10*su),9,q.seed+2.1,1.12);
    fillPoly(c,g0,A(TX[0],.34*fade));
    c.beginPath();g0.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
    c.closePath();c.strokeStyle=A(TX[1],.62*fade);c.lineWidth=1.8*SC;c.stroke();
    fillPoly(c,jagPoly(x,y,f.r*(.30+.34*su),7,q.seed+5.3,1.06),A(TX[1],.40*fade));
    PZdrip(c,t,x,y,f.r,2,fade*.8,SC,q.seed+3.3);
  }else{
    // **나선으로 샌다** — 도는 물건이 짜내는 것이라 나선이 근거를 갖는다.
    const P=[];
    for(let i=0;i<=18;i++){
      const a=t*2.0+q.seed+i*.50,rr=f.r*(.16+i*.098);
      P.push([x+Math.cos(a)*rr,y+Math.sin(a)*rr*.74]);}
    // ⚠️ 나선이 **굵어야** 한다 — 가늘게 길게 감으면 그게 「거미줄」이다
    //   (사용자가 낙광 여덟을 그 이유로 반려했다).
    celRibbon(c,P,7.0*SC*fade,PZTOX,.92*fade);
    gAdd(c,g=>gHalo(g,x,y,f.r*1.1,PZTOX,.20*fade));
    PZdrip(c,t,x,y,f.r,2,fade*.85,SC,q.seed+1.9);
  }

  // ── ⭐ L5 각성 — **부러진 조각이 곁으로 튄다** ──────────────────────────
  // 다 샌 표창이 부러지며 조각이 흩어져 곁의 적에게 **얕게** 박힌다.
  // ⚠️ 감염(`spore`)의 「파문이 나가 물들인다」와 갈린다 — 저쪽은 **면**이 옮고
  //   여기는 **물건**이 옮는다.
  if(atL(5)&&su>.70){
    const w=(su-.70)/.30;
    for(let k=0;k<3;k++){
      const a=ang+(k-1)*1.05+hash(q.seed+k*3.1)*.6;
      const d=f.r*.8+w*26*SC;
      const ex=x+Math.cos(a)*d,ey=y+Math.sin(a)*d+w*w*7*SC;
      celSpike(c,ex,ey,a,R*(.72-.24*w),R*.22*(1-w*.4),PZMET,(1-w)*.95);
      gAdd(c,g=>gHalo(g,ex,ey,R*.5*(1-w*.5),PZTOX,.26*(1-w)));}
  }
}

// ── 표창 3안 ─────────────────────────────────────────────────────────────
// 갈리는 축이 **회전축 + 박힌 표시 + 새는 방식** 셋이다. 날 수·크기·색·성장은
// 셋이 같아서, 나란히 놓으면 그 셋만 눈에 들어온다.
// ⚠️⚠️ **날 반지름이 11.5 → 21 이다.** 첫 렌더에서 표창이 「초록 알갱이」로
//   보였고 무엇이 꽂혔는지 안 읽혔다. 바람원반이 같은 판정을 이미 받았다
//   (`FX.discus`: 「13 은 300px 칸에서 지름 16px 이라 **불티와 구별이 안 됐다** —
//   던진 물건은 **손에 잡히는 크기**로 보여야 「되돌아온다」가 물건의 이야기가
//   된다」). 표창은 「**남는다**」가 값이라 더더욱 크게 보여야 한다.
// ⚠️ 21 까지 키웠다가 **적보다 커져** 「무엇에 꽂혔나」가 안 보였다 — 16 이
//   적(15~16)과 같은 크기라 「몸에 박힌 물건」으로 읽힌다. 적도 같이 키웠다.
// ⚠️ **회전도 늦췄다**(15 → 9). 너무 빨리 돌면 정지 화면에서 날이 안 세어진다.
const PZDARTA={blades:3,axis:"flat" ,stick:"out"  ,leak:"drip"  ,R:18,spin: 9,bend:.16};
const PZDARTB={blades:4,axis:"wheel",stick:"half" ,leak:"wash"  ,R:18,spin: 7,bend:.10};
const PZDARTC={blades:3,axis:"flat" ,stick:"grind",leak:"spiral",R:18,spin:12,bend:.22};

// ══════════════════════════════════════════════════════════════════════════
// ② 독가스 — **마법 계열.** 녹염을 「불」이 아니라 「가스」로 다시 그린다
// ══════════════════════════════════════════════════════════════════════════
//
// ── 불과 가스는 문법이 정반대다 ───────────────────────────────────────────
//   나가는 힘  불 **뿜는다**(압력)      ↔ 가스 **샌다**(밀려 나와 퍼진다)
//   경계       불 또렷                  ↔ 가스 **흐리다**(가장자리가 사라진다)
//   무게       불 **뜬다**              ↔ 가스 **가라앉는다**(바닥을 긴다)
//   시간       불 뿜는 동안만           ↔ 가스 **남는다**(지나간 자리에 머문다)
//   속도       불 빠르다                ↔ 가스 **느리다**(굼실굼실)
//
// ⇒ **제트를 없앤다.** 화염방사의 정체가 「총구의 흰 제트 .15」인데 가스는 그게
//   없다 — 총구에서 낮게 새어 나와 앞으로 기어간다. (확정된 G4 재료 중 제트
//   하나만 빠지고 나머지 일곱은 그대로 쓴다.)
// ⚠️ **넉백이 0 이다** — 가스는 안 민다. 화염방사가 미는 것과 갈리는 자리다.
//
// ── 마법 계열의 다른 둘과 어떻게 갈리나 ───────────────────────────────────
//   극독 `brand`  **한 마리**에게 고리가 겹겹이 **조여든다** — 한방형
//   감염 `spore`  발원지가 **적**이다. 적 몸에서 파문이 나가 옆을 물들인다 — 광역형
//   독가스        발원지가 **나**다. 내가 선 자리에서 **판을 덮는다** — 지속형
// ⇒ 셋이 「누가 발원지인가 · 무엇이 자라나」로 갈린다. 겹치는 칸이 없다.
//
// ⚠️ 색은 사용자가 고른 **녹염**(화학 불꽃 115° L58 · 심 100° L89)이다. 독 속성
//   (129~137°)과 14~22° 차이라 고르기 화면에서는 「독 스킬로 읽힌다」가 **위험**
//   이었는데, **여기서는 그것이 맞는 그림**이다 — 이건 독 스킬이다.

/// 가스의 색 사다리 — 총구 → 끝. `[몸통, 심]` 다섯 칸이고 **화염방사가 쓰는
/// 그 함수**(`PKmassAt`)가 그대로 읽는다.
/// ⚠️ **불과 반대로 간다.** 불은 총구가 제일 밝고 끝이 식는데, 가스는 총구에서
///   **옅게 새어 나와 퍼진 자리에서 제일 짙고** 끝에서 흩어진다 — 실제로 가스는
///   나오는 순간이 아니라 **퍼진 뒤에** 보인다.
// ⚠️ **겉(몸통)은 어둡고 밝은 것은 심에만** 있다. 첫 렌더에서 몸통까지 밝은
///   녹염을 쓰니 서른 겹이 쌓여 **네온 초록 판**이 됐다 — 가스가 아니라
///   방사능 발광이다. 사용자가 고른 녹염(115° L58)은 **제일 짙은 자리(0.50)의
///   몸통**과 심에만 서고, 총구·끝은 그 색을 어둡게 민 것이다.
const PZGCOL=[
  ["#1A3E1E", "#3E9E38" ],   // 0.00 총구 — 어둡고 옅다. 아직 안 퍼졌다
  ["#25601F", "#57D96B" ],   // 0.25
  // ⚠️ 0.50 의 **몸통을 한 단 낮췄다**(#57E04A L58 → #3E9B39 L42). 사용자가 고른
  //   녹염(115°)은 **색상은 그대로**이고 밝기만 내렸다 — 몸통까지 L58 이면
  //   마흔 겹이 쌓여 **형광**이 된다. 그 색은 이제 **심**에만 산다.
  ["#3E9B39", PKT.verdLt],   // 0.50 **제일 짙다** — 다 퍼진 자리
  ["#2F6630", "#7FBE62" ],   // 0.75
  ["#1A2618", "#38502E" ]];  // 1.00 끝 — 흩어져 사라진다
/// 가라앉는 알갱이의 색 — **불씨의 자리**다. 불은 위로 뜨고 이건 내려앉는다.
const PZGEMBC=PKT.verdLt;

/// 봉투 셋 — `hw` 반폭 · `lat` 좌우 어긋남 · `sink` **가라앉는 양** ·
/// `res` 지나간 자리에 **남는 정도** · `spd` 덩어리 속도 · `grow` 덩어리 크기.
/// ⚠️ 화염방사의 `PKENV` 와 **키가 하나 다르다**(`sink`) — 그것이 「가라앉는다」다.
const PZGENV={
  // (가) 샌다 — 총구에서 **낮게** 나와 바닥을 따라 기어간다. 넓고 납작하다.
  creep:{hw:(u,HL,w0)=>w0*.5+HL*(.36+1.04*Math.pow(u,.52)),
         lat:(u,t,HL)=>Math.sin(u*2.1-t*.55)*HL*.10*u,
         sink:(u,HL)=>HL*.86*u*u, spd:.50,res:.16,grow:1.10,sq:.54},
  // (나) 부푼다 — 조금 나가서 **뭉게뭉게 커진다.** 앞으로 덜 가고 옆으로 크다.
  bloom:{hw:(u,HL,w0)=>w0*.5+HL*(.20+1.18*Math.pow(Math.sin(Math.PI*Math.min(1,u*.88)),.66)),
         lat:(u,t,HL)=>Math.sin(u*1.6-t*.42)*HL*.13*u,
         sink:(u,HL)=>HL*.34*u, spd:.38,res:.26,grow:1.55,sq:.98},
  // (다) 고인다 — 앞으로 나가되 **지나간 자리마다 얕은 층이 남아** 뒤가 안 빈다.
  pool :{hw:(u,HL,w0)=>w0*.5+HL*(.28+.90*Math.pow(u,.74)),
         lat:(u,t,HL)=>Math.sin(u*2.4-t*.62)*HL*.09*u,
         sink:(u,HL)=>HL*.56*u*u, spd:.62,res:1.00,grow:1.18,sq:.78},
};

/// **가장자리가 사라지는 원판** — 가운데가 색이고 밖으로 갈수록 투명해진다.
/// ⚠️⚠️ **이것 하나가 「불 ↔ 가스」를 가른다.** 첫 렌더에서 덩어리를 불과 같은
///   방식(너덜너덜한 폴리곤을 진하게)으로 칠했더니 **각진 초록 판때기**가 됐다 —
///   경계가 또렷하니 그건 가스가 아니라 초록 불이다. 폴리곤은 아무리 흔들어도
///   **선이 남는다**. 밖으로 풀리는 그러데이션이라야 「사라진다」가 된다.
/// ⚠️ 가산이 아니다 — 겹쳐서 밝아지면 안 된다(가스는 스스로 안 빛난다).
/// ⚠️ 캔버스 흐림(`filter:blur`)은 안 쓴다 — 채우기 비용이 그대로 배가 된다.
/// [sy] 세로 눌림 — 1 보다 작으면 **납작해진다**(바닥을 기는 가스).
function PZsoft(c,x,y,r,col,a,sy){
  if(!(r>.3)||!(a>.004))return;
  const q=sy===undefined?1:Math.max(.12,sy);
  c.save();c.translate(x,y);c.scale(1,q);
  const g=c.createRadialGradient(0,0,r*.18,0,0,r);
  g.addColorStop(0,A(col,a));g.addColorStop(.55,A(col,a*.52));
  g.addColorStop(1,A(col,0));
  c.fillStyle=g;c.beginPath();c.arc(0,0,r,0,TAU);c.fill();
  c.restore();}

/// 덩어리 자리 — 화염방사의 `PKfBlobs` 와 같은 뼈대인데 **가라앉음**이 붙었고
/// 앞으로 가는 곡선이 더 **완만하다**(가스는 굼실굼실 간다).
function PZgasPuffs(t,cx,cy,SC,LEN,HALF,NL,NB,E,ang){
  const o=[],ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  for(let j=0;j<NL;j++){
    const lat=NL>1?(j-(NL-1)/2)/((NL-1)/2):0;
    for(let b=0;b<NB;b++){
      const sd=j*5.3+b*1.7+11;
      const ph=((t*E.spd+j*.29+b/NB)%1);
      const u=Math.pow(ph,.72);
      const d=LEN*u,half=E.hw(u,HL,0);
      const off=E.lat(u,t,HL)+lat*half*.66+Math.sin(ph*3.1+j*2.1)*half*.12;
      o.push({x:cx+ax*d+nx*off,y:cy+ay*d+ny*off+E.sink(u,HL),
        r:SC*3.0+half*(.42+1.05*hash(sd*1.9))*.66*E.grow,u,sd,
        // ⚠️ 시작·끝에서 **둘 다 0** 이라야 루프에 이음매가 안 생긴다.
        al:Math.min(1,ph*5)*Math.min(1,(1-ph)*3.2)});}}
  o.sort((p,q)=>q.u-p.u);
  return o;
}

// ⚠️ 수를 늘리고 **한 겹의 알파를 낮췄다** — 「빈 곳」은 겹으로 메우고
//   밝기는 낮춰야 「풍성한데 화려하진 않다」가 된다.
const PZGNL=[3,4,4,5,5],PZGNB=[4,5,6,7,8];   // 갈래 · 갈래마다 덩어리 수
// ── ⭐ **연기** — 2026-08-23 사용자 반려의 답 ────────────────────────────
// 사용자: 「독가스의 경우에는 **독형광물질 느낌이 아니라 '독 가스' 느낌**이니까
//   **연기도 섞여야** 되고 **좀 더 레이어를 쌓아서** '독가스' 느낌으로」
//
// ⚠️⚠️ **진짜 가스는 스스로 안 빛난다 — 빛을 가리고 흩뜨린다.** 앞 판은 초록
//   하나뿐이었고 그 초록이 가산으로 겹쳐 **형광 물질**이 됐다. 고친 것 셋:
//     ① **연기를 섞는다** — 회탁색 덩어리가 초록과 **얼룩덜룩하게** 엉킨다.
//        앞의 연기가 뒤의 초록을 **가려서** 「두께」가 생긴다.
//     ② **층을 쌓는다** — 다섯이다(아래 표). 화염방사에서 「풍성한데 화려하진
//        않다」의 답이 **다른 종류를 겹치는 것**이었던 그 수법 그대로다.
//     ③ **가산을 껐다** — 겹칠수록 밝아지면 형광이고, 가스는 겹칠수록 **짙어져야**
//        한다. 밝은 심도 좁혔다.
//
// ⚠️ **순수한 회색이면 어두운 배경에서 안 보인다.** 초록을 아주 조금 탄 회색이다:
//     #2B302A 110° S7 L18  ·  #454B42 100° S6 L28  ·  #6B7266 95° S6 L42
//   (독 본체 129~134° 대비 **20~35° 낮고 채도가 1/10** 이라 「탁하다」로 읽힌다)
const PZSMK=["#2B302A","#454B42","#6B7266"];
/// 연기 덩어리 수 — **작은 것 여러 개**다. 큰 반투명 면을 겹치는 것이 제일 비싸서,
/// 같은 잉크로 더 얼룩덜룩해지는 쪽을 골랐다(비용은 아래 절에 실측해 적었다).
const PZGSMK=[7,10,13,16,20];
const PZGEMB=[5,7,9,12,15];                  // 가라앉는 알갱이 — 작아서 싸다
const PZGRES=[4,5,7,8,10];                    // 머무는 자리 수

/// 가스 한 갈래. **화염방사의 재료 여덟 중 일곱을 그대로 쓴다** — 빠진 하나가
/// 제트다. 대신 「흐릿한 경계」와 「남는 것」 둘이 들어왔다.
function PZgasLane(c,t,cx,cy,SC,LEN,HALF,M,E,amul){
  const ang=FCDIR;
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  const w0=7*SC;
  // ⓐ **밑판 — 축을 따라 놓은 「풀리는 원판」 열다섯.**
  //   ⚠️ **여기서 「빈 곳」이 사라진다**(사용자: 「비어있는 곳이 있으면 안 됨」).
  //   ⚠️⚠️ **폴리곤 밑판을 썼다가 걷었다**(렌더 세 번). 화염방사처럼 봉투
  //     폴리곤을 [PKfillCool] 로 깔았는데, 알파를 .09 까지 낮춰도 **곧은 변이
  //     남아** 구름 둘레에 각진 실루엣이 보였다 — **폴리곤은 흐려지지 않는다.**
  //     원판 열다섯을 겹치면 빈 곳은 메워지고 둘레에는 선이 한 줄도 안 남는다.
  //   ⚠️ 캔버스 흐림(`filter:blur`)은 안 쓴다 — 채우기 비용이 그대로 배가 된다.
  //   ⚠️ 색은 여전히 사다리를 탄다 — 원판마다 그 자리의 색을 뽑아 칠한다.
  {const NS=15;
   for(let i=0;i<=NS;i++){
     const u=i/NS,d=LEN*u,half=E.hw(u,HL,w0),lt=E.lat(u,t,HL);
     const MM=PKmassAt(M,u);
     PZsoft(c,cx+ax*d+nx*lt,cy+ay*d+ny*lt+E.sink(u,HL),half*1.20,
       MM[0],.085*amul,E.sq||1);}}
  // ⓑ **바닥에 고인 것** — 제일 짙고 **안 움직인다.** 채택본 「고인다」의 정체다.
  //   ⚠️ **맨 뒤에 깐다** — 떠 있는 몸통이 그 위를 지나가야 「깔린 것 ↔ 떠 있는 것」
  //     둘로 읽힌다. 앞에 두면 그냥 한 덩어리다.
  if(E.res>0){
    const NR=PZGRES[LV-1];
    for(let k=0;k<NR;k++){
      const sd=k*7.7+3;
      const ph=((t*.28+k/NR)%1);
      const u=.16+.68*hash(sd);
      const d=LEN*u,half=E.hw(u,HL,0);
      const off=(hash(sd+1.7)-.5)*2*half*.72;
      const x=cx+ax*d+nx*off,y=cy+ay*d+ny*off+E.sink(u,HL)+half*.22;
      const rr=(half*.40+4*SC)*(.55+.60*ph);
      const al=Math.min(1,ph*4)*Math.min(1,(1-ph)*2.4)*E.res*.60*amul;
      if(al<=.01||rr<=.3)continue;
      const MM=PKmassAt(M,Math.min(1,u+.26));
      // ⚠️ **눌러서 바닥에 붙인다** — 머무는 것은 뜬 것이 아니라 **깔린 것**이다.
      PZsoft(c,x,y,rr*1.62,MM[0],al*.46,.40);
      fillPoly(c,PKrag(x,y,rr*.62,sd,13,.22,sd+t*.10),A(MM[0],al*.24));}}
  // ⓒ **떠 있는 몸통** — 색 사다리 · 너덜너덜한 가장자리 · 크기 편차 · 안쪽 결.
  //   ⚠️ 흔들림 폭이 불(.42)보다 **작다**(.22) — 불은 혀처럼 날름거리고
  //     가스는 뭉실거린다. 그 차이가 곧 「또렷 ↔ 흐릿」이다.
  const bs=PZgasPuffs(t,cx,cy,SC,LEN,HALF,PZGNL[LV-1],PZGNB[LV-1],E,ang);
  for(const b of bs){
    if(b.al<=.02)continue;
    const MM=PKmassAt(M,b.u),rn=b.r>9*SC?19:15;
    if(b.r<=.3)continue;
    // ⓑ-1 **풀리는 겉** — 두 겹. 이것이 덩어리의 윤곽을 지운다.
    const sy=E.sq||1;
    PZsoft(c,b.x,b.y,b.r*1.35,MM[0],b.al*.085*amul,sy);
    PZsoft(c,b.x,b.y-b.r*.06,b.r*1.00,MM[0],b.al*.105*amul,sy);
    // ⓑ-2 **몸** — 여기만 너덜너덜한 폴리곤이다(G4 재료 「너덜너덜한 가장자리」).
    //   ⚠️⚠️ **반지름이 .84 → .50 이다.** .84 로 두니 폴리곤의 곧은 변이 덩어리
    //     **바깥 윤곽**에 그대로 나와 구름 둘레가 각져 보였다(셋째 렌더). 안쪽으로
    //     들여놓으면 결은 남고 윤곽은 [PZsoft] 만 만든다 — 「흐릿한 경계」가 산다.
    fillPoly(c,PKrag(b.x,b.y,b.r*.50,b.sd,rn,.24,b.sd+t*.30),A(MM[0],b.al*.13*amul));
    // ⓒ-3 **심** — **아주 좁게.** 넓으면 그게 형광의 원인이다(2026-08-23 반려).
    PZsoft(c,b.x,b.y-b.r*.10,b.r*.40,MM[1],b.al*.07*amul,sy);
    // 안쪽 결 — 소용돌이 한둘. 「굼실굼실」이 여기서 나온다.
    if(b.r>5*SC){
      const gn=1+((b.sd*7)|0)%2;
      for(let q=0;q<gn;q++){
        const ga=b.sd*2.3+q*2.7+t*.35,gd=b.r*(.10+.20*hash(b.sd+q*5.1));
        const gr=b.r*(.18+.16*hash(b.sd+q*2.7));
        if(gr<=.2)continue;
        fillPoly(c,PKrag(b.x+Math.cos(ga)*gd,b.y+Math.sin(ga)*gd,gr,
          b.sd+q*11,9,.26,ga),A(PKmassAt(M,Math.max(0,b.u-.30))[1],b.al*.42*amul));}}}
  // ⓓ ⭐ **연기** — 회탁색이 초록과 **얼룩덜룩하게 엉킨다.**
  //   ⚠️⚠️ **가산이 아니다.** 그냥 위에 덮는다 — 앞의 연기가 뒤의 초록을 **가려야**
  //     「두께」가 생긴다. 겹쳐서 밝아지면 그건 형광이고 가스가 아니다.
  //   ⚠️ **위로 오른다**(초록은 가라앉는데 연기는 뜬다). 둘이 반대로 움직여야
  //     한 덩어리가 아니라 **섞인 둘**로 보인다.
  //   ⚠️ **작은 것 여럿**이다 — 큰 반투명 면 하나보다 싸면서 더 얼룩덜룩하다.
  {const NK=PZGSMK[LV-1];
   for(let k=0;k<NK;k++){
     const sd=k*4.13+21;
     const ph=((t*.34+hash(sd)+k/NK)%1);
     const u=Math.pow(ph,.62);
     const d=LEN*u,half=E.hw(u,HL,0);
     const off=(hash(sd+1.9)-.5)*2*half*.86+E.lat(u,t,HL);
     // 연기는 **뜬다** — 초록의 `sink` 를 절반만 따라가고 그만큼 위로 남는다.
     const x=cx+ax*d+nx*off,y=cy+ay*d+ny*off+E.sink(u,HL)*.35-u*u*10*SC;
     const rr=(half*(.22+.30*hash(sd*1.7))+3*SC);
     const al=Math.min(1,ph*4)*Math.min(1,(1-ph)*2.6)*amul;
     if(al<=.01||rr<=.3)continue;
     // 멀리 갈수록 옅어지고 밝아진다(식은 연기).
     const tone=PZSMK[u<.34?0:(u<.70?1:2)];
     PZsoft(c,x,y,rr*1.72,tone,al*.34,.92);
     fillPoly(c,PKrag(x,y,rr*.70,sd,11,.30,sd+t*.42),A(tone,al*.30));
     // 한 겹 더 짙게 — **가리는 것**이 연기의 일이다. 옅으면 안 가려진다.
     fillPoly(c,PKrag(x,y,rr*.40,sd+3.1,9,.26,sd-t*.31),A(PZSMK[0],al*.26));}}
  // ⚠️ **가산 빛번짐을 껐다**(2026-08-23 반려: 「독형광물질 느낌」). 옛 코드는
  //   `gAdd(...gHalo(...,PZTOX,.11*b.al))` 였다 — 덩어리 마흔이 겹치는 자리마다
  //   흰빛으로 타서 그것이 형광의 절반이었다. **가스는 스스로 안 빛난다.**
  // ⓔ **가라앉는 알갱이** — 불씨의 자리. 불티는 뜨고 이건 내려앉는다.
  for(let k=0;k<PZGEMB[LV-1];k++){
    const sd=k*3.77+ang*7+5;
    const sp=.26+.40*hash(sd),life=.70+.60*hash(sd+1.3);
    const q=((t*sp+hash(sd+2.1))%1);
    if(q>life)continue;
    const w=q/life;
    const u=Math.min(1,.22+.50*hash(sd+3.3)+.28*w);
    const d=LEN*u,half=E.hw(u,HL,0);
    const lat=E.lat(u,t,HL)+(hash(sd+5.2)-.5)*2*half*(.5+.85*w);
    const x=cx+ax*d+nx*lat,y=cy+ay*d+ny*lat+E.sink(u,HL)+w*w*20*SC;
    const r=SC*(.8+1.9*hash(sd+7.3))*(1-w*.45);
    if(r<=.2)continue;
    // ⚠️ 들어올 때 **fade-in** 을 준다 — 안 주면 `w=0` 에서 알파가 튀어 깜빡인다.
    fillPoly(c,PKrag(x,y,r,sd,7,.30,sd+t*1.1),
      A(PZGEMBC,Math.min(1,w*8)*(1-w)*(1-w)*.85*amul));}
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 독가스 **다시** — 전방 분사를 버리고 **몸 둘레로** 퍼진다  (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독가스는 보니까 **전방 분사가 아니라 캐릭터 주변으로 무작위 분사**로
//   해야 할 거 같아 **부우와아아앙** 느낌으로」
//
// ⭐ 이 한 판정이 셋을 같이 푼다:
//   ① **가스는 쏘는 게 아니라 부푸는 것**이다. 압력으로 뿜는 건 불의 문법이다.
//   ② **화염방사와 실루엣이 겹치던 문제가 사라진다** — 원뿔 대 구름.
//   ③ **독의 동사와 맞는다** — 몸 둘레에 고여 남는 것이 「깔아 두고 나중에」다.
//
// ── 「부우와아아앙」을 무엇으로 냈나 (의성어라 소리를 못 쓴다) ──────────────
//   느리다        확 안 터진다. 뭉치가 **밀려 나오듯** 천천히 부푼다(`pow(ph,.55)`)
//   무겁다        위로 안 뜨고 **가라앉으며 옆으로** 번진다(`sink`)
//   한 덩어리 아님 **뭉치 여럿**이 방향·크기·속도·수명이 **다 다르다**
//   끝이 없다     가장자리가 **사라진다** — [PZsoft] 만 윤곽을 만든다
//   차오른다      안쪽부터 짙고 바깥으로 옅다(색 사다리가 반지름을 탄다)
// ⚠️ **「무작위」가 핵심**이다. 고르게 퍼지면 그건 **원**이고 제각각이면 **가스**다.
//   ⚠️ 다만 **씨앗을 고정**했다([hash] 만 쓴다 · `Math.random` 0건) — 구울 때마다
//     같은 그림이 나와야 두 판을 견줄 수 있다.
//
// ── ⚠️ 엔진 참고 — **판정 모양은 아직 없다** ─────────────────────────────
// 독가스는 신설이라 엔진에 구현이 **없다**. 그래서 여기 그리는 것이 곧 제안이
// 된다. ⇒ **몸 중심 원 하나**로 그렸다: 이식할 때 `dist(foe, hero) < R` 한 줄이면
// 끝나고, 원뿔처럼 각도를 재는 코드가 필요 없다.
// ⚠️ 반경은 L5 에서 **몸에서 96**(칸 238 기준). 견줄 자리: 광주 기둥 원이 L5 에서
//   **160** 이므로 그 **60%** 다.
// ══════════════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 독가스 **정정** — **녹염을 바탕으로** 두고 「조금」만 바꾼다  (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독염(녹염)을 **가지고 이용하라니까** 지 멋대로 만들면 어쩌자는 거,,」
// 원래 지시: 「자염과 녹염은 **형태를 조금 바꿔서** '마' 캐릭터의 스킬과
//   '독' 캐릭터 스킬로 바꾸려고」
//
// ⚠️⚠️ **앞의 둘(전방 봉투판 · 둘레 분사판)은 녹염을 통째로 버린 것이라 틀렸다.**
//   함수는 남긴다(`PZgasA/B/C` · `PZgasAura`). 여기서 바탕은 **녹염 그대로**다:
//     재료  채움 · 너덜너덜한 가장자리 · 크기 편차 · 안쪽 결 · 불씨 · 가산 빛번짐 · 잔상
//     색    `PKCOL.verd` — 화학 불꽃 **115° L58** · 심 **100° L89** → 숯
//     모양  제트 **.15** · **S자**(`PKENV.ess`) · 진폭 **.33**
//   ⇒ **[PKflameLane] 을 그대로 부른다.** 사본을 안 뜬다(화염방사 담당의 것이다).
//
// ── ⭐ 불과 가스를 가르는 축은 **하나**다 ────────────────────────────────
//   불은 뿜은 것이 **바로 꺼지고**, 가스는 **안 꺼지고 남는다.**
//   ⇒ 모양을 갈아엎지 않고 **「수명」과 「탁함」**만 바꾼다:
//     ① **자취** — 지난 뿜음을 **셋** 더 그린다(0.7 · 1.4 · 2.1초 전, 점점 옅게).
//        몸이 걸어 다니므로 그 셋이 **지나온 자리에 깔린다** — 방구차가 그것이다.
//     ② **연기** — 회탁색 뭉치가 초록과 얼룩덜룩 엉킨다(가산 아님 · **가린다**).
//     ③ **탁함** — 원뿔 위에 회탁 막을 얹어 「형광」을 죽인다.
//     ④ **형광 죽이기** — [PKflameLane] 안의 가산 후광이 `"ember"` 톤을 쓰는데,
//        그 톤을 **잠깐 칙칙한 녹회색으로 갈아 끼워** 부른다([PZwithToneArr]).
//        ⚠️ 표를 **고치는 게 아니라** 한 프레임 동안 빌려 쓰고 되돌린다.
//
// ── ⚠️ 엔진 참고 (그리기만) ──────────────────────────────────────────────
// 독가스는 아직 엔진에 없다. **자취형**이면 판정이 「몸이 지나온 자리의 원들」이
// 되고, **불자취(`trail`)가 이미 그 모양**이라 이식할 자리가 있다.
// ══════════════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 독가스 **정정 3** — **사용자가 그린 그림**대로              (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「흰색을 캐릭터라고 하면 **초록색에 구멍이 2개가 뚫린 가스 수류탄 같은
//   걸 소환**하고, 해당 **수류탄 구멍 2개에서 '녹염' 같은 형태의 독가스를 일정
//   시간 분사**하다가 **분사를 멈춘다.** **일정 쿨타임이 지나면 다시 독가스를
//   분사.** 독가스는 **S자 형태의 각도를 좀 더 강하게** 분출.」
//
// ── 그림이 말한 것 넷 ────────────────────────────────────────────────────
//   ① **수류탄은 캐릭터에서 떨어져 있다** — 몸에 붙은 것이 아니라 **놓는 물건**
//   ② **수류탄은 작고 줄기는 크다** — 주인공은 **가스**다
//   ③ **두 줄기가 서로 다른 방향**으로 간다
//   ④ **S 굽이가 크다** — 확정본 진폭 `.33` 보다 훨씬
//
// ⭐ **바탕은 녹염 그대로다.** [PKflameLane] 을 부르고 색은 `PKCOL.verd`
//   (115° L58 · 심 100° L89), 재료 여덟과 제트 `.15` 도 그대로다.
//   **바꾸는 것은 둘뿐**: **진폭**과 **근원(총구 → 구멍 둘)**.
// ⚠️ `PKENV.ess` 를 **안 고친다** — 화염방사 담당의 것이다. 대신 그 함수를
//   **그대로 부르고 옆흔들림에만 배수를 곱한다**(아래 [PZbESS]). 사본이 아니라
//   **덧씌움**이라, 확정본이 바뀌면 이쪽도 같이 바뀐다.
//
// ── 정한 값 (전부 238 칸 기준 · 판정 대기) ───────────────────────────────
//   수류탄  몸에서 **위로 30 · 옆으로 21**(거리 37) · 반지름 **9** · 구멍 반지름 1.9
//   구멍 방향  위쪽 기준 **−32°** 와 **+56°** (**88° 벌어진다**)
//   줄기    길이 **78**(확정본 95 의 82%) · 반각 .30 그대로
//   진폭    **.60** (확정본 `.33` 의 **1.82배**) — 「좀 더 강하게」
//   주기    분사 **1.6초** → 멈춤(남아서 흩어짐) **0.7초** → 쿨 **1.0초** = **3.3초**
//
// ── ⚠️ 엔진에 이 구조가 있나 (이식용 메모) ───────────────────────────────
//   **「자리에 놓이는 물건이 뿜는다」는 구조가 엔진에 없다.** 광주는 몸 둘레에
//   서고(`w_pillar`), 결계는 몸에 붙고, 낙광은 **자리를 베껴 그리로 친다**
//   (`lightfall.dart:113` `_px[p]=e.x[j]` — 시전할 때 한 번 베낀다).
//   ⇒ **낙광의 「자리를 베낀다」가 제일 가깝다.** 수류탄 위치를 한 번 베끼고,
//     그 뒤로는 그 자리에서 원뿔 둘을 도는 식이면 새 개념이 안 필요하다.
// ══════════════════════════════════════════════════════════════════════════

/// 확정본 봉투를 **그대로 부르고 옆흔들림만 키운다.** 사본이 아니다 —
/// `PKENV.ess` 가 바뀌면 이쪽도 같이 바뀐다.
// ⚠️ **`PKENV.ess` 를 안 고친다** — 화염방사 담당의 것이다. 그 함수를 **그대로
//   부르고 옆흔들림에만 배수를 곱한다.** 사본이 아니라 덧씌움이라 확정본이
//   바뀌면 이쪽도 같이 바뀐다.
// ⭐ **진폭 2.00 확정**(2026-08-23 사용자: 「S자를 **완전히 휘게 좌우로 돌려**줘」
//   → 「진폭을 2배로」 → 「**2.0 으로**」). 세 단으로 갈라 세웠던 것은 **뺐다**.
//   ⚠️ 화염방사의 「살랑살랑 .33」과 **정반대 방향**이라 그 값에 안 매인다 —
//     확정본 대비 **6.06배**다.
const PZbAMPS=[2.00,1.00,1.50];         // [0] 이 확정값. 나머지는 함수로만 남긴다
// ⭐⭐ **왕복 속도** (2026-08-23 사용자: 「초록 줄기를 S자로 휘는 거 **좌 → 우 →
//   좌** 그 **속도를 더 빠르게**」). ⚠️ **진폭이 아니라 주파수다** — 진폭은 2.00 확정.
//   확정본의 `lat` 은 시간항이 `t*1.15` 라 **왕복 5.46초**(초당 0.18회)였다.
//   ⇒ **시각에 배수를 먹여** 왕복을 **1.00초**(초당 1.0회)로 만든다 = **5.46배 빠르다**.
//   ⭐ **분사 3.0초 안에 왕복이 정확히 세 번** 들어간다 — 주기 끝과 처음이 같은
//     스케줄에서 나오므로 분사가 어중간한 자리에서 안 끊긴다(이 저장소가 같은
//     원인으로 네 번 반려당한 자리다).
//   ⚠️ `PKENV.ess` 는 **안 고친다** — 그 함수를 그대로 부르고 **인자만** 갈아 넣는다.
// ⚠️⚠️ **1.00 은 지나쳤다** — 사용자: 「S자로 휘는 거 **너무 방정맞게** 움직인다
//   ㅋ **너무 빠르게 한 거 같아**」. 올리기 전 **5.46초**와 지금 **1.00초** 사이로
//   내린다 → **3.00초**(초당 0.33회 · 확정본의 1.82배). ⭐ **분사 3.0초 안에
//   왕복이 정확히 한 번** 들어가 분사가 시작한 자세로 끝난다.
//   ⭐ 기준어는 **「살랑살랑」**이다 — 화염방사 확정본이 그 말로 정해졌다.
//     진폭 2.00 은 그대로이므로 **멀리 휘되 천천히**가 지금 목표다.
// ⚠️⚠️ **2.40 으로 못 박은 까닭**: 총 주기가 4.8초인데 왕복이 3.0초면 4.8 이
//   3.0 의 배수가 아니라 **매 주기의 그림이 조금씩 달라진다**(1ms 2400점 검산에서
//   `lat` 이 이음매에서 3.18 튀는 것으로 잡혔다). **2.40 이면 4.8 안에 정확히
//   두 번** 들어가 매 주기가 **똑같이 재생**된다 — 이 저장소가 네 번 반려당한
//   「주기 끝과 처음은 같은 스케줄에서」가 그 뜻이다.
const PZbCYC=2.40;                      // 왕복 주기(초) — 총 주기 4.8 에 정확히 2번
const PZbW=2*Math.PI/PZbCYC;            // 각속도 2.094 rad/s

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **용 꼬리를 고친 자리 — 원인은 값이 아니라 좌표계였다**   (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독가스라면 좌우로 흔들릴 때 연기가 좀 더 **잔여**라고 해야 하나?
//   **그 위치에 잔상이 남으면서 따라와야** 되는데, 지금은 그냥 **용 꼬리 움직이듯이
//   휘저어지는** 거 같아」
//
// ⚠️⚠️ **원인**: 줄기의 모든 점이 **「지금 시각 `t`」의 함수**로 그려졌다. 그래서
//   뿌리를 흔들면 **끝까지 통째로 같이** 휜다 = 채찍·용 꼬리.
//   ⭐ 이 저장소가 **같은 부류를 이미 겪었다** — 광주 「스프링처럼 늘어난다」의
//     원인도 좌표계였다(보이는 구간 안에서 무늬를 그려 같은 `u` 의 점이 프레임마다
//     움직였다). 고친 법도 같다: **경로를 한 번 짓고 보이는 구간만 자른다.**
//
// ⭐ **고친 법 — 「태어난 시각의 위상」을 간직시킨다.**
//   가스 한 덩어리가 시각 `t0` 에 나와 진행도 `u` 까지 가는 데 `u·T` 초가 걸린다면,
//   그 덩어리의 가로 어긋남은 **`sin(−ω·t0)` 로 고정**돼야 한다. `t0 = t − u·T` 이므로
//       lat(u,t) = sin(ω·(u·T − t)) · HL · amp · u^1.6
//   이면 그 덩어리가 지나가는 내내 **같은 값**이 나온다 — 흔들림이 **아래에서 위로
//   번져 올라가고**, 지나간 S자가 **공중에 그대로 걸린다.**
//   ⚠️ 검산: `t = t0 + u·T` 를 넣으면 위상이 `−ω·t0` 로 **`u` 가 사라진다**.
//
// ⚠️⚠️ **여기서만 `PKENV.ess.lat` 을 안 쓴다.** 그 함수의 공간항은 `u·π·1.25` 로
//   **고정**이라 파동의 전파 속도가 `ω/k` 로 묶여 있는데, 가스가 실제로 흘러가는
//   속도(`PKflameLane` 이 `PKfBlobs` 에 넘기는 `spd=.85` ⇒ 끝까지 **1.18초**)와
//   **안 맞는다.** 시간 인자만 밀어서는 공간항을 **줄일 수가 없어**(더하기만 된다)
//   구조를 못 고친다. ⇒ **이 한 함수만 직접 쓴다.**
//   ⚠️ `hw`(폭)·제트·재료·색은 여전히 확정본 그대로다. 바꾼 것은 **가로 어긋남 하나**.
//   ⚠️ `PKENV.ess` 는 **한 글자도 안 고쳤다** — 화염방사 담당의 것이다.
const PZbT=1/.85;                       // 가스가 끝까지 가는 시간(초) = 1.18
const PZbEnv=(amp)=>({
  hw:(u,HL,w0,pw)=>PKENV.ess.hw(u,HL,w0,pw),
  lat:(u,t,HL)=>Math.sin(PZbW*(u*PZbT-t))*HL*amp*Math.pow(u,1.6),
  lanes:1});
const PZbESSA=PZbEnv(PZbAMPS[0]),PZbESSB=PZbEnv(PZbAMPS[1]),PZbESSC=PZbEnv(PZbAMPS[2]);
// ⚠️⚠️ **×6(반지름 54)로 키웠다가 되돌렸다** — 사용자가 보고 「엉망이 됐어,
//   **원래 빛으로 만든 작은 구** 형태 디자인 괜찮았잖아」라고 했다. 망가뜨린 것은
//   **모양이 아니라 크기**였다. ⇒ **9 로 되돌린다.** 디자인(빛의 구)은 그대로다.
//   ⭐ **줄기가 주인공**이라 구는 작아야 한다 — 손그림의 비가 그것이었다.
//   ⚠️ ×6 에 맞춰 같이 옮겼던 **자리**도 되돌린다(아래 `bx`·`by`).
const PZbDIST=37, PZbRAD=9;             // 수류탄 — 놓이는 거리 · 반지름(작다)
// ⚠️⚠️ **115° 로 벌렸다가 88° 로 되돌렸다.** 벌린 까닭이 「구가 6배라 줄기가
//   엉킨다」였는데 **구가 9 로 돌아가 그 까닭이 없어졌다** — 원인이 사라졌는데
//   대증요법만 남기지 않는다. 진폭 1.50 에서 엉키는지는 굽고 확인한다.
const PZbA1=-.56, PZbA2=.98;            // −32° · +56° = **88° 벌어진다**
// ⚠️⚠️ **구멍의 흔들림을 뺐다**(0 이다). 줄기의 방향을 프레임마다 돌리면 그것이
//   **둘째 채찍**이 되어 잔상 구조를 도로 깨뜨린다 — 나간 덩어리는 제 방향을
//   간직해야 하는데 축이 통째로 돌면 그럴 수가 없다. 좌 → 우 → 좌 는 이제
//   **실려 가는 파동**([PZbEnv])이 혼자 낸다.
//   ⚠️ 구의 자오선은 그대로 돈다 — 그건 **장식**이지 줄기의 축이 아니다.
const PZbSWING=()=>0;                   // 줄기 축은 **안 돈다**
// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **끝맺음은 「길이가 줄어드는 것」이다**                      (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독가스의 경우 **잔상을 먼저 남기고 깜빡깜빡거리니까** 바뀐 건지도
//   모르겠네… 독가스 스킬 끝나면 **잔상 남기는 식으로 하면 안 되고 크고 길게
//   나가던 게 점점 짧아지면서 마지막에 아주 조금 팅팅 나오다가 멈춰야 함.
//   일정 시간 지나면 다시 분출되고… 그런 식」
//
// ⚠️⚠️ **깜빡임의 원인은 잔상 겹이었다 — 추측이 아니라 실측이다.**
//   앞 판은 잦아듦에서 뿜기를 **끊고**(`spit` 표의 빈틈) 그 빈자리를 **길이를
//   안 줄인 잔상**(`rest`, `LEN` 그대로 · 세기 `1-on`)이 메웠다. 그 결과:
//     · 잦아듦 1.0초 내내 **화면에서 제일 긴 것이 77.345px 로 못 박혔다**
//       (1ms · 4801점 검산에서 그 구간 최대 도약 **0.000**). 짧아지는 것이
//       **한 픽셀도 안 보였다** — 「바뀐 건지도 모르겠네」가 그 뜻이다.
//     · 잔상 세기가 `1-on` 이라 뱉기와 **정확히 역위상**이었다. 줄기 겹 수가
//       **2 ⇄ 4 로 아홉 번** 뒤집히고 잉크가 2.20M ⇄ 2.43M 로 널뛰었다 = 「깜빡깜빡」.
//   ⇒ **잔상 겹을 걷어냈다.** 잔상은 **좌우로 휠 때** 필요한 것이고 그건
//     [PZbEnv] 가 위상을 실어 **혼자** 낸다 — **끝맺음의 수단이 아니다.**
//     둘을 섞은 것이 이 사고의 전부다.
//   ⚠️ 꼭짓점 상한은 **원인이 아니었다** — 이 칸의 최대 요구가 프레임당
//     **10,117 점**(경로 점 · 원 하나를 32각형으로 셈)이고 캔버스 2D 에는
//     상한이 없다. 8,192 는 엔진 쪽 `lib/render/vertex_batch.dart` 의
//     `kVertexCap` 이고 2026-08-22 에 32,768 로 올랐다. 289프레임 · 4801점
//     둘 다 **예외 0** 이라 조용히 사라진 것도 없다.
// ══════════════════════════════════════════════════════════════════════════

/// 끝맺음이 차지하는 시간 — 분사 3.0 중 **뒤 1.00초**.
const PZbFADE=1.00;
/// ⭐ 그 중 **앞 62%(0.62초)는 안 끊는다 — 길이만 준다.**
///   ⚠️ 앞에서부터 끊으면 그것이 곧 깜빡임이다. 끊는 것은 **뒤 38%(팅팅)뿐**이다.
const PZbSPUT=.62;
/// 제일 짧을 때의 길이 몫 — 78 × .15 = **11.6px**. 「구멍 앞에서 툭툭」.
const PZbLMIN=.15;
/// 분출이 **차오르는** 시간(초) — 길이가 [PZbLMIN] 에서 1 로 간다.
const PZbFILL=.28;
/// ⭐ **팅팅** — [시작, 길이, 세기]. 팅팅 구간 안의 자리(0 → 1)다.
///   첫 토막은 **잦아들던 분사가 끊기는 것**이고 뒤 셋이 **뽁 · 뽁 · 뽁**이다.
///   세기 1.00 → .60 → .38 → .20 · 사이 빈틈은 셋 다 **.10**(38ms)
/// ⚠️⚠️ **토막이 짧으면 그것이 도로 깜빡임이다.** 팅팅 구간이 0.38초뿐이라
///   토막을 다섯으로 쪼갰더니 뒤 둘이 **60fps 로 두 프레임**밖에 안 됐다
///   (30ms). 두 프레임짜리는 「뽁」이 아니라 **한 번 번쩍**이다. ⇒ 넷으로
///   줄이고 토막을 **61~76ms(4프레임 안팎)** 로 늘렸다 — 빈틈도 38ms 라
///   **비었다는 것이 보인다.**
/// ⚠️ **빈틈은 정말 빈다.** 아래 방울(⑥)이 그 자리에 남지만 실측으로 칸 전체
///   밝기가 몸·적이 움직이는 폭 안에 들어(빈틈 825k~859k · 완전 무음 805k~894k)
///   **메워 주지 않는다.** 그래도 좋다 — 「팅팅」은 끊기는 것이라 빈틈이 그 말이다.
/// ⚠️ 마지막 토막이 **정확히 1 에서 끝난다**(.84+.16) — 그 뒤로는 아무것도 없다.
/// ⚠️⚠️ 난수가 아니라 **표**라 매 주기 똑같이 재생된다(`Math.random` 을 쓰면
///   주기 끝과 처음이 안 맞아 이음매가 튄다 — 네 번 반려당한 자리다).
const PZbPOP=[[0,.20,1.00],[.30,.18,.60],[.58,.16,.38],[.84,.16,.20]];
const PZbLEN=78, PZbHALF=.30;
// ⭐ **지속을 늘렸다**(사용자: 「지속시간 더 길게」) 1.6 → **3.0초**.
//   ⚠️ 멈춤·쿨도 같이 봐야 「끊긴다」가 산다 — 지속만 늘리면 **사건이 상태**가 된다.
//     분사 **3.0** : 멈춤 **0.9** : 쿨 **0.9** = 주기 **4.8초** · 분사 몫 **62%**
//     (전: 1.6 : 0.7 : 1.0 = 3.3초 · 48%). 끊기는 1.8초가 그대로 남아 있다.
const PZbSPRAY=3.0, PZbHOLD=.9, PZbCOOL=.9;    // 분사 · 남음 · 쿨

/// ⭐⭐ **가스 수류탄 — 「빛으로 만들어진 작은 구」**
///
/// 사용자: 「독폭탄의 디자인은 좀 **세련되게** 못 바꿔? **'빛으로 만들어진 구 형태'**」
///   → 크게 만들었더니 「왜 갑자기 저렇게 엉망이 됐어 **원래 빛으로 만든 작은 구
///   형태 디자인 괜찮았잖아**」
/// ⚠️⚠️ **망가뜨린 것은 모양이 아니라 크기였다.** ×6(반지름 54)이 원인이고,
///   되돌린 것은 **크기뿐**이다 — 디자인은 이 「빛의 구」가 맞다.
///   ⭐ 말의 무게가 **「작은」**에 있다. 손그림에서도 수류탄이 작고 **줄기가
///     주인공**이었다 — 구가 줄기에 좀 묻히는 것이 **원래 비**다.
///
/// ⚠️⚠️ **이 저장소에 이미 그 물건이 있다** — 공전(`orbit`)의 구슬이다. 사용자가
///   「주변을 도는 동그라미를 **3D 구 형태로**」라고 해서 채택된 그 수법이고,
///   **같은 요청의 같은 답**이라 새로 만들 이유가 없다.
///   ⇒ `vfx.js` 의 [LX3arcs]·[LX3ball] 을 **그대로 부른다.** 사본도 수정도 안 한다.
///   자오선 + 실루엣 테두리로 **속을 안 칠하고 선으로 부피**를 낸다(엔진판
///   `glow.dart` 의 `glowBall` 이 216삼각형으로 싼 이유가 그것이다).
/// ⚠️ 공전 구슬과 갈리는 자리: 저쪽은 **몸 둘레를 돌고 작고 여럿**, 이쪽은
///   **자리에 놓이고 하나**이며 **구멍에서 가스를 뿜는다**.
/// ⚠️ 색 — 구는 `TONE.toxin` 의 **앞날 #E6FFEA(130° L95)** 로 그어 「빛」이고,
///   구멍과 그 둘레만 **#123D1C(134° L16)** 로 짙다.
function PZbomb(c,x,y,r,t,on,SC){
  const rot=0;
  const O=LX3arcs(x,y,r,t*.42);
  gAdd(c,g=>{
    LX3ball(g,O,x,y,r,PZTOX,.80,-1);          // 뒤 반달 — 어둡게
    gHalo(g,x,y,r*.95,PZTOX,.50);             // **속이 밝다**
    LX3ball(g,O,x,y,r,PZTOX,1.00,0);          // 실루엣 테두리 — 「이건 공이다」
    LX3ball(g,O,x,y,r,PZTOX,.95,1);});        // 앞 반달 — 밝게
  // 구멍 둘 — 「흰 점」이 아니라 **빛이 새어 나오는 자리**다.
  const TX=toneOf(PZTOX);
  for(const a of[PZbA1,PZbA2]){
    const ang=FCDIR+a+rot,hx=x+Math.cos(ang)*r*.70,hy=y+Math.sin(ang)*r*.70*LX3SQ;
    fillPoly(c,PKrag(hx,hy,r*.30,a*7.3,7,.26,ang),A(TX[0],.95));   // 짙은 테
    gAdd(c,g=>{
      gHalo(g,hx,hy,r*(.55+.55*on),PZTOX,.35+.55*on);
      if(on>.02)gLance(g,hx,hy,ang,r*(.30+.30*on),r*.16,PZTOX,.85*on);});}
  void SC;}

/// 구멍 하나의 자리.
const PZbHole=(x,y,r,a,t)=>{const ang=FCDIR+a+PZbSWING(t);
  return[x+Math.cos(ang)*r*.70,y+Math.sin(ang)*r*.70*LX3SQ,ang];};

function PZgasBomb(c,t,dt,W,H,st,E){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,FCCONE_F);stepFoes(st.F,dt);
  const LEN=PZbLEN*SC,HALF=PZbHALF;
  // 수류탄 — 몸에서 떨어진 **고정된 자리**에 놓인다(놓는 물건이라 안 따라다닌다).
  // ⚠️ 첫 렌더에서 수류탄을 너무 높이 놓아 **줄기가 칸 밖으로 나갔다.**
  //   칸 반너비가 119 인데 구멍에서 78 이 더 가므로, 수류탄은 몸에서
  //   **위로 30 · 옆으로 21** 자리라야 둘 다 안에 든다.
  const bx=cx+PZbDIST*SC*.57,by=cy-PZbDIST*SC*.82,br=PZbRAD*SC;  // 옆 21 · 위 30
  const PER=PZbSPRAY+PZbHOLD+PZbCOOL,u=t%PER;   // 초 단위
  // ⭐ **박자** — 분사 → 멈춤 → 쿨. 이 셋이 이 스킬의 정체다.
  // ⭐⭐ **끝맺음은 길이 하나로 말한다** (2026-08-23 사용자: 「**크고 길게 나가던
  //   게 점점 짧아지면서** 마지막에 **아주 조금 팅팅** 나오다가 **멈춰야** 함」).
  //   그린 순서가 곧 사용자가 그린 순서다:
  //     크고 길게 → **점점 짧아진다** → 아주 조금 **팅팅** → **멈춘다** → 쉰다 → 다시
  //   ⚠️ 줄일 것은 **그린 것의 알파**가 아니라 **뻗는 거리**다. 페이드아웃은
  //     「사라진다」고 잦아듦은 「**멀리 못 간다**」다.
  //   ⚠️⚠️ **잦아듦 앞쪽에서는 안 끊는다** — 끊는 것은 맨 마지막 **팅팅**뿐이다.
  //     앞에서부터 끊으면 그것이 곧 「깜빡깜빡」이다(앞 판이 그래서 반려됐다).
  //   ⚠️⚠️ **잔상을 안 남긴다.** 위 [PZbPOP] 절에 실측이 있다 — 길이를 안 줄인
  //     잔상 겹이 잦아듦 내내 77.345px 를 붙들어 **짧아지는 것을 통째로 가렸다.**
  // ⚠️⚠️ **끝·멈춤·다시 켜짐이 한 스케줄에서 나온다** — 따로 만들면 이음매가
  //   튄다(같은 원인으로 네 번 반려당했다). 아래 둘이 전부 `u` 하나에서 나온다.
  const rel=Math.min(1,Math.max(0,(u-(PZbSPRAY-PZbFADE))/PZbFADE));   // 0 → 1
  const S3=x=>x*x*(3-2*x);              // 매끈한 계단 — 시작·끝에서 기울기가 0
  // ⭐⭐ **길이가 주인공이다.** 한 함수가 주기 전체를 덮는다 —
  //   차오름(0 → .28초) · 꽉 참 · 잦아듦(2.0 → 3.0초) · 멈춤·쿨(그대로 [PZbLMIN]).
  //   ⚠️ **이음매 검산**: `u=0` 도 `u=PER⁻` 도 값이 [PZbLMIN] 이라 **정확히 맞물린다.**
  //     (그 두 자리에서는 [on] 이 0 이라 아무것도 안 그려지기도 한다 — 이중 안전.)
  const lenK=u<PZbSPRAY-PZbFADE
    ?PZbLMIN+(1-PZbLMIN)*S3(Math.min(1,u/PZbFILL))
    :1-(1-PZbLMIN)*S3(rel);
  // ⭐ **세기** — 잦아듦 앞쪽에서는 **1 그대로**다. 길이만 준다.
  //   ⚠️ 점화 램프(0 → .20초)도 같은 식에서 나온다 — 주기가 도는 순간 0 → 1 로
  //     튀면 그 자리가 이음매가 된다.
  let on;
  if(u>=PZbSPRAY)on=0;                                  // **완전히 멈춘다**
  else if(rel<PZbSPUT)on=Math.min(1,u/.20);             // 점화 → 1 → 그대로 1
  else{
    const s=(rel-PZbSPUT)/(1-PZbSPUT);                  // 팅팅 안의 자리 0 → 1
    // 첫 토막은 **이어지던 분사가 끊기는 것**이라 1 에서 시작해 내려간다.
    //   ⚠️ [S3] 로 내린다 — 코사인은 **끝에서 기울기가 안 죽어** 토막이 잘린
    //     자국을 남긴다. 여기는 이어지던 것이 잦아드는 자리라 양끝이 다 평평해야 한다.
    on=s<PZbPOP[0][1]?S3(1-s/PZbPOP[0][1]):0;
    // 나머지는 **뽁, 뽁** — `sin²` 이라 시작·끝에서 기울기가 0 이다.
    //   ⚠️ `sin` 그대로면 토막이 **켜지는 순간** 기울기가 최대라 그 한 점이
    //     「깜빡」으로 읽힌다. 팅팅은 끊기는 것이지 튀는 것이 아니다.
    for(let k=1;k<PZbPOP.length;k++){
      const[s0,du,pw]=PZbPOP[k];
      if(s>=s0&&s<s0+du){const w=Math.sin(Math.PI*(s-s0)/du);
        on=Math.max(on,w*w*pw);}}}
  // 판정 — 구멍 둘의 원뿔. ⚠️ 넉백 없음 · 틱 느림.
  st.tk=(st.tk||0)+dt;
  if(on>0&&st.tk>.30){st.tk=0;
    for(const f of st.F)for(const a of[PZbA1,PZbA2]){
      const H0=PZbHole(bx,by,br,a,t);
      const dx=cx+f.ox-H0[0],dy=cy+f.oy-H0[1],d=Math.hypot(dx,dy)||1;
      if(d>=LEN+f.r)continue;
      let ad=Math.atan2(dy,dx)-H0[2];
      while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
      if(Math.abs(ad)>HALF+.16)continue;
      f.pv=Math.min(3,(f.pv||0)+.72);break;}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.42;
  stepP(st,dt);
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);

  const ST=PKCOL.verd,R=PKtoFire(ST);
  const NL=PKFNL[LV-1],NB=PKFNB[LV-1];
  // ⓐ **줄기 둘** — 구멍마다 하나. 녹염을 그대로 부르고 **진폭만** 키웠다.
  //   ⚠️⚠️ **겹은 이것 하나뿐이다.** 잔상 겹을 걷어냈다(위 [PZbPOP] 절의 실측).
  //     좌우로 휘며 남는 자취는 [PZbEnv] 가 **위상을 실어** 혼자 낸다 — 덩어리가
  //     태어난 각도를 간직한 채 흘러가므로 지나간 S자가 공중에 걸린다.
  //     그 잔상과 **끝맺음의 잔상은 다른 물건**이고, 섞은 것이 깜빡임이었다.
  // ⭐ **짧아지면 덜 휜다** — 멀리 못 가니 굽이도 작다.
  //   ⚠️ 개수(`NB`)는 **안 줄인다** — 정수라 줄이면 값이 **계단**으로 튄다.
  //   ⚠️⚠️ 진폭 배수를 **길이와 같은 스케줄**([lenK])에서 뽑는다. 따로 두면
  //     이음매가 갈라진다. 꽉 찬 동안 `lenK=1` 이라 배수가 정확히 **1** —
  //     **확정값 진폭 2.00 이 한 글자도 안 바뀐다.**
  const ampK=.18+.82*lenK;
  const Ef={hw:E.hw,lat:(uu,tt,HLv)=>E.lat(uu,tt,HLv)*ampK,lanes:1};
  for(const a of[PZbA1,PZbA2]){
    if(on>.002){
      const H0=PZbHole(bx,by,br,a,t);
      PKflameLane(c,t,H0[0],H0[1],SC,LEN*lenK,HALF,R,ST,Ef,H0[2],.21,NL,NB,5.0,on,.15);}}
  // ⑥ **마지막 한 방울** — 못 뿜고 구멍에서 새어 **아래로 처진다.**
  //   ⚠️ **옅다.** 빈틈을 메우지는 못한다(위 [PZbPOP] 절의 실측). 이것이 하는 일은
  //     「다 썼다」를 구멍에서 한 번 말하는 것뿐이다.
  //   ⚠️ 팅팅이 끝나는 자리(`rel=1`)에서 **정확히 0** 이라 멈춤 구간엔 아무것도
  //     안 남는다 — 사용자: 「**멈춘다** — 완전히. 어중간하게 남기지 마라」.
  {const sp=(rel-PZbSPUT)/(1-PZbSPUT);
   const dr=rel>PZbSPUT?Math.sin(Math.PI*sp):0;
   if(dr>.01){const TXd=toneOf(PZTOX);
     for(const a of[PZbA1,PZbA2]){
       const H0=PZbHole(bx,by,br,a,t);
       for(let k=0;k<3;k++){
         const q=k/3;
         const rr=br*(.42-.10*k)*dr;
         if(rr<=.3)continue;
         fillPoly(c,PKrag(H0[0],H0[1]+br*(.6+2.2*q)*dr,rr,a*5.1+k,9,.32,a+t*.5),
           A(TXd[k?0:1],(.55-.14*k)*dr));}}}}
  // ⓑ **수류탄** — 줄기 위에 얹는다(구멍이 보여야 근원이 읽힌다).
  PZbomb(c,bx,by,br,t,on,SC);
  drawP(c,st);hero(c,t,cx,cy);}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 독가스 **복제본** — 밀도(빈 공간)를 **세기의 함수로**      (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독가스 수류탄 아주 훌륭한데, **이걸 유지한 채로 하나 더** 만들어 보자
//   (브랜치 따듯이). 복제본 하나 만들고 — 독가스라고 하면 분출을 하고 거기에
//   **가스의 잔상이 남듯이 독의 흔적들이 남고**, 세기가 약해지면 (지금은 분출할 때
//   **빽빽하게 빈 공간도 없이** 분출되는데) **분출 시작과 분출 종료 즈음에는
//   빈 공간이 듬성듬성** 있으면서 **발사하는 순간 공간이 꽉 메꿔지면서** 다시
//   **분출 종료될 때 화력이 약해지며 지금처럼 사그라드는** 식으로」
//
// ⚠️⚠️ **확정본을 한 글자도 안 고친다.** 위 [PZgasBomb]·[PZbomb]·`PZb*` 상수는
//   전부 **읽기만** 한다. 이 절이 더하는 것은 `PZq*` 뿐이고, 확정본은 이 절이
//   없어도 그대로 돈다(같은 파일에 두 판이 나란히 선다 — 「브랜치 따듯이」).
//   ⇒ 값(구 9 · 거리 37 · 구멍 88° · 진폭 2.00 · 왕복 2.40 · 박자 3.0/0.9/0.9 ·
//     끝맺음 `PZbFADE`·`PZbSPUT`·`PZbLMIN`·`PZbFILL`·`PZbPOP`)은 **물려받는다.**
//
// ── ⭐ 더하는 것은 **채널 하나**다 ────────────────────────────────────────
// 확정본은 세기를 **길이 하나로만** 말한다(77.3 → 11.6px). 그래서 줄기가 짧아지기
// **전에는** 힘이 빠지는 것이 안 읽힌다. ⇒ **밀도**를 둘째 채널로 깐다.
//
// ⚠️⚠️ **새 스케줄을 안 짠다.** 밀도는 이미 있는 길이 스케줄([lenK])에서 **압력**을
//   뽑아 그 함수로 깐다 — 따로 짜면 이음매가 하나 더 생긴다(이 저장소가 같은
//   원인으로 네 번 반려당했다).
//       P    = (lenK − PZbLMIN)/(1 − PZbLMIN)      압력 0 → 1 → 1 → 0
//       D    = P^PZqPOW                            밀도(길이보다 **늦게** 찬다)
//   `lenK(0) = lenK(PER⁻) = PZbLMIN` 이므로 `P` 도 `D` 도 **이음매에서 정확히 0** 이다.
//
// ── ⛔⛔ **「성기다」를 「투명하다」로 구현하면 안 된다** (2026-08-23 반려) ──
//   사용자: 「시작할 때 이렇게 **면이 엿가락 나오듯이 길게 나오는 형태가 아니라니까**
//   · **연하게 해서 투명하게 한다고 해결되는 게 아니라고** · **구멍을 만들라니까**
//   누가 **얇게 해서 투명하게 해 가지고 뒤에가 보이게** 만들어. 심지어 **네모난
//   실크천 같은 게 펄럭거리게** 만들어 놨네 · **물리학처럼 생각해 봐**」
//
//   ⚠️⚠️ 앞 판은 **같은 면을 알파만 낮췄다.** 그것은 「옅다」이지 「성기다」가 아니다.
//     반투명은 구멍이 아니라 **얇은 막**이고, 막이 있으면 그게 곧 **실크천**이다.
//       ❌ 뒤가 **비쳐 보인다**  ⇒ 막
//       ✅ 그 자리에 **아무것도 없다** ⇒ 구멍
//   ⭐⭐ **구멍 = 아무것도 안 칠한 자리다.** 그래서 이 판은 알파를 **한 군데도**
//     안 낮춘다 — 칠할 자리를 **오려낸다**([PZqMaskPath] · `c.clip`).
//
// ── ⭐ 물리로 읽는다 — 판은 「켜는」 것이 아니라 **겹쳐서 생기는** 것이다 ──
//   압력이 낮으면 **이어진 판이 아예 안 생긴다.** 노즐에서 덩어리가 뚝뚝 떨어져
//   나올 뿐이다. 판은 그 덩어리들이 **충분히 겹칠 때** 비로소 생긴다.
//       낮은 압력   ●   ●      ●        ← 판이 없다. 있지도 않다
//       중간        ●●  ●●●  ●●        ← 개수가 늘고 간격이 좁아진다
//       절정        ████████            ← 겹쳐서 이어진 판 = **확정본 그 그림**
//   ⇒ 밀도가 하는 일 넷 — **넷 다 「있다/없다」이지 「진하다/옅다」가 아니다**:
//     ① **판이 알갱이의 합집합 안에서만 존재한다** — 밖은 **안 칠한다**([PZqMaskPath])
//     ② **덩어리는 문턱을 넘어야 켜지고, 물러설 때 「작아져서」 물러선다**
//        ⚠️ 알파로 물러서면 그게 막이다. 그래서 문턱은 **반지름**에 먹인다
//     ③ **성길수록 덩어리가 작다** — 「뭉쳐서 커진다」의 뒤집음([PZqSMALL])
//     ④ **제트도 같은 마스크 안에서만 그린다** — 압력이 없으면 「입구 쪽 얇고
//        긴 것」이 **없다**(알파를 낮추는 것이 아니다)
//   ⚠️ **`cone()`·`hw` 는 한 글자도 안 건드린다** — 실루엣의 뼈대다(폭을 줄이면
//     「1자 스티커」가 된다). 잘리는 것은 **폭이 아니라 「그려지는 자리」**다.
//   ⚠️ `cone()` 은 `u=1` 에서 좌우를 직선으로 닫아 **평평한 끝**을 만든다. 확정본은
//     덩어리가 그 자리를 덮어 안 보이는데, **판만 남고 덩어리가 옅어지면 그 직선이
//     드러난다**(화염방사가 같은 이유로 반려당했다). ⇒ 마스크 조각을 **너덜너덜한
//     다각형**([PKrag])으로 오려 직선이 애초에 안 생기게 한다.
//
// ── ⚠️⚠️ 「듬성듬성」과 「깜빡임」은 종이 한 장 차이다 ────────────────────
//   바로 앞 판이 정확히 이것으로 반려당했다(사용자: 「잔상을 먼저 남기고
//   **깜빡깜빡거리니까** 바뀐 건지도 모르겠네」). 실측된 원인 둘:
//     · 잔상이 길이를 **한 번도 안 줄여** 1.0초 내내 77.3px 고정
//     · 잔상 세기가 `1−on` 이라 **역위상** ⇒ 겹 수가 2 ⇄ 4 로 아홉 번 뒤집힘
//   ⇒ 가르는 것은 하나다:
//       ❌ 깜빡임  — 빈 자리가 **프레임마다 바뀐다**
//       ✅ 성긴 것 — 덩어리가 **제 자리를 간직한 채 흘러간다**
//   ⇒ **잔상 좌표계를 고친 그 수법을 밀도에도 그대로 쓴다.** 덩어리가 보는 밀도는
//     **제가 태어난 시각**의 것이고([PZqLAG]), 문턱은 **제 씨앗**([sd])에서 나온다.
//     둘 다 프레임마다 다시 굴리지 않는다. ⇒ 무늬는 성기되 **자리는 안 튄다.**
//   ⚠️ `Math.random` **0건**. 들쭉날쭉은 전부 [hash] 표에서 파생된다.
//
// ── ⭐ 밀도도 **아래에서 위로 번져 올라간다** ────────────────────────────
//   압력을 올려도 줄기 **끝**이 곧바로 차지는 않는다 — 앞면이 타고 올라간다.
//   그래서 그 자리의 밀도는 **그 자리의 가스가 태어난 시각**의 것이다:
//       Dfront(u,t) = D( t − ph(u)·PZqLAG )
//   ⚠️ `PZqLAG` 는 물질이 가는 시간([PZbT]=1.18)이 아니라 **압력 앞면**이 가는
//     시간이다(압력파가 흐름보다 빠르다). 1.18 로 두면 차오르는 데만 분사의
//     39% 가 들어가 「한창」이 0.54초밖에 안 남는다.
//   ⇒ 그리는 밀도는 **둘 중 작은 것**이다:
//       Deff = min( D(t) , Dfront(u,t) )
//     · 차오를 때  D(t) 는 이미 1 인데 앞면이 아직 안 왔다 ⇒ **끝이 성기다**
//     · 사그라들 때 앞면은 아직 1 인데 D(t) 가 죽었다   ⇒ **통째로 성기다**
//     한 식이 **양 끝을 다** 낸다 — 이것이 「새 스케줄을 안 짠다」의 뜻이다.

/// 압력 → 밀도. 1 보다 크면 밀도가 길이보다 **늦게 찬다**(시작이 성기다).
const PZqPOW    = 2.00;
/// 밀도 앞면이 줄기를 타고 오르는 시간(초). ⚠️ 물질 속도([PZbT])가 아니다.
const PZqLAG    = .62;
/// ⭐⭐ **그려지는 밀도의 바닥.** ⚠️ 이것이 없으면 `D→0` 에서 판·덩어리·제트가
///   **한꺼번에** 죽어 사용자가 지킨 끝맺음(「아주 조금 팅팅」)까지 지워진다
///   (실측: 바닥 없이 팅팅 2.95초 잉크가 확정본의 **9.5%**).
///   ⚠️ 흔적([PZqTrace])은 이 바닥을 **안 쓴다** — 거긴 0 이 되어야 무음이 산다.
const PZqDMIN   = .12;
/// ⭐⭐ **알갱이 격자** — 이어진 판이 「존재하는 자리」다. 축을 따라 [PZqMNB] 칸,
///   가로로 [PZqMNL] 줄. 알갱이 하나하나가 사용자가 그림에 동그라미 친 그것이고,
///   압력이 차면 **서로 겹쳐 저절로 판이 된다**(판을 따로 켜는 것이 아니다).
/// ⚠️ 자리는 **격자에 못 박혀 있다** — 흘러가지 않는다. 정상 분사의 밀도장은
///   갈래 좌표계에서 **가만히 있고**(가스가 그 사이를 지나간다), 흘러가는 것은
///   덩어리·불티다. 자리가 안 움직이니 **깜빡일 수가 없다.**
const PZqMNL    = 5, PZqMNB = 14;
/// ⭐⭐ **판은 물방울보다 늦게 생긴다.** 압력이 어중간하면 가스는 **잘게 흩어지지**
///   이어진 면을 못 만든다(분무의 문턱이 응집의 문턱보다 낮다). 이 지수가 없으면
///   압력 53% 에서 벌써 총구 쪽이 통짜 쐐기로 서서 **「엿가락」**이 된다.
/// ⚠️ 밀도 1 에서는 `1^k = 1` 이라 절정의 그림에 **아무 영향이 없다.**
const PZqMPOW   = 2.60;
/// 알갱이가 덮는 가로 몫 — `cone(1.10)` 에 흔들림 ±10% 까지 문다.
const PZqMWID   = 1.26;
/// 덮기 반지름 배수. 격자 대각선의 절반이 1.00 이고, **다 자란** 알갱이의
/// 너덜거림(±[PZqMRAG]·.45)이 내접원을 0.726 배까지 깎으므로 그 역수(1.38)에
/// 여유를 얹었다. ⚠️ **이 값이 모자라면 절정에서 확정본과 안 같아진다**
/// (검산: 알갱이를 전부 다 키운 채 원뿔을 무는지 래스터로 세어 확인한다).
const PZqMR     = 1.74;
/// ⭐ 알갱이 가장자리의 **너덜거림** — 압력이 낮을수록 심하고, 다 자라면(`g=1`)
///   `.45` 배로 잦아들어 이웃과 **매끈하게 이어진다**(그래야 합집합이 원뿔을 문다).
/// ⚠️ 덮기는 `g=1` 에서만 따지므로 **성길 때는 마음껏 뾰족해도** 절정이 안 흔들린다 —
///   사용자가 그림에 동그라미 친 것이 「밝은 초록 **뾰족한** 덩어리」였다.
const PZqMRAG   = .40;
/// 알갱이 문턱의 최대치와 넘는 폭. ⚠️⚠️ **합이 정확히 1** 이라야 밀도 1 에서
///   알갱이가 하나도 안 빠져 **합집합이 원뿔을 통째로 덮는다** = 확정본 그대로.
const PZqMTHR   = .72, PZqMRAMP = .28;
/// 덩어리 문턱의 최대치와 넘는 폭. ⚠️⚠️ **둘의 합이 정확히 1** 이라야
///   밀도 1 에서 **덩어리가 하나도 안 빠진다**(= 확정본과 같은 그림).
const PZqTHR    = .82, PZqRAMP = .18;
/// ⭐⭐ **밀도 바닥에서 덩어리가 갖는 반지름 몫** — 밀도 1 에서 정확히 **1**(확정본).
/// ⚠️⚠️ **앞 판은 이 부호가 거꾸로였다**(성기면 커지게 했다). 사용자가 못 박았다:
///   「둥글고 뾰족한 걸 **사이즈를 줄여서** (**뭉쳐서 입자가 커지는 형태**니까)」
///   ⇒ 물리 모델이 「압력이 낮아 잘게 안 부서진다」가 아니라 **「나오면서 서로
///     뭉쳐 커진다」**다. 그래서 **막 나올 때가 제일 작다.**
const PZqSMALL  = .58;
/// ⭐ **독의 흔적** — 수 · 수명(초) · 알파 · 꺼지는 폭.
/// ⚠️ 흔적도 **또렷한 덩어리**다. 앞 판은 [PZsoft](풀리는 그러데이션)로 그려
///   낮은 알파가 넓은 면적을 덮었고 — 그것이 곧 **막**이다. 걷어냈다.
const PZqNT     = 7, PZqTLIFE = 1.30, PZqTRA = .74, PZqTOFF = .22;

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **머무는 안개** — 가스가 지나간 자리에 고여 남았다 걷힌다  (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「수류탄 쪽은 확정이고, 이제 여기에 **추가로** — 가스가 **흩뿌려진 곳에
//   뿌연 연무가 1~3초 정도 남고 사라지게** 해줘」
//   → 「독가스 뿌리고 남은 잔상을 좀 더 **강하게**」 → 「**안개처럼**」
//
// ── ⭐⭐ 「강하게」의 뜻은 **진하기가 아니라 질감**이었다 ────────────────
//   ❌ 알갱이 : 뭉치 몇 개가 **낱낱이** 보인다 · 셀 수 있다 · 자리마다 알파가 튄다
//   ✅ 안개   : **경계가 없다**(어디서 시작하고 끝나는지 모른다) · 셀 것이 없다 ·
//              **고르게** 깔린다 · **느리게** 굼실댄다 · 뒤가 **뿌옇게 흐려진다**
//   ⭐⭐ **안개의 정체는 「많은 것이 겹쳐 개별성을 잃은 것」이다.**
//     ⇒ 조각을 **진하게** 만들면 「진한 알갱이」지 안개가 아니다.
//     ⇒ **개수를 늘리고 하나하나는 옅게** 둔다. 진하기는 **겹침**이 낸다.
//   ⚠️ 이것은 분사에서 배운 것의 **반대편**이다 — 분사는 「성기다 = 겹침비 < 1 ⇒
//     낱낱이 보인다」였다([PZqMaskPath]). 안개는 **같은 자를 반대로** 쓴 것이다.
//
// ── ⭐ 뿌옇다 = 「경계가 흐리다」 ─────────────────────────────────────────
//   ⚠️ 이 사이클의 반려 하나가 「**연하게 해서 투명하게** 한다고 해결되는 게
//     아니라고 · 네모난 **실크천**」이었다. 그건 **또렷한 다각형에 알파만 낮춘**
//     것이라 막이 됐다. 안개는 **반대**다 — 낮은 알파가 **맞고**, 대신 가장자리가
//     **풀려야** 한다. ⇒ [PKrag] 가 아니라 [PZsoft](밖으로 풀리는 그러데이션)다.
//   ⚠️ 가산이 아니다 — 겹쳐도 안 밝아진다(고인 안개는 스스로 안 빛난다).
//   ⚠️ **적 위에 깔린다** — 그래야 「뒤가 뿌옇게 흐려진다」가 실제로 일어난다.
//     다만 **줄기·수류탄 아래**다(아래 「끝맺음을 가리면 안 된다」).
//
// ── ⭐⭐ 자리에 **못 박힌다** — 이것이 제일 중요하다 ────────────────────
//   줄기는 좌우로 휜다([PZbEnv] 가 위상을 실어 낸다). 안개를 **갈래 좌표계의
//   지금 값**으로 잡으면 줄기가 휠 때 **같이 휘어** 「긴 리본」이 된다.
//   ⇒ 조각의 자리는 **태어난 시각 `tb` 하나에서만** 나온다:
//       lenK(tb) · lat(ud, tb) · ampK(tb)  ⇒ 전부 **상수**
//   ⚠️ 유일하게 움직이는 것이 **굼실거림**([PZqHDRF])인데, 방향·속도가 **씨앗에서
//     나온 상수**라 프레임마다 다시 안 굴린다 — 1.7px/초로 줄기가 훑는 속도의 2.5%다.
//   ⚠️ 흔적([PZqTrace])은 자리를 **지금 길이**의 몫으로 잡아 줄기가 짧아지면
//     같이 당겨진다 — 그건 「따라다니는 것이 맞는」 층이라 그렇다. 안개는 아니다.
//
// ── ⭐ 진하기 = **지나간 양의 함수** ─────────────────────────────────────
//   「가스가 짙게 지나간 자리일수록 진하게」 ⇒ 태어난 시각의 **밀도**를 그대로
//   쓴다. 이미 있는 식이라 **새 스케줄을 안 짠다**:
//       dep = min( D(tb) , D(tb − ph(ud)·PZqLAG) )      ← [PZqSched] · [PZqPH]
//   `D` 는 **날것**(바닥 [PZqDMIN] 을 안 쓴다)이라 무음에서 **정확히 0** 이다.
//
// ── ⚠️ 수명 · 이음매 ────────────────────────────────────────────────────
//   태어남이 **방사 안에 못 박힌 격자**에 있고([tb]) 나이가 `lu − tb` 라 조각의
//   자리·진하기가 **시간의 함수가 아니다.** 주기가 15초로 늘어난 뒤로는 마지막
//   조각이 걷히는 시각이 주기보다 한참 앞이라(보고의 실측 참조) 이음매에서
//   **아무것도 안 그려진다** ⇒ 도약이 구조적으로 0 이다.
//   ⚠️ 사용자가 「**공백 5초간 독이 비는 거 의도한 거임**」이라고 못 박았다 —
//     안개가 그 공백을 침범하면 안 된다. 실측으로 확인한다.
//
// ── ⚠️ 끝맺음을 **가리면 안 된다** ───────────────────────────────────────
//   길이가 77.3 → 11.6px 로 줄어드는 것이 이 스킬의 끝맺음이다. 안개는 「뒤를
//   흐리는」 물건이라 **여기가 제일 위험하다.** ⇒ ① **줄기 밑에 깐다**
//   ② 조각 하나의 알파가 [PZqHA]=.055 뿐이다 ③ 조각이 **봉투 밖으로** 흩어져
//   있어([PZqHSPR]) 줄기가 서 있는 자리를 통째로 안 덮는다.
// ══════════════════════════════════════════════════════════════════════════

/// ⭐⭐ **안개의 수명(초).** ⚠️ 아무 숫자가 아니다 — 줄기가 좌우로 **한 번 왕복하는
///   시간**([PZbCYC] · 확정값 2.40)과 **같은 값**이다. 「줄기가 한 번 훑고 지나가는
///   동안 안개가 산다」 ⇒ 새 숫자를 안 지었고 사용자가 준 **1~3초** 안이다.
const PZqHLIFE  = PZbCYC;                   // = 2.40
/// ⭐⭐ **구멍 하나가 한 방사에 낳는 조각 수.** ⚠️ 안개의 정체는 「많은 것이 겹쳐
///   **개별성을 잃은 것**」이다 — 조각을 진하게 만들면 「진한 알갱이」지 안개가 아니다.
///   ⇒ **개수를 늘리고 하나하나는 옅게** 둔다. 겹침비를 재서 맞췄다(보고 참조).
const PZqHN     = 40;
/// 태어나는 시각의 들쭉날쭉 — 칸의 ±45%. ⚠️ 난수가 아니라 [hash] 표다.
const PZqHJIT   = .90;
/// 나이 몫으로 본 **피어오름 · 걷힘**. 양끝에서 정확히 0 이라 뚝 안 끊긴다.
/// ⚠️ 걷힘이 **길다**(.72) — 안개는 「빨리 흩어지면 연기」다.
const PZqHRISE  = .18, PZqHFALL = .72;
/// ⭐⭐ **조각 하나의 알파.** ⚠️ **낮아야 한다.** 진하기는 **겹쳐서** 나온다 —
///   이 값을 올리는 순간 조각이 낱낱이 보이고 그 순간 안개가 아니다.
const PZqHA     = .055;
/// 걸리는 자리(길이 몫) — 총구 바로 앞은 비운다(거긴 늘 줄기가 서 있다).
const PZqHU0    = .18, PZqHUD = .74;
/// ⭐ **봉투 밖으로 흩어진 몫** — 「흩뿌려진 곳」이라 줄기가 지나간 폭보다 넓다.
const PZqHSPR   = .58;
/// ⭐ 조각 반지름 — 봉투 반폭의 몫 + 밑값. **중간 크기 여럿**이다(큰 반투명 하나보다
///   싸고, 겹치면 그쪽이 더 안개 같다).
const PZqHR0    = .54, PZqHRV = .48, PZqHRC = 6.5;
/// ⭐⭐ **크기가 하나면 그것이 곧 「알갱이 크기」다** — 안개에는 **고유 크기가 없다.**
///   ⇒ [PZqHBIG] 개마다 하나를 **크고 더 옅게** 섞는다. 큰 것이 사이를 메워
///   **바깥 경계를 지우고**, 작은 것이 그 위에 결을 준다(둘 다 [PZsoft] 라 선이 없다).
const PZqHBIG   = 5, PZqHBR = 2.45, PZqHBA = .40;
/// ⭐ 나이 들며 **퍼진다** — .66 → 1.42 배.
const PZqHG0    = .66, PZqHGR = .76;
/// ⭐ **아주 느린 굼실거림.** 조각마다 **제 방향**으로 이만큼(px/수명) 흐른다.
/// ⚠️ 방향·속도가 **씨앗에서 나온 상수**라 프레임마다 다시 안 굴린다(= 안 깜빡인다).
///   4.0px / 2.40초 = **1.7px/초** — 줄기가 훑는 속도(78px/1.18초 = 66px/초)의 **2.5%**.
const PZqHDRF   = 4.0;
/// 살짝 눌린다 — 「고여 있다」의 신호. ⚠️ 바닥이 아니다(우주다) — 뜬 채로 고인다.
const PZqHFLAT  = .86;
/// 색 사다리에서 뽑는 자리 — **앞쪽**이라 초록이다(뒤쪽은 숯빛 = 진흙).
const PZqHCOL   = .44;

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **성장표 — 사용자가 통째로 정했다**                        (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 원문: 「L1 수류탄 2개, 독갈래 2개(현재 시안) / L2 수류탄 2개, 독갈래 3개
//   (길이와 폭 약간 증가)(쿨타임 감소) / L3 수류탄 3개, 독갈래 3개 / L4 수류탄
//   4개, 독갈래 3개(길이와 폭 약간 증가) / L5 수류탄 5개, 독갈래 4개 · 전체적으로
//   L5 올라갈수록 **유지시간 조금씩 증가**, 유지시간 증가에 따른 **방사 횟수 증가**,
//   **사거리 조금씩 증가**(나중 5개가 되면 여기저기 던져야 되니까) ·
//   **시간초 어긋나지 않게 너가 맞춰줘야 할 듯**」
//
// ── ⭐⭐ 「시간초를 맞춘다」 = **유지를 한 식에서 파생시킨다** ──────────────
//       유지 = 방사 횟수 × (방사 길이 + 쉼) = 방사 횟수 × [PZqBOUT]   한 벌 = 6.00 고정
//   ⇒ L1 **12.00** · L2 **12.00** · L3 **18.00** · L4 **18.00** · L5 **24.00**
//   ⭐ 마지막 쉼의 **끝 1.20초**가 부들부들(1.00) + 펑(0.20)이다 — 따로 더한 것이
//     아니라 쉼 안에 든다. 그래서 「방사 → 쉼」이 **한 벌로 반복**되고 계단이 안 진다.
//     ⚠️ L5 의 쉼이 **0.50초**라 부들부들이 마지막 방사에 **1.20 − 0.50 = 0.70초**
//       물린다. 뿜으면서 떨기 시작하는 셈인데 **그래도 좋다** — 「곧 사라진다」가
//       분사가 완전히 끊긴 뒤에 오면 이미 늦다.
//   ⚠️ **유지가 방사 횟수(2·2·3·3·4) 하나에서 나온다** ⇒ L1=L2 · L3=L4 다. 그 두
//     칸의 성장은 **갈래·쿨·길이폭·사거리·뿜는 몫**이 낸다(한 축이 쉬고 다른 축이
//     자라는 것은 이 저장소의 꼴이다 — 서리결정 연타가 `5·7·9·9·11` 이다).
//
// ── ⭐⭐ 겹침은 **결함이 아니라 설계다** ─────────────────────────────────
//   L5 는 2초 간격으로 **셋**을 던져 마지막이 4.00초에 나가고 수명이 24.70 이라
//   **28.70초**에 사라진다. 그런데 쿨이 **11초**다 ⇒ 다음 시전이 앞 수류탄이
//   살아 있는 동안 시작된다. **「만렙이 되면 판이 늘 오염돼 있다」가 성장의 보상**이다.
//   ⇒ 그러므로 「공백이 완전히 비어야 한다」는 **L1·L2 에만** 해당한다.
//   ⭐ **쿨은 한 글자도 안 바꿨다**(15·14·13·12·11) — 수류탄이 `1·1·2·2·3` 으로
//     줄어 마지막 던지기가 앞당겨진 덕에 L1 공백이 **2.30초 그대로**다.
//
// ── ⚠️⚠️ 겹치면 **주기 하나로 안 닫힌다** — 구조로 푼다 ─────────────────
//   이 저장소가 이음매로 **네 번** 반려당했다. ⇒ **수류탄 하나하나가 「제 나이」를
//   갖는다.** 시전이 `k·쿨` 마다 일어나고, 그리는 시각 `u = t mod 쿨` 에서
//       나이(j번째 앞 시전 · i번째 수류탄) = `u + j·쿨 − i·간격`
//   을 **전부 훑어** 살아 있는 것만 그린다. `u → 쿨⁻` 에서의 나이가 `u=0` 에서의
//   `j+1` 짜리 나이와 **정확히 같으므로** 이음매가 **구조적으로** 이어진다.
//   ⇒ 겹침이 **저절로** 그려지고, 표시 주기는 **쿨 그대로**다(따로 안 늘린다).
//   ⭐ 2차 방사 잘림을 고친 것과 **같은 수법**이다 — 「제 시각을 갖게 한다」 하나.
//
// ── ⭐⭐ 갈래는 **사방으로** 간다 — 한 방향 부채가 아니다 ───────────────────
//   사용자: 「**한 방향 말고 5각으로 사방으로 뿌리는 식** … 갈래가 나눠지면
//     **앞뒤 · 3각 · 동서남북 · 5각** 이렇게 생각한 거야」
//   ⇒ [PZqAngs] 가 **360°를 갈래 수로 나눈다.** 앞 판은 확정본의 88° 부채 **안에**
//     고르게 벌렸고 그것이 반려됐다 — 「한 방향으로 몰려 있다」가 그 그림이었다.
//   ⚠️⚠️ **`n=2` 도 예외가 아니다** — 88° 는 이 판이 더는 안 쓴다. **앞뒤 180°**다.
//     (확정본 [PZgasBomb] 은 제 88° 를 그대로 쓴다 — 한 글자도 안 고쳤다.)
//
// ── ⚠️⚠️ 사방이 되면 **몸을 덮는 버그의 방어선이 하나로 준다** ──────────────
//   앞 사이클에 「**아래쪽으로 던졌을 때 캐릭터 뒤쪽으로 깔리는 버그**」를 두 겹으로
//   막았다: ① **층 순서**(가스를 몸보다 먼저) ② **자리를 전부 몸 위로**.
//   ⇒ 이제 갈래가 사방으로 나가므로 **자리가 몸 위여도 아래로 뻗는 갈래가 몸을
//     향한다.** ②가 무효가 되고 **①이 유일한 방어선**이다.
//   ⚠️ 그래도 **자리를 옮겨 피하지 않는다 — 사방이 설계다.** 대신 층 순서가 정말
//     충분한지 **실측**한다(가스 켠 렌더 ↔ 전부 끈 렌더의 몸 심 픽셀 대조).
//   ⇒ [PZqBomb] 의 그리는 차례가 그 증명이다: 안개 → 흔적 → 줄기 → 방울 → 수류탄
//     → **[drawP] → [hero]**. 몸이 **언제나 맨 마지막**이라 무엇도 그 위에 못 온다.
//
// ── ⭐ 「엉킴」의 기준 ───────────────────────────────────────────────────
//   각 간격이 기준이 아니다 — 줄기 하나가 끝에서 이미 **±49°**를 쓸고 지나간다
//   (반폭 25.7 + 흔들림 46.4 를 길이 77.3 으로 나눈 각). 즉 **확정본의 둘(88°
//   간격)도 이미 끝에서 겹친다.** 그것이 이 스킬의 그림이다.
//   ⇒ 사방으로 벌리면 이웃 간격이 **180°/120°/90°/72°** 라 **앞 판(44°·29.3°)보다
//     오히려 덜 엉킨다.** 5각(72°)만 ±49° 가 서로 물린다 — 그건 재서 보고한다.
//
// ── ⭐⭐ **크기 세 축이 전부 「두 끝 + 등비」다** ────────────────────────────
//   사용자가 세 번에 걸쳐 크기를 손봤다. 셋 다 **손으로 고른 수가 둘씩**이고
//   가운데는 [FLXHUSHN] 이 쓴 규칙(「두 끝만 정하고 가운데는 등비」)으로 채웠다.
//     ① **탐지 반경** 「**범위가 커서 사거리 엄청 늘려도 되겠다**」
//        두 끝 **111 → 그 2배 222** · ×2^(1/4)=1.1892 ⇒ 111·132·157·187·222
//        ⚠️ **던지는 거리가 아니다** — 아래 [PZqSense] 절을 반드시 읽어라.
//     ② **줄기 길이** 「**L1 때 방사하는 사거리를 좀 짧게** … 지금은 방사 길이가
//        너무 긴 거 같기도」 ⇒ **거리로 읽었다**(초가 아니다 — 초는 ④가 늘렸다).
//        두 끝 **L5 = 78**(확정본 그대로) → **그 절반 39** ⇒ 배수 .50·.59·.71·.84·1.00
//     ③ **쉼**(④의 짝) 두 끝 **2.50 → 그 1/5 인 0.50**
//   ⚠️ ②는 배수를 **길이에만** 건다 — 원뿔 각([PZbHALF]=.30)은 다섯 칸이 같다.
//     그래야 **모양이 안 변하고 크기만** 자란다(폭은 길이를 따라 저절로 자란다).
//     앞 판은 각까지 키워(`HALF*1.16`) L5 만 더 벌어졌었다.
//   ⇒ **L5 가 확정본과 같은 줄기**다(길이 78 · 각 .30 · 끝맺음 77.3→11.6px).
//     ⚠️ 다만 **각도는 갈린다** — 확정본은 88° 부채, 이 판은 **사방**이다.
//   ⭐ 성장이 한 문장으로 읽힌다: **L1 은 가까운 뭉텅이 하나에 작게, L5 는 멀리까지
//     찾아 뭉텅이 셋에 크게 사방으로.**
// ══════════════════════════════════════════════════════════════════════════

/// ⭐⭐ **성장표.** `[수류탄 수, 갈래 수, 방사 횟수, 쿨(초)]`
/// ⭐ 수류탄 **1·1·2·2·3** — 사용자 확정(「**11223 으로 가자**」).
/// ⭐ 갈래 **2·3·3·4·5** = **앞뒤 · 3각 · 3각 · 동서남북 · 5각** — 사용자가 말한
///   넷이 전부 쓰인다([PZqAngs]). 총 갈래(수류탄×갈래) = **2·3·6·8·15**.
/// ⭐⭐ 쿨 **18·17·16·15·14** — ⚠️ **사용자가 실기 판정으로 너프한 값**이다
///   (「**쿨타임 조금 더 길게 해줘도 될 듯? (너프) 생각보다 너무 센 듯**해」).
///   앞 값 15·14·13·12·11 을 **한 줄로 +3** 했다 — 기울기(레벨마다 −1)를 지키면서
///   전체를 밀어야 「쿨이 준다」는 성장축이 안 죽는다.
///   ⭐ 그 결과 **L1 공백이 5.30초**가 되어 사용자가 「의도한 것」이라고 못 박은
///     **5초**에 딱 선다. L3~L5 는 여전히 겹치므로 「만렙은 판이 안 빈다」도 산다.
///   ⚠️ **이식 담당에게**: 이 다섯은 **그림이 아니라 밸런스**다. 근거는 위 한 줄
///     (사용자 실기 판정)이고, 시안이 도는 박자가 이식의 출발점이다.
/// ⚠️⚠️ **방사 길이·탐지 반경은 표에 없다** — [PZqSpray]·[PZqSense] 가 만든다.
///   두 벌을 두면 반드시 갈라진다(이 저장소가 목록 둘로 이미 앓았다).
const PZqLV = [[1,2,2,18.0],
               [1,3,2,17.0],
               [2,3,3,16.0],
               [2,4,3,15.0],
               [3,5,4,14.0]];
/// ⭐⭐ **줄기 길이 배수** — 두 끝 **.50 → 1.00**(L5 가 확정본 78 그대로), 가운데는
/// **등비**(×2^(1/4)). ⚠️ **길이에만** 건다 — 원뿔 각은 다섯 칸이 같다(위 절 ②).
const PZqLWN = 2;
const PZqLW  = L=>Math.pow(PZqLWN,(L-4)/4);
// ── ⭐⭐ **넷째 성장축 — 뿜는 몫(가동률)** (2026-08-23 · 사용자) ─────────────
// 사용자: 「**L5 때 너무 짧게 분출하다가 꺼지네. 전체적인 유지시간을 늘려야 할 듯**」
//   ⚠️ 원인이 방사 길이 하나가 아니었다 — **쉼이 방사와 똑같아 뿜는 몫이 정확히
//     50%** 였다(방사 2.50 : 쉼 2.50). 뿜자마자 같은 길이만큼 쉬니 「꺼졌다」로 읽힌다.
//   ⇒ 손잡이가 둘이다: **방사를 늘리고 · 쉼을 줄인다.**
// ⭐⭐ **화염방사 ⑩ 과 같은 문법**이다 — 거기서 「주기를 못 박고 무음만 갈랐다」.
//   여기서는 **한 벌(방사+쉼)을 못 박고 그 안의 나눔만** 갈린다.
//   ⇒ 유지 = 방사 횟수 × 한 벌 이라 **유지가 방사 횟수 하나에서 나온다**(2·2·3·3·4).
// ⭐ **손으로 고른 수가 둘뿐이다** — 한 벌 **6.00** · L1 이 L5 의 **5배**를 쉰다.
//   가운데 셋은 손이 아니라 **등비**(×5^(−1/4) = 0.6687)로 채웠다:
//     쉼   2.500 → 1.672 → 1.118 → 0.748 → 0.500
//     방사 3.500 → 4.328 → 4.882 → 5.252 → 5.500
//     몫   58.3% → 72.1% → 81.4% → 87.5% → **91.7%**
// ⚠️ **L5 도 0 은 아니다.** 화염방사 L5 는 「안 꺼짐」이 각성이지만 독가스는
//   **방사 횟수가 이미 성장축**이라 쉼이 0 이면 그 축이 통째로 사라진다.
/// ⭐⭐ **한 벌**(방사 + 쉼)의 길이(초) — 다섯 칸이 **같다.**
const PZqBOUT  = 6.00;
/// L1 의 **쉼**(초). ⚠️ 앞 판의 고정 쉼과 같은 값이라 **L1 은 쉼이 안 바뀌었다.**
const PZqREST1 = 2.50;
/// ⭐⭐ **L1 이 L5 의 몇 배를 쉬나** — 이 축의 **유일한 새 비**다.
const PZqRESTN = 5;
/// 그 칸의 **쉼**(초) — 표가 아니라 **등비 한 줄**이다.
const PZqRest  = L=>PZqREST1*Math.pow(PZqRESTN,-L/4);
/// 그 칸의 **방사 길이**(초) = 한 벌 − 쉼. ⚠️ 둘의 합이 언제나 [PZqBOUT] 이라
/// 「방사 → 쉼」 한 벌이 **레벨과 무관하게 같은 박자**로 반복된다.
const PZqSpray = L=>PZqBOUT-PZqRest(L);
/// 던지는 간격(초) — **사용자 확정**(「1개 던지면 **2초 뒤** 던질 수 있음 ·
/// **연속해서 한 자리에 던지는 거 방지**」) ⇒ 2초는 **자리가 갈리기 위한 시간**이다.
const PZqGAP  = 2.00;
/// 레벨(0-기준)의 값들.
const PZqN    = L=>PZqLV[L][0];
const PZqCOOL = L=>PZqLV[L][3];
/// ⭐ **유지(초)** = 방사 횟수 × (방사 + 쉼) = 방사 횟수 × [PZqBOUT]. 위 절이 근거다.
const PZqHold = L=>PZqLV[L][2]*PZqBOUT;
/// 수류탄 하나의 **총 수명** = 날아가는 시간 + 유지.
const PZqLife = L=>PZqFLY+PZqHold(L);
/// ⭐⭐ **구멍 각도 — 한 바퀴(360°)를 `n` 으로 나눈다.** 부채꼴이 **아니다.**
/// 사용자: 「독가스 방사 갈래가 지금 5갈래잖아? **한 방향 말고 5각으로 사방으로
///   뿌리는 식**을 말한 건데! … 갈래가 나눠지면 **앞뒤 · 3각 · 동서남북 · 5각**
///   이렇게 생각한 거야」 ⇒ 식은 **하나**다:
///       각도 j = [PZqA0] + j × 360°/n
///   n=2 **180°(앞뒤)** · n=3 **120°(3각)** · n=4 **90°(동서남북)** · n=5 **72°(5각)**
/// ⚠️⚠️ **`n=2` 도 예외가 아니다.** 확정본의 88° 부채(`PZbA1`·`PZbA2`)는 이 판이
///   **더는 안 쓴다** — 그 둘은 [PZbomb]·[PZgasBomb] 이 제 것으로 그대로 쓰고 있고
///   확정본은 한 글자도 안 고쳤다. 여기서만 갈라진다.
/// ⭐ 시작각이 **0** 이라 `FCDIR`(위)이 곧 **첫 갈래**다 ⇒ n=2 는 **위·아래**,
///   n=4 는 **위·오른쪽·아래·왼쪽**. 사용자가 말한 「앞뒤」·「동서남북」 그대로다.
/// ⚠️ 갈래가 몇이든 **한 글자도 안 고치고** 돈다 — `n` 만 바뀐다.
const PZqA0   = 0;
const PZqAngs = n=>{const o=[];for(let j=0;j<n;j++)o.push(PZqA0+TAU*j/n);return o;};
// ══════════════════════════════════════════════════════════════════════════
// ⚠️⚠️ **이 값은 「던지는 거리」가 아니라 「탐지 반경」이다**   (2026-08-23 · 사용자)
// ══════════════════════════════════════════════════════════════════════════
// 사용자 원문: 「독가스 **사거리가 꼭 멀리 던지라는 게 아니고**, 적이 멀리 있으면
//   **「인지하는」 영역**을 말하는 거야. 적이 멀리 있는데 멀리 죽었으면 **가까운
//   적에게 던져야 되는 게 당연**한 거야. 우리가 정한 규칙 중에 **뭉텅이로 있는
//   적에 자동 조준**이잖아? 맞지?」
//
// ⚠️⚠️ **이식 담당에게 — 한 줄로 못 박는다:**
//   **이 값은 탐지 반경이다. 자리는 그 안에서 「적이 뭉친 곳」으로 자동 선정된다.**
//   실제 던지는 거리는 **적이 어디 있느냐**가 정한다. 늘 이 거리에 던지지 않는다.
//   ⚠️ 이 저장소가 **같은 이름의 다른 양**으로 이미 한 번 헛돌았다
//     (`kFlamerHalfAngle` — 「부채 안 갈래 하나의 반각」 ↔ 「한 줄기의 퍼짐」).
//     ⇒ 그래서 이름을 [PZqSense] 로 바꿨다. `Range` 로 옮기면 그 사고가 재현된다.
//
// ⭐ **그래서 「엄청 늘려도 되겠다」가 성립한다** — 크게 잡아도 **가까운 적이 있으면
//   가까이 던지므로 손해가 없다.** 커지는 것은 「찾는 범위」뿐이다.
//
// ── ⭐⭐ 시안이 그걸 어떻게 보이나 — **뭉텅이를 놓고 그 위에 앉힌다** ──────────
//   반경 원·점선을 **안 그린다**(판정 안내선 금지). 대신:
//     ① 가짜 적을 **뭉텅이 셋**으로 놓는다 — 가까이 · 중간 · 멀리
//     ② **뭉텅이 자리는 다섯 칸이 똑같다**
//     ③ 수류탄이 **뭉텅이 한가운데에 앉는다** = 「적이 뭉친 곳에 자동 조준」
//     ④ 레벨이 덮는 뭉텅이 수가 는다 — **수류탄 수(1·1·2·2·3)가 곧 그 수**다
//   ⇒ L1·L2 는 **가까운 뭉텅이만** 치고 먼 뭉텅이는 **손도 못 댄다**(안 보이는 것이
//     아니라 **못 미치는 것**이다 — 적은 그대로 그려져 있다). L5 가 셋을 다 친다.
//   ⭐ 「인지 영역이 커진다」가 **원 없이** 읽히는 유일한 방법이 이것이다.
// ══════════════════════════════════════════════════════════════════════════

/// ⭐⭐ **탐지 반경** — 두 끝 **111 → 그 2배 222**, 가운데는 **등비**(×2^(1/4)).
///   ⇒ **111 · 132 · 157 · 187 · 222**
/// ⚠️⚠️ **[PZbDIST]=37 을 안 고친다** — 그건 확정본이 쓰는 값이다.
/// ⭐ 출발은 사용자 확정 「지금 사거리의 3배」(37 → 111)였고, 사용자가
///   **「범위가 커서 사거리 엄청 늘려도 되겠다」**고 해서 **끝을 두 배로 밀었다.**
/// ⚠️ **엔진 이식용은 픽셀이 아니라 비율로** — 몸 반지름이 **17** 이므로
///   `탐지 반경 = 몸 반지름 × 6.53 → 13.06` (확정본 사거리는 × 2.18 이었다).
/// ⚠️ 이 값은 **게임 좌표**다. 칸에 담을 때만 [PZqVIEW] 로 줄인다.
const PZqS1   = 111, PZqSN = 2;
const PZqSense= L=>PZqS1*Math.pow(PZqSN,L/4);
/// ⭐⭐ **뭉텅이 셋** — `[방향x, 방향y, 적 수]`. 거리는 [PZqClusD] 가 정한다.
/// ⚠️ 방향이 **좌우로 갈리고** 제일 먼 것이 거의 **곧게 위**다 — 그래야 칸이 안
///   한쪽으로 쏠려 같은 배율로 더 크게 담긴다.
/// ⭐ **멀수록 무리가 크다**(3 → 4 → 5) — 반경을 키울 **까닭**이 화면에 있어야 한다.
const PZqCLUS = [[ .530,-.848,3],
                 [-.530,-.848,4],
                 [ .150,-.989,5]];
/// 뭉텅이가 탐지 반경 **테두리 바로 안**에 선다는 몫. ⚠️ 이 절의 유일한 새 수다.
const PZqCK   = .90;
/// ⭐⭐ 뭉텅이 `j` 의 거리 — **그 뭉텅이를 처음 덮는 레벨**(L1·L3·L5)의 탐지 반경
///   × [PZqCK]. ⇒ **99.9 · 141.3 · 199.8**
/// ⚠️⚠️ **끼워 넣기 검산** — 뭉텅이가 「덮는 레벨 안 · 그 앞 레벨 밖」이라야
///   레벨이 오를 때 **새 뭉텅이가 하나씩 들어온다**:
///     141.3 > L2 의 132 ✓   ·   199.8 > L4 의 186.7 ✓
const PZqClusD= j=>PZqSense(2*j)*PZqCK;
/// 뭉텅이가 흩어지는 반지름 · 그 중 제일 안쪽 몫 · 각도 들썩임(rad) · 적 반지름.
const PZqCSPR = 30, PZqCRMIN = .60, PZqCJIT = .32, PZqCR = 9.5;
/// ⭐ 이 칸이 그리는 **가짜 적 목록** — `[x,y,r]`([mgInit] 규약).
/// ⚠️⚠️ **레벨을 안 탄다** — 다섯 칸이 **똑같은 판**이라야 「탐지 반경이 커져 더
///   먼 뭉텅이가 들어왔다」가 나란히 읽힌다. 갈리는 것은 **몇을 덮느냐**뿐이다.
/// ⚠️ 흩어짐은 난수가 아니라 [hash] 표다(`Math.random` 0건 유지).
/// ⭐⭐ **적을 갈래와 같은 자로 두른다** — 무리가 수류탄을 **고르게 에워싸고**
///   첫 자리가 [FCDIR](위) = **갈래 0 과 같은 각**이다.
///   ⚠️⚠️ 이게 없으면 **표식이 하나도 안 뜬다.** 흩뜨려 놨더니 L2·L3 에서 뭉텅이의
///     적이 **전부 갈래 사이 틈에 앉아** 판정을 한 번도 안 받았다(실측 0/3).
///     갈래는 360°를 `n` 으로 나눈 것이라 이어진 원뿔이 아니고, 판정 반각이
///     `.30+.16` 뿐이라 **덮는 몫이 갈래 둘이면 29% · 셋이면 44%** 밖에 안 된다.
///   ⭐ 덤: 뭉텅이 크기 **3·4·5** 가 갈래 **3·4·5** 와 맞물려 **L2·L3 은 셋 전부 ·
///     L4 는 넷 전부 · L5 는 다섯 전부**가 가스 안에 든다(실측).
///   ⚠️ 들썩임은 **±9.2°** 뿐이다 — 판정 반각 26.4° 안에 넉넉히 들어 「줄 세운 것」이
///     아니게만 흐트러뜨린다.
const PZqFoes = ()=>{const o=[];
  for(let j=0;j<PZqCLUS.length;j++){
    const[ux,uy,n]=PZqCLUS[j],D=PZqClusD(j);
    for(let k=0;k<n;k++){
      const sd=j*7.31+k*2.93+1.77;
      const a=FCDIR+TAU*k/n+(hash(sd)-.5)*PZqCJIT;
      const rr=PZqCSPR*(PZqCRMIN+(1-PZqCRMIN)*hash(sd+3.11));
      o.push([ux*D+Math.cos(a)*rr, uy*D+Math.sin(a)*rr*.78,
              PZqCR*(.85+.30*hash(sd+5.71))]);}}
  return o;};
/// ⭐⭐ **칸에 담는 배율** — ⚠️ **「보여 주기 위한 축소」다. 게임은 안 줄인다.**
///   L5 는 `제일 먼 뭉텅이 199.8 + 줄기 78 + 흔들림` 이라 필요 반경이 칸 반너비
///   **119** 를 넘는다. ⇒ ① 배율 [PZqVIEW] ② 몸을 [PZqCYOFF] 만큼 아래로.
/// ⚠️⚠️ **레벨마다 배율을 다르게 두지 않는다** — 성장 줄은 「커지는 것」을 보는
///   자리라 배율이 흔들리면 성장이 안 보인다. **다섯 칸이 같은 자**를 쓴다.
/// ⚠️⚠️ **배율을 반드시 밝힌다.** 이 저장소가 좌표계 혼동으로 크게 당한 적이 있다
///   (유도탄: 같은 3.8px 이 시안에서는 칸의 2.5%, 게임에서는 화면의 0.45% —
///   **5.7배 가늘었다**). ⇒ 이 칸의 픽셀 크기를 게임 값으로 읽으면 안 된다.
/// ⭐⭐ **0.43 → 0.35 → 0.56 으로 되돌렸다.** 「늘 최대 거리에 던진다」가 아니라
///   **뭉텅이 위에 앉는다**로 바뀌면서 제일 먼 자리가 222 → **199.8** 이 됐고,
///   뭉텅이 방향이 **좌우로 갈려**(±.530 · +.150) 칸이 한쪽으로 안 쏠린다.
///   ⇒ 실측 필요 반경 좌 **69** · 우 **64**(0.35 배 기준)라 **1.6배**를 더 담는다.
///   구 반지름이 화면에서 **4.82px**(0.35 일 때 3.12px).
const PZqVIEW  = .54;
/// 몸을 칸 가운데보다 이만큼 **아래**로(238 기준). 뭉텅이가 전부 위쪽이라
/// 몸을 내려야 **같은 배율로 더 크게** 담긴다. ⚠️ 확정본은 안 내린다.
/// ⭐ 실측으로 잡았다 — 잉크가 위로 **171.9px** · 아래로 **24.7px** 이라 그 폭
///   **196.6** 을 칸 236 한가운데 놓으면 몸이 `y≈192` 다 ⇒ 가운데보다 **74** 아래.
const PZqCYOFF = 74;
/// ① 날아가는 시간(초) · 나타나는 데 드는 시간 · 꼬리 수 · 꼬리 간격(px) · 꼬리 알파
/// ⭐ **0.50 → 0.70** — 거리가 3배가 됐으니 0.50 이면 화면에서 초당 128px 로 날아
///   「번쩍」이 된다. 0.70 이면 **91px/초**(프레임당 1.5px)라 **눈이 궤적을 따라간다**.
/// ⚠️ 유지는 **착지부터** 재므로 이 값이 바뀌어도 유지 초는 안 흔들린다.
const PZqFLY  = .70, PZqFLYFI = .10, PZqFLTN = 3, PZqFLTS = 7.0, PZqFLTA = .34;
/// 손에서 떠나는 자리 — 몸에서 **위로** 이만큼(px).
const PZqFLYUP = 10;
/// ⑤ 부들부들 길이(초) · 진폭(px) · 각속도 둘(서로 안 나누어떨어져야 「규칙적인
/// 흔들림」이 안 된다) · 차오르는 후광 알파. ⚠️ **떨림이지 새 사건이 아니다.**
const PZqSHK  = 1.00;
const PZqSHA  = 1.7, PZqSHW1 = TAU*11, PZqSHW2 = TAU*13.4, PZqSHGA = .16;
/// ⑥ 펑 — 길이(초) · 갈래 수 · 후광이 부푸는 배수 · 알파 · 구가 부푸는 배수 ·
///   갈래가 나가는 거리(구 반지름 몫) · 갈래 알파
/// ⚠️⚠️ **연출만이다. 피해 없음**(사용자 확정). 독침의 3스택 폭발과 어휘가 겹치면
///   「독은 터지는 속성」이 되어 버린다 ⇒ **작고 짧게**. 사라지는 신호지 공격이 아니다.
const PZqPOPT = .20, PZqPOPN = 6, PZqPOPR = 2.2, PZqPOPA = .55,
      PZqPOPB = .45, PZqPOPD0 = .50, PZqPOPD1 = 1.9, PZqPOPLA = .48;

// ── ⭐⭐ **제트 밝기 한 단 ↓** (2026-08-28 사용자: 「독가스 밝기 낮춰도 돼」) ──
// 온도 사다리([PKtoFire])의 네 칸은 **그늘 0 · 몸통 1 · 심 2 · 밝은 심 3** 이다.
// **한 칸씩** 아래를 쓴다 — 잔상·판 1→0 · 속판 2→1 · 제트 3→2.
// ⚠️⚠️ **알파·폭·모양·박자는 한 글자도 안 건드린다.** 사용자가 2026-08-23 에 두 번
//   반려한 것이 정확히 그 둘이다(「연하게 해서 투명하게」 · 「1자 스티커」).
//   여기서 바뀌는 것은 **칠하는 색 하나**뿐이다.
// ⚠️ **한 단만이다.** 두 단을 내리면 제트가 몸통색이 되어 「가스가 뿜어져 나온다」가
//   사라진다 — 부피를 얻자고 정체를 잃으면 안 된다.
// ⚠️ **이 칸 전용이다.** [PZqLane] 은 `FX.PZgasBombD` 만 부르고, 확정본
//   `FX.PZgasBombA` 는 [PZgasLane] 을 쓴다 ⇒ **다른 장은 한 화소도 안 바뀐다.**
const PZqRUNG = 1;

const PZqS3  = x=>x*x*(3-2*x);
const PZqC01 = x=>x<0?0:(x>1?1:x);
/// 이 칸(레벨)의 **방사 길이**(초). ⚠️ 아래 스케줄이 전부 이 하나를 본다 —
/// 인자로 네 함수에 실어 나르면 어긋날 자리가 넷이 된다.
const PZqBL = ()=>PZqSpray(Math.max(0,Math.min(4,LV-1)));
/// ⭐⭐ **확정본과 같은 스케줄**이다 — [PZgasBomb] 의 `lenK` 식을 그대로 쓰고
/// **방사 길이만** 레벨이 정한다(확정본은 3.00 · L1 은 2.50).
/// ⚠️⚠️ 인자는 **방사 안의 시각**이다(칸의 시각이 아니다 — 그 혼동이 「2차 방사가
///   고장 난 수류탄 같다」의 원인이었다). 범위 밖(음수 · 방사 뒤)은 [PZqC01] 이
///   양끝으로 **포화**시켜 `lenK=[PZbLMIN]` · `D=0` 을 준다 = **무음**.
///   ⇒ `PZqSched(0)` 과 `PZqSched(Bl)` 이 **둘 다 [PZbLMIN]** 이라 방사를 어디에
///     꽂아도 이음매가 안 생긴다(확정본이 이미 그렇게 만들어져 있다).
function PZqSched(ls){
  const Bl=PZqBL();
  const rel=PZqC01((ls-(Bl-PZbFADE))/PZbFADE);
  const lenK=ls<Bl-PZbFADE
    ?PZbLMIN+(1-PZbLMIN)*PZqS3(PZqC01(ls/PZbFILL))
    :1-(1-PZbLMIN)*PZqS3(rel);
  const P=(lenK-PZbLMIN)/(1-PZbLMIN);
  // `D` 는 **날것**(0 → 1)이라 무음에서 정확히 0 이다 — 안개·흔적이 이것을 쓴다.
  // `Dv` 는 **그려지는 밀도**로 바닥([PZqDMIN])이 깔려 있다 — 줄기가 이것을 쓴다.
  const D=Math.pow(P,PZqPOW);
  return{u:ls,rel,lenK,P,D,Dv:PZqDMIN+(1-PZqDMIN)*D};}
/// 그 자리(`u`)의 가스가 **태어난 지 얼마나 됐나**를 위상으로. `PKfBlobs` 의
/// `u = u0+(1−u0)·ph^.86` 을 되짚은 것이라 판과 덩어리가 **같은 시각**을 본다.
const PZqPH = (u,u0)=>u<=u0?0:Math.pow((u-u0)/(1-u0),1/.86);

/// ⭐⭐ **이어진 판이 「존재하는 자리」** — 알갱이들의 합집합. 이것이 이 판의 심장이다.
/// ⚠️⚠️ **알파를 낮추는 함수가 아니다.** 여기서 빠진 자리는 **아무것도 안 칠해진다.**
///   (2026-08-23 사용자 반려: 「구멍을 만들라니까 누가 얇게 해서 투명하게 해 가지고
///   뒤에가 보이게 만들어」 — 반투명은 구멍이 아니라 막이다.)
/// ⭐ 알갱이 하나는 **너덜너덜한 다각형**([PKrag])이라 합집합의 가장자리에 직선이
///   안 생긴다 — `cone()` 의 평평한 끝이 드러나는 것이 「네모난 실크천」이었다.
/// 돌려주는 것 셋:
///   `null`  — 다 덮었다 ⇒ **오려내지 않는다** = 확정본과 한 획도 안 다르다
///   `false` — 살아남은 알갱이가 없다 ⇒ **판을 아예 안 그린다**
///   `Path2D` — 그 합집합 안에서만 그린다
/// ⚠️⚠️⚠️ **`tt` 는 「방사 안의 시각」이다 — 칸의 시각이 아니다.**
///   복제본이 15초 주기로 바뀔 때 여기가 **칸의 시각을 그대로 읽고 있었다.**
///   그러면 2차 방사(u≈6.5~9.5)가 `u mod 4.8` = 1.7~4.7 을 읽어 **확정본의
///   잦아듦·무음 자리**를 밟는다 ⇒ 방사가 시작하자마자 밀도가 이미 내려가는 중이고
///   무음에서는 바닥 0.12 로 깔린다. 사용자가 본 것이 정확히 그것이다:
///   「**두 번째 방사 때는 고장 난 수류탄 같음 — 방사하다가 갑자기 피식 하고
///     금방 꺼져버려**」 (실측: 2차 잉크가 1차의 **40.0%**).
///   ⇒ [PZqBomb] 이 [PZqLoc] 으로 **방사 안의 시각**을 뽑아 넘긴다. 두 방사가
///     **같은 함수를 두 번 도는** 꼴이라 곡선이 두 벌이 아니다(미세하게 갈릴 수가 없다).
function PZqMaskPath(tt,cx,cy,LEN,HL,E,ang,w0,pw,u0){
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax;
  const Dn=PZqSched(tt).Dv;
  const P=new Path2D();let full=true,any=false;
  const dq=PZqMNL>1?2/(PZqMNL-1):0;
  for(let bm=0;bm<PZqMNB;bm++){
    const u=(bm+.5)/PZqMNB;
    const hwm=E.hw(u,HL,w0,pw)*PZqMWID;
    // 격자 한 칸의 **대각선 절반** — 이것이 「딱 덮는」 반지름이다.
    const Rb=PZqMR*.5*Math.hypot(LEN/PZqMNB,PZqMNL>1?2*hwm/(PZqMNL-1):2*hwm);
    // ⭐ 그 자리의 밀도 — 지금 압력과 **아래에서 올라오는 앞면** 중 작은 것.
    //   ⭐⭐ 여기에 [PZqMPOW] 를 먹인다 — **판은 물방울보다 늦게 생긴다.**
    const Dp=Math.pow(Math.min(Dn,PZqSched(tt-PZqPH(u,u0)*PZqLAG).Dv),PZqMPOW);
    const d=LEN*u,lt=E.lat(u,tt,HL);
    for(let jm=0;jm<PZqMNL;jm++){
      const sd=bm*3.13+jm*1.77+5.1;
      // 문턱은 **제 씨앗**에서 나온다(표 · 난수 아님) ⇒ 같은 알갱이는 늘 같은 문턱.
      const g=PZqS3(PZqC01((Dp-PZqMTHR*hash(sd))/PZqMRAMP));
      if(g<.999)full=false;
      if(g<=.004)continue;
      any=true;
      // ⭐ 물러설 때 **작아진다** — 옅어지는 것이 아니다(옅어지면 그게 막이다).
      const off=lt+(PZqMNL>1?-1+jm*dq:0)*hwm;
      const pl=PKrag(cx+ax*d+nx*off,cy+ay*d+ny*off,Rb*g,sd,11,PZqMRAG*(1-g*.55),sd*1.3);
      P.moveTo(pl[0][0],pl[0][1]);
      for(let i=1;i<pl.length;i++)P.lineTo(pl[i][0],pl[i][1]);
      P.closePath();}}
  return full?null:(any?P:false);}

/// `PKfBlobs` 와 **같은 식**이다(한 항도 안 바꿨다). 더 실어 보내는 것은
/// `ph`(태어난 시각을 짚는 데 쓴다) · `j`·`lat`(흔적이 같은 자리에 앉게).
/// ⚠️ `vfx.js` 를 안 고치려고 여기 둔다 — 그 파일은 **읽기만** 한다.
function PZqBlobs(t,cx,cy,SC,LEN,HALF,NL,NB,spd,u0,E,ang,pw){
  const o=[],ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  for(let j=0;j<NL;j++){
    const lat=NL>1?(j-(NL-1)/2)/((NL-1)/2):0;
    for(let b=0;b<NB;b++){
      const sd=j*5.3+b*1.7;
      const ph=((t*spd+j*.37+b/NB)%1);
      const u=u0+(1-u0)*Math.pow(ph,.86),d=LEN*u;
      const half=E.hw(u,HL,0,pw);
      const off=E.lat(u,t,HL)+lat*half*.62+Math.sin(ph*5.4+j*2.1)*half*.10;
      o.push({x:cx+ax*d+nx*off,y:cy+ay*d+ny*off,
        r:SC*2.2+half*(.40+1.20*hash(sd*1.9))*.62,u,sd,ph,j,lat,
        al:Math.min(1,ph*8)*Math.min(1,(1-ph)*8)});}}
  o.sort((p,q)=>q.u-p.u);
  return o;}

/// ⭐⭐ **밀도 채널이 붙은 갈래.** [PKflameLane] 의 재료·순서를 그대로 쓰고
/// **밀도 [D] 하나**를 더 받는다. ⚠️ `D=1` 이면 밀도 식이 전부 배수 1 로 접힌다.
/// ⚠️⚠️ **색만 한 단 아래를 쓴다**([PZqRUNG]) — 2026-08-28 사용자 허가. 그래서
///   `D=1` 에서도 확정본과 **색이 한 칸 다르다**(모양·알파·폭·박자는 같다).
/// ⚠️ `vfx.js` 의 [PKflameLane] 은 **한 글자도 안 고쳤다** — 화염방사 담당의 것이다.
function PZqLane(c,t,cx,cy,SC,LEN,HALF,R,M,E,ang,u0,NL,NB,w0,amul,jet,D){
  const pw=PKjetPow(jet);
  /// 온도 사다리에서 **한 칸 아래**를 칠한다. 알파는 [PKfillCool] 이 제 표
  /// (`R[s][4]`)로 정하므로 이 자리가 알파를 **못** 건드린다 — 구조적 안전장치다.
  const rung=i=>Math.max(0,i-PZqRUNG);
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  const m=[cx,cy],tip=[cx+ax*LEN,cy+ay*LEN];
  // ⚠️⚠️ **밀도는 폭에 절대 안 먹인다.** 아래 [edge]·[cone] 은 [PKflameLane] 과
  //   **한 글자도 다르지 않다.** 밀도가 건드리는 것은 **그려지는 자리**뿐이다.
  const edge=(u,side,k,tt)=>{const d=LEN*u,
    w=E.hw(u,HL,w0*SC,pw)*k*(1+Math.sin(u*5.2-tt*4.4+side*1.9)*.10*u),
    lt=E.lat(u,tt,HL);
    return[cx+ax*d+nx*(lt+side*w),cy+ay*d+ny*(lt+side*w)];};
  const cone=(k,tt)=>{const p2=[],T=tt===undefined?t:tt;
    for(let i=0;i<=16;i++)p2.push(edge(i/16,-1,k,T));
    for(let i=16;i>=0;i--)p2.push(edge(i/16, 1,k,T));
    return p2;};
  // ⓪ⓐⓑ **이어진 판** — 성기면 **아예 안 그린다**(알파를 안 낮춘다).
  // ⚠️⚠️ **폭은 절대 안 건드린다**(2026-08-23 사용자 반려: 「무슨 **1자 스티커**
  //   같은 게 길게 나가서 더 이상한 형태가 됐는데」). 폭 함수는 **「입구는 얇고
  //   길게, 바깥은 뾰족하고 둥근 덩어리들」이라는 실루엣의 뼈대**다.
  // ⚠️⚠️ **알파도 안 건드린다**(2026-08-23 두 번째 반려: 「연하게 해서 투명하게
  //   한다고 해결되는 게 아니라고 … 네모난 실크천 같은 게 펄럭거리게 만들어 놨네」).
  //   ⇒ 셋 다 **확정본과 똑같은 알파**로 그리고, 그리는 **자리**만 오려낸다.
  // ⭐ 오려내는 자[PZqMaskPath]는 **알갱이들의 합집합**이다 — 압력이 차면 알갱이가
  //   서로 겹쳐 **저절로 판이 되고**, 다 덮으면 오려내기 자체가 사라진다(`null`).
  // ⚠️ 잔상 겹은 `t−.09` 의 가스라 **마스크도 `t−.09` 것**을 쓴다. 지금 것을 쓰면
  //   S자 진폭이 커서 끝에서 9px 까지 어긋나 잔상이 제 마스크 밖으로 삐져나간다.
  const MK =PZqMaskPath(t    ,cx,cy,LEN,HL,E,ang,w0*SC,pw,u0);
  const MK9=PZqMaskPath(t-.09,cx,cy,LEN,HL,E,ang,w0*SC,pw,u0);
  const cut=(P,fn)=>{if(P===false)return;
    if(P===null){fn();return;}
    c.save();c.clip(P);fn();c.restore();};
  cut(MK9,()=>PKfillCool(c,cone(1.10,t-.09),R,.30*amul,m[0],m[1],tip[0],tip[1],rung(1)));
  cut(MK ,()=>{PKfillCool(c,cone(1)  ,R,amul,m[0],m[1],tip[0],tip[1],rung(1));
               PKfillCool(c,cone(.55),R,amul,m[0],m[1],tip[0],tip[1],rung(2));});
  // ⓒ **덩어리** — 문턱을 넘은 것만 켜지고, 성길수록 **작다.**
  const bs=PZqBlobs(t,cx,cy,SC,LEN,HALF,NL,NB,.85,u0,E,ang,pw);
  for(const b of bs){
    // ⭐⭐ **제가 태어난 시각의 밀도**를 본다. `ph` 가 `t/PZbT` 로 늘어나므로
    //   `t − ph·PZqLAG` 는 흐르는 내내 **거의 상수**다 — 프레임마다 다시 안 굴린다.
    const Db=Math.min(D,PZqSched(t-b.ph*PZqLAG).Dv);
    // 문턱은 **제 씨앗**에서 나온다(표 · 난수 아님) ⇒ 같은 덩어리는 늘 같은 문턱.
    const gate=PZqS3(PZqC01((Db-PZqTHR*hash(b.sd*3.1+7.7))/PZqRAMP));
    // ⭐⭐ **문턱을 반지름에 먹인다.** 알파에 먹이면 옅은 덩어리가 남고 그것이
    //   곧 「막」이다 — 덩어리는 **또렷하거나 없거나** 둘 중 하나여야 한다.
    // ⭐ **뭉쳐서 커진다** — 막 나올 때 작고 압력이 차면 확정본 크기가 된다.
    b.rr=b.r*(PZqSMALL+(1-PZqSMALL)*Db)*gate;
    // ⚠️ 알파는 **확정본 그대로**다([PKflameLane] 의 `b.al`).
    b.aa=b.al;}
  for(const b of bs){if(b.aa<=.02||b.rr<=.35)continue;
    const bu=(b.u-u0)/Math.max(1e-3,1-u0),MM=PKmassAt(M,bu);
    const rn=b.rr>9*SC?21:15;
    const sh=(r,dy,am)=>PKrag(b.x,b.y+dy,r,b.sd,rn,am,b.sd);
    fillPoly(c,sh(b.rr,0,.42),A(MM[0],b.aa*amul));
    fillPoly(c,sh(b.rr*.60,-b.rr*.08,.30),A(MM[1],b.aa*.95*amul));
    if(b.rr>5*SC){const gn=2+((b.sd*7)|0)%2;
      for(let q=0;q<gn;q++){
        const ga=b.sd*2.3+q*2.7,gd=b.rr*(.18+.30*hash(b.sd+q*5.1));
        const gr=b.rr*(.16+.16*hash(b.sd+q*2.7));
        fillPoly(c,PKrag(b.x+Math.cos(ga)*gd,b.y+Math.sin(ga)*gd,gr,
          b.sd+q*11,9,.34,ga),
          A(PKmassAt(M,Math.max(0,bu-.34))[1],b.aa*amul));}}}
  // ⓓ **빛번짐** — 덩어리를 그대로 따라가므로 반지름이 줄면 같이 줄어든다.
  gAdd(c,g=>{
    for(const b of bs){if(b.aa<=.05||b.rr<=.35)continue;
      gHalo(g,b.x,b.y-b.rr*.14,b.rr*(.72+.34*hash(b.sd*1.3)),"ember",.24*b.aa*amul);}
    // 총구의 번짐 — 압력이 만드는 빛이라 압력을 그대로 탄다(밀도 1 에서 `.30`).
    gHalo(g,cx+ax*LEN*.15,cy+ay*LEN*.15,LEN*.13*(.35+.65*D),"ember",.30*amul*D);});
  // ⓔ **제트** — 「입구 쪽 얇고 긴 것」. 사용자: 「처음에는 저 입구 쪽 얇고 긴 걸
  //   **없애고**」 ⇒ 압력이 없으면 **없다.**
  // ⚠️⚠️ 폭도 알파도 안 건드린다 — **판과 같은 마스크**로 오려낸다. 알파를 낮추면
  //   그것이 바로 사용자가 반려한 「얇게 해서 투명하게 해 가지고 뒤에가 보이는」 것이다.
  const uJ=jet,jp=[];
  for(let i=0;i<=6;i++){const u=uJ*i/6,d=LEN*u,w=E.hw(u,HL,w0*SC,pw)*.42,
    lt=E.lat(u,t,HL);
    jp.push([cx+ax*d+nx*(lt+w),cy+ay*d+ny*(lt+w)]);}
  for(let i=6;i>=0;i--){const u=uJ*i/6,d=LEN*u,w=E.hw(u,HL,w0*SC,pw)*.42,
    lt=E.lat(u,t,HL);
    jp.push([cx+ax*d+nx*(lt-w),cy+ay*d+ny*(lt-w)]);}
  cut(MK,()=>PKfillCool(c,jp,R,amul,m[0],m[1],tip[0],tip[1],rung(3)));
  // ⓕ **불씨** — 알갱이도 **제 자리**의 밀도를 본다.
  // ⚠️⚠️ 앞 판은 밀도를 **제 나이**(`q/sp`)로 짚었는데, 그 나이가 최대 **2.74초**라
  //   한창 한복판에서도 **쿨 구간의 밀도**를 읽어 불티가 빠졌다 — 그래서 절정에서
  //   확정본과 안 같았다(실측 t=0.90 에서 그리는 꼭짓점 **−92**개). 덩어리와 같은
  //   자[PZqPH]로 바꾸면 되짚는 시간이 [PZqLAG] 로 묶여 **한창이 정확히 확정본**이 된다.
  for(let k=0;k<PKFEMB[LV-1];k++){
    const sd=k*3.77+ang*7;
    const sp=.42+.80*hash(sd),life=.55+.60*hash(sd+1.3);
    const q=((t*sp+hash(sd+2.1))%1);
    if(q>life)continue;
    const w=q/life,u0e=.34+.46*hash(sd+3.3);
    const uu=u0e+.52*w*(.4+.9*hash(sd+6.1));
    const De=Math.min(D,PZqSched(t-PZqPH(Math.min(1,uu),u0)*PZqLAG).Dv);
    const eg=PZqS3(PZqC01((De-PZqTHR*hash(sd*2.9+4.1))/PZqRAMP));
    if(eg<=.004)continue;
    // ⚠️ `d/LEN` 을 그대로 쓴다 — `uu` 로 바꾸면 부동소수 왕복이 달라진다.
    const d=LEN*uu;
    const lt=E.lat(d/LEN,t,HL);
    const lat=lt+(hash(sd+5.2)-.5)*2*E.hw(d/LEN,HL,0,pw)*(.55+.95*w);
    const ex=cx+ax*d+nx*lat,ey=cy+ay*d+ny*lat;
    // ⭐ 문턱은 **크기**로 먹인다(알파는 확정본 그대로) — 옅은 불티는 곧 막이다.
    const r=SC*(.7+2.1*hash(sd+7.3))*(1-w*.6)*(PZqSMALL+(1-PZqSMALL)*De)*eg;
    if(r<=.12)continue;
    const S3c=PKmassAt(M,Math.min(1,u0e+w*.55));
    fillPoly(c,PKrag(ex,ey,r,sd,5,.42,sd+t*3.1),
      A(M.emb||S3c[0],(1-w)*(1-w)*.95*amul));
    if(w<.42)gAdd(c,g=>gHalo(g,ex,ey,r*2.3,"ember",.50*(1-w/.42)*amul));}}

/// ⭐⭐ **독의 흔적** — 「가스의 잔상이 남듯이」. 지나간 자리에 **걸려 남는** 것이라
/// 빠른 줄기가 그 옆을 지나간다.
/// ⚠️⚠️ **끝맺음의 수단이 아니다.** 앞 판이 반려된 원인 둘을 구조로 막았다:
///   ① **「제일 긴 것」을 절대 안 붙든다** — 자리를 **지금 길이**(`LEN`)의 몫으로
///      잡으므로 줄기가 짧아지면 흔적도 **같이 당겨진다.** 잔상이 77.3px 를
///      붙들어 짧아지는 것을 가렸던 그 일이 구조적으로 못 일어난다.
///   ② **팅팅과 역위상이 안 된다** — 팅팅이 시작하기 **전에 이미 0** 이다([PZqTOFF]).
///      3.00~4.80초 무음도 그대로다(밀도 `D` 가 0 이라 이중 안전).
/// ⭐ 흔들리지 않는다 — 태어날 때 그 자리의 **파동 위상을 얼려서** 갖는다.
function PZqTrace(c,t,hx,hy,SC,LEN,HALF,M,ang,S){
  // ⭐⭐ **밀도가 1 이면 정확히 0 이다.** 사용자가 도착점을 못 박았다 —
  //   「밀도가 낮은 분사 형태가 나가다가 그게 점점 빈 공간을 메꾸면서 **지금의
  //   형태처럼 되어야 한다**」. 한창 구간이 확정본과 **픽셀까지 같아야** 하므로
  //   이 층도 거기서는 **없어야 한다.** ⇒ `4·D·(1−D)` 는 `D=1` 에서도 `D=0` 에서도
  //   **정확히 0**이라 ① 한창은 확정본 그대로고 ② 이음매·무음도 0 이다.
  //   ⇒ 흔적은 **덜 뭉친 가스**다 — 다 뭉치면 줄기에 흡수돼 안 보인다.
  const trK=4*S.D*(1-S.D)*PZqS3(PZqC01((PZbSPUT-S.rel)/PZqTOFF));
  if(trK<=.01)return;
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  for(let k=0;k<PZqNT;k++){
    const sd=k*6.31+13;
    const ph=((t/PZqTLIFE+hash(sd)+k/PZqNT)%1);      // 나이 몫 0 → 1
    const t0=t-ph*PZqTLIFE;                          // **태어난 시각** — 사는 내내 불변
    const ud=.16+.72*hash(sd+2.3);                   // 걸린 자리(길이 몫)
    // 태어난 시각의 파동 위상 · 태어난 시각의 진폭 배수 ⇒ **둘 다 상수** = 안 흔들린다.
    // ⚠️ **줄기 봉투 밖으로 조금 나간다**(`.62` 항). 안에만 두면 줄기가 통째로
    //   덮어 버려 실측 잉크 기여가 **+0.2%** 밖에 안 됐다 — 안 보이는 층이었다.
    //   흔적은 「이미 흩어진 것」이라 봉투보다 넓은 것이 물리로도 맞다.
    const off=Math.sin(PZbW*(ud*PZbT-t0))*HL*PZbAMPS[0]*Math.pow(ud,1.6)
             *(.18+.82*PZqSched(t0).lenK)
             +(hash(sd+3.7)-.5)*2*HL*.34;
    const d=LEN*ud;
    const x=hx+ax*d+nx*off, y=hy+ay*d+ny*off+HL*.18*ph;
    // ⚠️⚠️ **세기는 「크기」로 말한다 — 알파로 말하지 않는다.**
    //   앞 판은 `al = ramp·trK·알파` 였다. 그래서 흔적이 옅어질 때 **낮은 알파가
    //   넓은 면적을 덮었고**(실측: 성긴 프레임에서 알파 .05~.30 화소가 마스크의
    //   **42.8%** — 그중 36%p 가 이 층이었다) 그것이 곧 사용자가 반려한 **막**이다.
    //   ⇒ 알파는 **또렷한 채로 두고**, [trK] 는 **반지름**에 먹인다.
    //     `trK=0`(밀도 1 · 이음매 · 무음)에서 반지름이 0 이라 사라지는 것은 같다.
    const ramp=Math.min(1,ph*4)*Math.min(1,(1-ph)*3);
    const rr=(HL*(.15+.17*hash(sd+1.1))+3.5*SC)*(.70+.70*ph)*(.30+.70*ramp)*trK;
    const al=PZqTRA*PZqS3(PZqC01(ramp*1.8));
    if(al<=.006||rr<=.3)continue;
    // ⚠️ 색 사다리의 **앞쪽**에서 뽑는다 — 뒤쪽(u≳.75)은 숯빛(#2A0F08)이라
    //   또렷하게 칠하면 **진흙 덩어리**가 된다. 흔적은 「독」이니 초록이어야 한다.
    const MM=PKmassAt(M,Math.min(1,ud*.52));
    // ⭐ **또렷한 덩어리**다 — [PZsoft](풀리는 그러데이션)를 걷어냈다.
    fillPoly(c,PKrag(x,y,rr,sd,13,.34,sd*1.7),A(MM[0],al));
    fillPoly(c,PKrag(x,y,rr*.56,sd+2.1,9,.28,sd+t*.22),A(MM[1],al*.88));}}

/// ⭐⭐ **머무는 안개** — 위 절이 근거 전부다. 하는 일은 딱 하나:
/// **방사 안에 못 박힌 시각 `tb` 마다 조각 하나를 그 자리에 놓고, 제 나이대로 걷는다.**
/// ⚠️ 그리는 값 중 **시간의 함수는 나이(`w`) 하나**다 — 자리·진하기·색은 전부
///   `tb` 에서 나오는 **상수**라 줄기가 휘어도 안 따라간다(= 안 깜빡인다).
/// ⚠️ `lu` 는 **수류탄 제 시각**(던진 뒤 몇 초)이고 `u` 는 **칸의 주기 시각**이다.
function PZqHaze(c,lu,hx,hy,SC,LEN0,HALF,M,ang){
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax;
  const HC=PKmassAt(M,PZqHCOL)[0];
  const L=Math.max(0,Math.min(4,LV-1)),NBu=PZqLV[L][2],Bl=PZqSpray(L);
  for(let bi=0;bi<NBu;bi++){
    const B=PZqFLY+bi*PZqBOUT;
    for(let k=0;k<PZqHN;k++){
      const sd=k*3.97+11.3+ang*6.1+bi*21.7;
      // 태어난 시각 — **방사 안에 못 박혀 있다.** ⚠️ 난수가 아니라 [hash] 표다.
      const tb=B+Bl*(k+.5+(hash(sd+.7)-.5)*PZqHJIT)/PZqHN;
      const ag=lu-tb;                                   // 나이
      if(ag<0||ag>=PZqHLIFE)continue;                   // 아직 없거나 이미 걷혔다
      const w=ag/PZqHLIFE;
      // 피어오름 · 걷힘 — 양끝에서 정확히 0 이라 뚝 안 끊긴다.
      const env=PZqS3(PZqC01(w/PZqHRISE))*PZqS3(PZqC01((1-w)/PZqHFALL));
      if(env<=.003)continue;
      // ⭐ **태어난 시각의 스케줄**만 본다 — 여기서 나오는 것은 전부 상수다.
      const Bs=PZqSched(tb-B),lk=Bs.lenK,LB=LEN0*lk,HLB=HALF*LB;
      const ud=PZqHU0+PZqHUD*hash(sd+2.9);
      // ⭐ 진하기 = **그 자리를 지나간 가스의 양**. 날것 `D` 라 무음에서 정확히 0.
      const dep=Math.min(Bs.D,PZqSched(tb-B-PZqPH(ud,.21)*PZqLAG).D);
      if(dep<=.004)continue;
      // 자리 — 태어난 시각의 파동 위상·진폭·길이. ⚠️ **지금 시각이 안 들어간다.**
      const off=Math.sin(PZbW*(ud*PZbT-(tb-B)))*HLB*PZbAMPS[0]*Math.pow(ud,1.6)*(.18+.82*lk)
               +(hash(sd+5.3)-.5)*2*HLB*PZqHSPR;
      const d=LB*ud;
      // ⭐ **아주 느린 굼실거림** — 방향·속도가 씨앗에서 나온 **상수**다.
      const dr=PZqHDRF*SC*w, da=sd*2.1;
      const x=hx+ax*d+nx*off+Math.cos(da)*dr, y=hy+ay*d+ny*off+Math.sin(da)*dr;
      // ⭐ 나이 들며 **퍼진다** — 등방이라 조각의 무게중심은 그대로다.
      // ⭐ 다섯에 하나는 **크고 더 옅다** — 그것이 바깥 경계를 지운다.
      const big=(k%PZqHBIG)===0;
      const rr=(HLB*(PZqHR0+PZqHRV*hash(sd+7.1))+PZqHRC*SC)*(PZqHG0+PZqHGR*w)
              *(big?PZqHBR:1);
      const al=PZqHA*env*dep*(big?PZqHBA:1);
      if(al<=.0025||rr<=.4)continue;
      // ⭐⭐ **경계가 풀린 그러데이션 하나**([PZsoft]) — 또렷한 다각형이면 그게 막이다.
      //   진하기는 이 한 조각이 아니라 **겹침**이 낸다.
      PZsoft(c,x,y,rr,HC,al,PZqHFLAT);}}}

/// ⭐⭐ **방사 안의 시각** — 수류탄 제 나이(`lu`)를 방사 안의 시각으로 접는다.
/// 방사 밖(날아가는 중 · 쉼 · 끝난 뒤)이면 **범위 밖 값**을 주어 [PZqSched] 가
/// 무음으로 포화시킨다. ⇒ 방사가 몇 번이든 **같은 함수를 그만큼 도는** 꼴이다.
function PZqLoc(lu){
  const L=Math.max(0,Math.min(4,LV-1)),B=PZqLV[L][2],Bl=PZqSpray(L);
  const x=lu-PZqFLY;
  if(x<0)return -9;                       // 아직 날아오는 중
  const b=Math.floor(x/PZqBOUT);
  if(b>=B)return Bl+9;                    // 방사가 다 끝났다
  const ls=x-b*PZqBOUT;
  return ls<Bl?ls:Bl+9;}                  // 쉼

/// ① **던져져 날아와 그 자리에 멈춘다.** 돌려주는 것: `[x,y,알파,속도몫]`
/// ⚠️ **감속 곡선**이다(`1−(1−q)³`) — 끝에서 속도가 정확히 0 이라 「멈췄다」가 읽힌다.
///   ⚠️ 착지 충격·먼지·그림자를 안 그린다. **우주라 바닥이 없다.**
function PZqFlight(lu,cx,cy,bx,by,SC){
  const q=PZqC01(lu/PZqFLY),iq=1-q;
  const s=1-iq*iq*iq;                       // 감속
  const hx=cx,hy=cy-PZqFLYUP*SC;            // 손에서 떠나는 자리
  return[hx+(bx-hx)*s,hy+(by-hy)*s,PZqS3(PZqC01(lu/PZqFLYFI)),iq*iq];}

/// ⑤ **부들부들** — 사라진다는 예고. ⚠️ 떨림이지 새 사건이 아니다(장식 금지).
/// 돌려주는 것: `[dx,dy,세기]`. 세기는 펑 구간에서 **1 로 포화**돼 이어진다.
function PZqShake(lu,SC,SHK0){
  const k=PZqS3(PZqC01((lu-SHK0)/PZqSHK));
  if(k<=0)return[0,0,0];
  return[Math.sin(lu*PZqSHW1)*PZqSHA*SC*k,
         Math.sin(lu*PZqSHW2+1.7)*PZqSHA*SC*k*.72,k];}

/// ⑥ **펑** — ⚠️⚠️ **연출만이다. 피해 없음**(사용자 확정). **작고 짧게.**
/// ⚠️ 알파가 `s=0` 에서 정확히 0 이라 앞 구간과 **이어진다**(터지는 순간 안 튄다).
function PZqPop(c,x,y,r,s){
  const fa=Math.sin(Math.PI*Math.pow(s,.42));      // 빨리 차고 천천히 진다
  if(fa<=.004)return;
  gAdd(c,g=>{
    gHalo(g,x,y,r*(1+PZqPOPR*s),PZTOX,PZqPOPA*fa);
    for(let i=0;i<PZqPOPN;i++){
      const sd=i*5.7+2.3,aa=FCDIR+TAU*(i+hash(sd)*.6)/PZqPOPN;
      const dd=r*(PZqPOPD0+PZqPOPD1*s);
      gLance(g,x+Math.cos(aa)*dd,y+Math.sin(aa)*dd*LX3SQ,aa,
        r*.34*fa,r*.11,PZTOX,PZqPOPLA*fa);}});}

/// 복제본 본체 — **스킬 전체**다(위 성장표 절의 시각표). 방사 하나의 속은
/// [PZgasBomb] 과 **한 획도 안 다르고**([PZqLoc] 이 시각만 접는다), 더한 것은 넷:
/// ⓐ 던져져 날아와 멈춤 · ⓑ 방사 사이의 쉼 · ⓒ 부들부들 → 펑 · ⓓ 머무는 안개.
/// ⚠️⚠️ **수류탄마다 「제 나이」를 갖는다** — 시전이 `k·쿨` 마다 일어나므로 앞
///   시전의 수류탄이 아직 살아 있으면 **그것도 같이 그린다**(L3 부터 겹친다).
///   `u → 쿨⁻` 의 나이가 `u=0` 의 `j+1` 짜리 나이와 **정확히 같아** 이음매가
///   구조적으로 이어진다 — 겹침을 특별히 다루는 코드가 **한 줄도 없다.**
/// ⚠️ 그리는 시각이 **방사 안의 시각**이다(전역 `t` 가 아니다) — 그래야 방사 둘이
///   **같은 모양**이 된다. 몸·적만 전역 `t` 를 쓴다(그 둘은 스킬이 아니다).
function PZqBomb(c,t,dt,W,H,st){
  const E=PZbESSA;
  const L=Math.max(0,Math.min(4,LV-1));
  const NG=PZqLV[L][0],NLN=PZqLV[L][1],NBU=PZqLV[L][2],BL=PZqSpray(L);
  const COOL=PZqLV[L][3],LWM=PZqLW(L);
  const ANG=PZqAngs(NLN);
  // ⚠️ **칸에 담는 배율**([PZqVIEW])이 여기 한 번만 들어간다 — 몸·적·표식까지
  //   전부 같은 배율로 줄어든다. **게임은 안 줄인다**(위 절).
  const K0=Math.min(W,H)/238;
  const cx=W/2,cy=H/2+PZqCYOFF*K0,SC=K0*PZqVIEW;
  st.p=st.p||[];
  // ⭐⭐ **뭉텅이 셋** — 확정본의 `FCCONE_F`(다섯이 흩어진 판)를 안 쓴다.
  //   이 스킬은 「**적이 뭉친 곳에 자동 조준**」이라 **뭉쳐 있어야** 그 규칙이 보인다.
  mgInit(st,SC,PZqFoes());stepFoes(st.F,dt);
  // ⚠️ 배수는 **길이에만** 건다 — 원뿔 각([PZbHALF])은 다섯 칸이 같아야
  //   **모양이 안 변하고 크기만** 자란다(폭은 길이를 따라 저절로 자란다).
  const LEN0=PZbLEN*SC*LWM,HALF=PZbHALF,br=PZbRAD*SC;
  const u=((t%COOL)+COOL)%COOL;
  const LIFE=PZqLife(L);
  const ST=PKCOL.verd,R=PKtoFire(ST);
  const NL=PKFNL[LV-1],NB=PKFNB[LV-1];
  // ⭐ **살아 있는 수류탄 전부** — 앞 시전(`j`)까지 훑는다. 이것이 겹침의 전부다.
  const G=[];
  const JMAX=Math.ceil((LIFE+(NG-1)*PZqGAP)/COOL);
  for(let j=0;j<=JMAX;j++)for(let i=0;i<NG;i++){
    const lu=u+j*COOL-i*PZqGAP;
    if(lu<0||lu>=LIFE+PZqHLIFE)continue;          // 안개까지 걷힌 뒤엔 안 본다
    const ls=PZqLoc(lu),S=PZqSched(ls);
    // ⭐⭐ **수류탄 `i` 는 뭉텅이 `i` 한가운데에 앉는다** = 자동 조준이 눈에 보인다.
    //   ⇒ 수류탄 수(1·1·2·2·3)가 곧 **덮는 뭉텅이 수**다. 못 미치는 뭉텅이의 적은
    //     그대로 그려져 있고 **아무 표식도 안 받는다** — 그것이 「탐지 반경 밖」이다.
    const DD=PZqClusD(i);
    const bx=cx+PZqCLUS[i][0]*DD*SC,by=cy+PZqCLUS[i][1]*DD*SC;
    // 세기 — **확정본 그대로**(점화 램프 · 잦아듦 앞 62% 는 1 · 팅팅 넷).
    let on=0;
    if(ls>=0&&ls<BL){
      if(S.rel<PZbSPUT)on=Math.min(1,ls/.20);
      else{
        const s=(S.rel-PZbSPUT)/(1-PZbSPUT);
        on=s<PZbPOP[0][1]?PZqS3(1-s/PZbPOP[0][1]):0;
        for(let k=1;k<PZbPOP.length;k++){
          const[s0,du,pw]=PZbPOP[k];
          if(s>=s0&&s<s0+du){const w=Math.sin(Math.PI*(s-s0)/du);
            on=Math.max(on,w*w*pw);}}}}
    G.push({lu,ls,S,bx,by,on,live:lu<LIFE});}
  // 판정 — 확정본과 같다. ⚠️ 넉백 없음 · 틱 느림 · **안내선 안 그린다.**
  st.tk=(st.tk||0)+dt;
  if(st.tk>.30){st.tk=0;
    for(const g of G){if(!(g.on>0))continue;
      for(const f of st.F)for(const a of ANG){
        const H0=PZbHole(g.bx,g.by,br,a,g.ls);
        const dx=cx+f.ox-H0[0],dy=cy+f.oy-H0[1],d=Math.hypot(dx,dy)||1;
        if(d>=LEN0+f.r)continue;
        let ad=Math.atan2(dy,dx)-H0[2];
        while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
        if(Math.abs(ad)>HALF+.16)continue;
        f.pv=Math.min(3,(f.pv||0)+.72);break;}}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.42;
  stepP(st,dt);
  // ⭐⭐ **㉧㉤ 바닥 쪽은 적 「앞」이다**(2026-08-28 「3D 로 다시」). 그림자와
  //   눌려 퍼진 밑동은 **바닥에 눌린 것**이라 적이 그 **위에 서야** 한다 —
  //   적 뒤에 그리면 적이 구름에 잠긴 게 아니라 **구름이 적을 덮는다**.
  for(const g of G){
    const gu=Math.min(1,Math.max(0,(g.lu-PZqFLY)/.55));
    if(gu<=0)continue;
    PZ5gasFoot(c,g.ls,g.bx,g.by,LEN0*.70*gu,PZTOX,.78*gu,SC,g.bx*.03+g.by*.017);}
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);
  // ⭐⭐ **㉠㉡㉢㉣㉥㉦ 뜬 층은 적 「뒤」다** — 구름 안에 든 적이 **흐려진다.**
  //   ⚠️ 이 자리가 이미 그 규율이었다(바로 아래 안개 주석). 새 층도 **같은 자리**다.
  for(const g of G){
    const gu=Math.min(1,Math.max(0,(g.lu-PZqFLY)/.55));
    if(gu<=0)continue;
    PZ5gasLift(c,g.ls,g.bx,g.by,LEN0*.78,PZTOX,.95*gu,SC,g.bx*.03+g.by*.017,gu);}
  // ⓓ **머무는 안개** — **제일 밑**이다(적 위에 깔려 **뒤를 흐린다**). 줄기·끝맺음·
  //   수류탄이 전부 그 위에 그려져야 「길이가 77.3 → 11.6 으로 줄어드는 것」이 산다.
  for(const g of G)for(const a of ANG){
    const H0=PZbHole(g.bx,g.by,br,a,g.ls);
    PZqHaze(c,g.lu,H0[0],H0[1],SC,LEN0,HALF,ST,H0[2]);}
  // ⓪ **독의 흔적** → ⓐ **줄기들** — 수류탄마다. 인자는 확정본 그대로다.
  for(const g of G){
    if(!g.live)continue;
    const lenK=g.S.lenK,D=g.S.Dv,ampK=.18+.82*lenK;
    const Ef={hw:E.hw,lat:(uu,tt,HLv)=>E.lat(uu,tt,HLv)*ampK,lanes:1};
    for(const a of ANG){
      const H0=PZbHole(g.bx,g.by,br,a,g.ls);
      PZqTrace(c,g.ls,H0[0],H0[1],SC,LEN0*lenK,HALF,ST,H0[2],g.S);}
    for(const a of ANG){
      if(g.on>.002){
        const H0=PZbHole(g.bx,g.by,br,a,g.ls);
        PZqLane(c,g.ls,H0[0],H0[1],SC,LEN0*lenK,HALF,R,ST,Ef,H0[2],.21,NL,NB,5.0,g.on,.15,D);}}
    // ⑥ **마지막 한 방울** — 확정본 그대로.
    {const sp=(g.S.rel-PZbSPUT)/(1-PZbSPUT);
     const dr=(g.ls>=0&&g.ls<BL&&g.S.rel>PZbSPUT)?Math.sin(Math.PI*sp):0;
     if(dr>.01){const TXd=toneOf(PZTOX);
       for(const a of ANG){
         const H0=PZbHole(g.bx,g.by,br,a,g.ls);
         for(let k=0;k<3;k++){
           const q=k/3;
           const rr=br*(.42-.10*k)*dr;
           if(rr<=.3)continue;
           fillPoly(c,PKrag(H0[0],H0[1]+br*(.6+2.2*q)*dr,rr,a*5.1+k,9,.32,a+g.ls*.5),
             A(TXd[k?0:1],(.55-.14*k)*dr));}}}}}
  // ⭐⭐ **가까운 반쪽은 줄기 「앞」이다**(2026-08-28 · 실측이 시킨 자리). 구름도
  //   줄기를 **지나가는 것**이라 「몸을 지나는 고리는 앞뒤 반으로 가른다」가 그대로
  //   붙는다. ⚠️ **그리는 것은 하나도 안 늘었다** — [PZ5gasLift] 에서 **옮겼다.**
  for(const g of G){
    const gu=Math.min(1,Math.max(0,(g.lu-PZqFLY)/.55));
    if(gu<=0)continue;
    PZ5gasNear(c,g.ls,g.bx,g.by,LEN0*.78,PZTOX,.95*gu,SC,g.bx*.03+g.by*.017,gu);}
  // ⓑ **수류탄** — 확정본의 [PZbomb] 을 **그대로 부른다**(사본을 안 뜬다).
  //   ⚠️⚠️ 자리에 멈춰 있는 동안은 `globalAlpha=1` · 반지름 `br` · 자리 그대로라
  //     **확정본과 한 획도 안 다른 호출**이다.
  const GONE=LIFE,POP0=GONE-PZqPOPT,SHK0=GONE-PZqPOPT-PZqSHK;
  for(const g of G){
    if(!g.live)continue;
    let x=g.bx,y=g.by,rr=br,al=1;
    if(g.lu<PZqFLY){                                   // ① 날아온다
      const F=PZqFlight(g.lu,cx,cy,g.bx,g.by,SC);
      x=F[0];y=F[1];al=F[2];
      // 꼬리 — **속도에 비례**한다. 멈추면 정확히 0 ⇒ 그것이 「멈췄다」다.
      if(F[3]>.004&&al>.01){
        const dx=g.bx-cx,dy=g.by-(cy-PZqFLYUP*SC),dl=Math.hypot(dx,dy)||1;
        gAdd(c,gg=>{for(let i=1;i<=PZqFLTN;i++){
          const Lt=PZqFLTS*SC*F[3]*i;
          gHalo(gg,x-dx/dl*Lt,y-dy/dl*Lt,br*(1-.16*i),PZTOX,PZqFLTA*F[3]*al/i);}});}
    }else{
      const K=PZqShake(g.lu,SC,SHK0);                  // ⑤ 부들부들
      x+=K[0];y+=K[1];
      if(K[2]>.01)gAdd(c,gg=>gHalo(gg,x,y,br*(1.15+.55*K[2]),PZTOX,PZqSHGA*K[2]));
      if(g.lu>=POP0){                                  // ⑥ 펑
        const s=(g.lu-POP0)/PZqPOPT;
        al=1-PZqS3(s);rr=br*(1+PZqPOPB*s);
        PZqPop(c,x,y,br,s);}}
    if(al>.004){c.save();c.globalAlpha=al;
      PZbomb(c,x,y,rr,g.ls,g.on,SC);c.restore();}}
  drawP(c,st);hero(c,t,cx,cy,"gold",PZqVIEW);}


/// 표의 한 칸을 **잠깐 빌려** 남의 함수를 부른다([PZwithTone] 의 배열판).
/// ⚠️ 동기 한 프레임 안에서 끝나고 `finally` 로 되돌린다.
function PZwithToneArr(k,arr,fn){
  const sv=TONE[k];TONE[k]=arr;
  try{fn();}finally{TONE[k]=sv;}}

/// 가산 후광용 **칙칙한 녹회색** — 「형광」을 죽이는 자리.
/// 115° 계열이되 채도를 1/3 로 내렸다(#8FC46A 는 90° S38 L59).
const PZVDULL=["#16351A","#2E6B2E","#8FC46A"];
/// 몸이 걷는 길 — **좌우로 천천히.** 지난 뿜음이 그 자리에 남아 **자취**가 된다.
/// ⚠️ `vfx.js` 의 불자취(`mgFireTrail` 18574행)가 같은 이유로 몸을 걷게 한다.
const PZvHX=(t,cx,SC)=>cx+Math.cos(t*.62)*44*SC;
const PZvHY=(t,cy,SC)=>cy+Math.sin(t*1.24)*9*SC;
/// **자취 셋** — [초 전, 알파]. 이것이 「안 꺼지고 남는다」의 전부다.
const PZvGHOST=[[2.1,.11],[1.4,.17],[0.7,.26]];
const PZvSMK=[6,8,11,14,17];      // 연기 뭉치 수

function PZgasVerd(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,FCCONE_F);stepFoes(st.F,dt);
  const LEN=95*SC,HALF=.30;           // ⚠️ 화염방사 확정본과 **같은 값**이다
  const hx=PZvHX(t,cx,SC),hy=PZvHY(t,cy,SC);
  // 판정 — 원뿔. ⚠️ 넉백 없음 · 틱 느림(독은 시간을 판다).
  st.tk=(st.tk||0)+dt;
  if(st.tk>.30){st.tk=0;
    for(const f of st.F){
      const dx=cx+f.ox-hx,dy=cy+f.oy-hy,d=Math.hypot(dx,dy)||1;
      if(d>=LEN+f.r)continue;
      let ad=Math.atan2(dy,dx)-FCDIR;
      while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
      if(Math.abs(ad)>HALF+.14)continue;
      f.pv=Math.min(3,(f.pv||0)+.72);}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.42;
  stepP(st,dt);
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);

  const ST=PKCOL.verd,R=PKtoFire(ST),E=PKENV.ess;
  const NL=PKFNL[LV-1],NB=PKFNB[LV-1];
  PZwithToneArr("ember",PZVDULL,()=>{
    // ⓐ **자취** — 지난 뿜음이 안 꺼지고 그 자리에 남아 있다.
    //   ⚠️ 같은 함수를 **과거 시각 · 과거 몸 자리**로 부르는 것뿐이다. 새 그림이
    //     아니라 **같은 그림의 나이 든 판**이라 바탕이 안 흔들린다.
    for(const[back,al]of PZvGHOST){
      const tt=t-back;
      // ⚠️ **음수 시각을 넘기면 NaN 이 난다.** [PKfBlobs] 가 `((t*spd)%1)` 를
      //   `Math.pow(ph,.86)` 에 넣는데, 음수의 분수 거듭제곱은 NaN 이고 그러면
      //   좌표가 통째로 NaN 이 되어 **아무것도 안 그려진다**(예외도 안 난다).
      if(tt<0)continue;
      PKflameLane(c,tt,PZvHX(tt,cx,SC),PZvHY(tt,cy,SC),SC,LEN,HALF,R,ST,E,
        FCDIR,.21,NL,NB,5.0,al,.15);}
    // ⓑ **지금 뿜는 것** — 알파를 조금 내렸다(형광 죽이기).
    PKflameLane(c,t,hx,hy,SC,LEN,HALF,R,ST,E,FCDIR,.21,NL,NB,5.0,.82,.15);});

  // ⓒ **연기** — 회탁색이 초록과 얼룩덜룩 엉킨다. **가산이 아니다.**
  //   앞의 연기가 뒤의 초록을 **가려야** 두께가 생긴다. 연기는 조금 **뜬다**.
  const ax=Math.cos(FCDIR),ay=Math.sin(FCDIR),nx=-ay,ny=ax,HL=HALF*LEN;
  for(let k=0;k<PZvSMK[LV-1];k++){
    const sd=k*4.13+31;
    const life=2.6*(.75+.55*hash(sd));
    const off=hash(sd+1.7),cyc=Math.floor(t/life+off),ph=(t/life+off)-cyc;
    const s2=sd+cyc*3.7;
    const born=t-ph*life;
    const u=Math.pow(ph,.55);
    const d=LEN*(.10+.80*u),half=E.hw(Math.min(1,u),HL,0,PKjetPow(.15));
    const lat=(hash(s2)-.5)*2*half*.95+E.lat(Math.min(1,u),t,HL);
    const x=PZvHX(born,cx,SC)+ax*d+nx*lat;
    const y=PZvHY(born,cy,SC)+ay*d+ny*lat-u*u*8*SC;
    const rr=half*(.26+.34*hash(s2+2.3))+4*SC;
    const al=Math.min(1,ph*4)*Math.min(1,(1-ph)*2.2);
    if(al<=.01||rr<=.3)continue;
    const tone=PZSMK[u<.34?0:(u<.70?1:2)];
    PZsoft(c,x,y,rr*1.75,tone,al*.30,.94);
    PZsoft(c,x,y,rr*1.08,tone,al*.26,.94);
    PZsoft(c,x,y+rr*.08,rr*.58,PZSMK[0],al*.24,.94);}

  // ⓓ **탁한 막** — 원뿔 위에 회탁을 아주 옅게 깔아 「형광」을 한 번 더 죽인다.
  {const NSm=9;
   for(let i=1;i<=NSm;i++){
     const u=i/NSm,d=LEN*u,half=E.hw(u,HL,7*SC,PKjetPow(.15));
     const lt=E.lat(u,t,HL);
     PZsoft(c,hx+ax*d+nx*lt,hy+ay*d+ny*lt,half*1.15,PZSMK[1],.055,.94);}}
  drawP(c,st);
  hero(c,t,hx,hy);   // ⚠️ 몸이 **걷는다** — 그래야 자취가 자취로 읽힌다
}

/// 몸이 도는 길 — **자취가 남는 것**을 보여 주려고 캐릭터가 천천히 돈다.
/// ⚠️ 뭉치는 **태어난 시각의 몸 자리**에서 나오므로, 이 함수 하나로 「걸어 다니면
///   지나온 자리에 가스가 남는다」가 상태 없이 나온다(과거 위치를 안 저장한다).
// ⚠️ 8자다(가로:세로 주기가 2:1) — 길이 **제 자취를 가로지르게** 해서 「지나온
//   자리에 남았다」가 한 장에 보이게 한다. 이 모양은 `vfx.js` 의 불자취
//   (`mgFireTrail` 18574행: `cos(t*2.4)*64*SC, sin(t*4.8)*40*SC`)가 같은 이유로
//   쓰는 그 길이고, **속도만 2.7배 늦췄다** — 가스는 느리다.
const PZheroAt=(t,cx,cy,SC)=>
  [cx+Math.cos(t*.90)*62*SC, cy+Math.sin(t*1.80)*38*SC];

// ⚠️⚠️ **주인공이 「뿜는 것」에서 「남는 것」으로 바뀌었다** (2026-08-23 사용자:
//   「독 분사가 아니라 **독이 잔상처럼 남는 느낌**… **방구차** 돌아다니는 거」).
//   ⇒ ① 뭉치가 **거의 안 나간다**(`spd` .95 → **.24**) — 태어난 자리에 머문다
//     ② **오래 남는다**(수명 2.5 → **L5 4.4초**) — 그 초가 이 스킬의 정체다
//     ③ **짙다**(뒤가 안 보여야 한다) ④ 색 사다리를 **나이**로 탄다(신선 → 삭음)
//   ⇒ 몸이 지나가면 **길에 자취가 줄지어 남는다.** 그것이 방구차의 그림이다.
const PZaR   =[62,72,82,90,96];      // 뭉치가 커지는 자(238 기준 px · 광주 160 의 39~60%)
/// ⭐ **자취가 남는 시간** — 짧으면 분사고 길면 자취다. 이 수가 이 스킬의 정체다.
const PZaLIFE=[2.6,3.1,3.6,4.0,4.4];
// ⚠️ 첫 렌더가 **성겼다** — 뭉치가 띄엄띄엄해 「가스」가 아니라 「색종이」로
//   보였다. 수를 올리고 하나하나를 키웠다. 잉크는 그래도 원뿔판보다 싸다
//   (**작은 것 여럿이 넓고 큰 하나보다 싸다** — 아래 실측 참조).
const PZaN   =[14,19,24,30,36];      // 초록 뭉치 수
const PZaSMK =[8,11,14,18,22];       // 연기 뭉치 수
const PZaPOOL=[4,5,7,9,11];          // **고인 자취** 수
const PZaDUST=[5,7,9,12,15];         // 가라앉는 알갱이

/// 뭉치 하나의 상태 — **씨앗과 주기에서 전부 파생한다.** 저장하는 것이 없다.
/// 주기가 돌 때마다 씨앗이 바뀌어 방향·크기·속도·수명이 새로 뽑힌다.
function PZaPuff(t,k,cx,cy,SC,R,life0,spd0,rise){
  const life=life0*(.72+.56*hash(k*2.7));
  const off=hash(k*5.3);
  const cyc=Math.floor(t/life+off);
  const sd=k*7.31+cyc*3.17+1.9;
  const ph=(t/life+off)-cyc;
  const age=ph*life;
  const born=t-age;
  const H0=PZheroAt(born,cx,cy,SC);
  const a=hash(sd)*TAU;
  const sp=R*spd0*(.45+1.10*hash(sd+1.3));
  // ⚠️ **거의 안 나간다.** 뿜는 것이 주인공이 아니라 **남는 것**이 주인공이다.
  const d=sp*Math.pow(ph,.42);
  // 대신 **제자리에서 부푼다** — 뭉게뭉게 굴러 퍼지는 것이 그것이다.
  const rr=R*(.17+.24*hash(sd+2.7))*(.34+1.00*Math.pow(ph,.38));
  // **무겁다** — 가라앉는다. 연기만 `rise` 로 조금 뜬다.
  const sink=R*.13*ph*ph-(rise||0)*R*.10*ph;
  return{x:H0[0]+Math.cos(a)*d,y:H0[1]+Math.sin(a)*d*.82+sink,
    r:rr+3*SC,u:ph,sd,ph,      // ⚠️ 색 사다리를 **나이**로 탄다(신선 → 삭음)
    al:Math.min(1,ph*5)*Math.min(1,(1-ph)*2.0)};
}

/// 적 배치 — 몸 **둘레**로 퍼지므로 사방에 세운다.
const PZAFOE=[[-78,-40,13],[10,-84,14],[76,-30,13],[58,52,12],[-52,58,12]];

/// ⭐ **둘레 분사** — 채택본 (다) 「고인다」의 축은 그대로다: **지나간 자리마다
/// 얕은 층이 남아 뒤가 안 빈다.** 이제 「지나간 자리」가 앞이 아니라 **몸이 지나온
/// 자리**라 걸어 다니면 자취가 남는다.
function PZgasAura(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZAFOE);stepFoes(st.F,dt);
  const R=PZaR[LV-1]*SC;
  const M=PZGCOL;
  const HH=PZheroAt(t,cx,cy,SC);
  // ── 판정 — **몸 중심 원 하나.** 넉백 없음 · 틱 느림(독은 시간을 판다).
  st.tk=(st.tk||0)+dt;
  if(st.tk>.30){st.tk=0;
    for(const f of st.F)
      if(Math.hypot(cx+f.ox-HH[0],cy+f.oy-HH[1])<R*.92)
        f.pv=Math.min(3,(f.pv||0)+.72);}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.42;
  stepP(st,dt);
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);

  // ── ⓐ **고인 자취** — 몸이 지나온 자리에 **깔린다.** 제일 짙고 안 움직인다.
  //   맨 뒤에 깔아야 떠 있는 뭉치가 그 위를 지나 「깔린 것 ↔ 뜬 것」이 갈린다.
  for(let k=0;k<PZaPOOL[LV-1];k++){
    const life=PZaLIFE[LV-1]*1.4*(.75+.5*hash(k*3.3));
    const off=hash(k*9.1),cyc=Math.floor(t/life+off),ph=(t/life+off)-cyc;
    const H0=PZheroAt(t-ph*life,cx,cy,SC);
    const sd=k*4.7+cyc*2.3;
    const x=H0[0]+(hash(sd)-.5)*R*.7,y=H0[1]+(hash(sd+1.1)-.5)*R*.4+R*.10;
    const rr=R*(.20+.16*hash(sd+2.2))*(.6+.5*ph);
    const al=Math.min(1,ph*3)*Math.min(1,(1-ph)*2.0)*.55;
    if(al<=.01||rr<=.3)continue;
    const MM=PKmassAt(M,.62);
    PZsoft(c,x,y,rr*1.70,MM[0],al*.46,.38);      // ⚠️ **눌러서 바닥에 붙인다**
    PZsoft(c,x,y,rr*.72,MM[0],al*.24,.38);}

  // ── ⓑ **떠 있는 몸통** — 무작위 뭉치. 방향·크기·속도·수명이 다 다르다.
  const bs=[];
  for(let k=0;k<PZaN[LV-1];k++)bs.push(PZaPuff(t,k,cx,cy,SC,R,PZaLIFE[LV-1],.24,0));
  bs.sort((a,b)=>b.u-a.u);
  for(const b of bs){
    if(b.al<=.02||b.r<=.3)continue;
    const MM=PKmassAt(M,b.u);
    PZsoft(c,b.x,b.y,b.r*1.42,MM[0],b.al*.25,.84);
    PZsoft(c,b.x,b.y-b.r*.06,b.r*1.02,MM[0],b.al*.30,.84);
    // ⚠️⚠️ **너덜너덜한 폴리곤을 통째로 걷었다**(둘레판 렌더 세 번). 알파를
    //   .10 까지 낮추고 안쪽으로 .34 까지 들여도 **곧은 변이 그대로 보여**
    //   화면이 「각진 색종이」가 됐다. 폴리곤은 흐려지지 않는다 —
    //   **가스에는 [PZsoft] 만 쓴다.** 얼룩덜룩함은 초록과 연기가 **겹쳐서** 낸다.
    //   ⚠️ G4(화염방사)의 「너덜너덜한 가장자리」는 **불의 재료**다. 가스는
    //     「가장자리가 사라진다」가 정체라 그 재료를 못 쓴다 — 반대 요구다.
    PZsoft(c,b.x,b.y,b.r*.52,MM[0],b.al*.20,.84);
    // 심 — **아주 좁게.** 넓으면 그게 형광이다.
    PZsoft(c,b.x,b.y-b.r*.10,b.r*.38,MM[1],b.al*.09,.86);
    // 안쪽 결 — 「굼실굼실」
    if(b.r>5*SC){const ga=b.sd*2.3+t*.35,gd=b.r*(.10+.20*hash(b.sd+5.1));
      const gr=b.r*(.20+.18*hash(b.sd+2.7));
      PZsoft(c,b.x+Math.cos(ga)*gd,b.y+Math.sin(ga)*gd,gr,
        PKmassAt(M,Math.max(0,b.u-.30))[1],b.al*.20,.86);}}

  // ── ⓒ ⭐ **연기** — 회탁색이 초록과 얼룩덜룩하게 엉킨다. **가산이 아니다.**
  //   앞의 연기가 뒤의 초록을 **가려야** 「두께」가 생긴다. 초록은 가라앉고
  //   연기는 조금 **뜬다**(`rise`) — 둘이 반대로 움직여야 「섞인 둘」로 보인다.
  for(let k=0;k<PZaSMK[LV-1];k++){
    const b=PZaPuff(t,k+91,cx,cy,SC,R,PZaLIFE[LV-1]*1.15,.30,1);
    if(b.al<=.02||b.r<=.3)continue;
    const tone=PZSMK[b.u<.34?0:(b.u<.70?1:2)];
    // ⚠️⚠️ **연기는 폴리곤을 안 쓴다.** 너덜너덜한 폴리곤을 섞었더니 알파 .22
    //   에서도 **평평한 오각형**이 또렷하게 보여 「색종이」가 됐다(둘레판 둘째
    //   렌더). 연기는 경계가 있으면 안 되는 층이라 **풀리는 원판만** 쓴다.
    PZsoft(c,b.x,b.y,b.r*1.72,tone,b.al*.30,.92);
    PZsoft(c,b.x,b.y,b.r*1.06,tone,b.al*.26,.92);
    PZsoft(c,b.x,b.y+b.r*.08,b.r*.58,PZSMK[0],b.al*.24,.92);}
  // ⚠️ **가산 빛번짐은 안 쓴다**(2026-08-23 반려: 「독형광물질 느낌」).
  //   겹칠수록 밝아지면 형광이고, 가스는 겹칠수록 **짙어져야** 한다.

  // ── ⓓ **가라앉는 알갱이** — 불씨의 자리. 불티는 뜨고 이건 내려앉는다.
  for(let k=0;k<PZaDUST[LV-1];k++){
    const sd=k*3.77+7;
    const life=1.5*(.7+.7*hash(sd));
    const off=hash(sd+2.1),cyc=Math.floor(t/life+off),w=(t/life+off)-cyc;
    const s2=sd+cyc*5.1;
    const H0=PZheroAt(t-w*life,cx,cy,SC);
    const a=hash(s2)*TAU,d=R*(.20+.70*hash(s2+1.3))*Math.pow(w,.6);
    const x=H0[0]+Math.cos(a)*d,y=H0[1]+Math.sin(a)*d*.82+w*w*16*SC;
    const r=SC*(.8+1.9*hash(s2+7.7))*(1-w*.45);
    if(r<=.2)continue;
    fillPoly(c,PKrag(x,y,r,s2,7,.30,s2+t*1.1),
      A(PZGEMBC,Math.min(1,w*8)*(1-w)*(1-w)*.85));}
  drawP(c,st);
  hero(c,t,HH[0],HH[1]);       // ⚠️ 몸이 **움직인다** — 그래야 자취가 자취로 읽힌다
}

/// 적 배치 — 가스는 **넓게 덮는** 것이라 불보다 벌려 세운다.
const PZGFOE=[[-62,-70,10],[6,-96,11],[62,-62,10],[-24,-40,9],[44,-38,9]];
/// 가스의 시뮬 — 화염방사의 `FCsim` 과 **틱·반각·넉백 셋**이 다르다.
function PZgasSim(st,t,dt,cx,cy,SC){
  st.p=st.p||[];
  mgInit(st,SC,PZGFOE);stepFoes(st.F,dt);
  // ⚠️ 불(95·.30)보다 **넓고 멀다** — 가스는 퍼지는 것이라 부채가 벌어진다.
  const LEN=104*SC,HALF=.42;
  st.tk=(st.tk||0)+dt;
  // ⚠️ 틱이 **느리다**(불 .16 ↔ 가스 .30). 독이 파는 것은 한 방이 아니라 시간이다.
  if(st.tk>.30){st.tk=0;
    for(const f of st.F){
      const dx=f.ox+f.kx,dy=f.oy+f.ky,d=Math.hypot(dx,dy)||1;
      if(d>=LEN+f.r)continue;
      let ad=Math.atan2(dy,dx)-FCDIR;
      while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
      if(Math.abs(ad)>HALF+.14)continue;
      // ⚠️ **넉백이 없다.** `hitFoe` 를 안 부른다 — 가스는 밀지 않는다.
      f.pv=Math.min(3,(f.pv||0)+.72);
      f.hit=Math.max(f.hit,.30);}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.42;
  stepP(st,dt);
  return{LEN,HALF};
}
function PZgasRun(c,t,dt,W,H,st,key){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  const{LEN,HALF}=PZgasSim(st,t,dt,cx,cy,SC);
  const E=PZGENV[key];
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);
  // ⚠️ **판정 부채 안내선은 안 그린다**(2026-08-23 사용자 판정).
  PZgasLane(c,t,cx,cy,SC,LEN,HALF,PZGCOL,E,1);
  // 총구 — 불처럼 **번쩍이지 않는다.** 새는 것이라 옅은 김만 오른다.
  gAdd(c,g=>gHalo(g,cx+Math.cos(FCDIR)*LEN*.08,cy+Math.sin(FCDIR)*LEN*.08+3*SC,
    LEN*.10,PZTOX,.22));
  drawP(c,st);hero(c,t,cx,cy);
}

// ══════════════════════════════════════════════════════════════════════════
// ③ 폭마 — **뇌+독.** 시안에만 세운다(엔진 편입 없음)
// ══════════════════════════════════════════════════════════════════════════
//
// 정체는 시안이 이미 정해 뒀다(`vfx.js` 의 확정 안 `FVSET.numb[FVFIX.numb.base-1]`):
//   「**그물이 끊긴다** — 번지던 신호가 죽은 마디 앞에서 멈춘다」
// ⇒ 정체는 **「전달이 멈추는 것」**이고, **뇌+독**이라 그림에 **번개의 각짐**과
//   **독의 번짐**이 **둘 다** 있어야 한다.
//
// ⚠️ **엔진에 안 녹인다** — 특수 열둘은 출시 범위 밖 · 상점 해금 대상이다
//   (사용자 지시: 「특수속성은 실제 소스코드에 녹이진 않을 거지만 미리 페이지
//   만들어서 넣어줘」). 이 둘은 **보관**이다.
// ⚠️ 색은 자염 **자주 307° L54**(`PKT.violet`) · 심 **308° L81**(`PKT.violLt`)이고
//   표식·그물은 `TONE.numb`(320° 자홍)다. ⚠️ **뇌(259~267°)와 40° 차이**라
//   화면에서 뇌 스킬로 읽힐 수 있다 — 칸 설명에 그대로 적어 뒀다.

/// **굳음 표식** — 폭마가 거는 것의 그림. 뇌와 독이 한 표식에 다 들어간다:
///   각진 껍질(굳었다 · 독) + 그 **안에서만** 튀는 짧은 번개(못 나간다 · 뇌).
/// ⚠️ 번개가 껍질 **밖으로 안 나간다** — 그것이 「신호가 멈춘다」의 그림이다.
function PZnumbMark(c,x,y,r,f,t,SC){
  const T=toneOf(PZNUM),al=Math.min(1,f*1.6);
  const P=jagPoly(x,y,r*1.14,9,7.3,1.12);
  fillPoly(c,P,A(T[0],al*.50));
  fillPoly(c,jagPoly(x,y,r*.72,7,3.7,1.06),A(T[1],al*.26));
  c.beginPath();P.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
  c.closePath();c.strokeStyle=A(T[2],al*.85);c.lineWidth=2.2*SC;c.stroke();
  gAdd(c,g=>{
    for(let i=0;i<2;i++){
      const s=((t*6)|0)*3.1+i*7.7+f*.7;      // 0.17초마다 새 경로 — 뇌의 문법
      const a0=hash(s)*TAU,a1=a0+2.0+hash(s+1.3);
      const Q=PKjag(x,y,[Math.cos(a0)*r*.70,Math.sin(a0)*r*.70],
                        [Math.cos(a1)*r*.70,Math.sin(a1)*r*.70],s,r*.40,4);
      gStroke(g,Q,2.4*SC,PZNUM,al*.80);}});
}
function PZnumbMarks(c,t,cx,cy,F,SC){
  drawFoes(c,t,cx,cy,F);
  for(const f of F)if(f.pv>0)
    PZnumbMark(c,cx+f.ox+f.kx,cy+f.oy+f.ky,f.r,f.pv,t,SC);
}

/// 잠깐 팔레트를 바꿔 남의 함수를 부른다.
/// ⚠️ **왜 이런 짓을 하나**: `PKflameLane` 은 확정된 화염방사의 재료 여덟을 통째로
///   가진 함수인데, 안에서 후광 색을 `"ember"` 로 **직접 적어** 넣었다. 사본을
///   뜨면 「같은 재료」라는 말이 그 날로 거짓이 된다 ⇒ 표만 잠깐 갈아 끼운다.
/// ⚠️ **동기 한 프레임 안에서 끝나고 `finally` 로 되돌린다** — `tile()` 이
///   `RECOLOR`·`LV` 로 쓰는 그 수법 그대로다.
function PZwithTone(k,to,fn){
  const sv=TONE[k];TONE[k]=TONE[to];
  try{fn();}finally{TONE[k]=sv;}
}

/// **안쪽 결만 번개로** — 실핏줄. 불의 덩어리 **안에서** 짧게 흐른다.
/// ⚠️ 가는 획을 많이 깔면 거미줄이 된다(낙광 여덟이 그렇게 떨어졌다).
///   ⇒ 획을 **적게(레벨당 2~4) · 굵게(2.6px) · 짧게(덩어리 하나 길이)** 만 긋는다.
const PZVEIN=[2,3,3,4,4];
function PZveins(c,t,cx,cy,SC,LEN,HALF,E,ang,jet){
  const ax=Math.cos(ang),ay=Math.sin(ang),nx=-ay,ny=ax,HL=HALF*LEN;
  const pw=PKjetPow(jet);
  gAdd(c,g=>{
    for(let k=0;k<PZVEIN[LV-1];k++){
      const step=((t*5)|0)*2.7+k*13.1;        // 0.2초마다 새 길 — 뇌의 문법
      const u0=.10+.15*k+.08*hash(step),u1=Math.min(.92,u0+.30+.14*hash(step+1.7));
      const p=(u)=>{const d=LEN*u,w=E.hw(u,HL,0,pw)*.44*(hash(step+u*7)-.5)*2;
        const lt=E.lat(u,t,HL);
        return[ax*d+nx*(lt+w),ay*d+ny*(lt+w)];};
      const Q=PKjag(cx,cy,p(u0),p(u1),step,HL*.30,5);
      // ⚠️ **굵어야 한다.** 가는 획을 여럿 깔면 그게 곧 거미줄이다.
      gStroke(g,Q,3.6*SC,PZNUM,1);
      // 끝에서 **한 번 갈라진다** — 곁가지 하나뿐이다(많으면 거미줄).
      if(atL(3))gStroke(g,PKjag(0,0,Q[3],
        [Q[4][0]+(hash(step+3.3)-.5)*HL*.42,Q[4][1]+(hash(step+5.1)-.5)*HL*.30],
        step+9,HL*.16,3),2.0*SC,PZNUM,.60);}});
}

/// ⭐ (A) **저림** — 자주 불꽃 **안쪽에 보라 번개가 실핏줄처럼 흐른다.**
/// 맞은 적은 그 자리에서 **굳는다.** 확정된 화염방사 재료(G4)를 그대로 쓰고
/// **안쪽 결만** 번개로 바꾼 것이다 — 뇌와 독이 한 화면에 같이 선다.
function PZnumbA(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZGFOE);stepFoes(st.F,dt);
  const LEN=95*SC,HALF=.30;
  st.tk=(st.tk||0)+dt;
  if(st.tk>.20){st.tk=0;
    for(const f of st.F){
      const dx=f.ox+f.kx,dy=f.oy+f.ky,d=Math.hypot(dx,dy)||1;
      if(d>=LEN+f.r)continue;
      let ad=Math.atan2(dy,dx)-FCDIR;
      while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
      if(Math.abs(ad)>HALF+.12)continue;
      // ⚠️ 넉백 0 — **굳는 것**이라 안 밀린다. 밀면 「굳었다」가 깨진다.
      f.pv=Math.min(3,(f.pv||0)+.85);f.hit=Math.max(f.hit,.28);}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.50;
  stepP(st,dt);
  PZnumbMarks(c,t,cx,cy,st.F,SC);
  const ST=PKCOL.viol,R=PKtoFire(ST),E=PKENV.ess;
  // ⚠️ 재료는 **화염방사 확정본 그대로** 부른다(제트 .15 · S자 · 진폭 .33).
  PZwithTone("ember",PZNUM,()=>{
    PKflameLane(c,t,cx,cy,SC,LEN,HALF,R,ST,E,FCDIR,.21,
      PKFNL[LV-1],PKFNB[LV-1],5.0,1,.15);});
  PZveins(c,t,cx,cy,SC,LEN,HALF,E,FCDIR,.15);
  gAdd(c,g=>gFlare(g,cx,cy-5*SC,8*SC,PZNUM,.95,FCDIR,4));
  drawP(c,st);hero(c,t,cx,cy);
}

// ── (B) 끊긴 그물 ─────────────────────────────────────────────────────────
// 시안 문구를 **그대로 그림으로** 만든 것이다: 뿜은 것이 적들 사이를 그물처럼
// 잇는데 **중간중간 끊겨 있고**, 끊긴 자리가 이미 마비된 적이다.
//
// ⚠️⚠️ **거미줄로 반려당할 위험이 제일 큰 안이다.** 사용자가 낙광 여덟을 그
//   이유로 떨어뜨렸다(「솜사탕 실이 엉키듯이 거미줄」). 실패 조건 넷을 전부
//   뒤집어 세웠다:
//     ① 획이 가늘다   → **속 빈 두께**(`PKboltThick`)로 굵게. 마디마다 굵기가 튄다
//     ② 갈래가 많다   → 잇는 줄이 **넷뿐**이다(사슬 하나, 곁가지 없음)
//     ③ 굵기가 균일   → 굵기 곡선을 주고 마디마다 흔든다
//     ④ 서로 엉킨다   → **사슬**이라 교차가 없다
//   그리고 **마디를 덩어리로** 세웠다 — 매듭이 점이면 선만 남아 거미줄이 된다.
const PZBFOE=[[-66,-30,11],[-24,-72,10],[34,-70,11],[70,-16,10],[26,34,9]];
/// 죽은 마디 — **이미 마비된 적.** 신호가 여기서 멈춘다.
/// ⚠️ 레벨이 오르면 **살아 있는 마디가 늘어난다**(신호가 더 멀리 간다).
const PZBRUN=[2,2,3,3,4];
function PZnumbB(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZBFOE);stepFoes(st.F,dt);
  const F=st.F,n=F.length;
  const K=Math.min(PZBRUN[LV-1],n-1);       // 신호가 닿는 마디 수
  const per=2.30,u=(t%per)/per;
  const run=Math.min(1,u/.62);              // 앞으로 달린다 → 끊긴 자리에서 멎는다
  const stop=Math.max(0,Math.min(1,(u-.62)/.16));   // 멎은 뒤의 한 박자
  // ⚠️⚠️ **죽은 마디가 먼저 마비돼 있다** — 그것이 「신호가 멎는」 **이유**다.
  //   순서를 거꾸로 두면(신호가 지나가며 죽인다) 그림이 「연쇄」가 되어
  //   뇌의 문법이 되고, 폭마의 정체(전달이 **안 되는** 것)가 사라진다.
  for(let i=0;i<n;i++){
    if(i>=K){F[i].pv=3;continue;}                 // 죽은 마디 — 늘 굳어 있다
    if(i<K*run)F[i].pv=Math.min(2.2,(F[i].pv||0)+dt*2.2);}
  for(let i=0;i<K;i++)if(F[i].pv>0)F[i].pv-=dt*.55;
  stepP(st,dt);
  const T=toneOf(PZNUM);
  const at=(i)=>i<0?[cx,cy]:[cx+F[i].ox+F[i].kx,cy+F[i].oy+F[i].ky];

  // ── ⓐ 독의 번짐 — 사슬 아래 깔리는 **흐린 띠.** 선만 있으면 뇌뿐이다.
  //    ⚠️ 이 한 겹이 「번진다」를 낸다 — 없으면 그림이 통째로 뇌가 된다.
  for(let s=-1;s<K;s++){
    const a=at(s),b=at(s+1);
    const on=(s+1)<=K*run?1:0;if(!on)continue;
    const P=[];
    for(let i=0;i<=6;i++){const p=i/6;
      P.push([a[0]+(b[0]-a[0])*p+Math.sin(p*3.1+t*.9+s)*5*SC,
              a[1]+(b[1]-a[1])*p+Math.cos(p*2.7+t*.8+s)*5*SC]);}
    celRibbonEven(c,P,13*SC,PZNUM,.30,false);}

  // ── ⓑ 그물 — **굵은 사슬 하나.** 곁가지가 없다.
  gAdd(c,g=>{
    for(let s=-1;s<n-1;s++){
      const a=at(s),b=at(s+1);
      const live=(s+1)<K;                    // 살아 있는 마디까지가 이어져 있다
      const seed=(s+2)*31+((t*8)|0)*3;
      const P=PKjag(0,0,a,b,seed,16*SC,6);
      if(live){
        const drawn=Math.max(0,Math.min(1,(K*run-(s+1))+1));
        const kk=Math.max(2,Math.round((P.length-1)*drawn)+1);
        // **속 빈 두께** — 폭은 굵고 칠한 것은 획 셋이다.
        PKboltThick(g,P.slice(0,kk),7.2*SC,PZNUM,.95,seed,
          (v)=>.42+.58*Math.sin(Math.PI*Math.min(1,v*1.02+.02)));
      }else{
        // **끊겼다** — 양쪽에서 짧게 나오다 허공에서 끝난다. 가운데가 비어 있다.
        //   ⚠️ 살아 있는 쪽 토막이 **굵고**, 죽은 마디 쪽 토막은 **가늘고 어둡다** —
        //     어디까지 갔고 어디서 못 갔는지가 굵기로 읽힌다.
        const A1=P.slice(0,3),B1=P.slice(4);
        PKboltThick(g,A1,4.8*SC,PZNUM,.55,seed,(v)=>.70-.48*v);
        PKboltThick(g,B1,3.0*SC,PZNUM,.22,seed+7,(v)=>.16+.34*v);}}});

  // ── ⓒ 마디 — **덩어리다.** 점으로 두면 선만 남아 거미줄이 된다.
  PZnumbMarks(c,t,cx,cy,F,SC);
  for(let i=0;i<n;i++){
    const p=at(i),r=F[i].r;
    if(i<K){
      // 살아 있는 마디 — 밝은 덩어리 + 가산 심.
      fillPoly(c,jagPoly(p[0],p[1],r*.62,7,i*3.1,1.10),A(T[1],.55));
      fillPoly(c,jagPoly(p[0],p[1],r*.34,7,i*4.7,1.06),A(T[2],.80));
      gAdd(c,g=>gHalo(g,p[0],p[1],r*.95,PZNUM,.30));
    }else{
      // **죽은 마디** — 어둡고 각진 덩어리가 굳음 껍질 **안에** 앉는다.
      //   여기서 신호가 멈춘다. 밝은 마디와 **명도로** 갈린다(색은 같다).
      const Q=jagPoly(p[0],p[1],r*.58,7,i*5.3,1.14);
      fillPoly(c,Q,A(T[0],.95));
      c.beginPath();Q.forEach((v,k)=>k?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
      c.closePath();c.strokeStyle=A(T[1],.75);c.lineWidth=2.6*SC;c.stroke();}}

  // ── ⓓ 신호 — 사슬을 달리다 **죽은 마디 앞에서 멎는다.** 이 장의 전부다.
  const idx=Math.min(K-1,Math.floor(run*K));
  const loc=Math.max(0,Math.min(1,run*K-idx));
  const a=at(idx-1),b=at(idx);
  const sx=a[0]+(b[0]-a[0])*loc,sy=a[1]+(b[1]-a[1])*loc;
  const sa=Math.min(1,u/.07)*Math.min(1,(1-u)/.20);
  if(sa>.01){
    gAdd(c,g=>{
      gFlare(g,sx,sy,5.2*SC*(1-stop*.4),PZNUM,.95*sa,t*3,4);
      // 멎은 자리에서 **되튄다** — 못 넘은 것이 눈에 보인다.
      if(stop>0){
        const bx=at(Math.min(K,n-1));
        gHalo(g,bx[0],bx[1],F[Math.min(K,n-1)].r*1.5*stop,PZNUM,.42*(1-stop)*sa);
        for(let k=0;k<4;k++){
          const ang=Math.atan2(sy-bx[1],sx-bx[0])+(k-1.5)*.5;
          const d=F[Math.min(K,n-1)].r*(.9+stop*1.5);
          gStroke(g,[[bx[0]+Math.cos(ang)*F[Math.min(K,n-1)].r*.7,
                      bx[1]+Math.sin(ang)*F[Math.min(K,n-1)].r*.7],
                     [bx[0]+Math.cos(ang)*d,bx[1]+Math.sin(ang)*d]],
            2.2*SC,PZNUM,.55*(1-stop)*sa);}}});}
  drawP(c,st);hero(c,t,cx,cy);
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 독침 — **바늘 같은 빛이 독침처럼 꽂힌다**              (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「독표창의 경우에는 **'바늘' 같은 형태의 '빛'이 '독침처럼' 꽂히도록**」
//
// ⚠️ **표창(날 넷 · 회전)은 버린다.** 바늘은 안 돈다. 함수 `PZdartA/B/C` 는
//   그대로 살아 있고 목록에서만 뺐다.
// ⭐ **채택본에서 살린 것 둘** — 「반쯤 잠긴다」와 「독이 몸을 타고 번진다」.
//   그 둘이 「독침」과 정확히 맞아서 그대로 왔다(오히려 더 맞는다: 벌침이다).
//
// ── 셋이 다 들어가야 한다 ─────────────────────────────────────────────────
//   **바늘**   가늘고 길다. 날개도 회전도 없다 — 길이 **30** · 굵기 **2.2**(238 기준)
//   **빛**     속이 밝고 가장자리로 풀린다. `vfx.js` 의 빛 붓을 그대로 쓴다:
//              [gLance](날카로운 머리) · [gStroke](네 번 덧그어 심이 희다) · [gHalo]
//   **독침**   **박히는 것이 정체**다. 꽂힌 뒤 독이 **몸 안으로 주입**된다
//
// ── 「꽂힌 뒤가 본론이다」 ────────────────────────────────────────────────
//   나는 시간 **0.26초** · 박혀 있는 시간 **1.5~2.3초** = **6~9배**.
//   빛은 식고(`lit=1-su*.86`) 독은 진해진다 — 그것이 독의 동사
//   (「깔아 두고 나중에 값이 난다」)가 그림이 되는 자리다.
//
// ── ⚠️ 겹치면 안 되는 둘 ─────────────────────────────────────────────────
//   유도탄 `seeker` — 가늘고 길고 날아간다. 갈리는 자리: **저쪽은 휘어 쫓고**
//     (코일 꼬리가 궤적을 따라 감긴다) **이쪽은 곧게 간다.** 그래서 경로에
//     **휨을 한 톨도 안 넣었다**(앞 표창판의 `bend` 를 뺐다). 그리고 유도탄은
//     닿으면 **없어지고** 바늘은 **남는다**.
//   ⭐ 갈리는 진짜 자리는 **「맞은 뒤에 화면에 남는다」**이고, 일반 계열 열하나 중
//     그런 것이 **0종**이다.
//
// ── 색 — **빛과 독을 갈랐다** ────────────────────────────────────────────
//   빛  `#E6FFEA` **130° · L95** (`TONE.toxin` 의 앞날) + [gLance]/[gStroke] 의 흰 심
//   독  `#123D1C` **134° · L16** (같은 팔레트의 바닥)
//   ⇒ 색상은 **4° 차이**인데 밝기가 **79 포인트** 벌어져 있어 「빛 ↔ 묻은 것」으로
//     갈린다. ⚠️ 바늘 몸에 `#57D96B`(129° L59)를 쓰면 다시 「독 물건」이 된다.
// ══════════════════════════════════════════════════════════════════════════
// ── ⭐ 성장 — **사용자가 축을 정했다** (2026-08-23) ──────────────────────
// 「레벨업이 올라갈수록 **발사 갯수 늘려**주고, **동시발사 갈래 늘려**줘」
// ⚠️ **둘은 다른 축이다**: 「갯수」는 **시간**(연달아 나간다) · 「갈래」는 **공간**
//   (한 번에 같이 나간다). 둘 다 자란다.
//     L1  1발·1갈래 = 침 1   L2  2발·1갈래 = 2   L3  2발·2갈래 = 4
//     L4  3발·2갈래 = 6      L5  각성 3발·3갈래 = **9**
// ⚠️ **갈래를 부채로 안 편다** — 그건 산탄(`scatter`)의 문법이고 표창판에서 이미
//   피하기로 정했다. **나란히** 나가되 앞뒤로 조금 어긋난다(`PZnSKEW`) — 그래야
//   한 줄로 겹쳐 보이지 않으면서도 부채가 안 된다. 유도탄과도 안 닮는다(안 휜다).
// ⚠️ **다른 축은 레벨을 안 탄다** — 길이 30 · 굵기 3.6 · 꽂혀 있는 시간 2.0초는
//   다섯 칸이 **전부 같다**. 사용자가 말한 둘만 자란다.
// ⚠️⚠️ **축이 셋이고 내가 앞판에서 둘을 헷갈렸다**(2026-08-23 사용자 정정):
//   **발사 갯수** 한 번 쏠 때 **연속으로** 몇 발 — 「뿅, 뿅뿅, 뿅뿅뿅…」 **1자로**
//   **갈래(표적)** **동시에 몇 명**을 겨누나 — **서로 다른 적**이다(같은 적에 여럿 X)
//   **스택**       같은 적이 **3번 연속 맞으면 폭발** — 새 장치
// ⭐ **L3 이 분기점**이다 — 3발이면 **한 번의 연사로 스택 3이 차서 터진다.**
//   그 전(L1·L2)에는 **두 번 쏴야** 터진다.
// ⭐ **표적 2 는 L4 부터**로 제안한다 — L3 에서 「한 연사로 터진다」를 먼저 배우고,
//   L4 에서 그것을 **둘에게 동시에** 하는 것이 사다리로 읽힌다.
const PZnSHOT=[1,2,3,4,5];                // 발사 갯수(연사) — 뿅 … 뿅뿅뿅뿅뿅
const PZnTGT =[1,1,1,2,2];                // 동시 표적 수 — **서로 다른 적**
const PZnDW  =2.00;                       // 박혀 있는 시간(초) — **레벨을 안 탄다**
const PZnBURST=.13;                       // 연사 간격(초)
// ── 스택 (시안 장치 · 엔진에 없다 — 이식할 때 쓸 값을 표로 적어 둔다) ──────
const PZnSTKMAX=3;                        // 스택 상한 — 여기서 터진다
const PZnSTKHOLD=2.6;                     // 스택 유지 시간(초) — 안 맞으면 풀린다
// ── 폭발 · 넉백 (시안 장치 · 엔진에 없다 — 이식할 때 쓸 값) ──────────────
//   폭발 반경 **34** · 보이는 시간 **0.62초**(정지 0.09 + 터짐 0.53)
//   넉백 **밖으로 26**(238 기준) · 감쇠 `0.86^(60·dt)`(엔진 `stepFoes` 와 같다)
//   경직 **0.35초** — 밀린 뒤 잠깐 못 움직인다(시안에서는 자국으로만 보인다)
// ⚠️⚠️ **사용자가 두 번 물었다** — 「3스택에 터질 때 **폭탄 터지듯이 효과 크게**
//   내달라니까? **아직 구현 안 한 건가?**」. 층은 다 들어가 있었는데 **작았다**:
//   반경 34 는 **칸의 14%**(침 길이 30 과 거의 같다)라 「펑」이 아니라 「톡」이고,
//   보이는 시간 .45 초는 240프레임 중 27프레임뿐이라 **구운 그림이 거의 못 잡았다.**
//   ⇒ **반경을 세 값으로 세우고** 시간을 **.95 초**로 늘렸다.
// ⭐ **반경 50 확정**(2026-08-23 사용자: 「독표창 폭발반경 50으로 고고」).
//   34/70/110 나란히 세우기는 끝났다 — 함수 인자로만 남긴다.
const PZnBOOMRS=[50,70,110];              // [0] 이 확정값 — 칸의 21%
const PZnBOOMT=.95;                       // 폭발이 보이는 시간(초)
const PZnFREEZE=.09;                      // ⭐ **터지기 전 한 박자 정지** — 무게는 여기서 난다
const PZnKB=26;                           // 넉백 거리(238 기준 px)
const PZnSHARD=7;                          // 부러져 튀는 침 조각
// ⚠️⚠️ **「면봉」으로 반려당했다**(2026-08-23 사용자: 「독침은 바늘이 아니라
//   면봉이구만 ㅋㅋ **존나 긴 면봉**이네」). 원인이 넷이고 넷 다 고쳤다:
//     ① **양 끝이 둥글었다** — [gStroke] 는 `lineCap="round"` 로 획을 긋는다.
//        둥근 마감이 양쪽에 붙으면 그게 **면봉**이다. ⇒ 획을 버리고 **뾰족한
//        폴리곤**([PZspikePoly])을 직접 그린다. **앞끝의 폭이 0** 이다.
//     ② **가운데가 가늘고 양끝이 굵었다** — [gLance] 의 타원이 끝에 붙어서다.
//        ⇒ 앞은 **한 점**, 몸통은 굵고, 뒤끝만 **살짝 두툼**(손잡이).
//     ③ **너무 길었다**(30) — 몸에서 적까지 거의 닿아 「이어진 막대」였다.
//        ⇒ 길이를 **세 값**으로 세워 고르게 한다.
//     ④ **발광이 끝에 뭉쳐 있었다** — ⇒ 후광은 **꽂힌 자리(뒤끝)에만**.
const PZnW=3.6;                            // 굵기(238 기준 px) — 셋이 같다
/// 길이 세 값 — **이 축만 갈린다.** ⚠️ 너무 짧으면 「초록 알갱이」로 돌아간다
/// (표창판에서 반지름 11.5 로 겪은 그것) — 그래서 12 가 하한이다.
const PZnLENS=[30,18,12];
const PZnFOE=[[-74,-44,16],[46,-74,16],[80,20,15],[-46,34,15]];

/// **침의 실루엣** — 앞끝이 **한 점**, 몸통이 굵고, 뒤끝만 살짝 두툼하다.
/// ⚠️ 양쪽이 둥글면 면봉이고, 앞이 뾰족하고 뒤가 두툼하면 **침·다트**다.
/// [tipx,tipy] 는 **바늘 끝**이고 [ang] 은 그 끝이 향하는 쪽(= 파고드는 쪽)이다.
function PZspikePoly(tipx,tipy,ang,L,w,tail){
  const ca=Math.cos(ang),sa=Math.sin(ang),px=-sa,py=ca;
  const at=(k,ww)=>[tipx-ca*L*k+px*ww,tipy-sa*L*k+py*ww];
  return[[tipx,tipy],                    // ⬅ **폭 0** — 여기가 침을 침으로 만든다
    at(.26,w*.58),at(.66,w),at(.90,w*tail),at(1,w*tail*.52),
    at(1,-w*tail*.52),at(.90,-w*tail),at(.66,-w),at(.26,-w*.58)];
}
/// 바늘 하나 — **빛.** [px] 0 = 갓 쏜 빛 · 1 = 다 식고 독만 남았다.
/// [k0]~[k1] 은 그릴 구간이다(0=꽁무니, 1=바늘 끝) — 반쯤 잠긴 것을 앞뒤로 나눠
/// 그릴 때 쓴다. 잠긴 몫은 적보다 **먼저**, 드러난 몫은 **나중에**.
function PZneedle1(c,tipx,tipy,ang,L,w,al,px){
  const p=px||0,lit=1-p*.86;
  const TX=toneOf(PZTOX);
  const P=(k)=>PZspikePoly(tipx,tipy,ang,L,w*k,1.35);
  // ⓐ **빛의 몸** — 같은 뾰족 폴리곤을 폭만 줄여 네 겹. 가산이라 **속이 희다**.
  //   ⚠️ [gStroke] 를 안 쓴다 — 그 함수의 둥근 마감이 면봉을 만들었다.
  //   ⚠️ 층 구성은 그 함수와 **같은 사다리**다(어두움 → 몸통 → 앞날 → 흰 심).
  gAdd(c,g=>{
    fillPoly(g,P(1  ),A(TX[0],.55*al*lit));
    fillPoly(g,P(.62),A(TX[1],.75*al*lit));
    fillPoly(g,P(.30),A(TX[2],.95*al*lit));
    fillPoly(g,P(.12),A("#FFFFFF",.90*al*lit));});
  // ⓑ **묻은 독** — 가산이 아니다. **뒤쪽 절반**에만 묻어 있다.
  //   ⚠️ 침 전체를 초록으로 칠하지 마라 — 그러면 「독으로 만든 침」이다.
  const ca=Math.cos(ang),sa=Math.sin(ang),nx=-sa,ny=ca;
  const at=(k,ww)=>[tipx-ca*L*k+nx*ww,tipy-sa*L*k+ny*ww];
  const w2=w*(.72+.45*p);
  fillPoly(c,[at(.52,w2*.42),at(.90,w2*1.10),at(1,w2*.60),
              at(1,-w2*.60),at(.90,-w2*1.10),at(.52,-w2*.42)],
    A(TX[0],(.62+.32*p)*al));
  // ⓒ **뒤끝의 독 방울** — 맺혀 있다가 꽂히면 몸으로 들어간다.
  const e=at(1,0),r=w*(.62+.55*p);
  if(r>.3)fillPoly(c,PKrag(e[0],e[1],r,ang*7.3,7,.34,ang),A(TX[0],(.72+.28*p)*al));
}

/// ⭐ **주입** — 꽂힌 자리에서 독이 **몸 안으로** 번져 들어간다(밖으로 뿜는 게
/// 아니다). 벌침이 그렇다. `su` 를 따라 자국이 커지고 짙어진다.
/// ⚠️ 적의 실루엣 안에서만 자란다 — 밖으로 나가면 「뿜었다」가 되어 뜻이 바뀐다.
function PZinject(c,x,y,fx,fy,r,su,SC,al){
  const TX=toneOf(PZTOX),g=Math.min(1,su*1.25);
  if(g<=.02)return;
  c.save();c.beginPath();
  const S=jagPoly(fx,fy,r*1.04,9,7.3,1.10);
  S.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
  c.closePath();c.clip();
  // 찔린 자리에서 몸 중심 쪽으로 번진다 — 세 겹이 크기만 다르다.
  // ⚠️ 자국이 **적의 몸(거의 검다) 위에서 보여야** 한다 — 바닥 톤만 쓰면 묻힌다.
  //   바깥은 짙게, 안으로 갈수록 밝게 세 겹.
  const MID=mixHex(TX[0],TX[1],.55);
  for(const[k,aa,col]of[[1.15,.34,TX[0]],[.72,.40,MID],[.38,.42,TX[1]]]){
    const bx=x+(fx-x)*g*.75,by=y+(fy-y)*g*.75;
    const rr=r*(.22+.86*g)*k;
    if(rr>.3)fillPoly(c,PKrag(bx,by,rr,x+k*3.1,11,.30,x*.3+k),A(col,aa*g*al));}
  c.restore();
  // 찔린 점 — 작고 진한 자국 하나. 「여기로 들어갔다」
  if(r*.12>.3)fillPoly(c,PKrag(x,y,r*.12+1.2*SC,y*.7,7,.30,x),A(TX[0],.9*al));
}

function PZneedleRun(c,t,dt,W,H,st,LEN,BOOMR){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZnFOE);stepFoes(st.F,dt);
  const NS=PZnSHOT[LV-1],NT=PZnTGT[LV-1],N=NS*NT,DW=PZnDW;
  // ⚠️ **나는 시간이 짧고 박혀 있는 시간이 길다** — 6~9배. 「꽂힌 뒤가 본론」이다.
  const FLY=.26,GAP=.30,PER=FLY+DW+GAP;
  const L=(LEN||PZnLENS[0])*SC,w=PZnW*SC;
  const BR0=(BOOMR||PZnBOOMRS[0])*SC;
  if(!st.nq||st.nq.length!==N){
    st.nq=[];
    // ⚠️ **표적(b)마다 한 줄**이고, 그 줄 안에서 **발(a)이 연사**로 나간다.
    //   같은 표적으로 가는 것들은 **같은 직선** 위에 있고 시간만 어긋난다(1자).
    for(let b=0;b<NT;b++)for(let a=0;a<NS;a++){
      st.nq.push({i:b*NS+a,shot:a,tgt:b,lane:0,
        u:(a*PZnBURST)%PER,
        fi:(b*2)%PZnFOE.length,ax:0,ay:0,hit:0,seed:(b*7+a)*5.77+2.3});}}
  for(const q of st.nq){
    const pu=q.u;q.u=(q.u+dt)%PER;
    if(q.u<pu){
      q.fi=(q.fi+NT*2)%st.F.length;q.hit=0;
      // 꽂히는 자리 — **날아온 쪽**(몸에서 본 가까운 면)에 흔들림을 준다.
      const g=st.F[q.fi],base=Math.atan2(g.oy,g.ox)+Math.PI;
      const a=base+(hash(q.seed+q.fi*2.7)-.5)*1.2;
      q.ax=Math.cos(a)*.92;q.ay=Math.sin(a)*.92;}
    const f=st.F[q.fi];
    if(!q.hit&&q.u>=FLY){
      q.hit=1;
      const dx=f.ox,dy=f.oy,d=Math.hypot(dx,dy)||1;
      // ⚠️ 넉백이 **거의 없다** — 바늘은 미는 물건이 아니다.
      hitFoe(st,f,cx,cy,dx/d,dy/d,1.4*SC,PZTOX);
      f.pv=Math.min(3,(f.pv||0)+1.0);
      // ⭐ **스택** — 꽂힌 침 수가 곧 스택이다. 셋이 차면 터진다.
      if(t-(f.stkT||-9)>PZnSTKHOLD)f.stk=0;      // 오래 안 맞으면 풀린다
      f.stk=(f.stk||0)+1;f.stkT=t;
      if(f.stk>=PZnSTKMAX){f.stk=0;f.boom=t;
        // ⭐ **넉백** — 몸에서 바깥으로 민다. 「밀렸다」가 보여야 3타가 값이 산다.
        f.kx+=dx/d*PZnKB*SC;f.ky+=dy/d*PZnKB*SC;
        f.kb0=[cx+f.ox+f.kx,cy+f.oy+f.ky];   // 밀리기 전 자리 — 자국을 그린다
        emit(st,cx+f.ox+f.kx,cy+f.oy+f.ky,22,
          {k:PZTOX,sp:190,r:3.0,life:.62,g:40,spikeP:.60});}}
    if(q.u>=FLY&&q.u<FLY+DW)f.pv=Math.min(3,(f.pv||0)+dt*.66);}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.30;
  stepP(st,dt);

  // 자리를 재는 도우미 — 꽂힌 점과 각도.
  const spot=(q)=>{const f=st.F[q.fi];
    let x=cx+f.ox+f.kx+f.r*q.ax,y=cy+f.oy+f.ky+f.r*q.ay;
    const ang=Math.atan2(y-cy,x-cx);
    // ⚠️ **밀지 않는다** — 「갈래」는 **표적 수**이지 탄의 배치가 아니다(2026-08-23
    //   사용자 정정). 같은 표적으로 가는 것들은 **같은 직선** 위에 시간만 어긋나
    //   있다 — 그것이 「1자로 뿅뿅뿅」이다.
    return{f,x,y,ang,ox:0,oy:0};};

  // ── ⓐ **잠긴 몫** — 적보다 먼저. 몸이 그대로 마스크가 되어 「반쯤 잠겼다」가 난다.
  for(const q of st.nq){
    if(q.u<FLY||q.u>=FLY+DW)continue;
    const su=(q.u-FLY)/DW,S=spot(q);
    const fade=Math.min(1,(1-su)*4.2)*Math.min(1,su/.05);
    if(fade<=.01)continue;
    // **잠긴 몫** — 바늘 끝이 몸 **안**에 있다. 온전한 침을 그리면 몸이 절반을 먹는다.
    //   ⚠️ [ang] 은 **파고드는 쪽**(몸 → 적)이라 뒤끝이 밖으로 남는다.
    const into=S.ang;
    const tx=S.x+Math.cos(into)*L*.45,ty=S.y+Math.sin(into)*L*.45;
    PZneedle1(c,tx,ty,into,L,w,.85*fade,su);}
  mgMarks(c,t,cx,cy,st.F,"poison",PZTOX,SC);

  // ── ⓑ **날아가는 중** — **곧게** 간다(유도탄과 갈리는 자리).
  for(const q of st.nq){
    if(q.u>=FLY)continue;
    const uu=q.u/FLY,S=spot(q);
    // 출발점도 같이 밀어야 **평행**이 된다(밀지 않으면 부채가 된다).
    const sx=cx+S.ox,sy=cy+S.oy;
    const dx=S.x-sx,dy=S.y-sy;
    const x=sx+dx*uu,y=sy+dy*uu;
    const ang=Math.atan2(dy,dx);
    // 잔상 — 두 겹. 빠른 물건이라 이것이 속도를 말한다.
    for(let k=2;k>=1;k--){
      const v=uu-k*.075;if(v<=0)continue;
      PZneedle1(c,sx+dx*v,sy+dy*v,ang,L,w*.9,(.26-k*.07),0);}
    PZneedle1(c,x,y,ang,L,w,1,0);}

  // ── ⓒ **드러난 몫 + 주입** — 여기가 본론이다.
  for(const q of st.nq){
    if(q.u<FLY||q.u>=FLY+DW)continue;
    const su=(q.u-FLY)/DW,S=spot(q);
    const fade=Math.min(1,(1-su)*4.2)*Math.min(1,su/.05);
    if(fade<=.01)continue;
    // **드러난 몫** — 꽂힌 점을 끝으로 하는 짧은 침. 뒤끝이 밖에 남는다.
    PZneedle1(c,S.x,S.y,S.ang,L*.55,w*.88,fade,su);
    // **주입** — 몸 안으로 번져 들어간다.
    PZinject(c,S.x,S.y,cx+S.f.ox+S.f.kx,cy+S.f.oy+S.f.ky,S.f.r,su,SC,fade);
    // 꽂힌 점의 빛 — 식는다.
    gAdd(c,g=>gHalo(g,S.x,S.y,w*4.2,PZTOX,.60*fade*(1-su*.86)));}

  // ── ⓓ **스택 폭발** — 셋이 찬 순간. 「펑」이다.
  //   ⚠️⚠️ **화려함은 「같은 재료를 더」가 아니라 「다른 종류를 겹치는 것」**이다 —
  //     사용자가 화염방사·낙광에 같은 말로 지적했고 답이 같았다(「불씨라던가
  //     빛이라던가 **레이어가 섞여야**」). 그래서 일곱 층을 겹쳤다:
  //     ⓪ 정지 한 박자 ① 번쩍(불규칙) ② 충격파 **속 빈 테** ③ **부러진 침**
  //     ④ 독이 확 번짐 ⑤ 알갱이 ⑥ 잔광 ⑦ 밀린 자국
  //   ⚠️ **큰 반투명 면을 안 쓴다** — 이 게임의 병목이 GPU 채우기다. 테는 **획**,
  //     번쩍은 **작고 불규칙한 폴리곤**, 조각은 **스프라이트**다.
  const TXe=toneOf(PZTOX);
  for(const f of st.F){
    if(f.boom===undefined)continue;
    const el=t-f.boom;
    if(el<0||el>=PZnBOOMT)continue;
    const x=cx+f.ox+f.kx,y=cy+f.oy+f.ky,BR=BR0;
    // ⓪ **한두 프레임 멎는다** — 그 정지가 무게를 만든다. 터짐은 그 뒤에 시작한다.
    if(el<PZnFREEZE){
      const q=el/PZnFREEZE;
      gAdd(c,g=>gHalo(g,x,y,f.r*(1.1+.5*q),PZTOX,.55+.45*q));
      fillPoly(c,PKrag(x,y,f.r*.9,f.ox+1.7,9,.22,f.oy),A("#FFFFFF",.35*q));
      continue;}
    const bu=(el-PZnFREEZE)/(PZnBOOMT-PZnFREEZE),fo=(1-bu)*(1-bu);
    // ① **번쩍** — 첫 두어 프레임만. ⚠️ 원형이 아니라 **불규칙**하다.
    const fl=Math.max(0,1-bu/.18);
    if(fl>0){
      fillPoly(c,PKrag(x,y,BR*(.34+.30*bu),f.ox+5.1,9,.44,f.oy+t),A("#FFFFFF",.80*fl));
      fillPoly(c,PKrag(x,y,BR*(.52+.30*bu),f.ox+9.3,11,.40,f.oy-t),A(TXe[2],.45*fl));}
    // ② **충격파** — 밖으로 퍼지는 **속 빈 테**. 채우지 않는다.
    for(const[k,lw,aa]of[[1.00,2.6,.90],[.72,1.4,.55]]){
      const rr=BR*(.20+1.05*bu)*k;
      if(rr<1)continue;
      c.lineWidth=lw*SC;c.strokeStyle=A(TXe[1],aa*fo);
      c.beginPath();c.arc(x,y,rr,0,TAU);c.stroke();}
    // ③ ⭐⭐ **꽂혔던 침이 부러져 튄다** — 「쌓인 것이 터졌다」가 한눈에 읽힌다.
    //   ⚠️ **크고 느리게.** 작고 빠르면 가볍다(낙광에서 얻은 규칙 그대로).
    for(let k=0;k<PZnSHARD;k++){
      const a=k/PZnSHARD*TAU+f.ox*.031;
      const sp=(.62+.55*hash(f.ox+k*3.1));
      const d=BR*(.22+1.15*Math.pow(bu,.62))*sp;
      const rot=a+(hash(f.oy+k)-.5)*.6;
      PZneedle1(c,x+Math.cos(a)*d,y+Math.sin(a)*d,rot,L*(.52-.16*bu),w*(1.0-.25*bu),
        fo*.98,.75);}
    // ④ **독이 확 번진다** — 갇혀 있던 것이 한꺼번에. 폭발 반경만큼.
    fillPoly(c,PKrag(x,y,BR*(.30+.85*bu),f.ox+7.1,13,.30,f.oy+t*1.6),A(TXe[0],.42*fo));
    // ⑤ **알갱이** — 사방으로. 스프라이트라 싸다.
    for(let k=0;k<8;k++){
      const a=k/8*TAU+f.oy*.05,sd=f.ox+k*2.7;
      const d=BR*(.35+1.30*bu)*(.6+.7*hash(sd));
      const r2=(1.1+1.7*hash(sd+1.3))*SC*(1-bu*.5);
      if(r2<.3)continue;
      fillPoly(c,PKrag(x+Math.cos(a)*d,y+Math.sin(a)*d,r2,sd,7,.34,a+t),
        A(TXe[1],fo*.9));}
    // ⑥ **잔광** — 터진 자리가 남아 식는다. 눈에 남는 것이 무게다.
    gAdd(c,g=>gHalo(g,x,y,BR*(.45+.35*bu),PZTOX,.50*fo));
    // ⑦ **밀린 자국** — 밀려난 자리에 짧은 자취. 정지 화면에도 「밀렸다」가 남는다.
    if(f.kb0){
      const g0=f.kb0;
      c.lineCap="round";c.lineWidth=f.r*.55;
      c.strokeStyle=A(TXe[0],.30*fo);
      c.beginPath();c.moveTo(g0[0],g0[1]);c.lineTo(x,y);c.stroke();}}

  // ── ⓔ **쌓인 스택** — 몸 둘레의 점.
  //   ⭐ **꽂힌 침 개수가 곧 스택**이다(맞을 때마다 하나가 박히고 2.0초 남는다).
  //     그래서 이 점은 **덤**이다 — 침이 겹쳐 있을 때 수를 세기 쉬우라고 둔다.
  //   ⚠️ 1·2 스택이 눈에 달라야 3에서 터지는 것이 「드디어」가 된다.
  for(const f of st.F){
    const n=f.stk||0;if(!n)continue;
    if(t-(f.stkT||-9)>PZnSTKHOLD)continue;
    const x=cx+f.ox+f.kx,y=cy+f.oy+f.ky;
    for(let k=0;k<n;k++){
      const a=-Math.PI/2+(k-(n-1)/2)*.42;
      const px=x+Math.cos(a)*f.r*1.42,py=y+Math.sin(a)*f.r*1.42;
      fillPoly(c,PKrag(px,py,2.6*SC,k*3.1,7,.30,t*1.2+k),A(TXe[1],.95));
      gAdd(c,g=>gHalo(g,px,py,4.4*SC,PZTOX,.40));}}
  drawP(c,st);hero(c,t,cx,cy);
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 폭마 **다시** — 「제3의 느낌」                            (2026-08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「**독번개라는 느낌을 좀 더 창의적으로 표현이 안 되려나?** 꼭 **번개의
//   느낌이나 독의 느낌이 안 살아도 돼.** 그냥 **제3의 느낌을 창작**하고 싶은데,,」
//
// ⇒ 앞 둘(저림 · 끊긴 그물)은 **반려**다. 이유가 하나다 — **둘 다 「번개 + 독」을
//   더한 것**이라 제3이 아니다. 자주 불꽃에 번개를 넣은 것, 번개 사슬에 번짐을
//   깔아 준 것. 더하면 부모가 보인다.
//
// ⭐⭐ **더하지 말고 뺀다.** 정체는 시안이 이미 적어 뒀다 —
//   「**그물이 끊긴다 — 번지던 신호가 죽은 마디 앞에서 멈춘다**」.
//   번개도 독도 **퍼지는** 것인데 마는 **퍼지던 것이 멎는** 것이다.
//   ⇒ **「없어지는 것」이 이 속성의 그림**이다. 그 어휘로 둘을 만든다:
//     (1) **글리치** — 신호가 **깨진다**(가로 띠가 어긋나고 · 몇 줄은 아예 없다)
//     (2) **탈색**   — 감각이 **빠진다**(색만 없어지고 형태는 남는다)
//   ⚠️ (3) 떨림(잔상이 안 사라지고 쌓인다) · (4) 역상(그 자리만 색이 뒤집힌다)은
//     **글로만 적어 둔다.** 말한 개수보다 많이 만들면 반려당한다(이 사이클에 세 번).
//
// ⚠️ **폭마는 엔진에 안 녹인다**(사용자 지시) ⇒ 판정 반경 같은 제약에 안 매인다.
//   여섯 속성에서라면 못 할 짓을 여기서는 해도 된다.
// ══════════════════════════════════════════════════════════════════════════

/// 적 배치 — 둘이 같이 쓴다. 다섯을 **넓게** 벌린다: (2) 탈색은 「고리 안은 회색 ·
/// 밖은 제 색」이 한 장에 같이 보여야 하고, (1) 글리치는 띠가 여럿을 가로질러야 한다.
const PZNFOE=[[-66,-54,13],[26,-86,14],[72,-22,13],[-36,16,12],[46,44,12]];

/// 적 실루엣 — `drawFoes` 가 그리는 **그 도형**이다(9각 · 같은 흔들림 `.1*sin(t*2+i)`).
/// ⚠️⚠️ **사본인 것을 안다.** 그런데 글리치의 정체가 「그 실루엣을 **잘라 옆으로
///   미는 것**」이라 도형을 손에 쥐어야 하는데 [drawFoes] 는 그걸 안 내준다.
///   값이 갈리면 글리치가 「엉뚱한 도형이 겹친 것」이 된다 ⇒ **두 곳을 같이 고쳐라**
///   (`vfx.js` 의 [drawFoes] · 여기).
function PZfoeShape(x,y,r,t){
  const p=[];
  for(let i=0;i<9;i++){const a0=i/9*TAU,a1=(i+.5)/9*TAU;
    p.push([x+Math.cos(a0)*r*1.06,y+Math.sin(a0)*r*1.06]);
    p.push([x+Math.cos(a1)*r*(.78+.1*Math.sin(t*2+i)),y+Math.sin(a1)*r*.82]);}
  return p;}
/// 적 다섯의 실루엣을 한 색으로 — 띠 안에서 잘라 밀 때 쓴다.
function PZfoeSil(c,cx,cy,F,t,body,rim,al,lw){
  for(const f of F){
    const P=PZfoeShape(cx+f.ox+f.kx,cy+f.oy+f.ky,f.r,t);
    fillPoly(c,P,A(body,al));
    if(!rim)continue;
    c.beginPath();P.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
    c.closePath();c.strokeStyle=A(rim,al);c.lineWidth=lw||2;c.stroke();}}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ 폭마 **정정** — **자염을 바탕으로** 두고 「그 불이 하는 일」이 제3   (08-23)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「**'자염'을 활용한** 새로운 아이디어를 만들라니까 ㅅㅂ 아예 새로운 걸
//   만들면 우째」 / 원래 지시: 「자염과 녹염은 **형태를 조금 바꿔서** '마' 캐릭터의
//   스킬과 '독' 캐릭터 스킬로 바꾸려고」
//
// ⚠️⚠️ **앞의 넷이 다 틀렸다**(저림 · 끊긴 그물 · 글리치 · 탈색). 앞 둘은 「번개+독」을
//   **더해서**, 뒤 둘은 **자염을 통째로 버려서**. 함수는 다 남긴다.
// ⭐ **바탕은 자염 그대로**다 — `PKCOL.viol`(자주 **307° L54** · 심 **308° L81** →
//   암적 → 숯) · 재료 여덟 · 모양(제트 **.15** · S자 · 진폭 **.33**).
//   ⇒ [PKflameLane] 을 **그대로 부른다.** 사본을 안 뜬다.
// ⭐ **제3은 「그 불이 무엇을 하느냐」에 있다** — 번개도 독도 **퍼지는** 것인데
//   마는 **퍼지던 것이 멎는** 것이다(`FVWHY.numb`: 「번지던 신호가 죽은 마디 앞에서
//   멈춘다」). 그래서 둘 다 **불은 흐르는데 무언가가 멎는** 그림이다.
// ⚠️ 화염방사 확정본과 **실루엣이 같아진다.** 갈리는 것은 **색(307° ↔ 20°)**과
//   **닿은 뒤**(굳음 · 어긋남)뿐이다 — 그 둘이 이 안의 전부다.
// ══════════════════════════════════════════════════════════════════════════

/// 적 하나를 그린다 — `vfx.js` 의 [drawFoes] 가 한 마리에 하는 것과 같은 그림.
/// ⚠️ **사본인 것을 안다.** 「멎는다」는 **적의 흔들림을 굳은 시각에 못 박는 것**이라
///   시각을 마리마다 따로 넘겨야 하는데, [drawFoes] 는 `t` 를 하나만 받는다.
///   ⇒ 값이 갈리면 굳은 적만 딴 도형이 되므로 **두 곳을 같이 고쳐라.**
function PZfoeDraw(c,tt,x,y,f,rim){
  const P=PZfoeShape(x,y,f.r,tt);
  fillPoly(c,P,f.hit>.02?A("#FFFFFF",.2+.7*f.hit):"#16101C");
  c.beginPath();P.forEach((q,i)=>i?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1]));
  c.closePath();
  c.strokeStyle=rim||`rgba(${180+70*f.hit},${60+160*f.hit},${110+100*f.hit},.95)`;
  c.lineWidth=2+f.hit*2;c.stroke();
  c.fillStyle=rim?"#8A2A6A":"#FF2D55";const er=1.9+f.hit*1.3;
  c.beginPath();c.arc(x-f.r*.26,y-f.r*.08,er,0,TAU);c.fill();
  c.beginPath();c.arc(x+f.r*.26,y-f.r*.08,er,0,TAU);c.fill();}

/// 자염 원뿔 — 확정본을 **그대로** 부른다. [tt]·[amul] 만 밖에서 준다.
function PZviolCone(c,tt,cx,cy,SC,LEN,HALF,amul){
  const ST=PKCOL.viol,R=PKtoFire(ST),E=PKENV.ess;
  PZwithTone("ember",PZNUM,()=>{
    PKflameLane(c,tt,cx,cy,SC,LEN,HALF,R,ST,E,FCDIR,.21,
      PKFNL[LV-1],PKFNB[LV-1],5.0,amul,.15);});}

/// 자염 공통 시뮬 — 넉백이 **0** 이다(굳는 것은 안 밀린다).
function PZviolSim(st,t,dt,cx,cy,SC){
  st.p=st.p||[];
  mgInit(st,SC,FCCONE_F);stepFoes(st.F,dt);
  const LEN=95*SC,HALF=.30;
  st.tk=(st.tk||0)+dt;
  if(st.tk>.20){st.tk=0;
    for(const f of st.F){
      const dx=f.ox+f.kx,dy=f.oy+f.ky,d=Math.hypot(dx,dy)||1;
      if(d>=LEN+f.r)continue;
      let ad=Math.atan2(dy,dx)-FCDIR;
      while(ad>Math.PI)ad-=TAU;while(ad<-Math.PI)ad+=TAU;
      if(Math.abs(ad)>HALF+.12)continue;
      // ⭐ **굳는 순간의 시각을 못 박는다** — 이 한 줄이 「멎는다」의 전부다.
      if(!(f.pv>.05))f.frz=t;
      f.pv=Math.min(3,(f.pv||0)+.85);}}
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.50;
  stepP(st,dt);
  return{LEN,HALF};}

// ── ⭐ (1) 멎는다 — **불은 흐르고 맞은 것만 정지한다** ────────────────────
// 자주색 불은 계속 흐르는데 **닿은 적은 그 순간의 자세로 굳어** 안 움직인다.
// ⚠️ 그 대비가 「마비」다 — 둘 다 움직이면 그냥 화염방사고, 둘 다 멎으면 정지 화면이다.
// ⚠️ **굳은 적은 흔들림이 멈춘다** — `drawFoes` 의 도형이 `sin(t*2+i)` 로 꿈틀대는데
//   그 `t` 를 **굳은 시각(`f.frz`)에 못 박아** 넘긴다. 시간이 그 마리에게만 멎는다.
// ⚠️ **넉백도 0** 이고 눈빛도 죽는다(#FF2D55 → 어두운 자주). 「살아 있지 않다」.
function PZnumbHalt(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  const{LEN,HALF}=PZviolSim(st,t,dt,cx,cy,SC);
  const T=toneOf(PZNUM);
  for(const f of st.F){
    const x=cx+f.ox+f.kx,y=cy+f.oy+f.ky;
    const frozen=f.pv>.05;
    PZfoeDraw(c,frozen?f.frz:t,x,y,f,frozen?A(T[1],.95):null);
    if(!frozen)continue;
    // **자주 테두리** — 「저기까지 닿았다」가 보이는 자리. 각지고 안 움직인다.
    const al=Math.min(1,f.pv*.8);
    const Q=jagPoly(x,y,f.r*1.20,9,7.3,1.10);
    c.beginPath();Q.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
    c.closePath();c.strokeStyle=A(T[2],al*.85);c.lineWidth=2.0*SC;c.stroke();
    fillPoly(c,Q,A(T[0],al*.30));}
  PZviolCone(c,t,cx,cy,SC,LEN,HALF,1);
  gAdd(c,g=>gFlare(g,cx,cy-5*SC,8*SC,PZNUM,.95,FCDIR,4));
  drawP(c,st);hero(c,t,cx,cy);}

// ── ⭐ (2) 어긋난다 — **불 안에서 결이 밀린다** ──────────────────────────
// 불꽃은 자염 그대로인데 **가로로 한두 칸씩 어긋나** 흐른다. 「번지던 신호가 죽은
// 마디 앞에서 멈춘다」를 **불 안에서** 보여 준다.
// ⚠️ **자염을 안 버리고 위에 얹는다** — 같은 원뿔을 띠로 잘라 **옆으로 밀어** 한 번
//   더 그리는 것뿐이다. 새 그림이 아니라 **같은 그림의 어긋난 판**이다.
// ⚠️ **시간이 매끄러우면 어긋남이 아니다** — 초당 열두 번만 자리가 바뀐다.
const PZsNB=[2,2,3,3,4];             // 어긋나는 띠 수
function PZnumbShift(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  const{LEN,HALF}=PZviolSim(st,t,dt,cx,cy,SC);
  const T=toneOf(PZNUM);
  mgMarks(c,t,cx,cy,st.F,"shock",PZNUM,SC);
  PZviolCone(c,t,cx,cy,SC,LEN,HALF,1);          // ⓐ 자염 원뿔 — 그대로
  const K=(t*12)|0,sd=K*7.31+5.3;               // ⬅ 열두 번만 바뀌는 시계
  const NB=PZsNB[LV-1],top=cy-LEN*1.05,hgt=LEN*1.12;
  for(let i=0;i<NB;i++){
    const y0=top+hgt*hash(sd+i*3.7)*.86;
    const bh=hgt*(.05+.09*hash(sd+i*5.1));
    const dx=Math.round((hash(sd+i*13.1)-.5)*2*16*SC);
    if(Math.abs(dx)<2)continue;
    // ⓑ **밀린 조각** — 같은 원뿔을 그 띠만 잘라 옆으로 옮겨 다시 그린다.
    //   ⚠️ 시각도 **조금 뒤로** 민다(`t-.05`) — 자리만 밀면 「복사」로 보이고
    //     시간을 같이 밀어야 「신호가 어긋났다」가 된다.
    c.save();c.beginPath();c.rect(0,y0,W,bh);c.clip();c.translate(dx,0);
    PZviolCone(c,t-.05,cx,cy,SC,LEN,HALF,.92);
    c.restore();
    // ⓒ **끊긴 자리** — 띠의 위아래에 얇은 선 하나씩. 「여기서 잘렸다」
    c.fillStyle=A(T[2],.45);c.fillRect(0,y0,W,1.1*SC);
    c.fillStyle=A(T[0],.55);c.fillRect(0,y0+bh-1.1*SC,W,1.1*SC);}
  gAdd(c,g=>gFlare(g,cx,cy-5*SC,8*SC,PZNUM,.95,FCDIR,4));
  drawP(c,st);hero(c,t,cx,cy);}

// ── (1) 글리치 — **신호가 깨진다** ────────────────────────────────────────
//
// ⭐ **왜 이것이 제3인가.** 번개는 갈래고 독은 번짐인데, 글리치는 **직각**이다 —
//   이 게임에 가로 띠로 어긋나는 그림이 **한 장도 없다**. 어휘 자체가 새것이다.
// ⭐ **렌더러와도 맞는다.** 이 게임은 단색 삼각형을 칠하는 렌더러이고, 글리치는
//   **가로 띠를 잘라 옆으로 미는 것**뿐이라 사각형 몇 개면 끝난다 — 잉크가 싸다.
// ⭐ 「신호가 죽은 마디 앞에서 멈춘다」가 **글리치의 정의 그대로**다.
//
// ⚠️⚠️ **시간이 매끄러우면 글리치가 아니다.** 초당 열두 번만 상태가 바뀐다
//   (`(t*12)|0`). 부드럽게 이어 놓으면 그건 물결이지 고장이 아니다.
//   ⚠️ 그래서 이 안은 **정지 화면에서 손해를 본다** — 한 장에는 한 상태만 담긴다.
//
// ⚠️ **색** — 몸은 마 팔레트(`TONE.numb` **320° 자홍**) 그대로다. 거기에 글리치의
//   모국어인 **채널 갈라짐**을 얹는다: 한쪽 가장자리에 **청록 177°**, 다른 쪽에
//   **흰색**(색상 없음 ⇒ 충돌 없음).
//   ⚠️ 잰 값: 청록 177° ↔ **풍 160~171° 와 6~17°** · **빙 185~201° 와 8~24°** —
//     **겹친다.** 다만 **획 2px 짜리 가장자리 색**이라 면적이 거의 0 이고,
//     지배색은 자홍이다(⑪ 보색 튐이 통과한 것과 같은 근거).
const PZgCY="#2BE8E0";                 // 청록 177° — 채널 갈라짐의 한쪽
const PZgNB  =[5,7,9,11,13];           // 띠 수
const PZgAMP =[7,9,11,14,17];          // 어긋나는 폭(238 기준 px)
const PZgDROP=[.10,.13,.16,.19,.22];   // **아예 없어지는 줄**의 비율
function PZglitch(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZNFOE);stepFoes(st.F,dt);
  const K=(t*12)|0,sd=K*7.31+3.7;      // ⬅ 열두 번만 바뀌는 시계
  const PER=1.55,u=(t%PER)/PER;
  // 깨져 있는 동안 / 멀쩡한 동안. 시작·끝에서 0 이라 루프에 이음매가 없다.
  const on=u<.44?Math.min(1,u/.05)*Math.min(1,(.44-u)/.09):0;
  if(on>0)for(const f of st.F)f.pv=Math.min(3,(f.pv||0)+dt*2.6);
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.62;
  stepP(st,dt);
  drawFoes(c,t,cx,cy,st.F);            // ⓐ 멀쩡한 그림이 먼저 있어야 「깨짐」이 산다
  const T=toneOf(PZNUM);
  const NB=PZgNB[LV-1],bh=H/NB,amp=PZgAMP[LV-1]*SC*on;

  // ⓑ **띠를 잘라 옆으로 민다.** 이것이 전부다.
  if(on>0)for(let i=0;i<NB;i++){
    const y0=i*bh;
    const drop=hash(sd+i*3.7)<PZgDROP[LV-1]*on;
    if(drop){
      // **없어진 줄** — 신호가 안 닿은 자리. 단색 막대 하나로 끝난다.
      c.fillStyle=A(T[0],.92*on);c.fillRect(0,y0,W,bh*(.55+.45*hash(sd+i)));
      c.fillStyle=A(T[1],.55*on);c.fillRect(0,y0,W,1.4*SC);
      continue;}
    const dx=Math.round((hash(sd+i*13.1)-.5)*2*amp);
    if(Math.abs(dx)<1)continue;
    // 밀린 조각 — 그 줄만 잘라 옮겨 그린다.
    c.save();c.beginPath();c.rect(0,y0,W,bh);c.clip();c.translate(dx,0);
    PZfoeSil(c,cx,cy,st.F,t,T[0],T[1],.95,2.2*SC);
    c.restore();
    // **채널 갈라짐** — 같은 조각을 ±2px 옮겨 가산으로 두 번. 겹치는 자리만 탄다.
    gAdd(c,g=>{
      for(const[o,col]of[[-2*SC,PZgCY],[2*SC,"#FFFFFF"]]){
        g.save();g.beginPath();g.rect(0,y0,W,bh);g.clip();g.translate(dx+o,0);
        PZfoeSil(g,cx,cy,st.F,t,col,null,.30*on);
        g.restore();}});}

  // ⓒ **엉뚱한 자리의 잔상** — 한 마리가 한 프레임 딴 데 찍힌다.
  if(on>.4){
    const j=((sd*3)|0)%st.F.length,f=st.F[j];
    const ox=(hash(sd+5.1)-.5)*90*SC,oy=(hash(sd+9.3)-.5)*40*SC;
    const P=PZfoeShape(cx+f.ox+ox,cy+f.oy+oy,f.r,t);
    fillPoly(c,P,A(T[0],.55*on));
    gAdd(c,g=>{const Q=PZfoeShape(cx+f.ox+ox+2*SC,cy+f.oy+oy,f.r,t);
      fillPoly(g,Q,A(PZgCY,.26*on));});}

  // ⓓ **총구** — 깨짐이 여기서 나간다. 짧고 굵은 가로 막대 하나.
  if(on>0){
    const bw=(30+70*on)*SC;
    c.fillStyle=A(T[2],.85*on);
    c.fillRect(cx-bw/2,cy-3*SC,bw,2.2*SC);
    c.fillStyle=A(T[1],.60*on);
    c.fillRect(cx-bw*.36,cy+2*SC,bw*.72,1.6*SC);}

  // ⓔ **남는 표식** — 깨짐이 지나간 뒤에도 적마다 한두 줄이 어긋나 있다.
  for(const f of st.F){
    if(!(f.pv>.05))continue;
    const x=cx+f.ox+f.kx,y=cy+f.oy+f.ky,al=Math.min(1,f.pv*.8);
    for(let k=0;k<2;k++){
      const yy=y+(hash(sd+f.ox+k*2.3)-.5)*f.r*1.4;
      const dx2=Math.round((hash(sd+f.oy+k*5.7)-.5)*2*6*SC);
      if(!dx2)continue;
      c.save();c.beginPath();c.rect(x-f.r*1.3,yy,f.r*2.6,f.r*.30);c.clip();
      c.translate(dx2,0);
      fillPoly(c,PZfoeShape(x,y,f.r,t),A(T[0],.95*al));
      c.restore();}}
  drawP(c,st);hero(c,t,cx,cy);
}

// ── (2) 탈색 — **감각이 빠진다** ──────────────────────────────────────────
//
// ⭐ **왜 이것이 제3인가.** 다른 스킬은 전부 **무언가를 더해서** 보인다(불·얼음·
//   번개·독을 화면에 **얹는다**). 이것은 **빼서** 보인다 — 지나간 자리의 **색이
//   없어진다**. 저릴 때 감각이 없어지는 것의 직역이고, 폭마 말고는 쓸 데가 없다.
//
// ⭐⭐ **캔버스 혼합 모드 하나로 끝난다** — `globalCompositeOperation="saturation"`.
//   회색으로 칠하면 **밑에 이미 그려진 것의 채도만** 빠진다(형태는 그대로).
//   ⇒ 적의 분홍 테와 빨간 눈이 **회색으로 굳고**, 고리 밖의 적은 제 색 그대로다 —
//     한 장에 「든 것 ↔ 안 든 것」이 같이 보인다. 그림을 새로 안 그린다.
//   ⚠️ 이 수법이 성립하는 조건 하나: **바탕이 불투명해야 한다.** 투명한 자리에
//     혼합 모드로 칠하면 그냥 **회색 원판**이 얹힌다. 다행히 이 저장소의 프레임
//     루프가 매 프레임 `#0C0C12` 로 **칸을 채우고** 시작한다(`vfx.js` 의 `frame`:
//     「`if(a.clear)…else{c.fillStyle="#0C0C12";c.fillRect(…)}`」) — 우리 칸은
//     `clear` 를 안 걸었으니 불투명이다. ⚠️ 나중에 이 칸에 `{clear:true}` 를 걸면
//     **이 안이 회색 원판으로 망가진다.**
//
// ⚠️⚠️ **어두운 배경에서 회색은 잘 안 보인다**(코디네이터가 미리 짚었다). 그래서
//   셋을 같이 넣었다: ① **전선**(퍼지는 가장자리)에 마지막 색이 몰린다 ·
//   ② 안쪽을 아주 살짝 죽인다(구역이 보이게) · ③ 색이 **빠져나가는 알갱이**가
//   전선 쪽으로 흘러 나가며 회색이 된다.
// ⚠️ **색** — 전선만 마 자홍 320°(`TONE.numb`)다. 안쪽은 **색이 없는 것**이 정체라
//   충돌할 색 자체가 없다. 여섯 속성 어느 것과도 안 겹친다.
const PZbR  =[.34,.40,.46,.50,.54];    // 다 퍼졌을 때 반경(칸 짧은 변 대비)
function PZbleach(c,t,dt,W,H,st){
  const cx=W/2,cy=H/2,SC=Math.min(W,H)/238;
  st.p=st.p||[];
  mgInit(st,SC,PZNFOE);stepFoes(st.F,dt);
  const PER=2.9,u=(t%PER)/PER;
  const R0=Math.min(W,H)*PZbR[LV-1];
  const grow=Math.min(1,u/.44);
  const rr=R0*Math.pow(grow,.66);
  // 다 퍼진 뒤 **머물다** 옅어진다 — 「빠진 감각이 천천히 돌아온다」.
  const hold=u<.44?1:Math.max(0,1-(u-.44)/.56);
  for(const f of st.F)
    if(Math.hypot(f.ox,f.oy)<rr&&u<.44)f.pv=Math.min(3,(f.pv||0)+dt*2.0);
  for(const f of st.F)if(f.pv>0)f.pv-=dt*.55;
  stepP(st,dt);
  drawFoes(c,t,cx,cy,st.F);            // ⓐ 색이 살아 있는 그림이 먼저 있어야 뺄 것이 있다

  if(rr>1&&hold>.01){
    // ⓑ ⭐ **탈색** — 채도만 뺀다. 형태·명도는 한 톨도 안 건드린다.
    c.save();c.globalCompositeOperation="saturation";c.globalAlpha=hold;
    c.fillStyle="#808080";c.beginPath();c.arc(cx,cy,rr,0,TAU);c.fill();c.restore();
    // ⓒ 안쪽을 아주 살짝 죽인다 — 검은 배경에서 **구역**이 보이게.
    c.save();c.fillStyle=A("#000000",.15*hold);
    c.beginPath();c.arc(cx,cy,rr,0,TAU);c.fill();c.restore();
    // ⓓ 굳은 결 — 회색 동심 두 줄. 안이 비어 보이지 않게 아주 옅게.
    c.lineWidth=1.2*SC;
    for(const k of[.52,.80]){
      const r2=rr*k;if(r2<1)continue;
      c.strokeStyle=A("#9A9AA8",.16*hold);
      c.beginPath();c.arc(cx,cy,r2,0,TAU);c.stroke();}
    // ⓔ **전선** — 마지막 색이 여기 몰려 있다. 얇고 또렷하게.
    const T=toneOf(PZNUM);
    c.lineWidth=2.4*SC;c.strokeStyle=A(T[1],.90*hold);
    c.beginPath();c.arc(cx,cy,rr,0,TAU);c.stroke();
    c.lineWidth=1.0*SC;c.strokeStyle=A(T[2],.80*hold);
    c.beginPath();c.arc(cx,cy,rr*.985,0,TAU);c.stroke();
    // ⓕ **빠져나가는 색** — 알갱이가 전선 쪽으로 흘러 나가며 회색이 된다.
    for(let k=0;k<14;k++){
      const sd=k*3.77+1.3;
      const w=((t*(.42+.30*hash(sd))+hash(sd+2.1))%1);
      const a=hash(sd+5.3)*TAU;
      const d=rr*(.16+.86*w);
      const x=cx+Math.cos(a)*d,y=cy+Math.sin(a)*d;
      const r3=(1.0+1.8*hash(sd+7.7))*SC*(1-w*.35);
      if(r3<.3)continue;
      // 색이 **빠지는 중**이라 자홍 → 회색으로 섞인다. `w` 하나에서 다 파생한다.
      fillPoly(c,PKrag(x,y,r3,sd,7,.34,sd+t*1.4),
        A(mixHex(T[1],"#8E8E96",Math.min(1,w*1.25)),
          Math.min(1,w*6)*(1-w)*.95*hold));}}

  // ⓖ **굳음** — 색이 빠진 적은 윤곽만 남는다. 회색 테 하나뿐이고 안 움직인다.
  for(const f of st.F){
    if(!(f.pv>.05))continue;
    const x=cx+f.ox+f.kx,y=cy+f.oy+f.ky,al=Math.min(1,f.pv*.7);
    const P=jagPoly(x,y,f.r*1.12,9,7.3,1.12);
    c.beginPath();P.forEach((v,i)=>i?c.lineTo(v[0],v[1]):c.moveTo(v[0],v[1]));
    c.closePath();c.strokeStyle=A("#B4B4C0",al*.75);c.lineWidth=1.8*SC;c.stroke();}
  drawP(c,st);hero(c,t,cx,cy);
}

// ══════════════════════════════════════════════════════════════════════════
// 등록 — **더하기만 한다.** `FX` 의 기존 키는 한 개도 안 건드린다.
// ══════════════════════════════════════════════════════════════════════════
Object.assign(FX,{
  PZdartA(c,t,dt,W,H,st){PZdartRun(c,t,dt,W,H,st,PZDARTA);},
  PZdartB(c,t,dt,W,H,st){PZdartRun(c,t,dt,W,H,st,PZDARTB);},
  PZdartC(c,t,dt,W,H,st){PZdartRun(c,t,dt,W,H,st,PZDARTC);},
  PZgasA (c,t,dt,W,H,st){PZgasRun (c,t,dt,W,H,st,"creep");},
  PZgasB (c,t,dt,W,H,st){PZgasRun (c,t,dt,W,H,st,"bloom");},
  PZgasC (c,t,dt,W,H,st){PZgasRun (c,t,dt,W,H,st,"pool" );},
  // ⭐ 둘레 분사 — 위 셋(전방 원뿔)은 **함수로 남긴다**(규약).
  PZgasAura,PZgasVerd,
  PZgasBombA(c,t,dt,W,H,st){PZgasBomb(c,t,dt,W,H,st,PZbESSA);},
  PZgasBombB(c,t,dt,W,H,st){PZgasBomb(c,t,dt,W,H,st,PZbESSB);},
  PZgasBombC(c,t,dt,W,H,st){PZgasBomb(c,t,dt,W,H,st,PZbESSC);},
  // ⭐ **복제본** — 확정본(`PZgasBombA`)을 그대로 두고 **밀도 채널**만 더한 판.
  //   ⚠️ 위 셋과 **다른 함수**를 부른다([PZqBomb]) — 확정본 함수는 안 건드린다.
  PZgasBombD(c,t,dt,W,H,st){PZqBomb(c,t,dt,W,H,st);},
  // ⭐ 바늘 — 위 표창 셋(`PZdartA/B/C`)도 함수로 남긴다(규약).
  PZneedle30(c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[0],PZnBOOMRS[0]);},
  PZboom34 (c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[0],PZnBOOMRS[0]);},
  PZboom70 (c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[0],PZnBOOMRS[1]);},
  PZboom110(c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[0],PZnBOOMRS[2]);},
  PZneedle18(c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[1]);},
  PZneedle12(c,t,dt,W,H,st){PZneedleRun(c,t,dt,W,H,st,PZnLENS[2]);},
  // ⚠️ 앞 둘은 **반려**(2026-08-23) — 「번개 + 독」을 **더한 것**이라 제3이 아니다.
  //   함수는 안 지운다(규약). 목록에서만 뺐다.
  PZnumbA,PZnumbB,
  PZglitch,PZbleach,
  PZnumbHalt,PZnumbShift});

// ── 조립 ──────────────────────────────────────────────────────────────────
// ⚠️ **타일 크기 236.** 크게 만들면 한 줄에 둘밖에 안 서서 비교가 깨진다.
// ⚠️ **전부 L5** 로 그린다 — 스킬 격자의 규약이다(2026-08-13 사용자 확정:
//   L1 을 세우면 제일 약한 그림이 서서 「이 스킬이 무엇인가」가 안 읽힌다).
// ⚠️ 호스트가 없는 페이지에서는 조용히 넘어간다 — 이 파일이 두 장에 같이 실린다.
// ══════════════════════════════════════════════════════════════════════════
// ⭐ 판정 (2026-08-23) — **둘 다 「남는 쪽」이 뽑혔다**
// ══════════════════════════════════════════════════════════════════════════
// 사용자 원문: 「**독가스는 다 「고인다」만 두고 나머지 2개는 제거**」 ·
//              「**독표창은 「나」 제외하고 나머지 2개는 제거**」
//
// ⭐⭐ **고른 것에서 결이 읽힌다 — 다음 사람은 이 판단을 다시 하지 마라.**
//   여섯 안 중 **뽑힌 둘이 다 「남는 쪽」**이다:
//     가스 (다) 고인다  — 지나간 자리에 **얕은 층이 남는다**(축이 모양이 아니라 **시간**)
//     표창 (나) 반쯤 잠긴다 — **절반이 몸에 잠겨** 날 하나만 남고 독이 몸을 **타고 번진다**(면)
//   ⇒ **독의 동사와 정확히 맞는 쪽**을 둘 다 골랐다 —
//     「독은 **붙어서 퍼진다**」 · 「**깔아 두고 나중에 값이 난다**」
//     (`lib/data/skill_element.dart` 독 절).
//   ⇒ 앞으로 독 스킬을 만들 때 **그 결을 먼저 잡아라.** 한 방에 끝나는 것 ·
//     튀어나와 눈에 띄는 것 · 계속 돌아 바쁜 것은 **독이 아니다.**
//
// ⚠️ **함수는 하나도 안 지웠다** — 「그건 좋았는데」가 나올 수 있고, 지웠다 다시
//   만들면 값이 달라진다(이 저장소의 규약). **목록에서만 뺐다.**
// ══════════════════════════════════════════════════════════════════════════
// ⚠️⚠️ **목록은 한 벌이다 — 셋 다 남는다.** 고르기에서 한 칸씩만 서는 것은
//   아래 [PZPICK] 이 **거르기** 때문이고, 캐릭터 장에는 셋이 그대로 선다.
//   ⇒ **되돌릴 수 있다**(사용자: 「확정이 아니고 거기서 조금 더 다듬을 거야」).
//   장마다 목록을 따로 두면 그 날로 갈라진다.
const PZDART=[
 // ⚠️ **표창 셋을 목록에서 뺐다**(2026-08-23 사용자: 「'바늘' 같은 형태의 '빛'이
 //   '독침처럼' 꽂히도록 변경」). 회전하는 날 넷은 **바늘이 아니다.**
 //   함수 `PZdartA`·`PZdartB`·`PZdartC` 는 그대로 살아 있다.
 //   ⭐ 채택본 (나)에서 **「반쯤 잠긴다」와 「독이 몸을 타고 번진다」는 살렸다** —
 //     그 둘이 「독침」과 오히려 더 맞는다(벌침이다).
 // ⭐ **길이 30 · 폭발 반경 50 확정.** 나란히 세우기는 끝났고 다시 **성장 줄**이다.
 // ⚠️⚠️ **다섯 칸이 같은 함수(`PZneedle30`)를 `LV` 만 갈아 부른다** — 확정본을
 //   재해석해 두 번 반려당한 그 사고를 안 낸다. 다른 것은 `tile()` 인자 하나뿐이다.
 ["PZneedle30","L1 — <b>뿅</b> · 1발 · 표적 1",
  "가늘고 긴 <b>빛의 침</b>(길이 <b>30</b> · 굵기 <b>3.6</b>)이 <b>곧게</b> 날아가 <b>절반이 몸에 박힌다</b>. 꽂힌 뒤 독이 <b>몸 안으로 주입</b>되고 <b>빛은 식는다</b>(비행 0.26 : 체류 2.0초).<br>빛 <b>#E6FFEA 130° L95</b> · 독 <b>#123D1C 134° L16</b>. ⚠️ <b>스택 3 에서 터진다</b> — 1발이라 <b>세 번 쏴야</b> 찬다",1],
 ["PZneedle30","L2 — <b>뿅뿅</b> · 2발 · 표적 1",
  "연속 <b>두 발</b>(0.13초 간격 · <b>1자로</b> 같은 직선). ⚠️ 아직 <b>두 번 쏴야</b> 스택 3 이 찬다",2],
 ["PZneedle30","L3 — <b>뿅뿅뿅</b> · 3발 · 표적 1 <b>← 분기점</b>",
  "연속 <b>세 발</b>. ⭐ <b>한 번의 연사로 스택 3 이 차서 폭발한다</b> — 스킬의 성격이 바뀌는 자리다",3],
 ["PZneedle30","L4 — <b>뿅뿅뿅뿅</b> · 4발 · <b>표적 2</b>",
  "연속 네 발 + <b>동시에 서로 다른 적 둘</b>. 한 마리당 4발이 그대로 가서 <b>둘 다 터진다</b>",4],
 ["PZneedle30","L5 — <b>뿅뿅뿅뿅뿅</b> · 5발 · 표적 2",
  "연속 <b>다섯 발</b> × 표적 둘 = 침 <b>열</b>. 터지고 <b>남은 둘</b>이 다음 스택으로 이어진다.<br>폭발 <b>반경 50</b>(칸의 21% · 적 몸의 3.2배) · <b>0.95초</b> · 층 <b>일곱</b>(멎음 0.09초 · 번쩍 · 속 빈 테 둘 · <b>부러진 침 일곱</b> · 독 번짐 · 알갱이 · 잔광 · 밀린 자국) · 넉백 <b>26</b>",5]];
const PZGAS=[
 // ⚠️ 사용자가 (다)를 고르고 (가)·(나)를 뺐다(2026-08-23). **확정은 아니다.**
 //   함수 `PZgasA`·`PZgasB` 는 그대로 살아 있다.
 // ⚠️ **전방 원뿔 셋은 목록에서 뺐다**(2026-08-23 사용자: 「전방 분사가 아니라
 //   캐릭터 주변으로 무작위 분사」). 함수 `PZgasA`·`PZgasB`·`PZgasC` 는 그대로다.
 // ⚠️ **앞 판 셋은 목록에서 뺐다** — 전방 봉투판(`PZgasA/B/C`) · 둘레 분사판
 //   (`PZgasAura`) · 녹염 자취판(`PZgasVerd`). 함수는 다 살아 있다.
 // ⚠️ **앞 판 셋은 목록에서 뺐다** — 전방 봉투판(`PZgasA/B/C`) · 둘레 분사판
 //   (`PZgasAura`) · 녹염 자취판(`PZgasVerd`). 함수는 다 살아 있다.
 // ⭐ **갈리는 것은 S 진폭 하나뿐**이다 — 나머지(구 · 구멍 · 각도 · 박자 · 색 ·
 //   재료)는 셋이 전부 같다.
 ["PZgasBombA","진폭 <b>2.00</b> — 확정본 .33 의 <b>6.06배</b>",
  "몸에서 <b>위로 30 · 옆으로 21</b> 자리에 <b>빛으로 만들어진 작은 구</b>(반지름 <b>9</b> · 자오선+실루엣 = 공전 구슬과 같은 붓 <code>LX3ball</code>)를 놓고, 그 <b>구멍 둘</b>에서 <b>녹염 형태</b>로 뿜는다. <b>좌 → 우 → 좌 를 2.40초에 한 번</b>(초당 <b>0.42회</b> · 총 주기 4.8 에 <b>정확히 두 번</b>) — ⭐ 그런데 <b>줄기를 휘젓는 것이 아니라</b> 덩어리가 <b>태어난 시각의 각도를 간직한 채</b> 흘러간다(파동이 아래에서 위로 <b>번져 올라간다</b>). 지나간 S자가 <b>공중에 걸려</b> 있다 — 흔들림이 물건에서 나오므로 <b>흔들리는 이유가 화면에 있다</b>.<br>구멍 <b>88° 벌어짐</b>(−32°·+56°). 구 <b>#E6FFEA 130° L95</b> · 구멍 <b>#123D1C 134° L16</b> · 가스 <b>녹염 115° L58</b>.<br>박자 <b>분사 3.0 → 멈춤 0.9 → 쿨 0.9</b> = 주기 4.8초.<br>⭐⭐ <b>끝맺음은 길이 하나로 말한다</b> — 뒤 <b>1.0초</b> 동안 줄기가 <b>77.3px → 11.6px</b> 로 <b>한 번도 안 끊기고</b> 짧아지고(1ms·4801점 검산 최대 도약 <b>0.099px</b>), 맨 마지막 <b>0.38초</b>만 <b>팅팅</b>(뽁 <b>셋</b> · 61~68ms · 사이 38ms)이다가 <b>완전히 멈춘다</b>. 멈춤 0.9초엔 아무것도 안 남는다.<br>⚠️⚠️ <b>끝맺음의 잔상 겹을 걷어냈다</b> — 길이를 안 줄인 잔상이 잦아듦 내내 <b>77.3px 를 붙들어</b> 짧아지는 것을 통째로 가렸고, 세기가 <b>역위상</b>이라 겹이 <b>2 ⇄ 4 로 아홉 번</b> 뒤집혀 「깜빡깜빡」이었다. 좌우로 휠 때 남는 자취는 <b>봉투가 위상을 실어 혼자</b> 낸다 — 그 둘은 다른 물건이다"],
 ["PZgasBombD","<b>스킬 전체</b> — 던지고 · 방사 반복 · 부들부들 · 펑 <b>← 시안 확정 · L5</b>",
  "⭐ <b>사용자가 확정한 것이 이 칸</b>이다(2026-08-23: 「독가스는 <b>시안 확정</b>! 캐릭터 독 쪽으로 이동해줘」). 왼쪽은 <b>분사 그림의 정본</b>(4.8초 무한반복)이고 이쪽은 <b>스킬 전체</b>라 <b>주기가 다른 게 정상</b>이다. 이 칸은 <b>L5</b>(수류탄 3 · 갈래 <b>5각</b> · 방사 4회 · 쿨 11 → <b>14초</b>). 성장 다섯 칸이 아래에 있다.<br>"
  +"⭐⭐ <b>갈래가 사방으로 간다</b>(사용자: 「<b>한 방향 말고 5각으로 사방으로 뿌리는 식</b>을 말한 건데! … <b>앞뒤 · 3각 · 동서남북 · 5각</b> 이렇게 생각한 거야」). 식은 하나다 — <code>각도 j = j × 360°/n</code>. 갈래 <b>2 = 0/180°(앞뒤)</b> · <b>3 = 0/120/240(3각)</b> · <b>4 = 0/90/180/270(동서남북)</b> · <b>5 = 0/72/144/216/288(5각)</b>. 시작각이 0 이라 조준 방향(위)이 곧 첫 갈래다.<br>"
  +"⚠️⚠️ <b>갈래 둘도 예외가 아니다</b> — 확정본의 <b>88° 부채</b>는 이 판이 안 쓴다. 그 88° 는 왼쪽 칸이 제 것으로 그대로 쓰고 있고 <b>한 글자도 안 고쳤다</b>(코드 구간 13,086자 · SHA-256 동일).<br>"
  +"⚠️⚠️ <b>사방이 되면서 몸 덮임 방어선이 하나로 줄었다.</b> 앞 판은 ① <b>층 순서</b>(가스를 몸보다 먼저) ② <b>자리를 전부 몸 위로</b> 두 겹이었는데 <b>사방으로 뻗으면 ②가 무효</b>다. ⇒ <b>①이 유일한 방어선</b>이고, 자리를 옮겨 피하지 않았다 — <b>사방이 설계다</b>. 실측: 708² 칸 <b>1,600프레임</b>에서 몸 심의 색 차이 <b>0</b>(심 = <b>검정 바탕 렌더와 흰 바탕 렌더가 정확히 같은 화소</b>만 — 알파 255 라도 반투명 겹으로 도달한 자리는 바탕이 새므로 뺐다).<br>"
  +"⚠️⚠️ <b>「사거리」가 아니라 「탐지 반경」이다</b>(사용자: 「<b>사거리가 꼭 멀리 던지라는 게 아니고</b>, 적이 멀리 있으면 <b>「인지하는」 영역</b>을 말하는 거야 … <b>뭉텅이로 있는 적에 자동 조준</b>이잖아?」). <b>실제 던지는 거리는 적이 어디 있느냐가 정한다.</b> ⇒ 이식할 때 <code>range</code> 로 옮기면 안 된다.<br>"
  +"⭐ 그래서 이 칸은 <b>가짜 적을 뭉텅이 셋</b>으로 놓았다 — 가까이 <b>3마리 99.9</b> · 중간 <b>4마리 141.3</b> · 멀리 <b>5마리 199.8</b>(탐지 반경 × 0.90). <b>수류탄이 그 한가운데에 앉고</b> 못 미치는 뭉텅이의 적은 <b>표식을 하나도 안 받는다</b>. 실측으로 <b>덮은 뭉텅이 = 탐지 반경 안에 든 뭉텅이</b>가 다섯 레벨에서 정확히 일치한다. ⚠️ <b>반경 원·점선은 안 그린다</b>(판정 안내선 금지).<br>"
  +"⭐⭐ <b>적을 갈래와 같은 자로 두른다</b> — 뭉텅이의 적이 수류탄을 <b>고르게 에워싸고</b> 첫 자리가 <b>갈래 0 과 같은 각</b>이다. ⚠️ 이게 없으면 <b>표식이 아예 안 뜬다</b>(흩뜨렸더니 L2·L3 에서 <b>0/3</b> — 갈래는 이어진 원뿔이 아니라 덮는 몫이 <b>둘이면 29% · 셋이면 44%</b>다). 덤으로 뭉텅이 <b>3·4·5</b> 가 갈래 <b>3·4·5</b> 와 맞물려 L2·L3 은 셋 전부 · L4 는 넷 전부 · <b>L5 는 다섯 전부</b>가 가스 안에 든다.<br>"
  +"⭐⭐ <b>뿜는 몫이 넷째 성장축</b>이다(사용자: 「L5 때 <b>너무 짧게 분출하다가 꺼지네</b>」). 원인이 방사 길이 하나가 아니라 <b>쉼이 방사와 똑같아 몫이 정확히 50%</b> 였다. ⇒ <b>한 벌(방사+쉼)을 6.00초에 못 박고 안의 나눔만</b> 갈랐다(화염방사 ⑩ 과 같은 문법) — <b>58.3 → 72.1 → 81.4 → 87.5 → 91.7%</b>. L5 는 <b>5.50초 뿜고 0.50초</b> 쉰다.<br>"
  +"⭐ <b>크기 세 축이 전부 「두 끝만 정하고 가운데는 등비」</b>다 — 탐지 반경 <b>111 → 2배 222</b> · 줄기 길이 <b>L5 78(확정본 그대로) → 절반 39</b> · 쉼 <b>2.50 → 1/5 인 0.50</b>. 손으로 고른 수가 축마다 <b>둘</b>이다. ⚠️ 줄기 배수는 <b>길이에만</b> 건다 — 원뿔 각(.30)은 다섯 칸이 같아 <b>모양이 안 변하고 크기만</b> 자란다.<br>"
  +"⭐⭐ <b>수류탄 하나의 시각표</b>(던진 뒤) — <b>날아감 0.70</b> → [<b>방사</b> → <b>쉼</b>] × 방사 횟수, 한 벌 <b>6.00초</b>. 마지막 쉼의 <b>끝 1.20초</b>가 <b>부들부들 1.00 + 펑 0.20</b> 이다. ⇒ <code>유지 = 방사 횟수 × 6.00</code> = L5 <b>24.00초</b>. ⚠️ L5 는 쉼이 0.50 뿐이라 부들부들이 마지막 방사에 <b>0.70초 물린다</b> — 뿜으면서 떨기 시작하는 셈인데 <b>그래도 좋다</b>(「곧 사라진다」가 분사가 끊긴 뒤에 오면 이미 늦다).<br>"
  +"⚠️⚠️ <b>겹침은 설계다</b> — L3 부터 쿨보다 수명이 길어 다음 시전이 앞 수류탄이 살아 있는 동안 시작된다(L5 <b>14.70초 겹침</b>). <b>수류탄 하나하나가 「제 나이」를 갖는</b> 구조라 겹침을 다루는 코드가 <b>한 줄도 없다</b>.<br>"
  +"⭐ <b>쿨 너프는 그림이 아니라 밸런스다</b>(사용자 실기 판정: 「<b>쿨타임 조금 더 길게 해줘도 될 듯? (너프) 생각보다 너무 센 듯</b>해」). 15·14·13·12·11 → <b>18·17·16·15·14</b> — 기울기(레벨마다 −1)를 지키며 한 줄로 +3 했다. 그 결과 <b>L1 공백이 5.30초</b>로 사용자가 「의도한 것」이라 못 박은 <b>5초</b>에 선다.<br>"
  +"⭐⭐ <b>머무는 안개</b> · <b>날아가 멈춤</b> · <b>부들부들 → 펑</b>은 앞 판 그대로다. 안개 수명 <b>2.40초</b>(=왕복 <code>PZbCYC</code>) · <b>[PZsoft]</b> 로 그려 또렷한 외곽선이 없다. ⚠️ <b>착지 충격·먼지·그림자를 안 그린다 — 우주라 바닥이 없다.</b> <b>펑은 연출만이고 피해가 없다.</b><br>"
  +"⚠️ 난수 <b>0건</b> · 실측 <b>칸 밖 화소 0</b>(다섯 레벨 · 4,000프레임) · <b>이웃 갈래 겹침 0화소</b>(5각 72° 포함, 갈래를 하나씩 따로 그려 대조) · 236² 칸 잉크 최대 <b>4.07M</b>(확정본 칸 2.16M 의 <b>1.88배</b> — ⚠️ <b>배율이 0.43→0.54 로 커진 몫이 들어 있다</b>).<br>"
  +"⚠️⚠️ <b>꼭짓점이 프레임당 119,440</b> 까지 간다 — 엔진 상한(<code>kVertexCap</code> 32,768)의 <b>364%</b>다. ⭐ <b>꼭짓점은 배율과 무관하다</b>(시안을 줄여 담아도 안 준다). <b>이식 전에 반드시 나눠 그려야 한다.</b><br>"
  +"⚠️ <b>이 칸은 0.54배로 줄여 담았다</b> — 몸·적·표식이 <b>같은 배율</b>로 줄었고 몸을 <b>74 아래</b>로 내렸다. 구 반지름이 화면에서 <b>4.82px</b>. <b>게임은 안 줄인다</b> — 이식용은 <b>몸 반지름(17) 몫</b>으로 읽어라(탐지 반경 <b>×6.53 → ×13.06</b>)."]
];

// ⚠️ **앞의 넷은 목록에서 뺐다** — (A) 저림 · (B) 끊긴 그물은 「번개+독」을 **더한**
//   것이라, (1) 글리치 · (2) 탈색은 **자염을 통째로 버린** 것이라 반려됐다.
//   함수는 `FX.PZnumbA`·`PZnumbB`·`PZglitch`·`PZbleach` 로 다 살아 있다.
const PZNUMB=[
 ["PZnumbHalt","(1) <b>멎는다</b> — 불은 흐르고 맞은 것만 정지",
  "<b>자염 그대로</b>(307° L54 · 심 308° L81 · 제트 .15 · S자 · 진폭 .33 · 재료 여덟)인데 <b>닿은 적은 그 순간의 자세로 굳는다</b> — 몸의 흔들림이 <b>굳은 시각에 못 박히고</b> 넉백도 눈빛도 죽는다. 둘레에 <b>자주 테두리</b>가 남아 「저기까지 닿았다」가 보인다.<br>⚠️ 불은 계속 흐른다 — <b>그 대비</b>가 마비다"]];
 // ⚠️ (2) 어긋난다 — 사용자가 뺐다(2026-08-23). 함수 `FX.PZnumbShift` 는 살아 있다.

// ⚠️⚠️ **호스트가 장마다 둘씩이다** (2026-08-23, 사용자가 못 찾아서 옮겼다).
//   판정을 기다리는 시안은 **고르기 페이지**(`mockup-pick.html`)에 서야 한다 —
//   그게 그 페이지의 존재 이유다. 그런데 캐릭터 장에도 남겨 둔다: 고르고 나면
//   고르기에서 빼고 **캐릭터 장 것이 정본**이 되는 것이 이 저장소의 흐름이다
//   (광주 B · 뇌광 A · 낙광이 그 길로 갔다).
//   ⚠️ **같은 id 를 두 장에 두면 안 된다** — 고르기 쪽은 `pkz*`, 캐릭터 장 쪽은
//     `pz*` 다. 한 파일이 세 장에 실리고 **없는 쪽은 조용히 건너뛴다**(`if(H)`).
//   ⚠️ 목록·설명·크기는 **한 벌뿐**이다. 장마다 사본을 두면 그 날로 갈라진다.
// ⭐⭐ **성장 줄** — 사용자가 정한 표를 다섯 칸으로 세운다(캐릭터 장에만).
// ⚠️ **다섯 칸이 같은 함수(`PZgasBombD`)를 `LV` 만 갈아 부른다** — 확정본을 재해석해
//   두 번 반려당한 그 사고를 안 낸다. 다른 것은 `tile()` 인자 하나뿐이다.
// ⚠️ 고르기 페이지에는 안 세운다 — 거긴 **판정을 기다리는 안**이 서는 자리다.
const PZGASGROW=[
 ["PZgasBombD","L1 — 수류탄 <b>1</b> · 갈래 <b>2</b> <b>앞뒤 180°</b>",
  "방사 <b>3.50초</b> + 쉼 <b>2.50</b> = 한 벌 6.00 × 2회 ⇒ <b>유지 12.00초</b> · 뿜는 몫 <b>58.3%</b> · 줄기 <b>39.0</b> · 탐지 반경 <b>111</b> · 쿨 <b>18초</b>.<br>⭐ <b>가까운 뭉텅이 하나</b>(3마리 · 99.9)만 닿는다 — 중간·먼 뭉텅이는 <b>그려져 있는데 표식을 하나도 안 받는다</b>. 그것이 「탐지 반경 밖」이다.<br>⭐ <b>공백 5.30초</b> — 사용자가 「<b>의도한 것</b>」이라 못 박은 자리다. 마지막 수류탄이 <b>12.70초</b>에 사라지고 쿨이 18 이다",1],
 ["PZgasBombD","L2 — 갈래 <b>3</b> <b>3각 120°</b> · 쉼 <b>−0.83</b>",
  "수류탄은 그대로 1 인데 <b>갈래가 셋</b>이 되어 <b>3각</b>으로 돈다. 방사 <b>4.33</b> + 쉼 <b>1.67</b> ⇒ 유지 <b>12.00초</b>는 같고 <b>뿜는 몫이 58.3 → 72.1%</b> 로 오른다 — <b>같은 시간에 더 오래 뿜는다</b>.<br>줄기 <b>46.4</b> · 탐지 반경 <b>132</b> · 쿨 <b>17초</b> · 공백 <b>4.30초</b>.<br>⚠️ 중간 뭉텅이가 <b>141.3</b> 이라 아직 <b>9.3 만큼 모자란다</b> — 여기까지가 「가까운 하나만」이다",2],
 ["PZgasBombD","L3 — 수류탄 <b>2</b> · 방사 <b>3</b>회 <b>← 분기점</b>",
  "<b>중간 뭉텅이(4마리 · 141.3)가 탐지 반경(157) 안에 들어온다</b> ⇒ 수류탄이 둘이 되어 <b>둘 다 친다</b>. 방사가 <b>세 번</b>이라 유지 <b>18.00초</b> · 뿜는 몫 <b>81.4%</b> · 줄기 <b>55.2</b> · 쿨 <b>16초</b>.<br>⭐⭐ <b>여기서부터 판이 안 빈다</b> — 마지막 수류탄이 <b>20.70초</b>에 사라지는데 쿨이 16 이라 <b>4.70초가 겹친다.</b> 스킬의 성격이 바뀌는 자리다.<br>⭐ 갈래 셋과 뭉텅이 셋이 맞물려 <b>가까운 뭉텅이 3마리가 전부</b> 가스 안에 든다",3],
 ["PZgasBombD","L4 — 갈래 <b>4</b> <b>동서남북 90°</b>",
  "갈래가 <b>넷</b>이 되어 <b>위·오른쪽·아래·왼쪽</b>으로 돈다. 방사 <b>5.25</b> + 쉼 <b>0.75</b> ⇒ 뿜는 몫 <b>87.5%</b> · 유지 <b>18.00초</b> · 줄기 <b>65.6</b> · 탐지 반경 <b>187</b> · 쿨 <b>15초</b> · 겹침 <b>5.70초</b>.<br>⭐ 갈래 넷과 중간 뭉텅이의 <b>4마리</b>가 맞물려 <b>넷이 전부</b> 가스 안에 든다.<br>⚠️ 먼 뭉텅이가 <b>199.8</b> 이라 <b>13.1 이 모자란다</b> — 만렙이 그 마지막 턱을 넘는다",4],
 ["PZgasBombD","L5 — 수류탄 <b>3</b> · 갈래 <b>5</b> <b>5각 72°</b>",
  "<b>먼 뭉텅이(5마리 · 199.8)까지 탐지 반경(222) 안에 든다</b> ⇒ 수류탄 셋이 <b>세 뭉텅이를 다</b> 친다. 방사가 <b>네 번</b>이라 유지 <b>24.00초</b> · 뿜는 몫 <b>91.7%</b>(방사 <b>5.50</b> : 쉼 <b>0.50</b>) · 줄기 <b>78.0</b>(=확정본 그대로) · 쿨 <b>14초</b>.<br>⭐ <b>갈래 다섯과 먼 뭉텅이의 5마리가 정확히 맞물려 다섯이 전부</b> 가스 안에 든다 — 성장의 결론이 화면에 있다.<br>⭐ 마지막 수류탄이 <b>28.70초</b>에 사라지는데 쿨이 14 라 <b>14.70초가 겹친다</b> — <b>판이 늘 오염돼 있다</b>.<br>⚠️ <b>꼭짓점이 프레임당 119,440</b> — 엔진 상한(32,768)의 <b>364%</b>다. 이식 전에 반드시 나눠 그려야 한다",5]];

const PZMOUNT=[["pzdart","pkzdart",PZDART],
               ["pzgasgrow",""      ,PZGASGROW],
               // ⭐ 독가스는 **고르기에서 뺐다**(2026-08-23 사용자: 「독가스는
               //   **시안 확정**! 캐릭터 독 쪽으로 이동해줘」). 독침이 간 길 그대로다.
               ["pzgas" ,""       ,PZGAS ],
               ["pznumb","pkznumb",PZNUMB]];
/// ⭐ **고르기 페이지에만 서는 것** (2026-08-23 사용자 판정).
///   「독가스는 다 「고인다」만 두고 나머지 2개는 제거」·「독표창은 「나」 제외하고
///   나머지 2개는 제거」. 폭마는 제3안 **둘 다** 선다(아직 판정 전).
/// ⚠️⚠️ **「확정」이 아니다** — 사용자: 「고른 거는 **확정이 아니고 거기서 조금 더
///   다듬을 거야**」. 그래서 **목록에서 지우지 않고 여기서 거른다**:
///   캐릭터 장에는 셋이 그대로 서 있어 **언제든 되돌아갈 수 있다.**
///   ⇒ 광주 절은 「확정」이고 이 둘은 「다듬는 중」이다. 그 차이가 화면에도 있다.
// ⭐ **독침은 확정돼 캐릭터 장으로 갔다**(2026-08-23 사용자: 「독표창은 시안 확정.
//   독 쪽으로 이동」) ⇒ **고르기에서 뺀다.** 「옮겼으면 고르기에서 지워야지」가
//   이 사이클의 고정 실패라 넣기와 빼기를 **같이** 한다.
// ⚠️ **독가스 둘(`PZgasBombA`·`PZgasBombD`)을 뺐다** — 확정돼 독 장으로 갔다.
//   「옮겼으면 고르기에서 지워야지」가 이 사이클의 고정 실패라 **넣기와 빼기를 같이** 한다.
const PZPICK={PZnumbHalt:1,PZnumbShift:1};
for(const[charId,pickId,LIST]of PZMOUNT)
  for(const[id,onlyPicked]of[[charId,0],[pickId,1]]){
    const H=document.getElementById(id);if(!H)continue;
    for(const[k,nm,ds,lv]of LIST){
      if(onlyPicked&&!PZPICK[k])continue;
      // ⚠️ `lv` 를 안 주면 L5 다(스킬 격자의 규약). 성장 줄만 1~5 를 준다.
      tile(H,FX,k,nm,"",ds,236,236,undefined,lv||5);}}

// ══════════════════════════════════════════════════════════════════════════
// ④ 신설 넷 — 덫 · 뿌리창 · 수렁 · 미끼                        (2026-08-28)
//
// ⭐⭐ **독의 빈 네 칸을 채웁니다.** 지금 독은 여덟입니다(독침 · 기생 · 분열 ·
//   단전 · 극독 · 감염 · 독가스 · 결계·독 — 정본은 `lib/data/skill_element.dart`).
//   여기 넷이 서면 **열둘**이 찹니다.
//
// ⚠️⚠️ **아직 엔진에 없습니다.** 그래서 「스킬 열두 칸」 격자에는 안 넣습니다 —
//   그 격자는 `skill_element.dart` 를 되읽는 자리라 여기 넷을 얹으면 시안이
//   엔진보다 앞서 거짓말을 합니다. 독침 · 독가스가 그랬듯 **엔진에 들어가는
//   날 격자로 올라가고 이 절은 지웁니다**(그 흐름이 이 저장소의 규약입니다).
//
// ── 왜 이 넷인가 — **동사가 겹치지 않습니다** ─────────────────────────────
//   기존 여덟  쏜다 · 달라붙는다 · 쪼갠다 · 막는다 · 덧칠한다 · 옮는다 ·
//              퍼뜨린다 · 감싼다
//   신설 넷    **놓는다**(덫) · **솟는다**(뿌리창) · **고인다**(수렁) ·
//              **모은다**(미끼)
//   ⇒ 열둘의 동사가 전부 다릅니다.
//
// ── ⚠️ 되살리지 않은 것 ──────────────────────────────────────────────────
//   산성침 `acidspit` — 독침과 **둘 다 쏘는 것**이라 실루엣이 겹쳐 폐기됐습니다
//   독병  `venomvial` — 「독을 모은다」가 **엔진에 없는 메커니즘**이라 폐기됐습니다
//   가시덩굴 `thornvine` · 껍질 `carapace` — 폐기됐습니다
//   ⇒ 넷 중 어느 것도 그 넷의 자리를 다시 밟지 않습니다. 특히 **미끼는
//     「독을 모으는 것」이 아니라 「적을 모으는 것」**입니다 — 모으는 대상이
//     다르고, 엔진에는 이미 적의 자리를 옮기는 채널이 있습니다
//     (`sim/pools/status_groups.dart` 의 `displace` · `grab`).
//
// ── 지키는 규약 ───────────────────────────────────────────────────────────
//   ⑦ **난수를 한 톨도 안 씁니다** — 이 절은 `Math.random`(`R()`)을 쓰는
//     `emit`·`hitFoe`·`drawP` 를 **한 번도 안 부릅니다.** 알갱이도 손으로
//     그리고 위상은 전부 [hash] 파생입니다. (앞 절들은 `emit` 을 씁니다 —
//     그래서 이 넷만 「난수 0건」이 코드로 참입니다.)
//   ⑧ **루프의 끝과 처음이 같은 상태**라야 합니다 — 스킬마다 주기를 하나만
//     두고 모든 항을 그 하나에서 파생시킵니다.
//   ⑨ **판정 안내선을 안 그립니다**(반경 원 · 점선 금지).
// ══════════════════════════════════════════════════════════════════════════

// ── 눕는 면 — **타원이 기본값입니다** ─────────────────────────────────────
// `lib/data/fx_plane.dart` 의 `ground` 는 「바닥과 나란한 면 — 수평 궤도 ·
// 장판 · 자국 · 예고 · 발밑」이고 **눕습니다**. 이 파일이 이미 그 값을 쓰고
// 있습니다(`celHoop` 의 `.62`). 신설 넷도 같은 값 하나만 씁니다.
// ⚠️ 엔진으로 옮길 때 이 `.62` 는 **걷어야 합니다** — 세계가 한 번만 눕힙니다
//   (`render/world_fold.dart`). 두 번 눕히면 「이중 눕힘」이고, 이 저장소가
//   그 사고를 다섯 번 냈습니다.
const PZgSQ = .62;

/// 바닥에 눕는 얼룩 하나 — **원이 아니라 타원**입니다.
/// ⚠️ 가산이 아닙니다. 바닥 자국은 스스로 안 빛납니다.
function PZgLay(c, x, y, r, seed, col, a, sq) {
  if (!(r > .3) || !(a > .004)) return;
  const q = sq === undefined ? PZgSQ : sq;
  c.save(); c.translate(x, y); c.scale(1, q);
  fillPoly(c, PKrag(0, 0, r, seed, 11, .24, seed * .7), A(col, a));
  c.restore();
}

/// 가라앉는 알갱이 — 불티의 독 번역입니다(불티는 뜨고 이건 내려앉습니다).
/// ⚠️ 위상이 [hash] 파생이라 **매 프레임 처음부터 셉니다** — 난수가 없습니다.
function PZgGrit(c, t, x, y, r, n, seed, al, SC) {
  const TX = toneOf(PZTOX);
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 3.77;
    const ph = ((t * (.42 + .28 * hash(sd)) + hash(sd + 1.3)) % 1);
    const a = al * Math.min(1, ph * 6) * (1 - ph) * (1 - ph) * 1.7;
    if (a <= .012) continue;
    const ang = hash(sd + 2.7) * TAU;
    const d = r * (.20 + .78 * ph);
    const rr = (2.1 - 1.1 * ph) * SC * (.6 + .7 * hash(sd + 4.1));
    if (rr <= .2) continue;
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * PZgSQ + ph * ph * 6 * SC;
    fillPoly(c, PKrag(px, py, rr, sd, 7, .34, sd + t * 1.9), A(TX[0], a * .9));
    fillPoly(c, PKrag(px, py - rr * .16, rr * .52, sd + 5.1, 7, .28, sd - t * 1.6), A(TX[2], a * .8));
  }
}

// ══════════════════════════════════════════════════════════════════════════
// ⑴ 덫 — **설치물 문법의 첫 자리**
// ══════════════════════════════════════════════════════════════════════════
//
// ── 설치물이란 무엇인가 — **박자가 셋인 것** ──────────────────────────────
// 여태 독의 여덟은 전부 「걸면 그 자리에서 값이 나는 것」이었습니다. 설치물은
// **놓는 것과 값이 나는 것이 시간으로 갈라져** 있어 박자가 셋입니다:
//
//   ① **놓는 순간**   — 몸에서 나가 바닥에 닿고, 닿으면서 벌어집니다
//   ② **놓여 있는 동안** — 아무 일도 안 합니다. 숨만 쉬고 독을 흘립니다
//   ③ **밟혀 발동하는 순간** — 닫히고, 뿜고, 삭습니다
//
// ⚠️⚠️ **②를 안 그리면 설치물이 아닙니다.** ①과 ③만 그리면 그냥 「던져서
//   터지는 것」(수류탄 = 독가스)이 되고, 이 스킬이 새로 여는 문법이 사라집니다.
//   그래서 이 칸은 **주기의 45%를 「아무 일도 안 하는 동안」에 씁니다.**
//
// ⚠️ 「밟혀 발동」은 **적이 걸어 들어와야** 화면에 있습니다. 그래서 이 칸만
//   적을 움직입니다 — 덫마다 적 하나가 다가와 밟고, 물린 동안 붙잡혔다가,
//   놓이면 되돌아갑니다. 정지 화면에서도 읽히도록 **다가오는 자취**를 남깁니다.
//
// ⚠️ **독가스와 갈리는 자리를 한 줄로 못 박습니다** — 수류탄은 **제가 뿜고**
//   덫은 **밟혀야 뭅니다.** 하나는 시간이 정하고 하나는 적이 정합니다.

/// 적 넷 — 덫마다 하나씩 걸어 들어옵니다. **넓게 벌렸습니다**(꽂힌 표창이
/// 겹쳐 「초록 덩어리」로 보인 그 판정과 같은 이유).
const PZtFOE = [[-72, -50, 16], [64, -62, 16], [78, 34, 15], [-60, 46, 15]];
/// 덫이 놓이는 자리 — 몸과 적 사이입니다(적 발밑이 아닙니다).
const PZtSPOT = [[-36, -26], [33, -32], [40, 18]];
const PZtN = [1, 2, 2, 2, 3];        // 덫 수
const PZtBL = [3, 3, 3, 5, 5];        // 날 수 — L4 에서 삼엽이 오엽이 됩니다
// 박자(초) — **한 주기 6.00 에서 다 파생합니다.**
// ⚠️ 주기를 6.00 → **4.90** 으로 줄였습니다(첫 렌더 판정). 6.00 에서는 L1·L2 의
//   쉼이 1.70초라 **주기의 28% 동안 칸이 통째로 비었고**, 정지 화면에서 「덫이
//   없는 스킬」로 읽혔습니다. 지금은 쉼이 1.10초(22%)이고 L3~ 는 0.15초입니다.
const PZtPER = 4.90, PZtLAY = .28, PZtOPEN = .52, PZtBITE = 2.60,
  PZtSNAP = .10, PZtHOLD = .55, PZtRE = .30, PZtFADE = .55;
const PZtWALK = 1.70, PZtBACK = 1.30;   // 적이 다가오는 · 되돌아가는 시간

/// 덫 하나의 상태 — **스케줄 하나에서 전부 파생합니다.**
/// `fly` 나는 중(0~1) · `open` 벌어진 정도(0 닫힘 ~ 1 활짝) ·
/// `bite` 문 지 몇 초(−1 이면 안 물었습니다) · `al` 남은 진하기 ·
/// `hold` 붙잡고 있는가.
function PZtState(u, rearm) {
  const S = { fly: 0, open: 0, al: 0, bite: -1, hold: 0, gone: 0 };
  if (u < PZtLAY) { S.fly = u / PZtLAY; S.al = 1; return S; }
  S.fly = 1;
  const TB = [PZtBITE];
  if (rearm) TB.push(PZtBITE + PZtSNAP + PZtHOLD + PZtRE);
  const END = TB[TB.length - 1] + PZtSNAP + PZtHOLD + PZtFADE;
  if (u >= END) { S.gone = 1; return S; }
  S.al = 1;
  let open = Math.min(1, (u - PZtLAY) / (PZtOPEN - PZtLAY));
  for (let i = 0; i < TB.length; i++) {
    const b = TB[i], e = b + PZtSNAP, h = e + PZtHOLD, nxt = TB[i + 1];
    if (u >= b && u < b + .95) S.bite = u - b;
    if (u >= b && u < e) open = 1 - (u - b) / PZtSNAP;
    else if (u >= e && u < h) { open = 0; S.hold = 1; }
    else if (u >= h) {
      if (nxt !== undefined) open = Math.min(1, (u - h) / PZtRE);
      else { const f = Math.min(1, (u - h) / PZtFADE); open = .5 * f; S.al = 1 - f; }
    }
  }
  S.open = Math.max(0, Math.min(1, open));
  return S;
}

/// 덫 몸 하나 — **위에서 본 「이빨 고리」**입니다. [op] 1 활짝 ~ 0 닫힘.
///
/// ⚠️⚠️ **첫 판을 버렸습니다.** 표창의 날([PZblade1])을 셋 둘렀더니 화면에서
///   **초록 낙서**로 읽혔습니다 — 가는 획이 엉켜 글자 하나처럼 보였고, 이 파일
///   머리의 반려 규약 ①(「가는 획 여럿 = 거미줄」)에 그대로 걸립니다.
///   ⇒ 덫의 정체는 **날이 아니라 맞물리는 이**라, 실루엣을 **바닥 판 + 테 +
///     안팎으로 도는 이**로 다시 세웁니다. 셋 다 이미 있는 부품입니다
///     ([PZgLay] · [celHoop] · [celSpike]).
/// ⚠️ **닫힌 것과 벌어진 것이 같은 그림이면 안 됩니다** — 이가 **밖을 보다가
///   안을 보고**(π 를 돌아) 동시에 **길어집니다.** 회전만 주면 「돌았다」이고,
///   길이만 주면 「자랐다」입니다. 둘이 같이 가야 「물었다」입니다.
function PZtBody(c, x, y, R, rot, n, op, al, SC) {
  const TX = toneOf(PZTOX);
  // ⓐ **바닥 판** — 놓인 물건이라 발자국이 있어야 뜬 것처럼 안 보입니다.
  PZgLay(c, x, y, R * 1.10, rot * 3.1 + 7.7, TX[0], .62 * al);
  PZgLay(c, x, y, R * .74, rot * 5.3 + 2.9, PZSMK[0], .50 * al);
  // ⓑ **테** — 「여기까지가 덫이다」를 한 줄이 말합니다. 닫히면 더 밝습니다.
  celHoop(c, x, y, R * 1.02, PZgSQ, 0, 2.4 * SC, PZTOX, (.50 + .34 * (1 - op)) * al);
  // ⓒ **이** — 벌어지면 밖을 보고 짧고, 닫히면 가운데서 맞물리며 길어집니다.
  for (let i = 0; i < n; i++) {
    const a = rot + i * TAU / n;
    const bx = x + Math.cos(a) * R * .98, by = y + Math.sin(a) * R * .98 * PZgSQ;
    // ⚠️ 방향을 **눌린 좌표에서** 잽니다 — 눕는 면이라 안쪽이 `a+π` 가 아닙니다.
    const out = Math.atan2(by - y, bx - x);
    celSpike(c, bx, by, out + Math.PI * (1 - op),
      R * (.34 + .84 * (1 - op)), R * .26, PZTOX, (.72 + .28 * (1 - op)) * al);
  }
  // ⓓ **심** — 제일 밝은 점. 닫히면 물린 것이 여기 있습니다.
  gAdd(c, g => {
    gHalo(g, x, y, R * (.30 + .26 * (1 - op)), PZTOX, (.40 + .44 * (1 - op)) * al);
    gHalo(g, x, y, R * .15, PZTOX, .92 * al);
  });
}

FX.PZtrap = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  mgInit(st, SC, PZtFOE); stepFoes(st.F, dt);
  const TX = toneOf(PZTOX);
  const N = PZtN[LV - 1], BL = PZtBL[LV - 1];
  const REARM = atL(3), PUDDLE = atL(4), SHARD = atL(5);
  const R0 = 17 * SC;

  // ── 자리와 시각 ─────────────────────────────────────────────────────────
  const trap = [];
  for (let i = 0; i < N; i++) {
    const sp = PZtSPOT[i], f = st.F[i % st.F.length];
    const u = ((t + i * PZtPER / N) % PZtPER);
    // 적이 서는 자리 — 덫 **가장자리 밖**입니다(위에 올라서면 덫이 가려집니다).
    const sx = sp[0] * SC, sy = sp[1] * SC;
    const vx = f.hx - sx, vy = f.hy - sy, vd = Math.hypot(vx, vy) || 1;
    const stop = R0 * 1.30 + f.r * .92;
    trap.push({
      i, x: cx + sx, y: cy + sy, f, u, S: PZtState(u, REARM),
      tx: sx + vx / vd * stop, ty: sy + vy / vd * stop,
    });
  }
  // ── 적이 걸어 들어옵니다 ────────────────────────────────────────────────
  // ⚠️ 이 칸만 적을 움직입니다. 「밟혀 발동」은 밟는 것이 없으면 화면에 없습니다.
  for (const f of st.F) { f.ox = f.hx; f.oy = f.hy; f.pv = f.pv || 0; }
  for (const q of trap) {
    const f = q.f, u = q.u;
    const B = PZtBITE, LAST = REARM ? B + PZtSNAP + PZtHOLD + PZtRE : B;
    const OUTT = LAST + PZtSNAP + PZtHOLD;
    let e = 0;
    if (u >= B - PZtWALK && u < B) e = ease((u - (B - PZtWALK)) / PZtWALK);
    else if (u >= B && u < OUTT) e = 1;
    else if (u >= OUTT && u < OUTT + PZtBACK) e = 1 - ease((u - OUTT) / PZtBACK);
    q.e = e;
    if (e <= 0) continue;
    f.ox = f.hx + (q.tx - f.hx) * e; f.oy = f.hy + (q.ty - f.hy) * e;
    if (q.S.hold) { f.pv = Math.min(3, f.pv + dt * 2.4); f.hit = Math.max(f.hit, .55); }
  }
  for (const f of st.F) if (f.pv > 0) f.pv -= dt * .34;

  // ── 그리기 ──────────────────────────────────────────────────────────────
  // ⓐ **남은 자국**(L4~) — 제일 아래입니다.
  if (PUDDLE) for (const q of trap) {
    if (q.S.bite < 0) continue;
    const g = Math.max(0, 1 - q.S.bite / .95);
    PZgLay(c, q.x, q.y + 2 * SC, R0 * (1.5 + .7 * (1 - g)), q.i * 5.3 + 2.1, TX[0], .34 * g);
    PZsoft(c, q.x, q.y + 2 * SC, R0 * 1.9, TX[0], .16 * g, PZgSQ);
  }
  // ⓑ **다가오는 자취** — 정지 화면에서도 「걸어 들어왔다」가 읽힙니다.
  for (const q of trap) {
    if (!(q.e > .02) || q.e >= .999) continue;
    const f = q.f;
    for (let s = 3; s >= 1; s--) {
      const ee = Math.max(0, q.e - s * .085);
      const px = cx + f.hx + (q.tx - f.hx) * ee, py = cy + f.hy + (q.ty - f.hy) * ee;
      PZgLay(c, px, py + f.r * .8, f.r * (.52 - s * .09), q.i * 3.1 + s * 1.7, TX[0], .26 - s * .06);
    }
  }
  // ⓒ **적** — 표식은 앞뒤 층으로 끼워 그립니다.
  mgMarks(c, t, cx, cy, st.F, "poison", PZTOX, SC);
  // ⓓ **덫**
  for (const q of trap) {
    const S = q.S;
    if (S.gone) continue;
    if (S.fly < 1) {
      // ① **놓는 순간** — 낮게 날아가 바닥에 닿습니다. 날은 아직 접혀 있습니다.
      const v = S.fly, w = 1 - v;
      const px = cx + (q.x - cx) * v, py = cy + (q.y - cy) * v - Math.sin(Math.PI * v) * 22 * SC;
      for (let s = 2; s >= 1; s--) {
        const vv = v - s * .08; if (vv <= 0) continue;
        const qx = cx + (q.x - cx) * vv, qy = cy + (q.y - cy) * vv - Math.sin(Math.PI * vv) * 22 * SC;
        PZtBody(c, qx, qy, R0 * .62, t * 5.2 + q.i, BL, 0, .26 - s * .07, SC);
      }
      PZtBody(c, px, py, R0 * (.62 + .38 * v), t * 5.2 + q.i, BL, 0, 1, SC);
      // 그림자가 바닥에 남아 「높이」가 보입니다 — 날아가는 동안만 따로 그립니다.
      PZgLay(c, cx + (q.x - cx) * v, cy + (q.y - cy) * v, R0 * (.42 + .2 * w), q.i + 9.1, TX[0], .30);
      continue;
    }
    // ② **놓여 있는 동안** — 아주 느리게 숨 쉬고, 심에서 독이 떨어집니다.
    const brea = 1 + .06 * Math.sin(t * TAU / 2.6 + q.i * 2.1);
    PZtBody(c, q.x, q.y, R0 * brea, q.i * 1.7 + .3, BL, S.open, S.al, SC);
    if (S.open > .7 && S.bite < 0)
      PZdrip(c, t, q.x, q.y, R0 * .5, 2, .68 * S.al, SC, q.i * 4.3 + 1.9);
    // ③ **밟혀 발동하는 순간**
    if (S.bite >= 0) {
      const b = S.bite;
      // 물린 파문 — **눕는 고리**입니다(선 것이 아닙니다).
      if (b < .70) {
        const g = 1 - b / .70;
        celHoop(c, q.x, q.y, Math.max(2 * SC, R0 * (.5 + 2.6 * (1 - g))), PZgSQ, 0,
          (4.6 * g + 1.2) * SC, PZTOX, g * .90);
      }
      // 위로 뿜었다 가라앉는 알갱이 — **불티의 독 번역**입니다.
      if (b < .55) PZgGrit(c, t * 2.2 + q.i, q.x, q.y - 3 * SC, R0 * 2.2, 7, q.i * 8.1 + 3.3,
        (1 - b / .55) * .95, SC);
      // 부러진 침(L5) — 문 자리에서 침이 튑니다(독침의 조각 문법 그대로).
      if (SHARD && b < .85) {
        const g = 1 - b / .85;
        for (let k = 0; k < 6; k++) {
          const a = k / 6 * TAU + q.i * .7;
          const d = R0 * (.9 + 1.5 * (1 - g));
          celSpike(c, q.x + Math.cos(a) * d, q.y + Math.sin(a) * d * PZgSQ, a,
            8 * SC * g, 2.6 * SC * g, PZTOX, g * .95);
        }
      }
    }
  }
  hero(c, t, cx, cy, "gold", SC);
};

// ══════════════════════════════════════════════════════════════════════════
// ⑶ 수렁 — **장판입니다. 그래서 무조건 타원입니다**
// ══════════════════════════════════════════════════════════════════════════
//
// ⭐⭐ **이 스킬의 사건은 「자국」입니다.** 판이 걷혀도 바닥에 자국이 남고, 그
//   자국 위에 다시 깔면 **한 단 짙어집니다.** 그래서 같은 자리에 두 번 깔면
//   가운데에 **더 어두운 섬**이 생기고, 세 번이면 거의 검어집니다.
//   ⇒ 성장의 축이 「넓이」가 아니라 **「짙기」**입니다.
//
// ⚠️ **성역(`sanctum`)과 갈리는 자리** — 성역은 **몸을 따라다니는** 장판이라
//   내가 선 자리만 값이 나고, 자국을 안 남깁니다. 수렁은 **놓고 떠납니다.**
// ⚠️ **불웅덩이와 갈리는 자리** — 불웅덩이는 「사거리 끝에 고인 것」이라
//   분사의 부산물입니다. 수렁은 **그 자체가 스킬**이고 자국이 다음 판을 바꿉니다.
//
// ⚠️⚠️ **면은 고민할 것이 없습니다** — 장판입니다. 여기 그리는 원은 **전부**
//   타원이고 예외가 없습니다. 그것이 사용자가 못 박은 조건입니다.
//
// ── ⭐⭐ 발밑이 아니라 **떨어진 자리**입니다 (2026-08-28 사용자 판정) ───────
// 사용자 원문: 「보통 장판이라고 하면 **사거리가 있고, 캐릭터 주변에서 일정
//   사거리 바깥에다가 스킬 시전하는 경우**가 많더라고」 · 「같은 메커니즘으로
//   도는 게 있으면 **1개만 남기고**」.
//
// ⚠️⚠️ **첫 판은 몸 발밑이었습니다.** 자리가 `[-26,-14]`·`[26,-22]`·`[6,26]` 이라
//   판 셋이 전부 몸을 덮었고, 그러면 **독은 발밑 판을 둘 갖게 됩니다** —
//   결계·독(`wardtoxin`)의 발밑 웅덩이가 이미 그 자리에 있습니다. 무기를
//   여섯 자루까지 끼는 게임이라 같은 자리를 차지하는 두 판은 화면에서
//   **서로를 지웁니다.** ⇒ 자리를 몸 밖으로 뺐습니다(중심에서 60~69).
//
// ⇒ 자리가 밖으로 나가면서 **항이 셋 붙습니다**: ① 던지는 순간 ② 서 있는 동안
//   ③ 사라지는 순간. ①이 없으면 판이 **어디서 왔는지** 안 읽힙니다.
//
// ── ⚠️⚠️ 독가스(`gasbomb`)와 갈리는 자리 — **누적** ──────────────────────
// 둘 다 「던져서 그 자리에 무언가 생기는 것」이라 제일 가깝습니다. 갈림은 하나:
//   **독가스** — 퍼졌다 **사라지고 끝**입니다. 남는 것이 없습니다
//   **수렁**   — 걷혀도 **자국이 남고, 그 자국 위에서 다시 짙어집니다**
// ⇒ 독가스의 성장축은 「몇 갈래로 얼마나 오래 뿜나」이고, 수렁의 성장축은
//   **「몇 단까지 짙어지나」**입니다. 그림도 그렇게 갈립니다 — 독가스는 위로
//   뻗는 **줄기**, 수렁은 바닥에 눌어붙는 **얼룩**입니다.
// ⚠️ 던지는 물건도 다릅니다: 독가스는 **빛으로 만든 단단한 구**(자오선 + 실루엣)가
//   놓이고, 수렁은 **물컹한 덩이**가 날아가 **터집니다**(외곽선이 없습니다).
//
// ── ⚠️ 덫(`fangtrap`)과 갈리는 자리 — **점 ↔ 면** ────────────────────────
// 덫도 「바닥에 놓는 것」이라 ①의 그림이 닮을 수 있습니다. 갈라 둔 것 넷:
//   ⓐ **뜨는 높이** — 덫 22 · 수렁 **40**(수렁이 훨씬 높이 뜹니다)
//   ⓑ **도는가**   — 덫은 접힌 물건이 **돌면서** 갑니다 · 수렁 덩이는 **안 돕니다**
//   ⓒ **외곽선**   — 덫은 각진 폴리곤 · 수렁은 [PZsoft] 라 **경계가 없습니다**
//   ⓓ **닿을 때**  — 덫은 **벌어지고**(이가 밖으로 눕습니다) 수렁은 **터집니다**
//                    (방울 여덟이 사방으로 눕습니다)

// ⚠️ 이름을 `PZm` 으로 씁니다 — `PZb*` 는 **독가스 수류탄이 이미 다 씁니다**
//   (`PZbR`·`PZbHOLD`·`PZbLEN` …). 한 파일 안에서 `const` 가 하나만 겹쳐도
//   스크립트가 통째로 죽습니다.
const PZmFOE = [[-56, -40, 15], [-8, -66, 15], [42, -56, 15], [78, 6, 15], [-72, 22, 15]];
/// 판이 놓이는 자리 — **몸에서 떨어진 한 자리**입니다. 셋 다 중심에서 **58**
/// 이고 **90° 안에 모여** 있습니다(적이 뭉친 쪽에 깐다는 뜻입니다).
///
/// ⚠️⚠️ **두 조건을 같이 만족시켜야 합니다.** ① 몸 발밑이 아니어야 하고(사용자
///   판정) ② 서로는 **겹쳐야** 합니다(겹침이 이 스킬의 사건입니다). 처음엔 셋을
///   몸 둘레에 고르게 벌렸는데(`[-58,-32]`·`[56,-40]`·`[4,64]`) 이웃 간 거리가
///   114 라 **판끼리 한 화소도 안 겹쳤고**(2×44=88 < 114) 그런데도 코드가 겹침
///   얼룩을 그려 **없는 겹침을 그리는 거짓말**이 됐습니다. 지금 셋은 이웃 44 ·
///   양끝 82 라 **셋이 다 겹칩니다**(둘 다 2×44=88 미만).
/// ⭐ 그 결과 세 판이 다 겹치는 자리가 **(−8, −46)** — 몸에서 **46.7** 떨어진
///   곳입니다. 발밑이 아닙니다.
const PZmSPOT = [[-48, -33], [-10, -57], [33, -48]];
const PZmNP = [1, 2, 2, 3, 3];      // 판 수
const PZmR = 44;                    // 판 반지름(238 기준)
// 박자(초) — **던짐 · 터짐**이 앞에 붙었습니다.
const PZmTHROW = .40, PZmBURST = .20;
const PZmSPRD = .60, PZmBOIL = 4.00, PZmDRY = 1.00;
const PZmPER = 9.00;                // 한 판의 주기
/// 덩이가 뜨는 높이 — **덫의 22 와 갈립니다**(같은 「던져 놓는 것」이라 일부러).
const PZmLOB = 40;

/// 짙기 세 단 — 자국은 **겹친 만큼** 짙어집니다. 성장축이 이것입니다.
/// ⚠️ **0.24 / 0.40 / 0.54 에서 올렸습니다**(첫 렌더 판정): 1단 자국이 칸
///   바탕(`#0C0C12`)과 거의 같은 밝기라 **화면에 없는 것과 다름이 없었습니다.**
///   이 스킬의 사건이 자국인데 그 사건이 안 보이면 시안이 아무 말도 안 합니다.
const PZmDEEP = [.38, .56, .72];

FX.PZbog = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  mgInit(st, SC, PZmFOE); stepFoes(st.F, dt);
  const TX = toneOf(PZTOX);
  const NP = PZmNP[LV - 1], BOIL = atL(3), LONG = atL(4), WEB = atL(5);
  const RR = PZmR * SC;

  // ── 판 셋의 시각 — **한 스케줄에서 전부 파생합니다** ────────────────────
  const TF = PZmTHROW, TB = TF + PZmBURST, T1 = TB + PZmSPRD,
    T2 = T1 + PZmBOIL, T3 = T2 + PZmDRY;          // T3 = 6.20
  // ⚠️⚠️ 자국이 **주기 안에서 정확히 0 이 되어야** 합니다 — 안 그러면 되풀이가
  //   도는 순간 얼룩이 **툭 사라져** 이음매가 보입니다. 그래서 「오래」의 상한이
  //   남은 시간(2.80초)이고, 짧은 쪽은 그 42% 입니다.
  const REST = PZmPER - T3, MK = LONG ? REST : REST * .42;
  const pool = [];
  for (let i = 0; i < NP; i++) {
    const sp = PZmSPOT[i];
    const u = ((t + i * PZmPER / NP) % PZmPER);
    // 반지름 — 안에서 밖으로 번지고, 마를 때 가장자리부터 물러납니다.
    let r = 0, a = 0;
    if (u < TB) { r = 0; a = 0; }
    else if (u < T1) { r = RR * ease((u - TB) / PZmSPRD); a = 1; }
    else if (u < T2) { r = RR; a = 1; }
    else if (u < T3) { r = RR * (1 - .30 * (u - T2) / PZmDRY); a = 1 - (u - T2) / PZmDRY; }
    // 자국 — 판이 걷힌 뒤에도 남습니다. L4 부터 **더 오래** 남습니다.
    let ma = 0;
    if (u >= TB) ma = u < T3 ? 1 : Math.max(0, 1 - (u - T3) / MK);
    pool.push({ i, x: cx + sp[0] * SC, y: cy + sp[1] * SC, r, a, ma, u, sd: i * 7.31 + 2.3 });
  }

  // ── ① **던지는 순간** — 어디서 왔는지가 화면에 있어야 합니다 ────────────
  // ⚠️ 이 항이 빠지면 판이 **저절로 생긴 것**으로 읽히고, 「사거리 안의 한 자리에
  //   시전한다」는 규칙이 그림에서 사라집니다.
  for (const p of pool) {
    if (p.u >= TB) continue;
    // ⓐ **지목한 자리** — 던지는 내내 바닥에 옅은 테가 서 있습니다.
    const aim = Math.min(1, p.u / TF);
    celHoop(c, p.x, p.y, RR * (.34 + .30 * aim), PZgSQ, 0, 1.8 * SC, PZTOX, .34 * aim);
    if (p.u < TF) {
      const v = p.u / TF, w = 1 - v;
      const fx = cx + (p.x - cx) * v, fy = cy + (p.y - cy) * v - Math.sin(Math.PI * v) * PZmLOB * SC;
      // ⓑ **바닥 그림자** — 덩이가 다가올수록 커집니다(높이가 보입니다).
      PZgLay(c, cx + (p.x - cx) * v, cy + (p.y - cy) * v, RR * (.16 + .16 * v), p.sd + 4.1, TX[0], .34);
      // ⓒ **흘리는 꼬리** — 덩이는 **안 돕니다.** 뒤로 방울을 떨굽니다.
      for (let s = 3; s >= 1; s--) {
        const vv = v - s * .085; if (vv <= 0) continue;
        const qx = cx + (p.x - cx) * vv, qy = cy + (p.y - cy) * vv - Math.sin(Math.PI * vv) * PZmLOB * SC;
        PZsoft(c, qx, qy + s * 3 * SC, RR * (.16 - s * .028), TX[0], .40 - s * .09, 1);
      }
      // ⓓ **몸** — [PZsoft] 라 **외곽선이 없습니다**(덫은 각진 폴리곤입니다).
      //   날아가며 아래위로 늘어집니다 — 물컹한 것이라는 표시입니다.
      const sag = 1 + .34 * Math.sin(Math.PI * v);
      PZsoft(c, fx, fy, RR * .21 * (1 + .12 * w), TX[0], .92, sag);
      PZsoft(c, fx, fy - RR * .04, RR * .11, TX[1], .70, sag);
    } else {
      // ⓔ **터짐** — 방울 여덟이 사방으로 **눕습니다.**(덫은 이 자리에서 벌어집니다)
      const g = (p.u - TF) / PZmBURST;
      celHoop(c, p.x, p.y, Math.max(2 * SC, RR * (.20 + .62 * g)), PZgSQ, 0,
        (4.0 * (1 - g) + 1.0) * SC, PZTOX, (1 - g) * .95);
      for (let k = 0; k < 8; k++) {
        const a2 = k / 8 * TAU + p.sd, d = RR * (.16 + .74 * g);
        const rr = RR * .13 * (1 - g * .6);
        if (rr <= .3) continue;
        PZgLay(c, p.x + Math.cos(a2) * d, p.y + Math.sin(a2) * d * PZgSQ, rr,
          p.sd + k * 2.7, TX[0], (1 - g) * .80);
      }
    }
  }

  // ── ⓐ 자국 — **제일 아래**입니다. 겹친 자리가 짙어집니다 ────────────────
  for (const p of pool) {
    if (p.ma <= .01) continue;
    PZgLay(c, p.x, p.y, RR * 1.02, p.sd, TX[0], PZmDEEP[0] * p.ma);
    // 마른 테(L4~) — 자국이 판보다 **넓습니다**. 「여기까지 물이 찼었다」입니다.
    if (LONG) celHoop(c, p.x, p.y, RR * 1.06, PZgSQ, 0, 2.0 * SC, PZTOX, .22 * p.ma);
  }
  // 겹친 자리 — **두 판의 가운데**에 더 어두운 섬이 섭니다(2단).
  for (let i = 0; i < pool.length; i++) for (let j = i + 1; j < pool.length; j++) {
    const p = pool[i], q = pool[j], m = Math.min(p.ma, q.ma);
    if (m <= .01) continue;
    const d = Math.hypot(p.x - q.x, p.y - q.y);
    if (d > RR * 1.9) continue;
    const mx = (p.x + q.x) / 2, my = (p.y + q.y) / 2, mr = Math.max(0, RR * 1.02 - d / 2);
    PZgLay(c, mx, my, mr, p.sd + q.sd, TX[0], PZmDEEP[1] * m);
    // ⓑ **이어 붙음**(L5) — 자국끼리 손가락으로 이어져 한 덩이가 됩니다.
    if (WEB) for (let s = 1; s < 3; s++) {
      const v = s / 3;
      const lx = p.x + (q.x - p.x) * v, ly = p.y + (q.y - p.y) * v;
      PZgLay(c, lx, ly, RR * (.34 + .16 * Math.sin(v * Math.PI)), p.sd + s * 3.7,
        TX[0], PZmDEEP[1] * m * .9);
    }
  }
  // 세 판이 다 겹치는 한가운데 — **3단**입니다(거의 검습니다).
  // ⚠️ 짝 순회 **밖**에서 한 번만 그립니다 — 안에 두면 세 번 겹쳐 칠해져
  //   3단이 아니라 「까맣게 탄 자리」가 됩니다.
  // ⚠️⚠️ **셋이 진짜로 겹치는지 재고 그립니다.** 재기 전에는 무게중심에 그냥
  //   칠했는데, 자리를 몸 밖으로 뺀 뒤로 세 판이 서로 안 닿는데도 얼룩이
  //   섰습니다 — **없는 겹침을 그리는 거짓말**이고, 그 자리가 하필 **몸 발밑**
  //   이라 사용자가 금지한 「발밑 판」이 하나 더 생겨 있었습니다.
  if (pool.length > 2) {
    const m3 = Math.min(pool[0].ma, pool[1].ma, pool[2].ma);
    const dx = (pool[0].x + pool[1].x + pool[2].x) / 3;
    const dy = (pool[0].y + pool[1].y + pool[2].y) / 3;
    const inAll = pool.every((p) =>
      Math.hypot(dx - p.x, (dy - p.y) / PZgSQ) < RR * 1.02);
    if (m3 > .01 && inAll) PZgLay(c, dx, dy, RR * .42, 9.1, TX[0], PZmDEEP[2] * m3);
  }
  // ── ⓒ 판의 몸 ───────────────────────────────────────────────────────────
  for (const p of pool) {
    if (!(p.r > .5) || p.a <= .01) continue;
    // 몸 — 너덜너덜한 타원 둘을 겹쳐 「가장자리가 한 줄이 아니게」 만듭니다.
    PZgLay(c, p.x, p.y, p.r, p.sd, TX[0], .58 * p.a);
    // ⚠️ 둘째 겹은 **새 색이 아닙니다** — 이 파일이 이미 쓰는 연기색입니다
    //   (`PZSMK[0]` #2B302A). 진창은 「탁한 것」이라 그 색이 그 자리입니다.
    PZgLay(c, p.x, p.y, p.r * .93, p.sd + 3.3, PZSMK[0], .44 * p.a);
    // 안쪽 결 — **평평하면 안 됩니다.** 밀도 얼룩 여섯이 아주 느리게 돕니다.
    for (let k = 0; k < 6; k++) {
      const sd = p.sd + k * 5.1;
      const a2 = hash(sd) * TAU + t * .12 * (k % 2 ? 1 : -1);
      const d = p.r * (.20 + .52 * hash(sd + 1.1));
      PZsoft(c, p.x + Math.cos(a2) * d, p.y + Math.sin(a2) * d * PZgSQ,
        p.r * (.22 + .16 * hash(sd + 2.2)), TX[0], .30 * p.a, PZgSQ);
    }
    // 가장자리 테 — 「어디까지가 판인가」를 한 줄이 말합니다.
    celHoop(c, p.x, p.y, p.r, PZgSQ, 0, 2.4 * SC, PZTOX, .52 * p.a);
    // ⓓ **끓음**(L3~) — 거품이 솟았다 터집니다. 표면이 울퉁불퉁해집니다.
    if (BOIL) for (let k = 0; k < 9; k++) {
      const sd = p.sd + k * 3.91;
      const ph = ((t * (.52 + .34 * hash(sd)) + hash(sd + .7)) % 1);
      const a3 = hash(sd + 1.9) * TAU, d = p.r * .80 * hash(sd + 2.9);
      const bx = p.x + Math.cos(a3) * d, by = p.y + Math.sin(a3) * d * PZgSQ;
      const gr = (3.4 + 2.6 * hash(sd + 3.7)) * SC;
      if (ph < .72) {                       // 부풀어 오릅니다
        const g = ph / .72, rr = gr * (.3 + .7 * g);
        if (rr > .3) {
          fillPoly(c, PKrag(bx, by - rr * .3, rr, sd, 9, .18, sd + t), A(TX[0], .70 * p.a));
          fillPoly(c, PKrag(bx, by - rr * .42, rr * .44, sd + 2.1, 7, .16, sd - t), A(TX[1], .60 * p.a * g));
        }
      } else {                              // 터집니다 — 짧은 흰 심 + 눕는 고리
        const g = (ph - .72) / .28;
        celHoop(c, bx, by, Math.max(1, gr * (.5 + 1.5 * g)), PZgSQ, 0,
          (2.2 * (1 - g) + .8) * SC, PZTOX, (1 - g) * .85 * p.a);
      }
    }
    // 가라앉는 알갱이 — 판 위에 늘 조금 떠 있습니다.
    PZgGrit(c, t * .7 + p.i, p.x, p.y, p.r * .9, 5, p.sd + 17.7, .55 * p.a, SC);
    // ── ③ **사라지는 순간** — 가장자리가 안으로 물러납니다 ─────────────────
    if (p.u > T2) {
      const d = (p.u - T2) / PZmDRY;
      // ⓐ 물러난 자취 — 「여기까지 차 있었다」가 마지막까지 남습니다.
      celHoop(c, p.x, p.y, RR, PZgSQ, 0, 1.6 * SC, PZTOX, .30 * (1 - d));
      // ⓑ **테가 끊깁니다** — 마지막 0.35초에 고리가 조각으로 갈라집니다.
      //   ⚠️ 그냥 옅어지기만 하면 「꺼졌다」이고, 끊겨야 **「말랐다」**입니다.
      if (d > .65) celHoop(c, p.x, p.y, p.r, PZgSQ, 0, 2.0 * SC, PZTOX,
        .70 * (1 - d), (d - .65) / .35 * 1.05);
    }
  }
  // ── ⓔ 판 안의 적 — 중독됩니다 ──────────────────────────────────────────
  for (const f of st.F) {
    let inp = 0;
    for (const p of pool) if (p.r > .5 && p.a > .2) {
      const dx = (cx + f.ox + f.kx) - p.x, dy = ((cy + f.oy + f.ky) - p.y) / PZgSQ;
      if (Math.hypot(dx, dy) < p.r + f.r * .5) inp = 1;
    }
    if (inp) f.pv = Math.min(3, (f.pv || 0) + dt * 1.5);
    else if (f.pv > 0) f.pv -= dt * .40;
  }
  mgMarks(c, t, cx, cy, st.F, "poison", PZTOX, SC);
  hero(c, t, cx, cy, "gold", SC);
};

// ── 성장 줄 넷 — **다섯 칸이 같은 함수를 `LV` 만 갈아 부릅니다** ───────────
// ⚠️ 확정본을 칸마다 재해석해 두 번 반려당한 그 사고를 안 냅니다. 다른 것은
//   `tile()` 인자 하나뿐입니다.
// ⚠️⚠️ **다섯 칸이 서로 달라야 합니다** — 「L1 이 L5 와 모양이 같고 크기만
//   작은」 상태가 오늘 빙벽 셋에서 발견됐습니다. 그래서 레벨마다 **모양의
//   사건**을 하나씩 박았고, 아래 문구의 굵은 글자가 그 사건입니다.
const PZTRAPG = [
  ["PZtrap", "L1 — 덫 <b>하나</b> · 날 <b>셋</b> · 한 번 뭅니다",
    "몸에서 접힌 덩이가 <b>돌면서 낮게</b>(높이 22) 날아가 바닥에 닿고(0.28초), 닿으면서 <b>이 셋이 밖으로 벌어져 눕습니다</b>(0.24초). 그 뒤로는 <b>아무 일도 안 합니다</b> — <b>2.08초</b>(주기의 42%) 동안 아주 느리게 숨 쉬고(주기 2.6초) 심에서 독이 <b>한 방울씩 떨어질</b> 뿐입니다. 적이 걸어 들어와 밟으면 이가 <b>안을 보며 길어져</b> 0.10초에 맞물리고, 0.55초 붙잡았다가 <b>0.55초에 삭습니다</b>. 한 바퀴 <b>4.90초</b>", 1],
  ["PZtrap", "L2 — 덫 <b>둘</b> — 화면에 <b>두 자리</b>가 생깁니다",
    "덫이 <b>둘</b>이 되어 몸 좌우로 갈라 놓입니다. 서로 <b>박자가 어긋나</b>(주기의 절반) 한쪽이 무는 동안 다른 쪽은 놓이는 중입니다 — <b>세 박자가 한 화면에 같이 보이는</b> 첫 칸입니다", 2],
  ["PZtrap", "L3 — <b>다시 벌어집니다</b> · 한 덫이 <b>두 번</b> 뭅니다 <b>← 분기점</b>",
    "문 뒤 0.55초를 붙잡고 나서 <b>0.30초에 걸쳐 도로 열립니다.</b> 그리고 <b>한 번 더 뭅니다</b> — 놓는 값이 두 배가 되는 자리입니다. ⭐ 모양의 사건은 <b>닫힘 → 열림 → 닫힘</b>이라 정지 화면에서도 앞뒤 두 칸과 갈립니다", 3],
  ["PZtrap", "L4 — 날이 <b>다섯</b> · 문 자리에 <b>자국</b>이 남습니다",
    "실루엣이 <b>삼엽에서 오엽</b>으로 바뀝니다(독의 몸 표식이 삼엽이라 셋이 기본값이었습니다). 그리고 문 자리에 <b>눕는 자국</b>이 남아 덫이 삭은 뒤에도 <b>거기 무엇이 있었다</b>가 보입니다", 4],
  ["PZtrap", "L5 — 각성 · 덫 <b>셋</b> · 물 때 <b>침이 튑니다</b>",
    "덫이 <b>셋</b>이라 판에 늘 하나는 벌어져 있습니다. 그리고 무는 순간 물린 적 둘레로 <b>짧은 침 여섯</b>이 튀어 박힙니다 — 독침의 <b>부러진 조각</b> 문법을 그대로 씁니다(새 부품이 아닙니다)", 5]];

const PZBOGG = [
  ["PZbog", "L1 — 판 <b>하나</b> · 짙기 <b>1단</b>",
    "⭐ <b>몸 발밑이 아니라 떨어진 자리</b>(중심에서 <b>58</b>)에 <b>던져</b> 깝니다 — 물컹한 덩이가 <b>높이 40 으로 떠서</b> 0.40초 날아가(안 돌고 · 외곽선 없이 · 뒤로 방울을 흘리며) <b>터지고</b>(0.20초 · 방울 여덟이 사방으로 눕습니다) 그 자리가 <b>안에서 밖으로 번져</b> 판이 됩니다(0.60초). 4.00초 고여 있다가 <b>가장자리부터 마르고</b>(1.00초 · 반지름 0.70배로 물러나며 마지막 0.35초엔 테가 <b>끊깁니다</b>) 걷힙니다. 걷혀도 <b>자국이 남습니다</b>(1.18초). 한 바퀴 <b>9.00초</b>.<br>⚠️ 판은 <b>무조건 타원</b>입니다 — 장판이라 바닥과 나란한 면이고, 여기 그리는 원에 <b>예외가 하나도 없습니다</b>", 1],
  ["PZbog", "L2 — 판 <b>둘</b> · 겹친 자리가 <b>2단</b>으로 짙어집니다",
    "판이 둘이 되면서 <b>자국이 겹치기 시작합니다.</b> 겹친 자리에만 <b>더 어두운 섬</b>이 서서, 화면에 처음으로 <b>짙기 차이</b>가 생깁니다 — 이 스킬의 성장축이 넓이가 아니라 <b>짙기</b>라는 것이 여기서 보입니다", 2],
  ["PZbog", "L3 — <b>끓습니다</b> <b>← 분기점</b>",
    "거품 아홉이 <b>부풀었다 터집니다</b>(부풂 0.72 : 터짐 0.28 · 위상은 전부 해시 파생). 터질 때 <b>눕는 고리</b>가 한 번 퍼집니다. ⭐ 표면이 <b>평평한 것에서 울퉁불퉁한 것</b>으로 바뀌어 앞 두 칸과 정지 화면에서 갈립니다", 3],
  ["PZbog", "L4 — 판 <b>셋</b> · 자국이 <b>오래</b> · <b>3단</b>이 처음 나옵니다",
    "자국이 남는 시간이 <b>1.18 → 2.80초</b>로 늘어(주기 안에 남은 시간을 다 씁니다) 판이 늘 얼룩져 있습니다. 셋이 겹치는 한가운데가 <b>3단</b>이라 거의 검습니다. 그리고 자국 둘레에 <b>마른 테</b>가 생겨 <b>자국이 판보다 넓습니다</b> — 「여기까지 찼었다」가 보입니다.<br>⚠️ 「오래」의 상한이 <b>2.80</b>인 것은 <b>이음매 때문</b>입니다 — 자국이 주기 안에서 0 이 안 되면 되풀이가 도는 순간 얼룩이 <b>툭 사라집니다</b>", 4],
  ["PZbog", "L5 — 각성 · 자국끼리 <b>이어 붙습니다</b>",
    "자국 사이에 <b>손가락</b>이 뻗어 셋이 <b>한 덩이</b>가 됩니다. ⭐ 실루엣이 <b>「원 셋」에서 「이어진 한 덩이」</b>로 바뀌는 것이 각성의 전부입니다 — 크기를 안 키웠습니다(장판을 키우면 그냥 넓은 판이고, 그건 L1 과 모양이 같습니다)", 5]];

// ⚠️ **덫 · 수렁만 남았습니다**(2026-08-28 사용자: 「신설은 덫, 수렁 결정」).
//   뿌리창 · 미끼는 **정의와 지도를 같은 편집에서** 걷었습니다 — 그 둘이
//   나빴던 것이 아니라 **사용자가 다른 둘을 골랐습니다.**
const PZNEWM = [["pztrap", PZTRAPG], ["pzbog", PZBOGG]];
for (const [hid, LIST] of PZNEWM) {
  const H = document.getElementById(hid); if (!H) continue;
  for (const [k, nm, ds, lv] of LIST) tile(H, FX, k, nm, "", ds, 236, 236, undefined, lv);
}

// ══════════════════════════════════════════════════════════════════════════
// ⑤ 독의 **기존 넷을 다시** — 극독 · 감염 · 단전 · 기생        (2026-08-28)
// ══════════════════════════════════════════════════════════════════════════
//
// ── 사용자 반려 원문 ──────────────────────────────────────────────────────
//   「독의 경우 **극독과 감염의 차이점이 미비**하고(**누운 정도의 차이밖에 못
//    느끼겠음**). 스킬 메커니즘은 다르다는 걸 알고 있음. 그러나 **시전되는
//    방향과 이펙트가 두 개가 흡사**함. **퀄리티를 올려야 함. 더 다양한 형태의
//    시안들을 도전해야 함.** **단전**은 '**독' 스킬처럼 보이게** 다시 해 주고,
//    '**기생**'의 경우에도 **그림체 변화**가 필요함」
//
// ── ⭐⭐ 「누운 정도의 차이밖에」는 **말 그대로 참이었습니다** ──────────────
// 옛 둘을 코드로 견주면 갈리는 축이 **하나뿐**입니다:
//
//   극독 `MGFX.mgPoisonBrand`  celHoop(…, **1**  , …, "toxin", …)   ← 안 눕습니다
//   감염 `MGFX.mgPoisonSpread` celHoop(…, **.62**, …, "toxin", …)   ← 눕습니다
//
// 나머지는 같습니다 — **같은 초록(`TONE.toxin`)** · **적 몸을 감싼 동심 고리** ·
// **도는 삼엽 `celSpike` 셋**. 실측(480프레임 · L5 · 프레임당 호출 수):
//
//              celHoop   celSpike        ← 옛 둘이 **같은 부품**을 씁니다
//   옛 극독      4.0       19.2
//   옛 감염     17.6       22.7
//   새 여섯      0.0    0.0~0.3          ← 고리도 삼엽도 **안 씁니다**
//
// ⇒ 사용자가 본 것은 인상이 아니라 **코드에 그대로 적혀 있던 사실**입니다.
//
// ── ⭐⭐ 엔진은 이미 넷을 갈라 놨습니다 — **시안만 안 받았습니다** ──────────
// `lib/render/cel_tones.dart` 실측(색상각은 값에서 계산했습니다):
//
//   극독 `brand`  #D94FA0  **325° 자홍**    ← 짝이 **폭마**(뇌+독 · 한방형)
//   감염 `spore`  #C6E82A  **71° 유황황록** ← 짝이 **독무**(독+풍 · 광역형)
//   기생 `latch`  #57D96B  **129° 독녹**    ← 짝이 **역병**(빙+독 · 지속형)
//   단전 `halt`   #2FA845  **131° 짙은 독녹**(2026-08-22 놋쇠금 49° 에서 이적)
//
// 시안은 넷 중 **셋을 같은 초록**으로, 하나를 **회백 쇠(`gold`)** 로 그리고
// 있었습니다. ⇒ 색은 「새로 짓는 것」이 아니라 **엔진에서 받아 오는 것**입니다.
// ⚠️ 그래도 **색만으로는 안 갈립니다**(사용자가 「누운 정도의 차이밖에」라고
//   한 자리가 정확히 그것입니다) — 아래 넷은 **동사 · 방향 · 개수 · 실루엣 ·
//   박자**를 같이 바꿉니다. 색은 그중 한 항일 뿐입니다.
//
// ── ⭐ 동사는 **엔진 코드에서 뽑았습니다**(지어내지 않았습니다) ─────────────
//
//   극독 `brand`  **조인다**  — `_cinch += dt` · `rInner = R*(1−progress)` ·
//                 `_collapse()`. 표적이 **하나**(`_mark` 핸들 하나)이고 방향이
//                 **안으로**이며 끝이 **무너짐**입니다.
//   감염 `spore`  **옮는다**  — `_infect()` 가 물든 적을 **발원지 장부에 더합니다**
//                 (`_srcN++`). 표적이 **불어나고**(1 → 12) 방향이 **몸에서 몸으로**
//                 이며 끝이 **포화 뒤 동시 폭발**입니다.
//   단전 `halt`   **꿴다**    — 못이 **밖에서 안으로** 박히고 `applyShock` 로
//                 붙잡았다가 `_released` 에 튑니다.
//   기생 `latch`  **빤다**    — `_age` 가 자라며 `kLatchDmgMinMul → MaxMul` 로
//                 **한 대가 점점 아파집니다**. 몸에 붙어 **같이 움직입니다**.
//
// ⇒ 갈라야 할 축은 **넷**입니다: **하나 ↔ 여럿** · **안으로 ↔ 밖으로** ·
//   **끝나는 법**(무너짐 ↔ 번짐) · **마디 배분**(아래).
//
// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **모든 스킬은 다섯 마디로 설계한다**                  (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
//   「스킬시전 → 스킬생성(공격 넣기 전) → 스킬발현(공격) →
//     스킬소멸(공격 후) → 스킬종료」
//   사용자 원문: 「지금 우리 스킬은 대부분 '즉발'이거나 스킬이 발동되기 전까지의
//   시간들이 짧고 **소멸되는 시간도 짧아서 화려함이나 액션감이 부족**한 듯해」
//
// ── ⭐ 이 지시가 「극독 ↔ 감염」의 **두 번째 손잡이**입니다 ────────────────
// 정지 화면이 아니라 **시간**에서 갈립니다. 넷의 마디 배분을 일부러 다르게
// 줬습니다 — 같은 다섯 마디인데 **어디에 시간을 쓰는지가 반대**입니다:
//
//            시전   생성      발현      소멸    종료   ← 한 바퀴에서 차지하는 몫
//   극독     0.30   3.70      0.18      0.44   0.22    **생성이 76%** · 발현은 한 점
//   감염     0.34   0.30    2.2~5.8     0.45   0.60    **발현이 68%** · 되풀이한다
//   단전     0.18   0.22    1.0~1.5     0.26   0.12    **발현이 붙잡는 시간**
//   기생     0.08   0.40   1.6~3.6      0.50   0.40    **발현이 빨리는 내내**
//
//   ⇒ 극독은 **오래 조이고 한 점에 터지고**, 감염은 **곧장 번지기 시작해 오래
//     되풀이합니다.** 두 칸을 나란히 두고 보면 **시간의 모양이 반대**입니다.
//
// ⚠️ **밸런스 수는 한 톨도 안 건드렸습니다.** 엔진이 정한 것(조임 4.0/3.0 ·
//   반경 · 지속 · 붙잡는 시간 · 주기)은 그대로이고, **그 안에서 무엇을 언제
//   그리는가**만 다시 짰습니다. 늘어난 것은 시안의 **되풀이 꼬리**(소멸·종료)
//   뿐이고, 그것이 곧 아래 「엔진에 내야 하는 것」의 한 항이 됩니다.
//
// ⚠️ **다섯 마디가 각각 다른 그림**이라야 합니다(같은 도형의 알파만 오르내리면
//   그것은 마디가 하나입니다). 넷 다 마디마다 **부품이 바뀝니다** — 아래 각
//   함수의 `── 마디` 주석이 무엇이 바뀌는지 한 줄씩 적어 뒀습니다.
//
// ── ⭐⭐ 「퀄리티」 — **텍스쳐 · 파티클 · 덩어리 셋을 다** ─────────────────
// 염 · 뇌 갈래에 같은 날 난 지시와 **같은 방향**입니다(「셀셰이딩으로 그리지
// 말고 빛과 화려함을」 · 「텍스쳐, 파티클, 덩어리 3개 전부 다」).
// 이 파일이 그것을 내는 법은 **이미 이 저장소가 스스로 찾아 둔 것**입니다:
//
//   ① **덩어리** — [PZ5mass]. 너덜너덜한 3단 계조 면(가산 0).
//   ② **텍스쳐** — [PZ5grain]. 덩어리 **안쪽**에 해시 파생 얼룩.
//      ⭐ **면적이 안 늘어 쌉니다** — 이미 칠한 자리 위에 겹치기 때문입니다.
//   ③ **빛**   — `docs/design/시안-판정.md`:「`celStroke` 는 같은 경로를 세 번
//      긋는다 … **어두운 집 안에 밝은 심**이고, 그게 눈에는 글로우다」.
//      ⇒ 고리도 [PZ5ring] 처럼 `arcPts + celStroke` 로 만들면 **`celHoop` 의
//        가산을 안 탑니다.** 같은 문서의 실측표가 그 근거입니다.
//   ④ **파티클** — [PZ5motes]. 불티의 독 번역이라 **뜨지 않고 가라앉습니다**.
//
// ⚠️⚠️ **낙서가 되면 안 됩니다.** 이 파일이 이미 한 판을 통째로 버렸습니다
//   (덫 첫 판 — 「가는 획 여럿 = 초록 낙서」). 낙광 여덟이 떨어진 조건 넷
//   (① 가는 획 ② 많은 갈래 ③ 균일한 굵기 ④ 서로 엉킴)을 **전부 뒤집습니다**.
//
// ── 지키는 규약 ───────────────────────────────────────────────────────────
//   ⑦ **난수 0** — `emit`·`hitFoe`·`drawP`·`pvMark` 를 **한 번도 안 부릅니다**.
//   ⑧ **주기 하나에서 다 파생** — 되풀이의 끝과 처음이 같은 상태입니다.
//   ⑨ **판정 안내선을 안 그립니다** — 다만 **판정 겉면은 그립니다**(그것은
//     안내선이 아니라 「보이는 것 = 맞는 것」의 계약입니다).
//   ⑩ **새 색을 한 톨도 안 짓습니다** — 전부 `cel_tones.dart` 의 값 그대로입니다.
// ══════════════════════════════════════════════════════════════════════════

// ── 팔레트 — **엔진에서 받아 옵니다** ─────────────────────────────────────
// ⚠️ `vfx.js` 를 안 고칩니다. `TONE` 은 `const` 지만 **속성 추가는 됩니다**
//   (`const` 는 재바인딩만 막습니다). 이름을 `pz` 로 격리했습니다.
TONE.pzBrand = ["#3D0A28", "#D94FA0", "#FFE4F2"];  // 극독 · 자홍 325°
TONE.pzSpore = ["#4A4A08", "#C6E82A", "#F8FFD4"];  // 감염 · 유황황록 71°
TONE.pzHalt = ["#08210F", "#2FA845", "#C8F0D0"];  // 단전 · 짙은 독녹 131°
TONE.pzLatch = ["#123D1C", "#57D96B", "#E6FFEA"];  // 기생 · 독녹 129°
const PZ5BR = "pzBrand", PZ5SP = "pzSpore", PZ5HL = "pzHalt", PZ5LT = "pzLatch";

// ── ① 덩어리 — 너덜너덜한 3단 계조 면. **가산 0** ─────────────────────────
/// [sq] 눕힘(1 이면 안 눕습니다) · [rot] 가장자리 위상.
/// ⚠️ 세 겹이 **같은 자리에 겹칩니다** — 칠하는 면적은 바깥 겹 하나 몫이고
///   안쪽 둘은 그 안이라 거의 안 늘어납니다(잉크가 싼 화려함의 자리).
function PZ5mass(c, x, y, r, seed, k, a, sq, rot) {
  if (!(r > .35) || !(a > .004)) return;
  const T = toneOf(k), q = sq === undefined ? 1 : Math.max(.10, sq), ro = rot || 0;
  c.save(); c.translate(x, y); c.scale(1, q);
  fillPoly(c, PKrag(0, 0, r, seed, 11, .26, ro), A(T[0], a));
  fillPoly(c, PKrag(0, -r * .11, r * .66, seed + 3.1, 9, .22, ro + .7), A(T[1], a * .92));
  // ⭐⭐ **심만 가산**입니다(2026-08-28) — 겉 두 겹은 그대로 채운 면이라
  //   실루엣이 안 흔들리고, 넓이가 바깥의 **8.4%**(0.29²)뿐이라 값이 거의 안
  //   듭니다. 「면이 본체, 그 안에 빛이 든다」가 이 한 줄입니다.
  //   ⚠️ 겉 겹을 가산으로 두면 겹칠 때 바탕이 새어 **유령 덩어리**가 됩니다.
  c.globalCompositeOperation = "lighter";
  fillPoly(c, PKrag(0, -r * .19, r * .29, seed + 7.3, 7, .20, ro - .5), A(T[2], a * .95));
  c.restore();
}

// ── ② 텍스쳐 — 덩어리 **안쪽**의 결 ───────────────────────────────────────
/// 어두운 알갱이와 밝은 알갱이를 섞어 뿌립니다. **평평하고 단순한 것 금지**의
/// 답이고, 이미 칠한 면 위에 얹으므로 면적이 거의 안 늡니다.
function PZ5grain(c, x, y, r, seed, k, a, sq, n, rot) {
  if (!(r > 1.2) || !(a > .01)) return;
  const T = toneOf(k), q = sq === undefined ? 1 : Math.max(.10, sq), ro = rot || 0;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 2.39;
    const ang = hash(sd) * TAU, d = r * (.14 + .60 * hash(sd + 1.1));
    const rr = r * (.09 + .15 * hash(sd + 2.2));
    if (rr < .35) continue;
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * q;
    const dark = hash(sd + 3.3) < .58;
    fillPoly(c, PKrag(px, py, rr, sd + 5.5, 7, .36, ro + sd),
      A(dark ? T[0] : T[2], a * (dark ? .56 : .34)));
  }
}

// ── ③ 빛 — **가산 없는 고리**(`arcPts` + `celStroke`) ────────────────────
// ⚠️⚠️ **「가산 합성 금지」는 규칙이 아니었습니다**(2026-08-28 정정). 레포 원문은
//   「**배경** 한 장. 가산을 한 번도 안 쓴다 — **이펙트가 전부 가산이라**」이고,
//   금지 대상은 **배경**입니다. ⇒ 이 고리가 가산을 안 타는 까닭은 「금지」가
//   아니라 **값**입니다 — `celHoop` 의 가산 후광이 `lineWidth = w×3.2` 짜리
//   **넓은 면**이라 비쌉니다(감염 최대 잉크 −39% 가 그 몫입니다).
//   **가늘고 긴 것의 가산**(심 획 · 작은 후광)은 싸고 크게 이깁니다 — 기생 L5 의
//   연결부가 그 예입니다([PZ5cord]·[PZ5cordEnd] · L5 평균 잉크 +4.8%).
/// ⚠️ `celHoop` 을 안 씁니다. 저 함수는 `lineWidth = w*3.2` 짜리 **가산 후광**을
///   한 겹 더 긋습니다(`vfx.js:490`) — 넓은 면이라 이 저장소에서 제일 비싼
///   종류이고, `시안-판정.md` 가 지목한 「안 타도 되는 가산」이 바로 그것입니다.
/// [cut] 0 이면 닫힌 고리, 크면 그만큼 벌어진 호입니다.
function PZ5ring(c, x, y, r, sq, rot, w, k, a, cut) {
  if (!(r > .4) || !(a > .004) || !(w > .05)) return;
  const cu = cut || 0;
  if (cu >= TAU - .05) return;
  const q = sq === undefined ? 1 : sq;
  const a0 = rot - Math.PI + cu * .5, a1 = rot + Math.PI - cu * .5;
  const n = Math.max(9, Math.min(30, Math.round(r * .42)));
  const P = [];
  for (let i = 0; i <= n; i++) {
    const ang = a0 + (a1 - a0) * i / n;
    P.push([x + Math.cos(ang) * r, y + Math.sin(ang) * r * q]);
  }
  // ⭐⭐ **고리도 빛입니다**(2026-08-28) — 네 칸이 다 이 한 붓을 쓰므로, 여기
  //   한 줄이 다섯 마디 전부의 가산 몫을 올립니다. 획은 **가늘고 길어** 쌉니다.
  PZ5lit(c, P, w, k, a);
}

// ── ③-나 ⭐⭐ **빛나는 획** — 가산 획 + 밝기 층 셋   (2026-08-28 사용자 판정) ──
// 사용자: 「극독: **감기는 이펙트가 면인데 면으로 처리하지 말고 바꿔** 줘」
//
// ⚠️⚠️ 오늘 전 속성에서 나온 그 문제입니다 — 염에서 「투사체가 **빛이 아니고
//   그냥 면**」 · 「**색종이 덕지덕지**」. 독은 `PZ5` 블록이 **가산 2회**뿐이라
//   가장 심한 자리였고, **극독의 올가미가 그 대표**입니다.
//
// ⭐ 층 셋 — **어두운 가장자리 → 본색 → 거의 흰 심**:
//     ㉠ 가장자리 `T[0]` 폭 `w`    · **비가산** ← 실루엣을 지키는 층입니다.
//        여기까지 가산으로 두면 겹칠 때 바탕이 새어 **유령**이 됩니다.
//     ㉡ 본색   `T[1]` 폭 `.58w` · **가산**
//     ㉢ 흰 심  `T[2]` 폭 `.24w` · **가산** ← 「빛난다」는 이 한 획이 냅니다.
// ⚠️ **가는 것에만 씁니다.** 넓은 면의 가산은 이 저장소가 값 때문에 걷어 온
//   것이고(`celHoop` 의 `w×3.2` 후광 · 감염 최대 잉크 −39%), 가늘고 긴 것의
//   가산은 싸고 크게 이깁니다(기생 L5 연결부 **+4.8%**).
/// [pts] 점 목록 · [w] 제일 바깥 폭 · [a] 진하기.
function PZ5lit(c, pts, w, k, a) {
  if (!pts || pts.length < 2 || !(a > .004) || !(w > .05)) return;
  const T = toneOf(k);
  const path = () => {
    c.beginPath();
    pts.forEach((v, i) => i ? c.lineTo(v[0], v[1]) : c.moveTo(v[0], v[1]));
  };
  // 🔴🔴 **2026-08-29 재반려 — 「빛나는 획」이 실은 면이었습니다.**
  // 사용자: 「**올가미 꼬리 저거 셀셰이딩 여전한 거 아니야? 저거 빛으로 구현한
  //   거임? 걍 존나 딱 봐도 면적 같은데**」
  // ⚠️⚠️ **제 자가 못 봤습니다** — 앞 자는 `fill`(면)만 셌는데 꼬리는 **획**입니다.
  //   획을 세어 보니 이 붓 하나가 올가미 비가산 잉크의 **1위**였습니다.
  // ── 왜 면으로 읽혔나 — **잉크로 세면 답이 나옵니다** ──────────────────────
  //   옛 배분  어두운 테 `.88 × w`(**비가산**) · 본색 `.70 × .58w` · 심 `.95 × .24w`
  //     ⇒ 비가산 **0.880w** vs 가산 0.634w — **비가산이 58%**입니다.
  //       굵은 획일수록(올가미는 최대 `7×SC`) 어두운 몸통이 넓어져 **띠**가 되고,
  //       겹치는 자리는 그대로 **면**입니다. 밝은 심은 폭의 **24%** 뿐이라 묻힙니다.
  //   새 배분  어두운 테 `.38 × w` · 본색 `.85 × .80w` · 심 `.98 × .34w`
  //     ⇒ 비가산 **0.380w** vs 가산 **1.013w** — **비가산 27%**. 밝은 몫이
  //       **1.6배**가 되어 **획이 빛으로** 읽힙니다.
  // ⚠️ **어두운 테를 안 없앴습니다** — 없애면 겹칠 때 바탕이 새어 **유령**이 됩니다.
  //   테는 남기되 **테답게**(폭은 그대로, 진하기만 낮춰) 둡니다.
  // ⚠️⚠️ **이 붓은 독의 열두 칸이 전부 씁니다** — 한 곳을 고치면 장 전체가
  //   같이 밝아집니다. 그것이 의도입니다(「이펙트는 원래 가산으로 그린다」).
  c.lineCap = "round"; c.lineJoin = "round";
  path(); c.strokeStyle = A(T[0], .38 * a); c.lineWidth = w; c.stroke();
  gAdd(c, g => {
    g.lineCap = "round"; g.lineJoin = "round";
    path(); g.strokeStyle = A(T[1], .85 * a); g.lineWidth = w * .80; g.stroke();
    path(); g.strokeStyle = A(T[2], .98 * a); g.lineWidth = w * .34; g.stroke();
  });
}

// ── ④ 파티클 — 가라앉는 알갱이. **불티의 독 번역** ────────────────────────
/// ⚠️ 위상이 [hash] 파생이라 상태를 안 들고 다닙니다 — 난수 0 이고 되풀이가
///   주기 끝에서 저절로 닫힙니다.
/// [rise] 양수면 뜨고 음수면 가라앉습니다(독은 −).
function PZ5motes(c, t, x, y, r, n, seed, k, a, SC, sq, rise) {
  const T = toneOf(k), q = sq === undefined ? PZgSQ : sq, ri = rise === undefined ? -6 : rise;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 3.77;
    const ph = (t * (.44 + .30 * hash(sd)) + hash(sd + 1.3)) % 1;
    const al = a * Math.min(1, ph * 6) * (1 - ph) * (1 - ph) * 1.7;
    const ang = hash(sd + 2.7) * TAU;
    const d = r * (.18 + .80 * ph);
    const rr = (2.2 - 1.15 * ph) * SC * (.6 + .7 * hash(sd + 4.1));
    const px = x + Math.cos(ang) * d;
    const py = y + Math.sin(ang) * d * q - ri * ph * ph * SC;
    // ⭐⭐ **수명 끝에 터집니다** — `docs/vfx/REFERENCE.md` 독-1 의 그 한 항입니다.
    //   알갱이는 보통 **그냥 사라지는데**(알파 0), 사라지는 대신 터지게 하면
    //   알갱이 하나가 죽을 때마다 화면에 **작은 사건**이 하나 생깁니다.
    //   ⚠️ 링은 **테두리만** 긋습니다(안 채웁니다) — 참고장이 「거의 공짜」라고
    //     적어 둔 까닭이 그것입니다.
    if (ph > .86) {
      const u = (ph - .86) / .14;
      PZ5ring(c, px, py, rr * (1.0 + 1.6 * u) * 1.6, q, sd + t,
        (1.5 - .9 * u) * SC, k, a * (1 - u) * .80);
    }
    if (al <= .012 || rr <= .2) continue;
    fillPoly(c, PKrag(px, py, rr, sd, 7, .34, sd + t * 1.9), A(T[0], al * .9));
    // ⭐ 알갱이의 심은 **가산**입니다 — 제일 작은 것이라 가산이 제일 쌉니다.
    c.save(); c.globalCompositeOperation = "lighter";
    fillPoly(c, PKrag(px, py - rr * .16, rr * .52, sd + 5.1, 7, .28, sd - t * 1.6), A(T[2], al * .95));
    c.restore();
  }
}

// ══════════════════════════════════════════════════════════════════════════
// ⑦ **엔진 텍스처 18장의 캔버스 짝** — 결 셋            (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
// 사용자: 「**전부 다 꽂아 줘, 텍스쳐 18장 다 쓰라고**」.
//
// ── ⚠️⚠️ 시안은 엔진 아틀라스를 **못 씁니다** ────────────────────────────
// 엔진에는 `lib/render/atlas/sprite_id.dart` 의 **이펙트 텍스처 18장**이 이미
// 구워져 있고(`kFxTextureSprites`) `quadTex`/`quadTexGrad` 가 입힐 수 있는데,
// **스킬 드라이버 80종이 한 장도 안 씁니다.** 시안은 캔버스라 그 아틀라스를
// 직접 못 부릅니다. ⇒ **여기서는 그 결을 그리고**, 어느 칸이 어느 스프라이트로
// 가는지는 **이식 인벤토리**(장의 ⑫ 표)가 이름으로 적습니다.
// ⚠️ 그 줄이 없으면 이식하는 사람이 **폴리곤으로 다시 그려** 비싸지고 덜
//   화려해집니다 — 표가 곧 배관입니다.
//
// ── 왜 이 셋만 새로 짓나 ──────────────────────────────────────────────────
// 열여덟 중 **열다섯은 이미 있는 붓이 짝입니다**(덩어리 = `kenney_smoke` ·
// 결 = `noise_grainy` · 램프 = `mask_glow_soft` · 진 = `mask_crystal_mandala` …).
// 짝이 **없던 것이 셋**이라 그 셋만 짓습니다: **잎맥 · 흐르는 줄 · 방사 스포크**.

/// `fxNoiseVein` 의 캔버스 짝 — **잎맥.** 가운데 큰 줄기 하나에 곁줄기가 답니다.
/// ⭐ 균사(감염)와 마른 실뿌리(기생)가 이 결입니다 — **잎맥이 곧 「퍼지는 것」의
///   그림**이라, 덩어리 위에 얹으면 그 덩어리가 「자란 것」으로 읽힙니다.
/// ⚠️ **이미 칠한 면 위**라 면적이 안 늡니다(가는 획뿐입니다).
function PZ5vein(c, x, y, r, ang, K, a, SC, seed, n) {
  if (!(r > 1.4) || !(a > .01)) return;
  const N = n || 5;
  const ux = Math.cos(ang), uy = Math.sin(ang), nx = -uy, ny = ux;
  const M = [];
  for (let i = 0; i <= 4; i++) {
    const u = i / 4 - .5;
    M.push([x + ux * r * 1.7 * u + nx * r * .16 * Math.sin(u * 3.4 + seed),
    y + uy * r * 1.7 * u + ny * r * .16 * Math.sin(u * 3.4 + seed)]);
  }
  celStroke(c, M, 1.5 * SC, K, a * .90);
  for (let i = 0; i < N; i++) {
    const u = (i + .5) / N - .5, s = i % 2 ? 1 : -1;
    const bx = x + ux * r * 1.7 * u, by = y + uy * r * 1.7 * u;
    const L = r * (.34 + .30 * hash(seed + i * 2.7)) * (1 - Math.abs(u) * 1.3);
    if (L <= .5) continue;
    const aa = ang + s * (1.05 + .35 * hash(seed + i * 3.1));
    celStroke(c, [[bx, by],
    [bx + Math.cos(aa) * L * .58, by + Math.sin(aa) * L * .58],
    [bx + Math.cos(aa + s * .3) * L, by + Math.sin(aa + s * .3) * L]],
      1.1 * SC, K, a * .72);
  }
}

/// `fxNoiseStreak` 의 캔버스 짝 — **흐르는 줄.** 폴리라인을 따라 짧은 눈금이
/// 흘러갑니다. ⭐ 이것이 곧 **UV 흐름(panning)** 의 캔버스 흉내입니다 —
/// 엔진에서는 `quadTexGrad` 에 UV 를 밀어 넣으면 셰이더 없이 같은 그림이
/// 납니다(`REFERENCE.md` 3-5: 「없어서 못 하는 것이 아니라 몰라서 안 쓰는 것」).
/// [flow] 초당 흐르는 몫 — 위상이 `t` 파생이라 **되풀이 이음매가 없습니다.**
function PZ5streak(c, t, pts, w, K, a, SC, seed, n, flow) {
  if (pts.length < 2 || !(a > .01)) return;
  const seg = [];
  let tot = 0;
  for (let i = 0; i + 1 < pts.length; i++) {
    const d = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
    seg.push(d); tot += d;
  }
  if (!(tot > 1)) return;
  const at = (u) => {
    let d = u * tot, i = 0;
    while (i < seg.length - 1 && d > seg[i]) { d -= seg[i]; i++; }
    const w2 = seg[i] ? d / seg[i] : 0;
    return [pts[i][0] + (pts[i + 1][0] - pts[i][0]) * w2,
    pts[i][1] + (pts[i + 1][1] - pts[i][1]) * w2];
  };
  for (let i = 0; i < n; i++) {
    const ph = ((t * (flow === undefined ? .55 : flow) + hash(seed + i * 3.13) + i / n) % 1);
    const u0 = Math.max(0, ph - .07), u1 = Math.min(1, ph + .07);
    if (u1 - u0 < .02) continue;
    const p0 = at(u0), p1 = at(u1);
    celStroke(c, [p0, p1], w, K, a * Math.sin(ph * Math.PI) * .95);
  }
}

/// `fxNoiseSpokes` 의 캔버스 짝 — **방사 스포크.** 원 안쪽에서 밖으로 짧은
/// 눈금이 뻗습니다. ⭐ 굳은 몸(단전)이 「평평한 초록 원」이 되는 것을 막는 결이고,
/// 삭음이 깊어질수록 눈금이 길어져 **짙기가 아니라 결로도** 읽힙니다.
function PZ5spokes(c, x, y, r0, r1, n, rot, K, a, SC, seed) {
  if (!(r1 > r0) || !(a > .01)) return;
  for (let i = 0; i < n; i++) {
    const ang = rot + i / n * TAU;
    const j = .78 + .44 * hash(seed + i * 2.31);
    celStroke(c, [[x + Math.cos(ang) * r0, y + Math.sin(ang) * r0],
    [x + Math.cos(ang) * r1 * j, y + Math.sin(ang) * r1 * j]],
      1.0 * SC, K, a * (.55 + .40 * hash(seed + i * 5.7)));
  }
}

// ── ⑤ 몸에 묻은 독 — `pvMark` 를 안 씁니다(그 함수가 `R()` 를 탑니다) ──────
function PZ5taint(c, t, x, y, r, k, a, SC, seed) {
  if (!(a > .02)) return;
  const T = toneOf(k);
  for (let i = 0; i < 3; i++) {
    const sd = seed + i * 4.13;
    const ang = hash(sd) * TAU + t * .18, d = r * (.20 + .48 * hash(sd + 1.7));
    fillPoly(c, PKrag(x + Math.cos(ang) * d, y + Math.sin(ang) * d, r * (.20 + .16 * hash(sd + 2.9)),
      sd + 6.1, 8, .34, sd + t * .5), A(T[0], a * .70));
  }
  for (let i = 0; i < 3; i++)
    PZ5ring(c, x, y, r * 1.04, 1, i / 3 * TAU + t * .22, 1.5 * SC, k, a * .55, 4.4);
}

/// 마른 자국 — **소멸·종료 마디의 공용 부품**입니다. 눕고, 끊기고, 삭습니다.
/// ⚠️ 그냥 옅어지면 「꺼졌다」이고, **끊겨야 「말랐다」**입니다(수렁이 같은
///   판단을 이미 했습니다).
function PZ5scar(c, t, x, y, r, k, a, SC, seed, dry) {
  if (!(a > .01)) return;
  const T = toneOf(k), cut = 1.1 + 3.4 * dry;
  c.save(); c.translate(x, y); c.scale(1, PZgSQ);
  fillPoly(c, PKrag(0, 0, r * (1 - .22 * dry), seed + 2.2, 13, .22, seed), A(T[0], a * .55));
  c.restore();
  for (let i = 0; i < 3; i++)
    PZ5ring(c, x, y, r * (1 - .22 * dry) * (1 - .04 * i), PZgSQ,
      i / 3 * TAU + t * .06, (1.8 - .4 * i) * SC, k, a * (.8 - .2 * i), cut);
}


// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **독의 마법진** — 「화려함을 팍팍」의 공통 어휘        (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
// 사용자가 붉은 선화 마법진 넉 장을 레퍼런스로 줬습니다. 그 그림에서 **밀도가
// 나오는 자리가 여섯**이고, 아래 [PZ5sigil] 이 여섯을 그대로 답니다:
//
//   ① **동심 고리 3~5** — 굵기가 **다 다릅니다**(같으면 그냥 과녁입니다)
//   ② **파선 고리** 한두 겹
//   ③ **눈금·룬 띠** — 바깥 고리를 도는 **짧은 획 수십 개**
//   ④ **정다각별 둘을 회전시켜 겹칩니다**(삼각 · 오각 · 팔각)
//   ⑤ **위성 원 셋~넷** — 각각 다른 작은 기호
//   ⑥ **중심 코어** — **여기만 밝습니다**
//
// ── ⭐ 왜 이것이 「단전을 독처럼」과 「기생의 그림체 변화」를 같이 푸나 ──────
// 진에는 **무엇이 벌어지는지가 적혀 있습니다.** 단전이 뇌처럼 보이던 이유의
// 절반은 「예고 없이 쇠가 날아온다」였는데, 시전 마디에 독의 진이 서면 그
// 자리가 **주술**이 됩니다. 기생도 무는 순간이 한 프레임이라 안 보였는데,
// 진이 생성 마디를 채웁니다.
//
// ── ⚠️⚠️ 눕힘은 **0.500** 입니다 ─────────────────────────────────────────
// 마법진은 **땅에 눕습니다** — `vfx.js` 의 `LX3SQT`(= `render/world_fold.dart`
// 의 `kFoldSquashPick` = **0.500**)이 채택값입니다. 이 파일이 다른 데서 쓰는
// 바닥 눕힘 `PZgSQ`(.62)와 **다른 값**이라 헷갈리면 안 됩니다 — 저쪽은 얼룩·
// 장판의 값이고 이것은 **진의 값**입니다.
// ⚠️ 엔진으로 옮길 때 이 값은 **걷어야 합니다**(세계가 한 번만 눕힙니다).
const PZ5SQT = .500;

// ── ⚠️ 예산 — **가늘고 긴 잉크만 씁니다** ────────────────────────────────
// GPU 가 무는 것은 **칠하는 픽셀 면적**이지 도형 개수가 아닙니다
// (`docs/perf/BASELINE.md`: raster p95 18.24 vs build 0.49 — **37배**).
//   싼 것  — 획 · 짧은 눈금 · 파선 · 별꼴 교차선 · 방울   ⇒ 진은 **전부 이것**
//   비싼 것 — 넓은 블룸 · 넓은 반투명 면 · 큰 가산 원      ⇒ 진에는 **코어 하나**
// ⚠️ 독은 **넓은 반투명 면(안개·수렁)에 기대기 쉬운 속성**이라 이 함정에 제일
//   가깝습니다. 그래서 진의 밀도는 **개수**로 냈지 **면적**으로 안 냈습니다.

/// 별 하나 — `{n/k}` 정다각별의 **닫힌 폴리라인**입니다(면이 아니라 획).
function PZ5star(c, x, y, r, n, k, rot, w, K, a, grow) {
  const g = Math.max(0, Math.min(1, grow === undefined ? 1 : grow));
  if (g < .04 || !(a > .004)) return;
  const P = [], N = Math.max(2, Math.round(n * g) + 1);
  for (let i = 0; i <= N; i++) {
    const ang = rot + (i * k) / n * TAU;
    P.push([x + Math.cos(ang) * r, y + Math.sin(ang) * r * PZ5SQT]);
  }
  celStroke(c, P, w, K, a);
}

/// 파선 고리 — 짧은 호 [n] 개. **고리를 안 닫는 것**이 이 항의 전부입니다.
function PZ5dash(c, x, y, r, n, rot, w, K, a, grow) {
  const g = Math.max(0, Math.min(1, grow === undefined ? 1 : grow));
  if (g < .02 || !(a > .004)) return;
  const seg = TAU / n * .52;
  for (let i = 0; i < n; i++) {
    const a0 = rot + i / n * TAU;
    if (a0 - rot > g * TAU) break;
    const P = [];
    for (let j = 0; j <= 3; j++) {
      const ang = a0 + seg * j / 3;
      P.push([x + Math.cos(ang) * r, y + Math.sin(ang) * r * PZ5SQT]);
    }
    celStroke(c, P, w, K, a);
  }
}

/// 눈금·룬 띠 — 바깥 고리를 도는 **짧은 획 수십 개**. 길이가 셋씩 갈립니다
/// (전부 같은 길이면 톱니바퀴로 읽힙니다).
function PZ5ticks(c, x, y, r0, r1, n, rot, w, K, a, grow) {
  const g = Math.max(0, Math.min(1, grow === undefined ? 1 : grow));
  for (let i = 0; i < n; i++) {
    const u = i / n;
    if (u > g) break;
    const ang = rot + u * TAU;
    const len = (i % 4 === 0) ? 1 : (i % 2 === 0 ? .62 : .40);
    const ra = r0, rb = r0 + (r1 - r0) * len;
    celStroke(c, [[x + Math.cos(ang) * ra, y + Math.sin(ang) * ra * PZ5SQT],
    [x + Math.cos(ang) * rb, y + Math.sin(ang) * rb * PZ5SQT]],
      w * (i % 4 === 0 ? 1.35 : 1), K, a * (i % 4 === 0 ? 1 : .78));
  }
}

/// ⭐ 독의 마법진 한 벌.
/// [R] 바깥 반지름 · [d] 밀도(0~1 — 얕게 쓸 때 항을 줄입니다) ·
/// [grow] 0→1 이면 **제 손으로 그려집니다**(시전 마디의 그림).
/// ⚠️ 중심 코어만 면이고 나머지는 전부 획입니다.
function PZ5sigil(c, t, x, y, R, K, a, SC, seed, grow, d) {
  if (!(R > 4) || !(a > .006)) return;
  const g = Math.max(0, Math.min(1, grow === undefined ? 1 : grow));
  const dn = d === undefined ? 1 : d;
  const T = toneOf(K), sp = t * .16, sn = -t * .11;
  // ① 동심 고리 — 굵기가 다 다릅니다.
  const RG = [[1.00, 2.6], [.93, 1.1], [.74, 1.9], [.55, 1.0], [.34, 1.5]];
  const nr = dn > .7 ? 5 : (dn > .4 ? 4 : 3);
  for (let i = 0; i < nr; i++)
    PZ5ring(c, x, y, R * RG[i][0], PZ5SQT, sp + i, RG[i][1] * SC, K,
      a * (.62 + .30 * (i === 0 ? 1 : 0)) * Math.min(1, g * 1.6));
  // ② 파선 고리
  PZ5dash(c, x, y, R * .845, 18, sn, 1.5 * SC, K, a * .70, g);
  if (dn > .7) PZ5dash(c, x, y, R * .445, 11, sp * 2, 1.3 * SC, K, a * .58, g);
  // ③ 눈금·룬 띠
  PZ5ticks(c, x, y, R * .955, R * 1.075, dn > .7 ? 36 : 24, sn, 1.3 * SC, K, a * .78, g);
  // ④ 정다각별 둘 — **회전시켜 겹칩니다.**
  PZ5star(c, x, y, R * .70, 5, 2, sp * 1.7, 1.9 * SC, K, a * .80, g);
  if (dn > .55) PZ5star(c, x, y, R * .70, 8, 3, sn * 1.3 + .4, 1.4 * SC, K, a * .62, g);
  if (dn > .85) PZ5star(c, x, y, R * .40, 3, 1, sp * 2.4 + 1.1, 1.7 * SC, K, a * .70, g);
  // ⑤ 위성 원 셋~넷 — 각각 **다른 작은 기호**가 듭니다.
  const ns = dn > .7 ? 4 : 3;
  for (let i = 0; i < ns; i++) {
    const ang = sn * .8 + i / ns * TAU;
    if (i / ns > g) break;
    const sx = x + Math.cos(ang) * R * .845, sy = y + Math.sin(ang) * R * .845 * PZ5SQT;
    const sr = R * .13;
    PZ5ring(c, sx, sy, sr, PZ5SQT, 0, 1.3 * SC, K, a * .80);
    if (i % 3 === 0) PZ5star(c, sx, sy, sr * .72, 3, 1, sp * 3, 1.2 * SC, K, a * .75);
    else if (i % 3 === 1) PZ5dash(c, sx, sy, sr * .62, 5, sn * 3, 1.2 * SC, K, a * .75);
    else celStroke(c, [[sx - sr * .7, sy], [sx + sr * .7, sy]], 1.2 * SC, K, a * .75);
  }
  // ⑥ 중심 코어 — **여기만 밝고, 여기만 면입니다.**
  const cr = R * .10 * (.5 + .5 * g);
  PZ5glow(c, x, y, cr * 3.4, K, a * .50, PZ5SQT);      // 빛 램프 1
  PZ5mass(c, x, y, cr, seed + 3.3, K, a * .95, PZ5SQT, sp * 3);
  PZ5grain(c, x, y, cr, seed + 9.7, K, a * .8, PZ5SQT, 5, sn * 2);
}


// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **연쇄 터짐** — 「엉키고 돌고 부딪히며 터지고 터지는」  (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
// 리니지 계열 갈무리 여섯에서 뽑은 **공통 구조**를 그대로 답니다. 전부
// 「**바닥 진 + 솟는 기둥**」이고 층이 여섯입니다:
//
//   ① **바닥에 누운 고리** — 색 테 + 안쪽 밝은 면. **반드시 먼저.**
//   ② **그 위로 솟는 기둥** — 곧은 빛 한 줄이 아니라 **꼬인 여러 가닥**이
//      다발로 올라갑니다(사용자: 「**엉킨다**」·「**돈다**」)
//   ③ **밑동에서 부채꼴 스커트** — 주름진 치마꼴로 바깥으로 퍼집니다
//   ④ **바닥에 갈라진 금** — 진 바깥으로 뻗습니다
//   ⑤ **위로 튀는 파편** 수십
//   ⑥ **밝기 세 층** — 중심 **흰 포화** → 본색 → 어두운 바깥 테
//      ⚠️ 흰 코어 없이 본색만 쓰면 아무리 항을 늘려도 「연하다」로 읽힙니다.
//
// ── ⭐⭐ 이 한 부품이 「극독 ↔ 감염」의 **세 번째 손잡이**입니다 ────────────
// 사용자: 「한 번 펑이 아니라 **연쇄로** 터진다」. 그런데 **어디서** 연쇄가
// 나느냐를 둘이 반대로 씁니다 — 같은 「세 번」인데 정지 화면에서 갈립니다:
//
//   극독  **한 자리에서 깊게** — 세 번이 **같은 자리**에 겹칩니다
//         (반지름 .55 → .80 → 1.00 으로 **파고듭니다**)
//   감염  **옆으로 번지며**   — 세 번이 **자리를 옮겨** 납니다
//         (물든 몸 → 다음 몸 → 그 다음 몸)
//
// ⭐ 독은 이 「연쇄」가 **태생인 속성**입니다 — 중독이 원래 시간을 두고 번지는
//   것이니까요. 그래서 이것은 덧붙인 장식이 아니라 **속성의 문법**입니다.
//
// ── 박자 ──────────────────────────────────────────────────────────────────
//   터짐 셋이 **0.00 · 0.08 · 0.18초**에 시작하고 한 번이 [PZ5popT] 를 삽니다.
const PZ5popOFF = [0, .08, .18];
const PZ5popT = .30;

/// 터짐 한 번 — 위 여섯 층. [u] 0→1 이 이 한 번의 진행입니다.
/// [up] 기둥의 키(0 이면 기둥을 안 세웁니다 — 바닥짜리 터짐).
/// ⚠️ **넓은 면은 흰 코어 하나뿐**입니다. 나머지는 전부 획·짧은 획·작은 덩이라
///   raster 예산(칠하는 픽셀 면적)을 안 건드립니다.
function PZ5pop(c, t, x, y, R, K, a, SC, seed, u, up) {
  if (!(u > 0) || u >= 1 || !(a > .006)) return;
  const T = toneOf(K), e = u * u * (3 - 2 * u), fade = 1 - u;
  const UP = up === undefined ? 1 : up;
  // ① 바닥에 누운 고리 — **먼저** 깝니다.
  PZ5ring(c, x, y, R * (.18 + .92 * e), PZ5SQT, seed, (3.4 * fade + .8) * SC, K, a * fade * .95);
  PZ5ring(c, x, y, R * (.10 + .62 * e), PZ5SQT, -seed, (2.0 * fade + .6) * SC, K, a * fade * .70);
  // ③ 부채꼴 스커트 — 주름진 치마꼴(밑동에서 바깥으로).
  for (let j = 0; j < 9; j++) {
    const ang = seed * 2 + j / 9 * TAU;
    const r0 = R * .16 * e, r1 = R * (.30 + .74 * e) * (.78 + .34 * hash(seed + j));
    PZ5lit(c, [[x + Math.cos(ang) * r0, y + Math.sin(ang) * r0 * PZ5SQT],
    [x + Math.cos(ang) * r1 * .62, y + Math.sin(ang) * r1 * .62 * PZ5SQT - R * .10 * e],
    [x + Math.cos(ang) * r1, y + Math.sin(ang) * r1 * PZ5SQT]],
      (2.4 * fade + .5) * SC, K, a * fade * .78);
  }
  // ④ 바닥에 갈라진 금 — 진 **바깥**으로 뻗습니다.
  for (let j = 0; j < 5; j++) {
    const ang = seed * 5 + j / 5 * TAU + .3;
    const r0 = R * .86 * e, r1 = R * (1.05 + .40 * e);
    PZ5crack(c, [[x + Math.cos(ang) * r0, y + Math.sin(ang) * r0 * PZ5SQT],
    [x + Math.cos(ang + .10) * (r0 + r1) * .5, y + Math.sin(ang + .10) * (r0 + r1) * .5 * PZ5SQT],
    [x + Math.cos(ang - .06) * r1, y + Math.sin(ang - .06) * r1 * PZ5SQT]],
      1.6 * SC, K, a * fade * .70);
  }
  // ② 솟는 기둥 — **꼬인 가닥 셋이 서로를 감고 돕니다.**
  if (UP > .02) for (let j = 0; j < 3; j++) {
    const ph = j / 3 * TAU + t * 2.2 + seed;
    const HH = R * 1.55 * UP * e, P = [];
    for (let i = 0; i <= 8; i++) {
      const w = i / 8;
      const rr = R * .30 * (1 - w * .55) * Math.cos(ph + w * 5.0);
      P.push([x + rr, y - HH * w + R * .06 * Math.sin(ph + w * 5.0) * PZ5SQT]);
    }
    PZ5lit(c, P, (3.0 - 1.6 * u) * SC, K, a * fade * .90);
  }
  // ⑤ 위로 튀는 파편.
  for (let j = 0; j < 10; j++) {
    const sd = seed * 7 + j * 2.71, ang = hash(sd) * TAU;
    const d = R * (.30 + 1.05 * e) * (.5 + .8 * hash(sd + 1.1));
    const hgt = R * 1.05 * UP * e * hash(sd + 2.2) - R * .55 * e * e;
    const rr = (2.6 - 1.5 * u) * SC * (.6 + .8 * hash(sd + 3.3));
    if (rr < .25) continue;
    PZ5mass(c, x + Math.cos(ang) * d, y + Math.sin(ang) * d * PZ5SQT - hgt, rr,
      sd, K, a * fade * .95, .92, ang + t);
  }
  // ⑥ **밝기 세 층** — 중심 흰 포화. 이것이 없으면 「연하다」로 읽힙니다.
  // 🔴 2026-08-29 — **셋을 통째로 가산으로 감쌉니다.** 터짐의 중심은 **빛**이고,
  //   흰 포화를 비가산으로 두면 그것이 그대로 **흰 판**입니다(사용자가 올가미에서
  //   「딱 봐도 면적」이라 한 것과 같은 병). ⭐ 가산 눈금도 「**터지는 것 = 40%
  //   이상**」이라 이 자리가 바로 그 자리입니다.
  const cr = R * (.30 - .18 * u);
  gAdd(c, g => {
    PZ5glow(g, x, y, cr * 2.6, K, a * fade * .55, PZ5SQT);   // 빛 램프 1
    PZ5mass(g, x, y, cr, seed + 1.7, K, a * fade, PZ5SQT, t * 2);
    if (u < .55) {
      const wf = 1 - u / .55;
      fillPoly(g, PKrag(x, y, cr * .62 * (.5 + .5 * wf), seed + 4.4, 9, .22, t * 3),
        A(T[2], a * wf * .95));
    }
  });
}
/// 연쇄 셋 — [at] 가 터짐 `k` 의 자리를 돌려줍니다.
/// ⚠️ 자리를 함수로 받는 것이 이 부품의 요점입니다: **극독은 늘 같은 자리**를,
///   **감염은 옮겨 가는 자리**를 돌려줘 같은 코드가 정반대로 읽힙니다.
function PZ5chain(c, t, age, R, K, a, SC, seed, at, up) {
  for (let k = 0; k < 3; k++) {
    const u = (age - PZ5popOFF[k]) / PZ5popT;
    if (u <= 0 || u >= 1) continue;
    const p = at(k);
    if (!p) continue;
    PZ5pop(c, t, p[0], p[1], R * (p[2] === undefined ? 1 : p[2]), K, a, SC,
      seed + k * 3.7, u, up);
  }
}


// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ **2D 로 3D 처럼** — 전 속성 공통 여덟 조항        (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
// 사용자 원문: 「**2D 임에도 불구하고 3D처럼 충분히 효과를 낼 수 있을 것 같아.**
// 예시는 얼음이긴 한데, **모든 계열에 다 해당**하는 거 같아」
//
//   ㉠ **면을 쪼갠다** — 조각 하나가 한 색이 아니라 **서너 개의 면**으로 갈라지고
//      면마다 밝기가 다릅니다. **입체의 8할.** ⭐ 같은 픽셀을 몇 색으로 나눠
//      칠할 뿐이라 **면적이 안 늡니다**(삼각형만 조금 늘고 정원에 안 걸립니다)
//   ㉡ **앞은 크고 뒤는 작다**
//   ㉢ **뒤로 갈수록 밝고 옅다** — 대기 원근. **면적 안 늚**
//   ㉣ **앞의 것이 뒤의 것을 가린다** — 깊이의 제일 강한 신호. **공짜**(차례만)
//   ㉤ **밑동에 들쭉날쭉한 흰 테** — 「**뚫고 나왔다**」. 없으면 「붙여 놓았다」
//   ㉥ **각도가 다 다르고 바깥일수록 눕는다**
//   ㉦ **떨어져 나온 조각이 공중에** — 「지금 막 일어났다」
//   ㉧ **발치에 어두운 덩어리** — 그림자
//
// ── ⭐⭐ 이것이 「극독 ↔ 감염」의 **네 번째이자 제일 강한 손잡이**입니다 ─────
// 둘이 붙어 보이던 진짜 이유는 **둘 다 평평해서**입니다 — 넓은 반투명 면 하나에
// 점 몇 개라 **어느 쪽도 서 있지 않았습니다.**
//   극독  **바닥에서 솟습니다** — 독 결정이 땅을 뚫고 올라옵니다(㉠㉡㉣㉤ 전부)
//   감염  **깔리고 번집니다**   — 서지 않되 ㉢ 대기 원근으로 멀고 가까움을 냅니다
// ⇒ **하나는 서고 하나는 깔린다.** 정지 화면에서 즉시 갈립니다.
//
// ⚠️ ㉠ 의 면 밝기는 **세 단 이상**(밝은 면 · 본색 면 · 그늘 면)입니다 —
//   두 단이면 종이접기로 보입니다.
// ⚠️ `A()` 는 `#RRGGBB` 만 받습니다 — 면이 안 보이면 **칠 실패**를 먼저 의심합니다.

/// ㉠ **면을 쪼갠 조각** — 밑동에서 끝으로 좁아지는 결정 하나.
/// 세로로 **세 면**으로 갈라 밝기를 달리하고, 끝에 작은 면 하나를 더 답니다.
/// [dep] 0=앞(크고 짙다) → 1=뒤(작고 밝고 옅다 · ㉡㉢) · [lean] 눕는 정도(㉥)
function PZ5shard(c, x, y, h, w, ang, K, a, SC, seed, dep, lean) {
  const T = toneOf(K);
  const d = dep === undefined ? 0 : dep, ln = lean === undefined ? 0 : lean;
  const H = h * (1 - .34 * d), W = w * (1 - .28 * d), al = a * (1 - .30 * d);
  if (!(H > .6) || !(al > .01)) return;
  const ax = Math.cos(ang), ay = Math.sin(ang) * (1 - .55 * ln);
  const nx = -Math.sin(ang) * (1 - .30 * ln), ny = Math.cos(ang);
  const tx = x + ax * H, ty = y + ay * H;
  const jag = (u) => 1 + (hash(seed + u * 7.3) - .5) * .30;
  // ㉢ 뒤로 갈수록 **밝고 옅다** — 뒤엣것은 그늘 면을 본색으로 올립니다.
  const CF = d > .5 ? [T[2], T[2], T[1]] : [T[2], T[1], T[0]];
  const face = (u0, u1, col, aa) => {
    const bx0 = x + nx * W * (u0 * 2 - 1) * jag(u0), by0 = y + ny * W * (u0 * 2 - 1) * jag(u0);
    const bx1 = x + nx * W * (u1 * 2 - 1) * jag(u1), by1 = y + ny * W * (u1 * 2 - 1) * jag(u1);
    const tw = W * .17;
    const tx1 = tx + nx * tw * (u1 * 2 - 1), ty1 = ty + ny * tw * (u1 * 2 - 1);
    const tx0 = tx + nx * tw * (u0 * 2 - 1), ty0 = ty + ny * tw * (u0 * 2 - 1);
    fillPoly(c, [[bx0, by0], [bx1, by1], [tx1, ty1], [tx0, ty0]], A(col, aa));
  };
  // ⭐⭐ **제일 밝은 면만 가산**입니다(2026-08-28) — [PZ5mass] 의 심과 같은 규칙:
  //   겉 두 면은 채운 면이라 실루엣이 안 흔들리고, **빛이 드는 한 면**만
  //   겹칠수록 밝아집니다. 셋 중 하나라 넓이가 **1/3**이고 값이 거의 안 듭니다.
  c.save(); c.globalCompositeOperation = "lighter";
  face(0, .34, CF[0], al * .95);        // 밝은 면 — **가산**
  c.restore();
  face(.34, .70, CF[1], al * .92);      // 본색 면
  face(.70, 1, CF[2], al * .90);        // 그늘 면
  // 끝의 작은 면 하나 — 평평해 보이는 것을 막는 마지막 항입니다.
  const kx = tx - ax * H * .30, ky = ty - ay * H * .30;
  c.save(); c.globalCompositeOperation = "lighter";
  fillPoly(c, [[tx, ty], [kx + nx * W * .30, ky + ny * W * .30],
  [kx - nx * W * .18, ky - ny * W * .18]], A(T[2], al * .90));
  c.restore();
  // ㉤ **밑동의 들쭉날쭉한 흰 테** — 「뚫고 나왔다」. 없으면 「붙여 놓았다」.
  const P = [];
  for (let i = 0; i <= 5; i++) {
    const u = i / 5;
    P.push([x + nx * W * (u * 2 - 1) * 1.16,
    y + ny * W * (u * 2 - 1) * 1.16 + (hash(seed + i * 2.9) - .5) * W * .45]);
  }
  PZ5lit(c, P, 1.5 * SC, K, al * .85);
}

/// ㉧ 발치의 어두운 덩어리 — 그림자. **눕습니다.**
function PZ5foot(c, x, y, r, K, a, seed) {
  if (!(r > .5) || !(a > .01)) return;
  const T = toneOf(K);
  c.save(); c.translate(x, y); c.scale(1, .34);
  fillPoly(c, PKrag(0, 0, r, seed + 1.9, 9, .28, seed), A(T[0], a));
  c.restore();
}

/// ⭐ **솟는 독 결정 무리** — 극독이 「서는」 자리입니다.
/// ㉣ 뒤엣것부터 그려 **앞의 것이 뒤의 것을 가리게** 합니다(공짜인 깊이 신호).
/// [g] 0→1 자라는 몫 · [n] 개수.
function PZ5spires(c, t, x, y, R, n, K, a, SC, seed, g) {
  if (!(g > .02) || !(a > .01)) return;
  const list = [];
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 5.31;
    const ang = i / n * TAU + hash(sd) * .55;
    const d = R * (.42 + .46 * hash(sd + 1.1));
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * PZgSQ;
    // ㉡㉢ 깊이 — 위에 선 것이 **뒤**입니다(탑다운이라 y 가 곧 깊이입니다).
    const dep = Math.max(0, Math.min(1, .5 - (py - y) / (R * 1.5)));
    list.push({ px, py, sd, dep, i, ang });
  }
  // ㉣ **뒤부터** 그립니다 — 앞의 것이 뒤의 것을 가립니다.
  list.sort((p, q) => q.dep - p.dep);
  for (const s of list) {
    const gg = Math.max(0, Math.min(1, g * 1.35 - s.i / n * .30));
    if (gg <= .02) continue;
    const h = R * (.30 + .26 * hash(s.sd + 2.2)) * gg;
    const w = R * (.070 + .034 * hash(s.sd + 3.3));
    // ㉥ 각도가 다 다르고 **바깥일수록 눕습니다.**
    const lean = Math.min(.85, Math.hypot(s.px - x, s.py - y) / R * .95);
    const tilt = -Math.PI / 2 + (hash(s.sd + 4.4) - .5) * .8 + s.ang * .16;
    PZ5foot(c, s.px, s.py, w * 2.1, K, a * .40 * (1 - .4 * s.dep), s.sd);
    PZ5shard(c, s.px, s.py, h, w, tilt, K, a, SC, s.sd, s.dep, lean);
    // ㉦ **떨어져 나온 조각이 공중에** — 「지금 막 일어났다」.
    if (gg > .5) for (let k = 0; k < 2; k++) {
      const cs = s.sd + k * 3.7;
      const fly = ((t * .5 + hash(cs)) % 1);
      const cr = w * (.42 + .30 * hash(cs + 1.3));
      PZ5shard(c, s.px + Math.cos(s.ang) * R * .16 * fly,
        s.py - h * (.55 + .55 * fly) + R * .10 * fly * fly,
        cr * 2.2, cr, tilt + fly * 3.4, K, a * (1 - fly) * .9, SC, cs, s.dep, .3);
    }
  }
}


// ══════════════════════════════════════════════════════════════════════════
// ㉰ **투사체 문법** — 머리 · 몸통 · 꼬리                  (2026-08-28 사용자)
// ══════════════════════════════════════════════════════════════════════════
//
//   ① **머리 · 몸통 · 꼬리 셋으로 나뉩니다**
//   ② **머리만 작고 아주 밝고, 머리에 문양이 있습니다** — 문양이 정체성을 말합니다
//      ⭐ 독의 문양은 **삼엽**입니다 — 지어낸 것이 아니라 이 캐릭터의 **몸 표식**이
//        그것입니다(`vfx.js` 의 `EVSET`: `toxin:[["leaf",3,.50,.56]]` — 「날 셋이
//        도는 삼엽」). 날아가는 것의 머리에 제 속성의 표식이 찍힙니다.
//   ③ **몸통은 나선으로 꼬인 리본 두세 가닥** — 가닥끼리 서로를 감습니다
//   ④ **꼬리로 갈수록 가늘어지고 · 흐려지고 · 흩어집니다**
//   ⑤ **곧은 속도선 서넛이 리본을 관통합니다**
//   ⑥ **색이 둘 이상** — 본색 + 흰 코어 + 보조색 한 줄
//
// ⚠️ `celStroke` 는 굵기가 하나라 **테이퍼가 안 됩니다** — 그래서 리본을 세
//   토막으로 끊어 굵기를 `.78 → .50 → .26` 으로 떨어뜨립니다(④).
function PZ5bolt(c, t, ax, ay, bx, by, R, K, a, SC, seed, u) {
  const T = toneOf(K);
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1;
  const ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  const s = Math.max(0, Math.min(1, u));
  const e = s * s * (3 - 2 * s);
  const hx = ax + dx * e, hy = ay + dy * e - Math.sin(e * Math.PI) * L * .13;
  const TL = Math.min(L * .46, R * 8.5);
  // ③ 몸통 — **꼬인 리본 셋.** 서로를 감습니다(위상이 1/3 씩 어긋납니다).
  for (let k = 0; k < 3; k++) {
    const P = [];
    for (let i = 0; i <= 9; i++) {
      const w = i / 9, d = TL * w;
      const ph = k / 3 * TAU + t * 11 - w * 6.6 + seed;
      const off = R * (1 - w * .82) * Math.cos(ph);
      const lift = R * .55 * (1 - w) * Math.sin(ph);
      P.push([hx - ux * d + nx * off, hy - uy * d + ny * off - lift]);
    }
    // ④ 테이퍼 — 세 토막으로 끊어 굵기를 떨어뜨립니다.
    PZ5lit(c, P.slice(0, 4), R * .78, K, a * (.92 - .10 * k));
    PZ5lit(c, P.slice(3, 7), R * .50, K, a * (.72 - .10 * k));
    PZ5lit(c, P.slice(6), R * .26, K, a * (.48 - .08 * k));
  }
  // ⑤ 곧은 속도선 — 리본을 **관통합니다**(굵기 하나, 아주 가늘게).
  for (let k = 0; k < 3; k++) {
    const o = (k - 1) * R * .72;
    PZ5lit(c, [[hx - ux * TL * 1.18 + nx * o, hy - uy * TL * 1.18 + ny * o],
    [hx + ux * R * .5 + nx * o, hy + uy * R * .5 + ny * o]],
      R * .17, K, a * .42);
  }
  // ④ 꼬리 — **흩어지는 방울.** 뒤로 갈수록 흐려지고 벌어집니다.
  for (let k = 0; k < 6; k++) {
    const sd = seed + k * 3.13, w = .35 + .70 * hash(sd);
    const spread = R * 1.5 * w * (hash(sd + 1.1) - .5) * 2;
    const rr = R * (.42 - .22 * w) * (.6 + .8 * hash(sd + 2.2));
    if (rr < .2) continue;
    PZ5mass(c, hx - ux * TL * w + nx * spread, hy - uy * TL * w + ny * spread,
      rr, sd, K, a * (1 - w) * .85, .92, t + k);
  }
  // ① ② 머리 — **작고 아주 밝고, 삼엽 문양이 찍힙니다.**
  PZ5mass(c, hx, hy, R * .95, seed + 7.7, K, a, .95, t * 2);
  const spin = t * 7 + seed;
  for (let j = 0; j < 3; j++) {
    const ang = spin + j / 3 * TAU;
    PZ5shard(c, hx + Math.cos(ang) * R * .42, hy + Math.sin(ang) * R * .42,
      R * 1.35, R * .34, ang, K, a * .95, SC, seed + j, 0, .2);
  }
  // ⑥ 흰 코어 — 색이 둘 이상이라야 「연하다」를 면합니다.
  fillPoly(c, PKrag(hx, hy, R * .46, seed + 4.4, 9, .24, t * 4), A(T[2], a * .95));
}

/// ㉮ **큰 뼈대에 매달린 잔부속** — 총량은 큰 것 하나가 아니라 **거기 매달린
/// 수십**에서 납니다(거대 얼음 소환 레퍼런스의 「파편 수백 · 끝이 바늘」).
/// [pts] 뼈대의 폴리라인 · [n] 매달 개수 · [r] 잔부속의 크기.
/// ⚠️ 매달린 것은 **면을 쪼갠 조각**입니다(㉲) — 점을 뿌리면 먼지가 되고,
///   조각을 매달아야 **부피**가 됩니다.
function PZ5cling(c, t, pts, n, r, K, a, SC, seed) {
  if (!pts || pts.length < 2 || !(a > .01)) return;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 2.61;
    const w = hash(sd);
    const j = Math.min(pts.length - 2, Math.floor(w * (pts.length - 1)));
    const f = w * (pts.length - 1) - j;
    const p0 = pts[j], p1 = pts[j + 1];
    if (!p0 || !p1) continue;
    const px = p0[0] + (p1[0] - p0[0]) * f, py = p0[1] + (p1[1] - p0[1]) * f;
    const ang = Math.atan2(p1[1] - p0[1], p1[0] - p0[0]) + (hash(sd + 1.1) - .5) * 2.4;
    const rr = r * (.35 + .80 * hash(sd + 2.2));
    if (rr < .18) continue;
    // ㉡㉢ 절반은 **뒤**에 둡니다 — 작고 밝고 옅어져 깊이가 납니다.
    PZ5shard(c, px, py, rr * 2.6, rr * .44, ang, K,
      a * (.55 + .45 * hash(sd + 3.3)), SC, sd, hash(sd + 4.4) > .5 ? .75 : 0, .25);
  }
}


/// ㉮ **바닥 잔해** — 거대 소환 레퍼런스의 마지막 항입니다. 큰 것 둘레의 땅에
/// **부스러기가 깔려 있어야** 「방금 여기서 무슨 일이 있었다」가 됩니다.
/// ⚠️ **새로 지은 붓입니다.** 있는 붓으로는 안 나왔습니다 — `PZ5motes` 는
///   떠다니고(위상이 시간을 탑니다) `PZ5scar` 는 한 덩이 얼룩이라, 「바닥에
///   **눌어붙어 안 움직이는 조각 수십**」을 낼 것이 없었습니다.
/// ⚠️ 위상이 [hash] 파생이고 시간을 **안 탑니다** — 잔해는 안 움직입니다.
///   그래서 되풀이의 이음매가 원천에서 없습니다.
function PZ5litter(c, x, y, R, n, K, a, SC, seed, g) {
  const gg = g === undefined ? 1 : Math.max(0, Math.min(1, g));
  if (!(a > .008) || gg < .02) return;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 1.97;
    if (hash(sd + 8.1) > gg) continue;
    const ang = hash(sd) * TAU, d = R * (.28 + .78 * hash(sd + 1.1));
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * PZgSQ;
    const rr = R * (.020 + .034 * hash(sd + 2.2));
    if (rr < .16) continue;
    // 바닥에 **누운** 조각이라 각도가 제멋대로고 눕힘이 큽니다(㉥).
    PZ5shard(c, px, py, rr * 2.3, rr * .52, hash(sd + 3.3) * TAU, K,
      a * (.45 + .55 * hash(sd + 4.4)), SC, sd, hash(sd + 5.5) > .5 ? .8 : .2, .82);
  }
}


/// ⭐ **빛 램프** — 코어에서 가장자리로 알파가 떨어지는 부드러운 빛.
/// ⚠️ **엔진에 이미 있습니다** — `lib/fx/fx_light.dart` 가 램프를 **정적으로
///   굽어 두고 찍으므로** 매 프레임 비용이 거의 없고, `game_layers.dart` 가
///   이미 판에서 물고 돕니다. 그런데 **스킬 드라이버 80개 중 쓰는 것이 0개**
///   입니다 — 「엔진이 못 한다」가 아니라 **「할 수 있는데 안 이어 붙였다」**라,
///   시안이 먼저 써서 이식 지시서를 만듭니다.
/// ⚠️ **작고 여럿**이라야 합니다 — 넓은 램프는 그대로 넓은 반투명 면이라
///   raster 예산을 무는 바로 그 함정입니다(독이 제일 빠지기 쉬운 자리).
/// ⚠️ **가산이 아닙니다** — 겹쳐도 안 밝아집니다(이 저장소의 출발점).
/// ⭐⭐ **빛 램프는 가산입니다**(2026-08-28 규약 정정) — 「이펙트는 원래 가산으로
/// 그린다」. 겹칠수록 밝아져야 **빛**이고, 안 그러면 **밝은 얼룩**입니다.
/// ⚠️ [plain] 이면 **안 겹칩니다** — 독가스만 그렇게 부릅니다. 가스는 스스로
///   안 빛나고(겹칠수록 **짙어져야** 합니다), 2026-08-23 에 「독형광물질 느낌」으로
///   반려당한 자리가 정확히 그것입니다.
function PZ5glow(c, x, y, r, K, a, sq, plain) {
  if (!(r > .4) || !(a > .006)) return;
  const T = toneOf(K), q = sq === undefined ? 1 : Math.max(.12, sq);
  c.save();
  if (!plain) c.globalCompositeOperation = "lighter";
  c.translate(x, y); c.scale(1, q);
  const g = c.createRadialGradient(0, 0, r * .10, 0, 0, r);
  g.addColorStop(0, A(T[2], a));
  g.addColorStop(.42, A(T[1], a * .55));
  g.addColorStop(1, A(T[0], 0));
  c.fillStyle = g; c.beginPath(); c.arc(0, 0, r, 0, TAU); c.fill();
  c.restore();
}

/// 적 자리 — 시안 좌표를 SC 로 곱해 세웁니다.
function PZ5foes(list, SC) {
  return mkFoes(list.map((v) => [v[0] * SC, v[1] * SC, v[2] * SC]));
}

/// 적의 고정 씨앗 — 자리에서 뽑습니다(난수 0).
/// ⚠️⚠️ **이름이 `s0` 였습니다**(2026-08-28 개명). `vfx.js` 50,000줄 뒤에 실리는
///   파일이라 최상위 이름이 하나만 겹쳐도 스크립트가 **통째로 죽습니다** —
///   이 파일이 실제로 한 번 그렇게 죽었습니다(`t0` 가 이미 있어 `SyntaxError`).
///   `s0` 는 이 파일 안에서도 **지역 변수로 두 번 겹쳐** 쓰이고 있었습니다
///   (`const[s0,du,pw]=PZbPOP[k]`). ⇒ 규약대로 `PZ` 로 격리합니다.
function PZ5seed(f) { return f.ox * .031 + f.oy * .017; }

/// 갈라진 금 — **어둡게만** 긋습니다(`celStroke` 는 밝은 심을 넣어 「빛나는
/// 실」이 되므로 균열에 못 씁니다).
function PZ5crack(c, pts, w, K, a) {
  const T = toneOf(K);
  c.beginPath(); pts.forEach((v, i) => i ? c.lineTo(v[0], v[1]) : c.moveTo(v[0], v[1]));
  c.lineCap = "round"; c.lineJoin = "round";
  c.strokeStyle = A(T[0], a); c.lineWidth = w; c.stroke();
}

// ══════════════════════════════════════════════════════════════════════════
// ⑤-가 **극독** — 동사는 「조인다」. **하나 · 안으로 · 무너짐**
// ══════════════════════════════════════════════════════════════════════════
//
// 엔진이 정한 것(`sim/combat/magic/brand.dart` · `tuning.dart`)만 씁니다:
//   겉면 `kBrandRadius` 60 = **무너지는 반경**(판정도 그림도 이 하나를 읽습니다)
//   겹 수 [2,3,3,4,4] = `kBrandRings`/`L2`/`L4` — **피해가 겹 수에 걸려 있습니다**
//   조임 `kBrandCinch` 4.0 → `kBrandCinchL4` 3.0
//   L3 샘 `kBrandLeakTick` 0.55 · `kBrandLeakR` 96(시안 마당에 맞춰 74 로 좁힘)
//   L5 잔류 — `_cinch = castPeriod/_rings` 로 **한 겹 먹고 시작합니다**
//
// ── 다섯 마디 — **생성이 76%. 발현은 한 점** ──────────────────────────────
//   ① 시전 **0.30** 몸에서 표식이 날아가 **한 마리에 앉습니다**(누구를 잡았나)
//   ② 생성 **3.70**(L4 2.70) 올가미가 감겨 들며 몸이 **잘록해집니다**
//   ③ 발현 **0.18** 다 감긴 가닥에 **심이 달리고** 겉면까지 한 번에 무너집니다
//   ④ 소멸 **0.44** 내려앉은 독이 **스며듭니다** — 조각이 가라앉고 자국이 짙어집니다
//   ⑤ 종료 **0.22** 자국이 **끊기며 마릅니다**(L5 는 여기 올가미 하나가 남습니다)
//   ⚠️ ①+② 를 합친 것이 곧 엔진의 조임 시간입니다 — **밸런스를 안 건드립니다.**
//   ⚠️ ③④⑤ 0.84초는 **시안의 꼬리**입니다. 엔진 `_collapse()` 는 한 틱에
//     끝나고 다음 표식이 곧장 붙으므로 **소멸이 0** 입니다 — 사용자가 지적한
//     「소멸되는 시간도 짧아서」가 정확히 이 자리이고, 아래 배관 목록의 한 항입니다.
const PZ5bRING = [2, 3, 3, 4, 4];
const PZ5bSPAN = () => (atL(4) ? 3.0 : 4.0);
const PZ5bCAST = .30, PZ5bHIT = .18, PZ5bFADE = .44, PZ5bEND = .22;
// ── ⭐⭐ 2026-08-28 사용자 — **L1 장막이 너무 큽니다** ────────────────────
// 「극독의 경우 **Lv1 일 때도 장막의 범위가 너무 큰 거 같음. 줄일 필요가 있어
//   보임**」
//   ⚠️⚠️ **사다리가 아예 없었습니다.** 겉면이 `60` **고정**이라 L1 과 L5 의
//     장막이 **한 픽셀도 안 달랐습니다** — 다섯 칸이 「겹 수만 다른 같은 그림」이
//     되던 진짜 원인이 이것입니다(레벨을 올려도 화면이 안 커집니다).
//   ⇒ **L1 을 38 로 줄이고 L5 는 60(엔진 값)을 지킵니다.** 1 : 1.58 사다리가
//     처음 생깁니다.
// ⚠️⚠️ **엔진 판정 반경은 여기서 안 건드립니다**(엔진 몫이고 사용자가 「난이도
//   조절은 다 만들고 최종에」로 못 박았습니다). 다만 이 저장소는 「**보이는 호와
//   맞는 호가 같은 숫자에서 나온다**」를 원칙으로 삼으므로, 그림만 줄이면
//   **안 보이는 데서 맞는 사고**가 납니다 ⇒ 이식 인벤토리에 적어 뒀습니다:
//   「그림 반경을 L1 기준 **37% 줄였다 — 엔진 `kBrandRadius` 도 같이 재야 한다**」.
const PZ5bRAD = [38, 44, 50, 55, 60];   // L5 = `kBrandRadius` 60
const PZ5bR = 60;                       // = kBrandRadius (L5 · 이식 기준값)
/// 이 레벨에서 **그리는** 겉면. 열세 곳이 전부 이것을 읽습니다.
const PZ5bRr = () => PZ5bRAD[LV - 1];
const PZ5bLEAK = .55;                 // = kBrandLeakTick
const PZ5bLKR = 74;
const PZ5bFOE = [[62, -46, 11], [-66, -20, 10], [12, 62, 10], [-34, -62, 9]];

/// 세 안이 **같이 쓰는 다섯 마디 시계**. 안마다 다시 세지 않습니다.
/// ⚠️ 되풀이가 주기 하나에서 파생하므로 끝과 처음이 저절로 같습니다.
function PZ5bClock(t) {
  const RING = PZ5bRING[LV - 1], SPAN = PZ5bSPAN();
  const U0 = atL(5) ? 1 / RING : 0;        // L5 — 한 겹 먹고 시작합니다
  const TC = Math.max(PZ5bCAST + .2, SPAN * (1 - U0));   // 시전+생성
  const PER = TC + PZ5bHIT + PZ5bFADE + PZ5bEND;
  const T = saw(t, PER) * PER;
  const cast = Math.min(1, T / PZ5bCAST);
  const u = U0 + (1 - U0) * Math.max(0, Math.min(1, (T - PZ5bCAST) / (TC - PZ5bCAST)));
  const hit = T > TC ? Math.min(1, (T - TC) / PZ5bHIT) : 0;
  const fade = T > TC + PZ5bHIT ? Math.min(1, (T - TC - PZ5bHIT) / PZ5bFADE) : 0;
  const end = T > TC + PZ5bHIT + PZ5bFADE
    ? Math.min(1, (T - TC - PZ5bHIT - PZ5bFADE) / PZ5bEND) : 0;
  // ⭐ 연쇄 터짐은 **초**로 돕니다(0.00 · 0.08 · 0.18 에 하나씩) — 마디
  //   경계(`hit`/`fade`)를 넘나들므로 정규화 값으로는 못 셉니다.
  return { RING, SPAN, U0, TC, PER, T, cast, u, hit, fade, end,
    hitAge: T > TC ? T - TC : 0, i: (t / PER) | 0 };
}

/// 겉면 — **무너지는 반경**입니다. 눕습니다(`fx_plane` 의 `brand` = ground).
function PZ5bEdge(c, t, x, y, SC, k, Q) {
  const live = Q.hit === 0 && Q.fade === 0;
  if (!live) return;
  // ⭐ 겉면을 **진의 바깥 고리**로 씁니다 — 「보이는 것 = 맞는 것」을 지키면서
  //   화면의 밀도가 한 번에 여섯 항 늘어납니다(고리 · 파선 · 눈금 · 별 · 위성 ·
  //   코어). 조일수록 **진이 짙어집니다.**
  PZ5sigil(c, t, x, y, PZ5bRr() * SC, k, (.30 + .34 * Q.u) * Math.min(1, Q.cast * 1.4),
    SC, 5.5, Math.min(1, Q.cast * 1.3), .72);
}

// ══════════════════════════════════════════════════════════════════════════
// 🔴🔴 **올가미의 「면」을 걷습니다 — 전부 빛으로**   (2026-08-29 사용자 판정)
// ══════════════════════════════════════════════════════════════════════════
// 사용자 원문: 「'독' > **올가미** — 올가미 스킬의 경우 **올가미가 '면'으로
//   이루어진 셀셰이딩**인데 **밑에 장판하고 겹쳐서 이상하게 구현**되었음.
//   **'면' 셀셰이딩을 폐기 처분하고 '빛 올가미' 형태로 변경**」
//
// ── ⭐⭐ 왜 겹치면 이상해지나 — **원리** ─────────────────────────────────
//   **가산은 겹칠수록 밝아지고, 면은 덮어 버립니다.**
//   · 빛 획(가산)이 장판 위를 지나면 **장판 색이 비쳐 오르며** 두 층이 **한
//     그림**이 됩니다.
//   · 불투명 면이 장판 위에 앉으면 **그 자리의 장판이 사라집니다** — 「위에
//     붙인 스티커」가 되고, 그 면이 어두우면 **회색 판**으로 읽힙니다.
//   ⇒ **면을 걷고 전부 빛으로** 갑니다.
//
// ── 무엇을 걷었나 — **삼각 판을 내는 항 둘** ─────────────────────────────
//   ⛔ [PZ5spires] 「솟는 독 결정 무리」 — [PZ5shard] 파생이라 **면 셋으로 쪼갠
//      판**입니다. 조이는 내내 장판 위에 **아홉~열다섯 장**이 앉아 있었습니다.
//   ⛔ [PZ5litter] 「바닥 잔해」 — 같은 붓으로 **서른네 조각**입니다.
//   ⚠️ 둘 다 **함수는 안 지웠습니다** — 다른 칸(부식의 껍질 · 잔해)이 씁니다.
//     거기서는 **장판 위가 아니라 적의 몸 위**라 면이 맞습니다.
//     ⭐ **갈리는 것은 스킬이 아니라 항입니다.**
//   ✅ [PZ5cling](매달린 조각)은 **이미 `gAdd` 안**이라 그대로 둡니다.
//   ✅ [PZ5lit] 의 **어두운 가장자리 한 겹**도 그대로입니다 — 그것은 **획의
//      테두리**라 유령을 막는 자리이고, **회색이 아니라 독색을 어둡게 한 것**
//      입니다(`TONE.pzBrand[0]` = `#3D0A28`).

/// ⭐ **솟는 것을 빛으로** — 면(결정 무리)을 걷은 자리를 획이 대신합니다.
/// 밑동에서 위로 가는 **가는 획** + 끝의 **작은 후광**뿐이라, 장판 위를 지나도
/// 장판이 **비쳐 오릅니다.** ⚠️ 획은 전부 **제 각도**라 서로 안 만납니다 —
///   가로줄과 세로줄이 만나면 그 순간 **격자(파리채)**가 됩니다.
function PZ5bRise(c, t, x, y, R, n, K, a, SC, seed, g) {
  if (!(g > .02) || !(a > .01)) return;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 5.31;
    const ang = i / n * TAU + hash(sd) * .55;
    const d = R * (.42 + .46 * hash(sd + 1.1));
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * PZgSQ;
    const h = R * (.30 + .34 * hash(sd + 2.2)) * g;
    if (!(h > .6)) continue;
    // ⭐ 끝이 **기웁니다** — 곧게 세우면 여럿이 나란해져 빗살(=격자의 절반)이
    //   됩니다. 기울기가 제각각이라야 「솟은 것」입니다.
    const lean = (hash(sd + 3.3) - .5) * .70;
    PZ5lit(c, [[px, py], [px + lean * h * .5, py - h * .62], [px + lean * h, py - h]],
      (2.2 - .9 * (i % 3) * .3) * SC, K, a * (.62 + .38 * hash(sd + 4.4)));
    gAdd(c, gg => gHalo(gg, px + lean * h, py - h, h * .42, K, a * .55));
  }
}

/// ⭐ **바닥 잔해를 빛으로** — 면(조각 서른넷)을 걷은 자리를 **눌린 획**이
/// 대신합니다. 바닥에 **누워** 있고 각도가 제각각이라 격자가 안 됩니다.
function PZ5bDust(c, t, x, y, R, n, K, a, SC, seed, g) {
  const gg = g === undefined ? 1 : Math.max(0, Math.min(1, g));
  if (!(a > .008) || gg < .02) return;
  for (let i = 0; i < n; i++) {
    const sd = seed + i * 1.97;
    if (hash(sd + 8.1) > gg) continue;
    const ang = hash(sd) * TAU, d = R * (.28 + .78 * hash(sd + 1.1));
    const px = x + Math.cos(ang) * d, py = y + Math.sin(ang) * d * PZgSQ;
    const L = R * (.05 + .07 * hash(sd + 2.2));
    if (!(L > .4)) continue;
    const aa = hash(sd + 3.3) * TAU;                 // **제 각도** — 격자 금지
    PZ5lit(c, [[px - Math.cos(aa) * L, py - Math.sin(aa) * L * PZgSQ],
    [px + Math.cos(aa) * L, py + Math.sin(aa) * L * PZgSQ]],
      1.3 * SC, K, a * (.42 + .48 * hash(sd + 4.4)));
  }
}

/// ⏳️ 조여든 몸 — **잘록해집니다.** 
/// ⚠️ `drawFoes` 는 안 건드립니다(몸은 적 렌더의 것입니다) — 몸 **위에** 눌린
///   자국을 얹어 「조였다」를 냅니다. 엔진에도 그대로 옮길 수 있는 꼴입니다.
///
/// 🔴🔴 **2026-08-29 재반려 — 「딱 봐도 면적」의 정체가 여기였습니다.**
/// 사용자: 「**올가미 꼬리 저거 셀셰이딩 여전한 거 아니야? 저거 빛으로 구현한 거임?
///   걍 존나 딱 봐도 면적 같은데**」
/// ⚠️⚠️ 꼬리 획([PZ5lit])은 빛으로 고쳤는데 **그 아래 이 함수가 깔려**
///   있었습니다. 옛 판의 한 줄:
///     `fillPoly(PKrag(0,0, fr*1.08, …), A(T[0], .26 + .40*u))` — **적 반지름의
///     1.08배짜리 너덜너덜한 다각형을 불투명하게** 채우고(알파 최대 **0.66**),
///     `scale(1, .58→.18)` 로 **눌러** 놨으니 바닥에 깔린 판으로 보입니다.
///   ⇒ **그것이 「면적」입니다.** 꼬리가 그 위를 지나가니 꼬리가 면으로 읽혔습니다.
/// ⭐ 고친 법 — **면이 하던 일을 획의 겹으로** 냅니다. 「조이는 허리가 두껍다」는
///   **두께**이므로, 눌린 고리를 **겹쳐** 두께를 냅니다(조일수록 겹이 **2→4**로
///   늘고 밝아집니다). 가는 획의 가산은 싸고 크게 이깁니다.
/// ⚠️ 양옆으로 밀려 나온 살도 **덩어리에서 빛으로** 바꿨습니다 — 밝은 심
///   ([gHalo]) + 테 획 하나. 덩어리([PZ5mass])는 겉 두 겹이 **비가산**입니다.
function PZ5bWaist(c, t, x, y, fr, SC, k, u, sd) {
  // ⭐ **눌린 고리의 겹** — 조일수록 촘촘해지고 밝아집니다. 전부 [PZ5lit] 이라
  //   가산 심이 들어가고, 겹칠수록 밝아져 **두께가 빛으로** 납니다.
  const sq = Math.max(.10, .58 - .40 * u);
  const N = 2 + Math.round(u * 2);                 // 겹 2 → 4
  for (let i = 0; i < N; i++) {
    const rr = fr * (1.08 - .17 * i);
    if (!(rr > .5)) continue;
    PZ5ring(c, x, y, rr, sq, sd + i * .7 + t * .05,
      (2.4 - .45 * i) * SC, k, (.34 + .44 * u) * (1 - .13 * i));
  }
  // ⭐ **양옆으로 밀려 나온 살** — 밝은 심 + 테 획. 면이 아닙니다.
  for (const s of [-1, 1]) {
    const bx = x + s * fr * (1.05 - .34 * u), br = fr * (.38 + .12 * u);
    gAdd(c, g => gHalo(g, bx, y, br * 1.35, k, (.22 + .40 * u)));
    const P = [];
    for (let i = 0; i <= 6; i++) {
      const a0 = -Math.PI * .5 + s * Math.PI * (i / 6);
      P.push([bx + Math.cos(a0) * br * (.92 + .12 * Math.sin(i * 1.7 + sd)),
      y + Math.sin(a0) * br * .74]);
    }
    PZ5lit(c, P, 1.6 * SC, k, .30 + .46 * u);
  }
}

/// ① **시전** — 세 안이 같이 씁니다. 몸에서 표식이 날아가 **한 마리에 앉습니다.**
/// ⚠️ 옛 판에는 이 마디가 **아예 없었습니다** — 표식이 그냥 생겨 있었고,
///   그래서 「누구를 잡았나」가 화면에 한 번도 안 나왔습니다.
function PZ5bCast(c, t, cx, cy, tx, ty, fr, SC, k, w) {
  // ⭐ 표식이 앉는 자리에 **진이 그려집니다** — 「무엇이 벌어지는지」가 진에
  //   적히므로, 이 마디만으로 「저 한 마리가 4초 뒤 무너진다」가 읽힙니다.
  PZ5sigil(c, t, tx, ty, fr * 2.6, k, .34 + .52 * w, SC, 2.2, w, 1);
  // ㉰ **머리 · 몸통 · 꼬리.** 머리에 독의 **삼엽**이 찍힙니다.
  PZ5bolt(c, t, cx, cy, tx, ty, 4.2 * SC, k, .95, SC, 6.4, w);
  // 지목한 자리의 테 — 닿기 **전에** 서서 「저기다」를 말합니다.
  PZ5ring(c, tx, ty, fr * (2.4 - 1.2 * w), PZgSQ, t * .8, (1.2 + 1.4 * w) * SC, k, .28 + .52 * w);
  if (w > .82) PZ5motes(c, t * 4, tx, ty, fr * 2.2, 5, 21.7, k, (w - .82) / .18 * .8, SC, PZgSQ, -8);
}

/// ④⑤ **소멸 · 종료** — 세 안이 같이 씁니다. 발현과 **다른 그림**입니다:
///   발현은 밖으로 터지는 조각이고, 소멸은 **안으로 스며드는 얼룩**입니다.
function PZ5bSink(c, t, x, y, SC, k, fade, end, sd) {
  if (fade > 0 && end === 0) {
    PZ5scar(c, t, x, y, PZ5bRr() * SC * (.94 - .10 * fade), k, .40 * (1 - fade * .35), SC, sd, fade * .4);
    PZ5motes(c, t, x, y, PZ5bRr() * .7 * SC, 7, sd + 3.3, k, (1 - fade) * .70, SC, PZgSQ, -13);
    PZ5grain(c, x, y, PZ5bRr() * .8 * SC, sd + 8.8, k, (1 - fade) * .45, PZgSQ, 7, t * .2);
  }
  if (end > 0) PZ5scar(c, t, x, y, PZ5bRr() * SC * .82, k, .34 * (1 - end), SC, sd, .4 + .6 * end);
}

// ── 안 A 「올가미」 — **한 가닥이 감겨 들어갑니다** ────────────────────────
//
// ⭐ 겹 수가 **감김 수**입니다 — 정지 화면에서 세어집니다.
// ⭐ 아직 안 감긴 몫이 **늘어진 꼬리**로 남습니다 — 그것이 곧 **남은 시간**이라,
//   「4초 뒤 무너진다」가 그림 안에 시계로 들어 있습니다.
// ⚠️ 나선은 낙서가 되기 쉽습니다(`docs/vfx/README.md`:「나선은 낙서로 읽힌다」).
//   ⇒ 감김마다 **굵기를 키워** 균일한 굵기를 깨고, 갈래를 **하나로** 두고,
//     서로 **안 엉키게** 안쪽으로만 감습니다.
/// ⚠️ 바깥 반지름이 **겉면을 따라갑니다** — 옛 판은 `58` 고정이라 장막만
///   레벨을 안 탔습니다(사용자가 「L1 장막이 크다」고 본 자리의 절반이 이것).
function PZ5noosePts(u, RING, SC, x, y) {
  const R0 = PZ5bRr() * .967, R1 = R0 * .293;
  const N = Math.max(10, Math.round(RING * 15 * u) + 2), P = [];
  for (let i = 0; i <= N; i++) {
    const s = u * i / N;
    const ang = -Math.PI * .5 + s * RING * TAU;
    const rr = (R0 - (R0 - R1) * s) * SC;
    P.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr * PZgSQ]);
  }
  return P;
}

FX.PZbrandA = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  if (!st.F) st.F = PZ5foes(PZ5bFOE, SC);
  stepFoes(st.F, dt);
  const K = PZ5BR, Q = PZ5bClock(t), RING = Q.RING;
  const tf = st.F[Q.i % st.F.length];
  const tx = cx + tf.ox + tf.kx, ty = cy + tf.oy + tf.ky;
  const sd = tf.sd0 || (tf.sd0 = PZ5seed(tf));
  const u = Q.u;
  const leakN = atL(3) ? Math.floor(Q.T / PZ5bLEAK) : 0;
  const leakU = atL(3) ? (Q.T / PZ5bLEAK) % 1 : 0;

  // ── 마디 ④⑤ 소멸 · 종료 — 바닥에 먼저 깝니다 ──────────────────────────
  PZ5bSink(c, t, tx, ty, SC, K, Q.fade, Q.end, sd * 5);
  // ── 마디 ⑤ 종료 · L5 — 무너진 자리에 올가미 하나가 남습니다 ────────────
  if (atL(5) && Q.end > 0) {
    const al = (1 - Q.end) * .8;
    PZ5ring(c, tx, ty, 21 * SC, PZgSQ, t * .8, 2.6 * SC, K, al);
    // 🔴 남은 올가미의 심도 **빛**입니다(바닥 자국은 아래 [PZ5scar] 가 냅니다).
    gAdd(c, g => PZ5mass(g, tx, ty, 5.4 * SC, 4.4, K, al * .9, PZgSQ, -t * .6));
  }
  PZ5bEdge(c, t, tx, ty, SC, K, Q);
  // ㉮ 바닥 잔해 — 조일수록 쌓이고 무너진 뒤 제일 많습니다.
  // 🔴 2026-08-29 — **면을 걷고 빛으로**(사용자: 「'면' 셀셰이딩을 폐기 처분하고
  //   '빛 올가미' 형태로」). 옛 [PZ5litter] 는 [PZ5shard] 파생이라 **조각 서른넷이
  //   전부 불투명 판**이었고, 장판 위에 앉아 **회색 삼각**으로 읽혔습니다.
  PZ5bDust(c, t, tx, ty, PZ5bRr() * SC, 34, K, .40 + .40 * Q.u, SC, sd * 23 + 1,
    .30 + .70 * Q.u + (Q.hitAge > 0 ? .3 : 0));

  for (const f of st.F) f.hit = Math.max(0, f.hit - dt * 2.2);
  if (Q.hit > 0 && Q.hit < .5) tf.hit = 1;
  drawFoes(c, t, cx, cy, st.F);

  // ── 마디 ① 시전 ────────────────────────────────────────────────────────
  if (Q.cast < 1) { PZ5bCast(c, t, cx, cy, tx, ty, tf.r, SC, K, Q.cast); hero(c, t, cx, cy, "gold", SC); return; }

  // ── 마디 ② 생성 — 조여드는 올가미 ──────────────────────────────────────
  if (Q.hit === 0) {
    // ⭐⭐ **극독은 섭니다** — 조이는 내내 바닥에서 독이 솟습니다.
    //   감염은 끝까지 깔려 있으므로, 이 한 항이 정지 화면에서 둘을 가릅니다.
    // 🔴 2026-08-29 — **면을 걷고 빛으로**. 옛 [PZ5spires] 는 [PZ5shard] 파생이라
    //   **면 셋으로 쪼갠 판 아홉~열다섯 장**이 장판 위에 앉아 있었습니다 —
    //   그것이 사용자가 말한 「**면 셀셰이딩이 밑에 장판하고 겹쳐서 이상하다**」
    //   의 정확한 자리입니다. **솟는다는 사실은 안 버렸습니다** — 획으로 냅니다.
    PZ5bRise(c, t, tx, ty, PZ5bRr() * SC, RING * 3 + 3, K, .30 + .62 * u, SC, sd * 13 + 2, u);
    PZ5bWaist(c, t, tx, ty, tf.r, SC, K, u, sd);
    const P = PZ5noosePts(u, RING, SC, tx, ty);
    for (let k = 0; k < RING; k++) {
      const i0 = Math.floor(P.length * k / RING);
      const i1 = Math.min(P.length - 1, Math.floor(P.length * (k + 1) / RING) + 1);
      if (i1 - i0 < 2) continue;
      // ⭐⭐ **감기는 획이 빛입니다**(2026-08-28) — 채운 면이 아니라 가산 획입니다.
      PZ5lit(c, P.slice(i0, i1 + 1), (2.0 + 1.25 * k) * SC, K, .52 + .46 * u);
    }
    // ㉮ **큰 뼈대에 매달린 것들** — 올가미를 따라 조각이 답니다. 총량은
    //   큰 것 하나가 아니라 여기서 납니다.
    // ⚠️ 매달린 조각도 **가산**으로 얹습니다 — 채운 조각이 획 위에 덮이면
    //   그것이 곧 사용자가 말한 「면」입니다.
    gAdd(c, g => PZ5cling(g, t, P, 6 + RING * 4, 1.9 * SC, K, .30 + .60 * u, SC, sd * 19 + 3));
    const tail = 1 - u;
    if (tail > .02) {
      const Qs = [];
      for (let i = 0; i <= 6; i++) {
        const w = i / 6, ang = -Math.PI * .5 - w * (.85 + 1.75 * tail);
        const rr = PZ5bRr() * (.967 + .600 * tail * w) * SC;
        Qs.push([tx + Math.cos(ang) * rr, ty + Math.sin(ang) * rr * PZgSQ]);
      }
      // 늘어진 꼬리도 같은 획입니다 — 한쪽만 빛나면 두 물건이 됩니다.
      PZ5lit(c, Qs, (1.4 + 1.1 * tail) * SC, K, .26 + .34 * tail);
    }
    const ha = -Math.PI * .5 + u * RING * TAU, hr = PZ5bRr() * (.967 - .674 * u) * SC;
    const hx = tx + Math.cos(ha) * hr, hy = ty + Math.sin(ha) * hr * PZgSQ;
    // ⭐ 머리의 빛 — 램프 하나(넓은 면이라 한 겹만 씁니다). [PZ5glow] 가
    //   이제 **제 손으로 가산**이라 여기서 또 감싸지 않습니다.
    PZ5glow(c, hx, hy, (3.0 + 7.4 * u) * SC * 2.2, K, .40, .84);
    // 🔴 2026-08-29 — 머리를 **가산 덩어리**로 감쌉니다. [PZ5mass] 는 겉 두 겹이
    //   **비가산**이라, 커질수록(3.0 → 10.4) 그대로 「면적」이 됩니다.
    //   ⭐ `gAdd` 안에서는 [PZ5mass] 의 save/restore 가 **가산으로 되돌아오므로**
    //     세 겹이 전부 가산입니다 — 겹칠수록 밝아지는 **빛나는 구슬**입니다.
    gAdd(c, g => {
      PZ5mass(g, hx, hy, (3.0 + 7.4 * u) * SC, 2.7, K, .92, .84, t * .7);
      PZ5grain(g, hx, hy, (3.0 + 7.4 * u) * SC, 9.1, K, .8, .84, 6, t * .5);
    });
    // L3 「조이는 내내 독이 샌다」 — 짜여 나온 방울이 곁의 적에게 갑니다.
    if (atL(3)) {
      for (const f of st.F) {
        if (f === tf) continue;
        if (Math.hypot(f.ox - tf.ox, f.oy - tf.oy) > PZ5bLKR * SC) continue;
        const fx = cx + f.ox + f.kx, fy = cy + f.oy + f.ky;
        const w = Math.min(1, leakU * 1.35);
        const px = hx + (fx - hx) * w, py = hy + (fy - hy) * w - Math.sin(w * Math.PI) * 13 * SC;
        // 🔴 새어 나가는 방울도 **날아가는 빛**입니다 — 가산으로 감쌉니다.
        gAdd(c, g => PZ5mass(g, px, py, (2.4 - .9 * w) * SC, 5.3 + f.ox, K, .88, .9, t));
        PZ5taint(c, t, fx, fy, f.r, K, Math.min(.72, .16 + leakN * .13), SC, f.ox * .07 + 3);
      }
      PZ5motes(c, t, hx, hy, 16 * SC, 5, 3.3, K, .55, SC, PZgSQ, -5);
    }
  }

  // ── 마디 ③ 발현 — **한 자리에서 세 번 터집니다**(연쇄) ──────────────────
  // ⭐⭐ 감염과 갈리는 자리가 여기입니다: 셋이 **같은 자리**에 겹쳐 반지름만
  //   `.55 → .80 → 1.00` 으로 커집니다 — **파고드는** 그림입니다. 감염은 같은
  //   셋을 **자리를 옮겨** 냅니다(「번지는」 그림).
  if (Q.hitAge > 0 && Q.hitAge < PZ5popOFF[2] + PZ5popT) {
    if (Q.hitAge < .10)
      // ③ 발현의 **한 획** — 여기가 제일 밝습니다.
      PZ5lit(c, PZ5noosePts(1, RING, SC, tx, ty),
        (3.4 + 2.2 * (1 - Q.hitAge / .10)) * SC, K, .95);
    PZ5bWaist(c, t, tx, ty, tf.r, SC, K, 1, sd);
    PZ5chain(c, t, Q.hitAge, PZ5bRr() * SC, K, 1, SC, sd * 9 + 2,
      (k) => [tx, ty, [.55, .80, 1.00][k]], 1);
  }
  hero(c, t, cx, cy, "gold", SC);
};

// ══════════════════════════════════════════════════════════════════════════
// ⑤-나 **감염** — 동사는 「옮는다」. **여럿 · 몸에서 몸으로 · 번짐**
// ══════════════════════════════════════════════════════════════════════════
//
// 엔진이 정한 것(`sim/combat/magic/spore.dart` · `tuning.dart`)만 씁니다:
//   반경 `kSporeRadius` [66,73,81,88,96] — **첫 파문이 덮는 원 그대로**
//   지속 `kSporeDur`    [2.2,3.0,3.8,4.8,5.8]
//   박자 `kSporePulse`  0.5 → L3 부터 **절반**(`pulseGap`)
//   L4 — 숙주가 죽어도 **자리만 남은 발원지**가 계속 퍼뜨립니다
//   L5 — **더 옮길 곳을 못 찾은 그 박**에 사슬 전체가 동시에 터집니다
//
// ── 다섯 마디 — **극독과 시간의 모양이 반대입니다** ───────────────────────
//   ① 시전 **0.34** 몸에서 홀씨 한 줌이 **뭉텅이 쪽으로** 날아가 첫 적에 붙습니다
//     ⚠️ 옛 판에는 이 마디가 **없었습니다** — 씨앗이 그냥 켜져 있었고, 그래서
//       「내가 시전했다」가 화면에 한 번도 안 나왔습니다. 엔진은 실제로
//       [ClusterAim] 으로 **뭉텅이**를 고릅니다(`_ignitionSpot`) — 그것을 그립니다.
//   ② 생성 **0.30** 붙은 자리에서 자실체가 **부풀어 오릅니다.** 아직 안 퍼집니다
//     ⚠️ 엔진에도 이 창이 없습니다 — 물드는 즉시 첫 파문이 나갑니다.
//   ③ 발현 **2.2~5.8**(지속 그대로) 균사가 뻗어 옮고, 박마다 때립니다 — **되풀이**
//   ④ 소멸 **0.45** 지속이 다한 발원지가 **마릅니다** — 자실체가 오그라들고
//     얼룩의 테가 **조각으로 끊깁니다**(그냥 옅어지면 「꺼졌다」입니다)
//   ⑤ 종료 **0.60**(L5 1.00) 바닥 자국만 남았다 삭습니다
//
//   ⇒ 극독이 **생성 76% · 발현 한 점**인 데 반해 감염은 **시전+생성 9% ·
//     발현 68%** 입니다. 두 칸을 나란히 두면 **시간의 모양이 반대**입니다.
//
// ⭐⭐ **셋 다 「고리」를 안 씁니다.** 옛 판이 극독과 안 갈린 이유가 그것이라
//   (둘 다 적 몸을 감싼 동심 고리) 셋 다 다른 실루엣으로 갔습니다:
//     A **사슬이 눈에 보인다** — 굵은 균사 한 가닥이 몸에서 몸으로 기어갑니다
//     B **건너뛰는 것이 눈에 보인다** — 홀씨 뭉치가 날아가 내려앉습니다
//     C **면이 번진다** — 선이 하나도 없고 얼룩이 자라 서로 이어 붙습니다
// ── ⭐⭐ 2026-08-28 사용자 — **L1 범위도 양도 과합니다** ──────────────────
// 「감염의 경우 **Lv1 일 때도 너무 범위가 크고 감염되는 양도 많은 거 같음.
//   너프가 필요해 보임**」
//
// ── ⚠️⚠️ 재 보니 **사다리가 가짜였습니다** ───────────────────────────────
//   옛 마당(고리 여섯 · 반지름 53~58)의 쌍거리는 **54.7 · 54.8 · 55.6 · 55.6 ·
//   55.9 · 56.9** 그리고 **92.7** 부터입니다 — 즉 이웃 여섯 쌍이 **한 덩어리로
//   몰려** 있습니다. 그래서 옛 반경 [66, 73, 81, 88, 96] 은 **L1 부터 L4 까지
//   닿는 쌍이 12 로 똑같았습니다**(L5 만 18). ⇒ **L1 이 이미 L4 만큼 물들이고
//   있었습니다.** 사용자가 본 「L1 인데 범위도 양도 많다」가 정확히 이것입니다.
//
// ── 고친 법 — **반경만 줄이면 도감이 깨집니다** ───────────────────────────
//   도감 L1 은 「발원지가 적이다 — 감염된 적의 몸에서 파문이 나가 **옆 적을
//   물들인다**」입니다. 옛 마당에서 반경을 57 밑으로 내리면 **아무도 안 닿아**
//   그 문구가 거짓이 됩니다. ⇒ **마당을 다시 잡았습니다** — 쌍거리를 30 부터
//   100 까지 **고르게 벌려** 반경이 칸마다 다른 그림을 내게 했습니다.
//   ⚠️ 적 여섯 · 중심에서 45~58(옛 53~58과 같은 자리) — **몸 크기도 마당의
//     크기도 안 건드렸습니다.** 바꾼 것은 **서로의 사이**뿐입니다.
//
//   닿는 쌍(전체 15쌍 중)  L1 **2** → L2 4 → L3 **7** → L4 10 → L5 **15**
//   그림 반경             L1 **40**(옛 66 · **−39%**) … L5 **102**(옛 96 · +6%)
//   L1 : L5              **1 : 2.55** (옛 1 : 1.45)
// ⚠️ 이식 인벤토리에 적어 뒀습니다 — **엔진 `kSporeRadius` 도 같이 재야 합니다.**
const PZ5sFOE = [[55, 51], [249, 47], [283, 58], [144, 45], [327, 51], [3, 46]];
const PZ5sRR = [40, 54, 70, 86, 102];
/// 한 박에 **몇 마리까지** 옮나 — 「감염되는 양」이 이 줄입니다.
/// ⚠️ 옛 판은 **닿는 것 전부**라 L1 에서도 한 박에 둘씩 물들었습니다.
const PZ5sSPREAD = [1, 1, 2, 3, 6];
const PZ5sDUR = [2.2, 3.0, 3.8, 4.8, 5.8];
const PZ5sPUL = [.50, .50, .25, .25, .25];   // = kSporePulse · L3 부터 절반
const PZ5sGHOST = 2;
const PZ5sCAST = .34, PZ5sGROW = .30, PZ5sWILT = .45;

/// 판정 겉면 — **끊긴 테 + 안쪽 얼룩.** 동심 고리가 아닙니다.
function PZ5sEdge(c, t, x, y, RR, SC, K, a, seed, dry) {
  const T = toneOf(K), D = dry || 0;
  // ⚠️⚠️ **두 번 고친 자리입니다.**
  //   ① 첫 판은 매끈한 타원 셋이었습니다 — 발원지가 여섯이면 타원 여섯이 겹쳐
  //      화면이 **고리 그물**이 되고, 사용자가 반려한 「동심 고리」로 도로
  //      읽혔습니다.
  //   ② 그래서 너덜너덜한 **폴리라인 한 바퀴**로 바꿨더니 이번엔 가는 획이
  //      여섯 겹으로 엉켜 **노란 낙서**가 됐습니다 — 이 파일이 지키는 반려
  //      규약 ①(**가는 획 여럿 = 거미줄**)에 그대로 걸립니다.
  //   ⇒ 셋째 판: 가장자리를 **굵은 호 셋**으로만 냅니다. 한 바퀴를 안 돌므로
  //     겹쳐도 엉키지 않고, 굵어서 「자라는 얼룩의 가장자리」로 읽힙니다.
  //     ⭐ 얼룩의 **속**은 선이 아니라 아래 덩이들이 채웁니다(방울·기포·자국) —
  //       넓은 반투명 면(비싼 잉크)을 한 겹도 안 씁니다.
  const ARC = 3, SPAN = TAU / ARC * .62;
  for (let k = 0; k < ARC; k++) {
    const a0 = k / ARC * TAU + t * .06 + seed;
    const P = [];
    for (let i = 0; i <= 7; i++) {
      const ang = a0 + SPAN * i / 7;
      const rr = RR * (1 - .18 * D) * (1 + (hash(seed + k * 9.1 + i * 3.1) - .5) * .15);
      P.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr * PZgSQ]);
    }
    PZ5lit(c, P, (2.8 - .5 * k) * SC, K, a * (.92 - .16 * k));
  }
  for (let i = 0; i < 7; i++) {
    const sd = seed + i * 3.11;
    const ang = hash(sd) * TAU + t * .05, d = RR * (.22 + .64 * hash(sd + 1.4));
    fillPoly(c, PKrag(x + Math.cos(ang) * d, y + Math.sin(ang) * d * PZgSQ,
      RR * (.07 + .09 * hash(sd + 2.6)) * (1 - .3 * (dry || 0)), sd + 4.2, 8, .38, sd + t * .3),
      A(T[0], a * .50));
  }
}

/// ㉢ **대기 원근** — 감염은 안 서지만 평면도 아닙니다. 뒤(화면 위)에 있는
/// 발원지일수록 **밝고 옅게**, 앞엣것일수록 짙게 그려 멀고 가까움을 냅니다.
/// ⚠️ 면적이 **한 픽셀도 안 늡니다** — 알파와 색만 바뀝니다.
function PZ5sDep(oy, SC) { return Math.max(0, Math.min(1, .5 - oy / (150 * SC))); }

/// 자실체 — 물든 몸에 **돋아나는 덩어리**. 남은 지속만큼 마르며 작아집니다.
/// ⚠️ 이것이 「지속이 얼마나 남았나」의 눈금입니다 — 옛 판의 **몸에 두른 호**를
///   대신합니다(그 호가 극독의 겹 고리와 제일 헷갈리던 자리였습니다).
function PZ5sBloom(c, t, x, y, fr, SC, K, life, pop, beat, n, dep) {
  const g = Math.min(1, pop * 3.3), d = dep === undefined ? 0 : dep;
  // ㉣ 뒤엣것부터 — 앞의 것이 뒤의 것을 가립니다(차례만 바꾸는 공짜 신호).
  const q = [];
  for (let i = 0; i < n; i++) {
    const sd = i * 4.71 + 1.3;
    const ang = i / n * TAU + hash(sd) * .8, dd = fr * (.55 + .34 * hash(sd + 1.1));
    q.push({ sd, x: x + Math.cos(ang) * dd, y: y + Math.sin(ang) * dd, i });
  }
  q.sort((p1, p2) => p1.y - p2.y);
  for (const b of q) {
    const r = fr * (.30 + .22 * hash(b.sd + 2.2)) * g * (.55 + .45 * life)
      * (1 + .18 * Math.sin(beat * TAU + b.i)) * (1 - .22 * d);
    // ㉧ 발치의 어두운 덩어리 — 깔린 것에도 그림자는 있습니다.
    PZ5foot(c, b.x, b.y + r * .55, r * 1.15, K, (.30 - .12 * d) * (.4 + .6 * life), b.sd);
    PZ5mass(c, b.x, b.y, r, b.sd * 3, K, (.55 + .40 * life) * (1 - .26 * d), .88, t * .3 + b.i);
    PZ5grain(c, b.x, b.y, r, b.sd * 7, K, .7 * (1 - .3 * d), .88, 4, t * .2);
    // 결 — **잎맥**(엔진 `fxNoiseVein`). 자실체가 「부푼 덩이」가 아니라
    //   **「자란 것」**으로 읽히는 자리입니다.
    PZ5vein(c, b.x, b.y, r * .82, b.sd * 4 + b.i, K, (.62 - .24 * d) * (.4 + .6 * life),
      SC, b.sd * 11, 5);
  }
}

/// ① **시전** — 셋이 같이 씁니다. 홀씨 한 줌이 **뭉텅이 쪽으로** 날아갑니다.
function PZ5sCastDraw(c, t, cx, cy, tx, ty, fr, SC, K, w) {
  // ⭐ 엔진이 [ClusterAim] 으로 고른 **뭉텅이** 위에 진이 섭니다.
  PZ5sigil(c, t, tx, ty, fr * 3.0, K, .30 + .50 * w, SC, 7.7, w, .85);
  // ㉰ 홀씨 뭉치도 **날아가는 것**입니다 — 머리·몸통·꼬리로 갈라 그립니다.
  //   ⚠️ 다만 머리를 극독보다 **작게**(3.4 vs 4.2) 둡니다: 감염은 「한 발」이
  //     아니라 「한 줌」이라, 머리가 크면 극독의 표식과 실루엣이 겹칩니다.
  PZ5bolt(c, t, cx, cy, tx, ty, 3.4 * SC, K, .95, SC, 2.2, w);
  const s = w * w * (3 - 2 * w);
  const px = cx + (tx - cx) * s, py = cy + (ty - cy) * s - Math.sin(s * Math.PI) * 18 * SC;
  for (let q = 0; q < 7; q++) {
    const sd = q * 3.19 + 2.2, ang = hash(sd) * TAU;
    const d = (2.0 + 4.0 * hash(sd + 1.2)) * (1 + 1.8 * Math.sin(w * Math.PI)) * SC;
    PZ5mass(c, px + Math.cos(ang) * d, py + Math.sin(ang) * d,
      (1.5 + 1.4 * hash(sd + 2.4)) * SC, sd, K, .60 + .35 * w, .92, t * .8 + q);
  }
  PZ5ring(c, tx, ty, fr * (2.6 - 1.3 * w), PZgSQ, -t * .7, (1.2 + 1.3 * w) * SC, K, .24 + .52 * w);
}

/// 사슬 시늉 — **엔진 규칙 그대로**입니다. 다섯 마디를 여기서 굴립니다.
/// ⚠️ 다음 박에 **누가 누구를 물들일지**를 박이 시작할 때 미리 못 박습니다 —
///   그림이 「닿는 순간 물든다」를 그리려면 닿기 전에 대상을 알아야 합니다.
///   판정은 박의 **끝**에 한 번만 납니다(엔진과 같은 자리).
function PZ5sSim(st, t, dt, SC) {
  const RR = PZ5sRR[LV - 1] * SC, DUR = PZ5sDUR[LV - 1], PUL = PZ5sPUL[LV - 1];
  if (!st.F || st.k !== LV) {
    st.k = LV;
    st.F = mkFoes(PZ5sFOE.map((v) => [Math.cos(v[0] * Math.PI / 180) * v[1] * SC,
    Math.sin(v[0] * Math.PI / 180) * v[1] * SC, (v[0] % 120 ? 9.5 : 10.5) * SC]));
    st.inf = st.F.map(() => -1); st.had = st.F.map(() => 0);
    st.pop = st.F.map(() => 0); st.g = []; st.tree = []; st.scar = [];
    st.pu = 0; st.link = []; st.rest = 0; st.bang = 0; st.flash = 0;
    st.cast = -1; st.castTo = -1; st.grow = 1;
    // ⭐ 터짐 장부 — **물드는 자리마다** 하나씩 쌓입니다(자리가 옮겨 갑니다).
    st.popq = []; st.bangAt = [];
  }
  stepFoes(st.F, dt);
  // ── 마디 ① 시전 — 날아가는 동안은 **아무것도 안 물듭니다** ─────────────
  if (st.inf.every((v) => v < 0) && !st.had.every((v) => v)) {
    if (st.cast < 0) {
      st.cast = 0;
      for (let i = 0; i < st.F.length; i++) if (!st.had[i]) { st.castTo = i; break; }
    } else st.cast += dt / PZ5sCAST;
    if (st.cast >= 1) {
      st.inf[st.castTo] = 0; st.had[st.castTo] = 1;
      st.cast = -1; st.grow = 0; st.pu = 0; st.link = [];
    }
  }
  // ── 마디 ② 생성 — 첫 자실체가 부푸는 동안 파문이 안 나갑니다 ───────────
  if (st.grow < 1) st.grow = Math.min(1, st.grow + dt / PZ5sGROW);
  for (let i = 0; i < st.inf.length; i++) {
    if (st.inf[i] >= 0) {
      st.inf[i] += dt;
      // ── 마디 ④ 소멸 — 마르는 자리를 남깁니다 ────────────────────────────
      if (st.inf[i] > DUR) {
        st.inf[i] = -1;
        st.scar.push({ x: st.F[i].ox, y: st.F[i].oy, age: 0 });
      }
    }
    st.pop[i] = st.inf[i] >= 0 ? Math.min(1, st.pop[i] + dt * 3.2) : Math.max(0, st.pop[i] - dt * 2.4);
  }
  for (const g of st.g) g.age += dt;
  for (let i = st.g.length - 1; i >= 0; i--)
    if (st.g[i].age > DUR) { st.scar.push({ x: st.g[i].x, y: st.g[i].y, age: 0 }); st.g.splice(i, 1); }
  for (const s of st.scar) s.age += dt;
  for (let i = st.scar.length - 1; i >= 0; i--) if (st.scar[i].age > PZ5sWILT * 2) st.scar.splice(i, 1);
  if (atL(4)) for (let i = 0; i < st.F.length && st.g.length < PZ5sGHOST; i++)
    if (st.inf[i] > DUR * .55 && !st.F[i].gh) {
      st.F[i].gh = 1; st.g.push({ x: st.F[i].ox, y: st.F[i].oy, age: 0 });
    }
  // ── 마디 ③ 발현 — 박마다 옮고 때립니다 ─────────────────────────────────
  const srcs = [];
  for (let i = 0; i < st.F.length; i++) if (st.inf[i] >= 0) srcs.push([st.F[i].ox, st.F[i].oy, i]);
  for (const g of st.g) srcs.push([g.x, g.y, -1]);
  if (!st.link.length && srcs.length && st.grow >= 1) {
    for (let j = 0; j < st.F.length; j++) {
      if (st.inf[j] >= 0 || st.had[j]) continue;
      let bi = -1, bd = 1e9;
      for (let s = 0; s < srcs.length; s++) {
        const d = Math.hypot(st.F[j].ox - srcs[s][0], st.F[j].oy - srcs[s][1]);
        if (d <= RR && d < bd) { bd = d; bi = s; }
      }
      if (bi >= 0) st.link.push({ sx: srcs[bi][0], sy: srcs[bi][1], si: srcs[bi][2], j });
    }
  }
  if (st.grow >= 1) st.pu += dt / PUL;
  let fired = 0;
  if (st.pu >= 1) {
    st.pu -= 1;
    // ⭐ **한 박에 옮는 수를 레벨이 정합니다**(2026-08-28 「감염되는 양도 많다」).
    //   옛 판은 **닿는 것 전부**라 L1 에서도 한 박에 둘씩 물들었습니다. 가까운
    //   것부터 [PZ5sSPREAD] 마리까지만 물들이고 나머지는 **다음 박으로** 밉니다.
    // ⚠️ 넘긴 것을 **버리지 않습니다** — 버리면 그 적이 영영 안 물들어 판이
    //   안 씻기고(`had.every` 가 안 참) 되풀이가 멈춥니다.
    const CAP = PZ5sSPREAD[LV - 1];
    const ord = st.link.slice().sort((p, q) =>
      Math.hypot(st.F[p.j].ox - p.sx, st.F[p.j].oy - p.sy) -
      Math.hypot(st.F[q.j].ox - q.sx, st.F[q.j].oy - q.sy));
    const keep = ord.slice(0, CAP);
    for (const L of keep) {
      if (st.inf[L.j] >= 0 || st.had[L.j]) continue;
      st.inf[L.j] = 0; st.had[L.j] = 1; fired++;
      // ⭐⭐ 극독과 갈리는 자리 — 터짐이 **옮겨 간 자리**에서 납니다.
      st.popq.push({ x: st.F[L.j].ox, y: st.F[L.j].oy, age: 0 });
      if (st.tree.length < 8) st.tree.push({ si: L.si, sx: L.sx, sy: L.sy, j: L.j });
    }
    // 못 옮은 것은 **다음 박에 다시 겨눕니다**(위 ⚠️).
    st.link = [];
    if (atL(5) && fired === 0 && !st.bang && srcs.length > 1) {
      st.bang = 1; st.flash = 1.2;
      // L5 각성도 **연쇄**입니다 — 세 자리가 0.00 · 0.08 · 0.18 에 차례로 터집니다.
      st.bangAt = [];
      for (let i = 0; i < st.F.length && st.bangAt.length < 3; i++)
        if (st.inf[i] >= 0) st.bangAt.push([st.F[i].ox, st.F[i].oy]);
    }
  }
  st.flash = Math.max(0, st.flash - dt);
  for (const q of st.popq) q.age += dt;
  for (let i = st.popq.length - 1; i >= 0; i--)
    if (st.popq[i].age > PZ5popT) st.popq.splice(i, 1);
  // ── 마디 ⑤ 종료 — 판이 씻깁니다 ────────────────────────────────────────
  if (st.had.every((v) => v) && st.inf.every((v) => v < 0)) st.rest += dt; else st.rest = 0;
  if (st.rest > (atL(5) ? 1.0 : .6)) {
    st.rest = 0; st.bang = 0; st.g = []; st.tree = []; st.link = []; st.pu = 0; st.scar = [];
    st.popq = []; st.bangAt = [];
    st.inf = st.F.map(() => -1); st.had = st.F.map(() => 0);
    for (const f of st.F) f.gh = 0;
  }
  return { RR, DUR, PUL, srcs };
}

/// ④⑤ **소멸 · 종료** — 셋이 같이 씁니다. 마른 자국이 **끊기며** 삭습니다.
function PZ5sScars(c, t, cx, cy, st, RR, SC, K) {
  for (const s of st.scar) {
    const w = Math.min(1, s.age / (PZ5sWILT * 2));
    PZ5scar(c, t, cx + s.x, cy + s.y, RR * (.86 - .16 * w), K, (1 - w) * .40, SC, s.x * .07 + 4, w);
    if (w < .5) PZ5motes(c, t, cx + s.x, cy + s.y, RR * .5, 4, s.x * .11 + 9, K,
      (1 - w * 2) * .55, SC, PZgSQ, -8);
  }
}

/// 물드는 자리마다 나는 **작은 터짐** — 셋이 같이 씁니다.
/// ⚠️ 기둥을 낮게(0.5) 둡니다 — 감염은 「솟는 것」이 아니라 「번지는 것」이고,
///   기둥을 높이면 극독의 발현과 실루엣이 겹칩니다.
function PZ5sPops(c, t, cx, cy, st, SC, K, RR) {
  for (const q of st.popq)
    PZ5pop(c, t, cx + q.x, cy + q.y, RR * .44, K, .95, SC, q.x * .07 + 1.3,
      q.age / PZ5popT, .50);
}

/// L5 각성 — 셋이 같이 씁니다. **세 자리가 차례로** 터집니다(연쇄).
function PZ5sBang(c, t, cx, cy, st, SC, K, RR) {
  if (st.flash <= 0) return;
  const fl = st.flash / 1.2;
  if (st.bangAt && st.bangAt.length)
    PZ5chain(c, t, 1.2 - st.flash, RR * .62, K, 1, SC, 4.4,
      (k) => { const p = st.bangAt[k]; return p ? [cx + p[0], cy + p[1], 1] : null; }, .70);
  for (let i = 0; i < st.F.length; i++) {
    if (st.inf[i] < 0) continue;
    PZ5motes(c, t + i, cx + st.F[i].ox, cy + st.F[i].oy, 34 * SC * (1.2 - fl), 6,
      i * 4.4 + 30, K, fl * .9, SC, PZgSQ, -10);
    PZ5ring(c, cx + st.F[i].ox, cy + st.F[i].oy, (14 + 30 * (1 - fl)) * SC, PZgSQ, 0,
      (3.6 * fl + .6) * SC, K, fl * .95);
  }
}

/// 굵은 균사 한 가닥 — **마디마다 굵기가 튑니다**(균일한 굵기 = 거미줄).
/// ㉮ 그리고 뼈대를 따라 **작은 자실체가 매달립니다** — 균사가 선이 아니라
///   「무엇이 주렁주렁 달린 줄기」로 읽히는 자리입니다.
function PZ5hypha(c, ax, ay, bx, by, w, K, a, grow, seed, t, SC) {
  const g = Math.max(0, Math.min(1, grow));
  if (g < .02) return;
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1;
  const nx = -dy / L, ny = dx / L, P = [], N = 7;
  for (let i = 0; i <= N; i++) {
    const u = i / N * g;
    const bow = Math.sin(u * Math.PI) * L * .16 * (hash(seed) - .5) * 2;
    const wob = Math.sin(u * 9.1 + seed * 5 + t * .6) * L * .035;
    P.push([ax + dx * u + nx * (bow + wob), ay + dy * u + ny * (bow + wob)]);
  }
  const m = Math.max(2, Math.round(P.length * .55));
  PZ5lit(c, P.slice(0, m), w * 1.18, K, a);
  PZ5lit(c, P.slice(m - 1), w * .74, K, a * .92);
  for (let i = 1; i < P.length - 1; i += 2)
    PZ5mass(c, P[i][0], P[i][1], w * (.62 + .34 * hash(seed + i)), seed + i * 2.7, K, a * .82, .92, t + i);
  if (SC) PZ5cling(c, t, P, 5, w * .52, K, a * .75, SC, seed * 3 + 1.7);
  // 결 — **흐르는 줄**(엔진 `fxNoiseStreak` + UV 흐름). 균사를 타고 무엇이
  //   **옮겨 가고 있다**가 보입니다. ⚠️ 위상이 `t` 파생이라 이음매가 없습니다.
  if (SC) PZ5streak(c, t, P, w * .46, K, a * .80, SC, seed * 7 + 2.3, 3, .70);
}

// ── 안 A 「균사」 — **사슬이 화면에 남습니다** ─────────────────────────────
//
// ⭐ 정지 화면 한 장에서 **무엇이 무엇을 물들였나**가 읽힙니다. 극독에는 적과
//   적을 잇는 선이 **한 가닥도 없으므로**, 이 한 항만으로도 둘이 갈립니다.
// ⚠️ 균사는 **한 박에 한 가닥**(L3 부터 두 갈래)이고 **굵습니다**.
FX.PZsporeA = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const K = PZ5SP, S = PZ5sSim(st, t, dt, SC), RR = S.RR, DUR = S.DUR;
  const beat = st.pu;

  PZ5sScars(c, t, cx, cy, st, RR, SC, K);
  for (let i = 0; i < st.F.length; i++)
    if (st.inf[i] >= 0)
      PZ5sEdge(c, t, cx + st.F[i].ox, cy + st.F[i].oy, RR * (st.grow < 1 ? .5 + .5 * st.grow : 1),
        SC, K, .30 * (1 - st.inf[i] / DUR) + .16, i * 5.3, Math.max(0, st.inf[i] / DUR - .78) * 4.5);
  for (const g of st.g)
    PZ5sEdge(c, t, cx + g.x, cy + g.y, RR, SC, K, .26 * (1 - g.age / DUR) + .12, 31.7,
      Math.max(0, g.age / DUR - .78) * 4.5);

  for (const e of st.tree) {
    if (st.inf[e.j] < 0) continue;
    if (e.si >= 0 && st.inf[e.si] < 0) continue;
    const fl = st.flash > 0 ? st.flash / 1.2 : 0;
    PZ5hypha(c, cx + e.sx, cy + e.sy, cx + st.F[e.j].ox, cy + st.F[e.j].oy,
      (3.4 + 1.8 * fl) * SC, K, .48 + .46 * fl, 1, e.j * 3.7 + 1.1, t, SC);
  }
  const two = atL(3) ? 2 : 1;
  for (const L of st.link) for (let m = 0; m < two; m++)
    PZ5hypha(c, cx + L.sx, cy + L.sy, cx + st.F[L.j].ox, cy + st.F[L.j].oy,
      (5.2 - m * 1.4) * SC, K, .95 - m * .16, Math.min(1, beat * 1.06 + m * .06),
      L.j * 3.7 + 1.1 + m * 8.3, t, SC);

  for (const f of st.F) f.hit = Math.max(0, f.hit - dt * 2.6);
  // ⚠️⚠️ **박마다 전부 번쩍이면 안 됩니다**(첫 렌더 판정). L3 부터 박이 0.25초라
  //   여섯이 늘 흰 폭발을 뒤집어써서 **L3·L4·L5 가 한 덩어리로 같아 보였습니다.**
  //   번쩍이는 것은 **이번 박에 새로 물든 몸**뿐입니다 — 그래야 「옮았다」가
  //   사건으로 보이고, 레벨이 실루엣에서 갈립니다.
  for (let i = 0; i < st.F.length; i++)
    if (st.inf[i] >= 0 && st.inf[i] < .14) st.F[i].hit = 1;
  drawFoes(c, t, cx, cy, st.F);

  // ── 마디 ① 시전 ────────────────────────────────────────────────────────
  if (st.cast >= 0 && st.castTo >= 0) {
    const f = st.F[st.castTo];
    PZ5sCastDraw(c, t, cx, cy, cx + f.ox, cy + f.oy, f.r, SC, K, Math.min(1, st.cast));
  }
  for (let i = 0; i < st.F.length; i++) {
    if (st.pop[i] <= .02) continue;
    const f = st.F[i], x = cx + f.ox + f.kx, y = cy + f.oy + f.ky;
    const life = st.inf[i] >= 0 ? 1 - st.inf[i] / DUR : 0;
    // ㉮ 바닥 잔해 — **깔리는 것**이 이 스킬의 정체라 극독보다 넓게 깝니다.
    PZ5litter(c, x, y, RR * .78, 26, K, .34 + .30 * st.pop[i], SC, i * 13.3 + 2,
      .35 + .65 * st.pop[i]);
    PZ5taint(c, t, x, y, f.r, K, .28 + .38 * st.pop[i], SC, i * 7.7 + 2);
    PZ5glow(c, x, y, f.r * 1.9, K, .34 * st.pop[i] * (.4 + .6 * life), PZgSQ);   // 빛 램프 1/몸
    PZ5sBloom(c, t, x, y, f.r, SC, K, life, st.pop[i] * (st.inf[i] >= 0 && st.grow < 1 ? st.grow : 1),
      beat, atL(3) ? 4 : 3, PZ5sDep(f.oy, SC));
    PZ5motes(c, t, x, y, f.r * 2.1, 5, i * 9.1, K, .40 * st.pop[i], SC, PZgSQ, -4);
  }
  for (const g of st.g) {
    const life = 1 - g.age / DUR;
    PZ5sBloom(c, t, cx + g.x, cy + g.y, 11 * SC, SC, K, life, 1, beat, 4);
    PZ5motes(c, t, cx + g.x, cy + g.y, 22 * SC, 4, 17.3, K, .40 * life, SC, PZgSQ, -4);
  }
  PZ5sPops(c, t, cx, cy, st, SC, K, RR);
  PZ5sBang(c, t, cx, cy, st, SC, K, RR);
  hero(c, t, cx, cy, "gold", SC);
};

// ══════════════════════════════════════════════════════════════════════════
// ⑤-다 **단전** — 「'독' 스킬처럼 보이게」                        (사용자 원문)
// ══════════════════════════════════════════════════════════════════════════
//
// ── 무엇이 **뇌의 잔재**였나 (옛 `FX.mgBoltHalt` 실측) ────────────────────
//   ① **색이 통째로 뇌였습니다** — `WTONE.mgBoltHalt = "gold"`(회백 쇠)이고
//      `hero(…,"gold",…)` 까지 그 색입니다. 그런데 엔진은 **2026-08-22 에 이미
//      옮겼습니다**: `cel_tones.dart` 의 `halt` 가 놋쇠금 `#E8C93A`(49°) →
//      **`#2FA845`(131° 짙은 독녹)**. ⇒ **색은 이미 독인데 시안만 안 받았습니다.**
//   ② **못**(`celSpike` 프레임당 **58.8회** — 실측) — 각진 쇠 쐐기. 광물의 어휘입니다.
//   ③ **미늘**(`bgChip`) — 쇠 부스러기.
//   ④ **파열이 불꽃**(`celSplash`) — 튀는 것이 불티가 아니라 **스파크**였습니다.
//
// ── 독의 문법으로 옮긴 자리 넷 ────────────────────────────────────────────
//   쇠 못  → **가시 뿌리**   휘고 · 마디가 있고 · 끝이 뭉툭합니다
//   스파크 → **가라앉는 알갱이**(이 파일의 「불티의 독 번역」 그대로)
//   붙잡음 → **삭음**        박힌 자리에서 독이 번져 **짙기가 세 단으로** 깊어집니다
//   튕김   → **깨짐**        굳은 각이 조각으로 깨져 흩어집니다
//   ⚠️ **파르르 떠는 것은 남깁니다** — 엔진이 실제로 `applyShock` 를 겁니다
//     (`halt.dart:155`). 가만히 두면 「멈췄다」가 아니라 「죽었다」로 읽힙니다.
//     다만 진폭을 **절반**으로 줄이고 **맺힌 방울이 그 떨림에 떨어지게** 해서,
//     떨림이 뇌가 아니라 **독의 사건**이 되게 했습니다.
//
// ── 다섯 마디 — **예고가 없던 스킬에 예고를 냅니다** ──────────────────────
//   ① 시전 **0.18** 다음에 꿸 적의 **발밑에서 독이 배어 올라옵니다**(눕는 금
//     셋 + 옅은 얼룩). ⚠️ 옛 판에 **이 마디가 없었습니다** — 못이 예고 없이
//     곧장 날아왔습니다. 실측으로 이 저장소의 `w_*.dart` **85개 중 예고를 가진
//     것이 16개(19%)** 이고 단전은 그 밖이었습니다.
//     ⚠️ 이 마디는 **앞 주기의 꼬리에 겹쳐** 둡니다 — 붙잡는 주기(`hold+gap`)가
//       밸런스라 늘릴 수 없기 때문입니다. 자리도 다릅니다(**다음** 표적의 발밑).
//   ② 생성 **0.22** 가시가 밖에서 안으로 박힙니다 — **고정값**입니다(아래 ⚠️⚠️)
//   ③ 발현 **1.0~1.5**(`kHaltHoldAt`) 굳고 삭습니다. L5 는 도트가 **박동**합니다
//   ④ 소멸 **0.26** 굳은 각이 **깨지고** 조각과 불티가 흩어집니다
//   ⑤ 종료 **~0.5** 조각이 가라앉고 발밑 자국이 **끊기며 마릅니다**
//     (앞 주기의 자국을 다음 주기 앞머리에 겹쳐 그립니다 — 쉼이 0.3초뿐이라
//      그 안에 다 못 담습니다)
//
// ── ⚠️⚠️ 박자 결함 — **엔진이 6.8배 느립니다**(2026-08-28 감사) ───────────
//   시안:  `dr = min(1, T / **0.22**)`      ← 박음은 0.22초 **고정**
//   엔진 `w_halt_cel.dart:150`: `dr = m.rInner[k]`
//     그런데 `halt.dart:99` 가 싣는 값이 `(_cyc / _hold)` 이고 `_hold` 는
//     **1.0~1.5초**입니다 ⇒ 못이 **hold 내내 스르르 미끄러집니다**.
//     1.5 ÷ 0.22 = **6.82배.** `0.22` 는 엔진의 halt 경로 어디에도 없습니다
//     (같은 파일의 `_kSpin = 0.22` 는 **못이 도는 속도**로 다른 값입니다).
//   ⇒ **총구가 실어야 할 것이 하나 더 있습니다**: 「박음 진행도」는 `_cyc` 를
//     `_hold` 가 아니라 **0.22 로 나눈 값**입니다. 붙잡힌 진행도(`rInner`)와
//     **다른 시계**라 한 칸으로 못 겸합니다.
//   ⇒ 그리고 **풀림 불티가 통째로 없습니다** — 시안은 `POP ? 12 : 5` 알갱이를
//     뿜는데 엔진 halt 에는 파티클이 **한 줄도** 없습니다.
const PZ5hFOE = [[62, -44, 11], [-64, -22, 10], [-6, 58, 10], [40, 52, 9], [-46, -60, 9]];
const PZ5hNAIL = [4, 6, 6, 6, 8];
const PZ5hTGT = [1, 1, 2, 2, 3];            // = kHaltTargetsAt
const PZ5hHOLD = [1.0, 1.5, 1.5, 1.5, 1.5]; // = kHaltHoldAt
const PZ5hGAP = [0.8, 0.3, 0.3, 0.3, 0.3];  // = kHaltGap
const PZ5hPRE = .18;                        // ① 시전(예고)
const PZ5hDRIVE = .22;                      // ② 생성 — **hold 와 무관한 고정값**
const PZ5hREL = .26;                        // ④ 소멸
const PZ5hSCAR = .50;                       // ⑤ 종료
const PZ5hROT = 1.5;                        // 짙기 3단이 다 차는 시간(초)
const PZ5hSPARK = [5, 5, 5, 12, 12];        // 풀림 불티 — L4 에서 **5 → 12**
const PZ5hDOT = .30;                        // = kHaltDotTick

/// 가시 뿌리 하나 — **휘고 · 마디가 있고 · 끝이 뭉툭합니다.**
/// 못(`celSpike`)과 실루엣이 갈리는 자리가 이 셋입니다.
function PZ5thorn(c, t, x, y, ang, len, w, K, a, sd) {
  const P = [], N = 5, bend = (hash(sd) - .5) * .9;
  for (let i = 0; i <= N; i++) {
    const u = i / N, aa = ang + bend * u * u;
    P.push([x + Math.cos(aa) * len * u, y + Math.sin(aa) * len * u]);
  }
  PZ5lit(c, P.slice(0, 4), w, K, a);
  PZ5lit(c, P.slice(3), w * .62, K, a * .95);
  for (let i = 1; i < N; i += 2)
    PZ5mass(c, P[i][0], P[i][1], w * (.60 + .30 * hash(sd + i)), sd + i * 2.3, K, a * .85, .95, t + i);
  PZ5mass(c, P[N][0], P[N][1], w * .74, sd + 9.1, K, a * .92, .95, -t);
}

/// ① 시전 — **발밑에서 독이 배어 올라옵니다.** 아직 아무것도 안 박혔습니다.
function PZ5hPre(c, t, x, y, fr, SC, K, w) {
  const T = toneOf(K);
  // ⭐⭐ **여기가 「독 스킬처럼」의 답입니다.** 예고가 없던 자리에 독의 진이
  //   서고, 그 다음에야 가시가 박힙니다 — 쇠가 날아오는 것이 아니라 **주술이
  //   걸리는 것**으로 읽힙니다.
  PZ5sigil(c, t, x, y + fr * .58, fr * 2.7, K, .30 + .58 * w, SC, x * .05 + 2, w, 1);
  c.save(); c.translate(x, y + fr * .58); c.scale(1, .34);
  fillPoly(c, PKrag(0, 0, fr * (1.0 + 1.1 * w), x * .03 + 1.7, 11, .30, t * .3), A(T[0], .30 * w));
  c.restore();
  for (let k = 0; k < 3; k++) {
    const a0 = k / 3 * TAU + t * .12;
    PZ5crack(c, [[x, y + fr * .58],
    [x + Math.cos(a0) * fr * 1.5 * w, y + fr * .58 + Math.sin(a0) * fr * 1.5 * w * .34]],
      (1.4 + 1.0 * w) * SC, K, .70 * w);
  }
  PZ5motes(c, t * 2, x, y + fr * .5, fr * 1.6 * w, 3, x * .07 + 5, K, w * .55, SC, .34, 5);
}

FX.PZhalt = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  if (!st.F) st.F = PZ5foes(PZ5hFOE, SC);
  stepFoes(st.F, dt);
  const K = PZ5HL, T = toneOf(K);
  const NT = PZ5hTGT[LV - 1], NAIL = PZ5hNAIL[LV - 1];
  const HOLD = PZ5hHOLD[LV - 1], PER = HOLD + PZ5hGAP[LV - 1];
  const NSP = PZ5hSPARK[LV - 1], POP = atL(4), DOT = atL(5);
  const T0 = saw(t, PER) * PER, cyc = (t / PER) | 0;
  const drive = Math.min(1, T0 / PZ5hDRIVE);           // ② 생성 — 0.22 고정
  const rel = T0 > HOLD ? Math.min(1, (T0 - HOLD) / PZ5hREL) : 0;   // ④ 소멸
  const pre = T0 > PER - PZ5hPRE ? (T0 - (PER - PZ5hPRE)) / PZ5hPRE : 0;   // ① 시전
  const scar = T0 < PZ5hSCAR ? 1 - T0 / PZ5hSCAR : 0;  // ⑤ 종료(앞 주기의 자국)
  const rot = Math.min(1, Math.min(T0, HOLD) / PZ5hROT);
  const step = rot < .34 ? 1 : (rot < .70 ? 2 : 3);
  const dotU = DOT ? (T0 % PZ5hDOT) / PZ5hDOT : 0;
  // ⚠️ **음수 나머지**를 막습니다 — `cyc-1` 이 −1 이면 JS 의 `%` 가 음수를
  //   내어 `st.F[-1]` 이 `undefined` 가 됩니다(첫 주기에서 터졌습니다).
  const pick = (k) => {
    const o = [], n = st.F.length;
    for (let i = 0; i < NT; i++) o.push(st.F[((i * 2 + k) % n + n) % n]);
    return o;
  };
  const sel = pick(cyc);

  for (const f of st.F) f.hit = Math.max(0, f.hit - dt * 2.4);
  for (const f of sel) {
    if (drive >= 1 && rel <= 0) {
      const s = PZ5seed(f);
      f.kx = (hash(t * 61 + s * 7) - .5) * 1.3 * SC;
      f.ky = (hash(t * 57 + s * 11 + 9) - .5) * 1.3 * SC;
    }
    if (rel > 0 && rel < .2) f.hit = 1;
  }

  // ── 마디 ⑤ 종료 — 앞 주기가 남긴 자국이 **끊기며 마릅니다** ─────────────
  if (scar > 0) for (const f of pick(cyc - 1))
    PZ5scar(c, t, cx + f.ox, cy + f.oy + f.r * .58, f.r * 1.7, K, scar * .34, SC, PZ5seed(f) * 5, 1 - scar);
  // ── 마디 ① 시전 — **다음** 표적의 발밑 ─────────────────────────────────
  if (pre > 0) for (const f of pick(cyc + 1))
    PZ5hPre(c, t, cx + f.ox, cy + f.oy, f.r, SC, K, pre);

  // 발밑 — 붙잡힌 동안 **진이 남아 짙어집니다**(예고에서 그려진 그 진입니다).
  for (const f of sel) {
    const x = cx + f.ox + f.kx, y = cy + f.oy + f.ky;
    PZ5sigil(c, t, x, y + f.r * .58, f.r * (2.7 + rel * .8), K,
      (1 - rel) * (.26 + .26 * rot), SC, PZ5seed(f) * 3, 1, .62);
    PZ5foot(c, x, y + f.r * .62, f.r * (1.05 + .30 * rot), K, (1 - rel) * .34, PZ5seed(f) * 7);
    // ㉮ 바닥 잔해 — 삭을수록 쌓이고, 깨진 뒤에도 남습니다.
    PZ5litter(c, x, y + f.r * .58, f.r * 3.0, 22, K, .34 + .26 * rot, SC, PZ5seed(f) * 29 + 3,
      .30 + .70 * rot);
    PZ5ring(c, x, y + f.r * .58, f.r * (1.45 + rel * .85), .36, 0,
      (2.0 + .8 * rot) * SC, K, (1 - rel) * (.34 + .30 * rot));
    c.save(); c.translate(x, y + f.r * .58); c.scale(1, .36);
    fillPoly(c, PKrag(0, 0, f.r * 1.3 * (.6 + .5 * rot), PZ5seed(f), 11, .22, t * .1),
      A(T[0], (1 - rel) * .22 * rot));
    c.restore();
  }

  drawFoes(c, t, cx, cy, st.F);

  // ── 마디 ③ 발현 — **짙기 세 단으로 삭습니다** ──────────────────────────
  for (const f of sel) {
    const x = cx + f.ox + f.kx, y = cy + f.oy + f.ky, live = 1 - rel;
    const pulse = DOT ? (1 + .14 * (1 - dotU) * (1 - dotU)) : 1;
    for (let s = 0; s < step; s++) {
      const rr = f.r * (1.02 - .18 * s) * pulse;
      fillPoly(c, PKrag(x, y, rr, PZ5seed(f) + s * 4.4, 11, .24 - .05 * s, t * .12 + s),
        A(s === 2 ? T[1] : T[0], live * (.30 + .18 * s)));
    }
    PZ5grain(c, x, y, f.r * .95, PZ5seed(f) * 13 + 2, K, live * (.30 + .26 * rot), 1, 6, t * .2);
    // 결 — **방사 스포크**(엔진 `fxNoiseSpokes`). 굳은 몸이 「평평한 초록
    //   원」이 되는 것을 막고, 삭을수록 눈금이 길어져 **짙기가 아니라 결로도** 읽힙니다.
    PZ5spokes(c, x, y, f.r * .34, f.r * (.62 + .40 * rot), 9, PZ5seed(f) + t * .05,
      K, live * (.34 + .30 * rot), SC, PZ5seed(f) * 17 + 4);
    // 3단 — **갈라진 각.** L2 부터만 여기까지 옵니다(hold 1.0 → 1.5).
    if (step >= 3) for (let k = 0; k < 4; k++) {
      const a0 = k / 4 * TAU + PZ5seed(f) * 3;
      PZ5crack(c, [[x + Math.cos(a0) * f.r * .25, y + Math.sin(a0) * f.r * .25],
      [x + Math.cos(a0 + .3) * f.r * .70, y + Math.sin(a0 + .3) * f.r * .70],
      [x + Math.cos(a0 + .1) * f.r * 1.02, y + Math.sin(a0 + .1) * f.r * 1.02]],
        1.6 * SC, K, live * .75);
    }
    if (live > .2) PZ5motes(c, t, x, y + f.r * .3, f.r * 1.5, 3, PZ5seed(f) * 21 + 5, K,
      live * .45 * (.4 + .6 * rot), SC, PZgSQ, -5);
  }

  // ── 마디 ② 생성 — 가시가 **0.22초에 다 박고 멎습니다** ─────────────────
  for (let i = 0; i < sel.length; i++) {
    const f = sel[i], x = cx + f.ox + f.kx, y = cy + f.oy + f.ky, live = 1 - rel;
    for (let j = 0; j < NAIL; j++) {
      const a2 = j / NAIL * TAU + t * .18 + i;
      const r0 = f.r * (3.2 - 1.9 * drive) + f.r * rel * 2.2;
      const len = Math.max(f.r * .58, r0 - f.r * .40);
      // ㉰ 박히기 **전**에는 날아오는 것입니다 — 머리·몸통·꼬리로 그립니다.
      if (drive < 1) {
        const s0x = x + Math.cos(a2) * f.r * 3.4, s0y = y + Math.sin(a2) * f.r * 3.4;
        PZ5bolt(c, t, s0x, s0y, x + Math.cos(a2) * f.r * 1.15,
          y + Math.sin(a2) * f.r * 1.15, 2.6 * SC, K, .95, SC, j * 3.7 + i * 9.1, drive);
        continue;
      }
      PZ5thorn(c, x + Math.cos(a2) * r0, y + Math.sin(a2) * r0, a2 + Math.PI,
        len, (3.4 + .8 * rot) * SC, K, live * .92 + rel * .25, j * 3.7 + i * 9.1);
      // ㉮ 큰 뼈대(가시)에 **매달린 잔부속** — 총량은 여기서 납니다.
      PZ5cling(c, t, [[x + Math.cos(a2) * r0, y + Math.sin(a2) * r0],
      [x + Math.cos(a2) * (r0 - len), y + Math.sin(a2) * (r0 - len)]],
        3, 1.5 * SC, K, live * .80, SC, j * 7.1 + i * 3.3);
    }
    // ── 마디 ④ 소멸 — 굳은 각이 **깨지고 불티가 가라앉습니다** ────────────
    if (rel > 0 && rel < 1) {
      // ㉦ **떨어져 나온 조각이 공중에** — 「지금 막 깨졌다」. 면을 쪼갭니다(㉠).
      const n = POP ? 7 : 4;
      for (let j = 0; j < n; j++) {
        const a2 = j / n * TAU + .3 + i, rr = f.r * (.5 + 1.5 * rel);
        const cx2 = x + Math.cos(a2) * rr, cy2 = y + Math.sin(a2) * rr - f.r * .5 * rel * (1 - rel) * 4;
        PZ5foot(c, cx2, y + f.r * .58, f.r * .22 * (1 - rel), K, .30 * (1 - rel), j * 5.1);
        PZ5shard(c, cx2, cy2, f.r * (.72 - .34 * rel) * (POP ? 1.35 : 1), f.r * .20,
          a2 + t * 2, K, (1 - rel) * .95, SC, j * 5.1 + i, (j % 3) * .35, .30);
      }
      PZ5motes(c, t * 3 + i, x, y, f.r * (2.0 + 1.6 * rel), NSP, i * 17.3 + 3, K,
        (1 - rel) * .85, SC, PZgSQ, -11);
      // ⭐ 「터지고 터진다」 — 한 자리에서 셋이 차례로 깨집니다.
      PZ5chain(c, t, rel * PZ5hREL, f.r * 3.0, K, 1, SC, PZ5seed(f) * 11 + i,
        (k) => [x, y, [.60, .84, 1.00][k]], .72);
    }
  }
  hero(c, t, cx, cy, "gold", SC);
};

// ══════════════════════════════════════════════════════════════════════════
// ⑤-라 **기생** — 「그림체 변화」. **말라간다의 축을 면으로 되살립니다**
// ══════════════════════════════════════════════════════════════════════════
//
// ── ⚠️⚠️ 감사가 짚은 자리 (2026-08-28) ───────────────────────────────────
//   「시안은 적 몸을 **42% 줄여** 「말라간다」를 말하는데 **엔진에 그 코드가
//    없습니다.** 드라이버가 「적 렌더 소유」로 위임한 곳에 **받는 코드가 없어**,
//    껍질이 빈 껍질이 아니라 **그냥 테두리**로 읽힙니다」
//
//   실측으로 확인한 것 둘:
//   ① 엔진 `w_latch_cel.dart:43` 이 **글로만** 위임합니다 —
//      「`f.r=f.r0*(1-.42*f.dr)` 몸 줄이기 — **적 렌더 소유**」. 그런데
//      적 몸의 배율은 `game_layers_dark.dart:245` 의 `enemyLandScale × rageS`
//      둘뿐이고 **둘 다 전역**입니다. FX 가 쓸 칸이 **없습니다**.
//   ② 그래서 엔진은 `fr = e.radius[host]` **하나**를 「원래 몸」과 「지금 몸」
//      **양쪽으로** 씁니다(`:152`). 두 값이 같으니 껍질과 몸 사이의 **틈이
//      언제나 0** 이고, `w_latch_parts.dart:91` 이 그 결과를 적어 뒀습니다 —
//      「줄지 않은 몸에 눈금을 그으면 **길이가 늘 0 이다**」.
//
// ── 시안이 고치는 자리 — **껍질을 선에서 면으로** ─────────────────────────
//   옛 시안도 42% 를 줄이기는 했습니다. 그런데 껍질이 `celStroke` **윤곽선**
//   하나라 「빈 껍질」이 아니라 **그냥 테두리**였습니다(감사의 표현 그대로).
//   ⇒ 껍질을 **속이 빈 고리 면**(annulus)으로 세웠습니다. 그리고 몸을
//     **쭈그러뜨립니다** — 줄기만 하면 「작아진 적」이고, 눌린 자국이 있어야
//     「말라붙은 적」입니다.
//   ⭐ 「빈 껍질」이 보이려면 **줄어든 몸 · 그 사이의 빈 자리 · 바깥 테** 셋이
//     다 있어야 하는데, **옛 판에는 셋째만 있었습니다.**
//
// ── 다섯 마디 — **발현이 빨리는 내내** ────────────────────────────────────
//   ① 시전 **0.08** 몸에서 실이 날아갑니다(가는 획 하나 — 이것으로 충분합니다)
//   ② 생성 **0.40** 문 자리에서 **주머니가 맺힙니다.** 아직 **안 마릅니다**
//     ⚠️ 옛 판은 무는 즉시 마르기 시작했습니다 — 「물었다」와 「빨기 시작했다」가
//       한 프레임에 붙어 있어 무는 사건이 안 보였습니다
//   ③ 발현 **1.6~3.6** 빨립니다 — 몸이 줄고 껍질이 자랍니다(L4 는 1.6배 빠름)
//   ④ 소멸 **두 갈래**(2026-08-28) — L1·L2 는 **0.50** 스스로 놓으며 껍질이
//     부스러지고, L3+ 는 **굳어 멎었다가**(0.50) **표적이 죽으면 0.42** 만에
//     **허공에서 끊깁니다.** 「안 놓는다」가 곧 이 마디를 갈아 끼우는 것입니다
//   ⑤ 종료 **0.70** 물린 자국이 잠깐 남았다 삭습니다(곁적 자리에도 남깁니다)
//
// ── ⭐ 엔진이 받을 수 있는 꼴 ─────────────────────────────────────────────
//   총구는 이미 **빨아낸 양**을 싣고 있습니다 — `latch.dart:112`
//   `out.dmgScale[n] = (_age[c]/_rampSec).clamp(0,1)`. 모자란 것은 **그 값을
//   적 몸 그리기에 꽂을 칸 하나**뿐입니다:
//     `enemyDrawScale[slot] = 1 − 0.42 × dmgScale`  ← 이 한 줄이 없습니다.
//   ⚠️ 적 몸은 `drawRawAtlas` 라 `RSTransform` 이 **등방 배율만** 받는데,
//     여기 필요한 것이 정확히 등방 배율 하나라 **막히는 데가 없습니다**.
const PZ5lFOE = [[70, -40, 11], [-66, -24, 10], [26, 62, 10], [-42, 50, 9]];
const PZ5lNB = [2, 3, 3, 3, 3];        // = kLatchTargetsAt
const PZ5lDRAIN = .28;                  // 빨리는 속도(초당)
const PZ5lFAST = 1.6;                   // L4 — `kLatchRampFastMul` 의 자리
const PZ5lSHRINK = .42;                 // ⭐ 채택값 — **레벨로 안 팝니다**
const PZ5lLIFE = 5.0;
const PZ5lGROW = .40, PZ5lDIE = .50, PZ5lSCAR = .70;
// ── ⭐⭐ **끝이 없던 스킬에 끝을 냅니다** (2026-08-28 사용자) ────────────────
// 사용자: 「기생 **L4와 L5는 죽을 때까지 괴롭히는 거야?** 너무 밸런스 파괴 같은데.
//   **사라지는 애니메이션도 추가해** 줘」
//
// ⚠️⚠️ **밸런스는 안 건드립니다.** 「죽을 때까지 문다」는 **엔진의 것**입니다 —
//   `lib/sim/combat/magic/latch.dart` 가 **L3 부터** 그렇게 적어 뒀고(L4·L5 는 그
//   위에 `kLatchRampFastMul` 과 곁가지 둘을 얹은 것입니다), 사용자가 「난이도
//   조절은 다 만들고 최종에」라고 못 박았습니다. ⇒ **시안은 그 규칙을 그리기만**
//   합니다. 재판정이 필요하다는 것은 **이식 인벤토리**에 한 줄로 남깁니다.
//
// ⚠️⚠️ **떨어지는 때가 둘이고 그림이 달라야 합니다**:
//   ① **L1·L2 — 시간이 다 되어 스스로 떨어짐**. 힘이 빠져 **놓는** 그림이라
//      주머니가 **아래로 처지고** 껍질이 **부스러집니다**. 느립니다([PZ5lDIE]).
//   ② **L3+ — 표적이 죽어서 끝남**. 붙잡고 있던 것이 사라져 **허공에서 끊기는**
//      그림이라 주머니가 죽은 자리에 얼어붙었다가 **바깥으로 튕깁니다**.
//      빠릅니다([PZ5lSNAP]).
// ⚠️⚠️ **적의 죽음 연출에 안 묻히게** 두 가지를 갈랐습니다 —
//   ㉠ **늦게 시작합니다**([PZ5lLAG] 만큼) ㉡ **반대 방향으로 갑니다**(적은 안으로
//   오므라들고 기생은 바깥으로). 같은 프레임에 같은 방향으로 나가면 안 보입니다.
/// 표적이 죽고 나서 기생이 끊기기까지(초).
const PZ5lLAG = .18;
/// ② 「허공에서 끊김」의 길이(초) — ① 의 [PZ5lDIE] 보다 **짧고 날카롭습니다.**
const PZ5lSNAP = .42;
/// 표적이 무너지는 시간(초) · 다음 표적이 서기까지(초).
/// ⚠️ **되살아나는 것은 시안의 사정입니다** — 칸이 계속 돌아야 하기 때문이고,
///   엔진에는 이런 것이 없습니다(이식할 때 옮기지 마십시오).
const PZ5lFDIE = .34, PZ5lRESP = 1.30;
/// ① 처짐 · ② 튕김 거리(238 기준 px).
const PZ5lSAG = 15, PZ5lFLING = 24;

/// 빈 껍질 — **고리 면**입니다. 굳으면 이어지고 안 굳으면 세 토막입니다.
/// [burst] 0~1 이면 조각이 밖으로 밀려 나가며 부스러집니다(마디 ④).
function PZ5husk(c, t, x, y, r0, r, K, a, solid, SC, sd, burst) {
  const T = toneOf(K), bu = burst || 0;
  const sect = (a0, a1, off) => {
    const P = [], M = 6;
    for (let i = 0; i <= M; i++) {
      const ang = a0 + (a1 - a0) * i / M;
      const ro = r0 * (1.07 + .09 * (hash(sd + i * 3.1 + a0) - .5) * 2) + off;
      P.push([x + Math.cos(ang) * ro, y + Math.sin(ang) * ro]);
    }
    for (let i = M; i >= 0; i--) {
      const ang = a0 + (a1 - a0) * i / M;
      const ri = r * (1.03 + .13 * (hash(sd + i * 5.7 + a0) - .5) * 2) + off;
      P.push([x + Math.cos(ang) * ri, y + Math.sin(ang) * ri]);
    }
    return P;
  };
  const spin = t * (solid ? .06 : .22);
  for (let s = 0; s < 3; s++) {
    const g = (solid && !bu) ? 0 : .34 + 1.1 * bu;
    if (g >= TAU / 3 - .04) continue;
    const a0 = s / 3 * TAU + spin + g * .5, a1 = (s + 1) / 3 * TAU + spin - g * .5;
    const off = (solid && !bu ? 0 : (r0 - r) * .5 * hash(sd + s) * .8) + r0 * 1.4 * bu * hash(sd + s + 3);
    const P = sect(a0, a1, off);
    fillPoly(c, P, A(T[0], a));
    fillPoly(c, P, A(T[0], a * .45));            // 한 번 더 — **속이 빈 것처럼 짙게**
    PZ5ring(c, x, y, r0 * 1.07 + off, 1, (a0 + a1) * .5, 1.7 * SC, K, a * .95,
      TAU - Math.abs(a1 - a0));
  }
  for (let k = 0; k < 5; k++) {
    const ang = k / 5 * TAU + spin + .3;
    PZ5crack(c, [[x + Math.cos(ang) * r * 1.04, y + Math.sin(ang) * r * 1.04],
    [x + Math.cos(ang + .12) * (r + r0) * .55, y + Math.sin(ang + .12) * (r + r0) * .55],
    [x + Math.cos(ang - .06) * r0 * 1.05, y + Math.sin(ang - .06) * r0 * 1.05]],
      1.4 * SC, K, a * .8 * (1 - bu));
  }
}

// ══════════════════════════════════════════════════════════════════════════
// ⑧ **기생의 연결부** — 적과 적을 잇는 것          (2026-08-28 사용자 판정)
// ══════════════════════════════════════════════════════════════════════════
//
// 사용자: 「기생의 경우 **독 걸린 애들끼리 연결되는 부분의 디자인을 다시** 해
//   줬으면 좋겠음」.
//
// ── ⚠️⚠️ 옛 판이 진 자리 넷 — 전부 짚어 고칩니다 ─────────────────────────
//   ① **선이 한 가닥**이었습니다 — `celStroke` 폴리라인 하나. 기생의 연결은
//      **살아 있는 것**인데 그러면 **밧줄**로 읽힙니다.
//      ⇒ 가닥 **셋이 서로를 감고**(위상이 서로 다른 사인), 굵기가 **가닥마다
//        다르고**(1.00 · 0.62 · 0.40), **마디**가 답니다.
//   ② **방향이 없었습니다** — 「이어져 있다」이지 「빨아들이고 있다」가
//      아니었습니다. ⇒ **흐르는 결**([PZ5streak])이 **곁적 → 주머니** 한 방향으로
//      흐르고, 굵기도 **주머니 쪽으로 몰립니다**(테이퍼가 한쪽입니다).
//   ③ **양 끝이 어디 붙었는지 모호**했습니다(한쪽 끝에 덩이 하나뿐). ⇒ 양 끝에
//      **빨판**을 답니다 — 고리 면 + 살 물린 자국 + 갈고리 넷.
//   ④ ⚠️⚠️ **줄이 적 위에 그려졌습니다.** `for (const q of st.b)` 가 통째로
//      `drawFoes` **뒤**라 잇는 줄이 적의 몸을 덮었습니다(오늘 무속성에서 같은
//      결함이 넷 나온 그 자리입니다).
//      ⇒ **줄은 `drawFoes` 앞**([PZ5cords])에, **빨판은 뒤**([PZ5cordEnds])에.
//        끝점은 「이 놈이 물렸다」는 **표식**이라 덮이면 뜻을 잃습니다.
// ⭐ 텍스처 — 이 자리가 `fxNoiseVein`(가닥의 결)과 `fxNoiseStreak`(흐름 · UV 를
//   **한 방향으로**)의 정확한 자리입니다. 둘 다 실제로 실었습니다.

/// 잇는 줄 하나 — **가닥 셋이 서로를 감습니다.** 굵기가 고르지 않고 마디가 있습니다.
/// [dr] 빨린 몫(굵기와 흐름 속도가 여기 걸립니다) · 점 목록을 돌려줍니다.
/// [cut] **끊긴 몫** 0~1 — 곁적 쪽 끝이 놓이고 남은 토막이 **주머니 쪽으로 말립니다.**
/// ⚠️ **`drawFoes` 앞**에서 부릅니다 — 줄은 적의 **아래**로 갑니다.
function PZ5cord(c, t, ax, ay, bx, by, K, a, SC, sd, dr, cut) {
  const cu = Math.max(0, Math.min(.92, cut || 0));
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1;
  const nx = -dy / L, ny = dx / L, N = 9;
  const bow = (hash(sd) - .5) * L * .17;
  // ⭐⭐ **끊기면 말려 들어갑니다.** 팽팽하던 것이 끊기면 자유단이 **주머니 쪽으로
  //   확 당겨지고 감깁니다** — 이 한 항이 「끊어졌다」를 냅니다(길이만 줄이면
  //   「사라진다」이지 「끊어졌다」가 아닙니다).
  //   ⚠️ 감김은 **자유단 쪽에서 제일 크고 주머니 쪽에서 0** 입니다. 반대로 하면
  //     붙어 있는 끝이 흔들려 「아직 이어져 있다」로 읽힙니다.
  const axis = [];
  for (let i = 0; i <= N; i++) {
    const w = i / N, u = cu + (1 - cu) * w, s = Math.sin(u * Math.PI);
    const coil = cu * L * .21 * Math.sin(w * Math.PI * 1.6) * (1 - w) * Math.cos(w * 7.4 + sd);
    axis.push([ax + dx * u + nx * (bow * s + coil), ay + dy * u + ny * (bow * s + coil)]);
  }
  const av = a * (1 - cu * .55);
  // 가닥 셋 — 위상이 다르고 굵기가 다릅니다(균일한 굵기 = 거미줄).
  const WID = [1.00, .62, .40], PH = [0, 2.1, 4.2], TW = [3.0, 3.7, 4.6];
  for (let k = 0; k < 3; k++) {
    const P = [];
    for (let i = 0; i <= N; i++) {
      const u = i / N;
      // ⚠️ **감김은 `u` 파생**입니다 — 시간을 안 타므로 되풀이 이음매가 없습니다.
      const off = Math.sin(u * TW[k] * Math.PI + PH[k] + sd) * L * .055 * Math.sin(u * Math.PI);
      P.push([axis[i][0] + nx * off, axis[i][1] + ny * off]);
    }
    // ② **한쪽으로 몰리는 굵기** — 주머니(끝) 쪽이 굵습니다.
    const m = Math.max(2, Math.round(P.length * .5));
    const w0 = (1.5 + 2.6 * dr) * SC * WID[k];
    PZ5lit(c, P.slice(0, m), w0 * .70, K, av * .82);
    PZ5lit(c, P.slice(m - 1), w0, K, av * .95);
    if (k === 0) {
      // 마디 — 굵은 가닥에만. 「살아 있는 것」의 눈금입니다.
      for (let i = 3; i < N; i += 4)
        PZ5mass(c, P[i][0], P[i][1], w0 * (.72 + .34 * hash(sd + i)), sd + i * 3.7,
          K, av * .88, .95, t * .3 + i);
      // ⭐ 결 — **잎맥**(`fxNoiseVein`). 굵은 가닥이 「줄」이 아니라 「살」이 됩니다.
      const mid = P[(N / 2) | 0];
      PZ5vein(c, mid[0], mid[1], L * .17, Math.atan2(dy, dx), K, av * .52, SC, sd * 7 + 1, 5);
    }
  }
  // ⭐ ② **방향** — 흐르는 결이 **곁적 → 주머니** 한 방향으로만 흐릅니다.
  //   (`fxNoiseStreak` + UV. 이 한 항이 「이어져 있다」를 「빨아들이고 있다」로
  //    바꿉니다 — 정지 화면에서도 눈금이 한쪽에 몰려 보입니다.)
  PZ5streak(c, t, axis, (1.9 + 1.4 * dr) * SC, K, av * .95, SC, sd * 11 + 3, 3, .55 + .55 * dr);
  // ⭐⭐ **줄은 빛입니다** — 심을 **가산**으로 한 번 더 긋습니다(2026-08-28 규약
  //   정정: 「이펙트는 원래 가산으로 그린다」). 채운 면만으로 그리면 「색종이를
  //   덕지덕지 붙여 날리는 것」이 되는데, 빨아들이는 줄은 **빛이 흐르는 것**입니다.
  //   ⚠️ **가는 심에만** 겁니다 — 굵게 걸면 줄이 흰 막대가 되어 가닥 셋이 뭉갭니다.
  gAdd(c, gg => celStroke(gg, axis, (.9 + 1.3 * dr) * SC, K, av * .40));
  return axis;
}

/// 줄의 **끝점 — 빨판.** 고리 면 + 물린 자국 + 갈고리 셋.
/// [rel] **놓인 몫** 0~1 — 고리가 벌어지고 갈고리가 살에서 빠집니다.
/// ⚠️ **`drawFoes` 뒤**에서 부릅니다 — 「이 놈이 물렸다」는 표식이라 몸에 덮이면
///   뜻을 잃습니다(줄은 아래, 표식은 위).
function PZ5cordEnd(c, t, x, y, r, ang, K, a, SC, sd, dr, rel) {
  if (!(r > .8)) return;
  const R = Math.max(0, Math.min(1, rel || 0)), al = a * (1 - R * .82);
  if (!(al > .01)) return;
  PZ5foot(c, x, y + r * .55, r * 1.1, K, al * .34, sd + 1.3);
  PZ5ring(c, x, y, r * (1.15 + 1.00 * R), .82, ang + t * .18, (2.2 - 1.1 * R) * SC, K, al * .90);
  PZ5mass(c, x, y, r * (.74 - .40 * R), sd * 3 + 2, K, al * .95, .90, t * .35);
  // ⭐⭐ **빨판이 빛납니다** — 빨아들이는 지점이라 여기가 제일 밝습니다. 가산
  //   하나로 「면」이 「빛」이 됩니다(2026-08-28 규약 정정).
  //   ⚠️ 놓이면 **꺼집니다** — 빛이 남아 있으면 「아직 빨고 있다」로 읽힙니다.
  gAdd(c, gg => gHalo(gg, x, y, r * (1.5 + .9 * R), K, (.26 + .30 * dr) * (1 - R)));
  // 갈고리 셋 — **살을 문 자리**. 안을 봅니다. 놓이면 **벌어져 빠집니다.**
  // ⚠️ 넷에서 **셋**으로 줄였고 결(`PZ5grain`)과 물린 자국(`PZ5taint`)을 뺐습니다 —
  //   빨판이 여섯이라(주머니 셋 × 곁적 둘) 그 둘이 잉크를 **두 배로** 물었고,
  //   물린 자국은 **몸이 이미 갖고 있어**(둘레의 `PZ5taint`) 겹치기만 했습니다.
  for (let k = 0; k < 3; k++) {
    const aa = ang + k / 3 * TAU + t * .10 + R * .60;
    const dd = r * (1.02 + .95 * R);
    PZ5shard(c, x + Math.cos(aa) * dd, y + Math.sin(aa) * dd * .90,
      r * (.60 + .34 * hash(sd + k)), r * .26, aa, K, al * .92, SC,
      sd * 13 + k * 4.4, k % 2 ? .6 : 0, .40);
  }
}

/// ⭐⭐ **주머니의 자리 — 한 곳에서만 냅니다.** 줄 · 빨판 · 주머니가 각자 계산하면
/// 소멸 마디에서 셋이 **서로 다른 데로** 갑니다(이 파일이 이미 한 번 낸 사고입니다).
/// ⚠️ 소멸 마디의 **방향이 두 갈래**입니다 — 위 [PZ5lLAG] 절이 근거입니다.
function PZ5sacAt(q, cx, cy, SC) {
  const f = q.f;
  const fx = cx + f.ox + f.kx, fy = cy + f.oy + f.ky;
  const bx = fx + Math.cos(q.a) * f.r * q.rr, by = fy + Math.sin(q.a) * f.r * q.rr;
  if (!(q.die >= 0)) return [bx, by];
  const u = Math.min(1, q.die);
  // ① 스스로 놓음 — 적을 **따라가며 아래로 처집니다**(힘이 빠집니다).
  if (!q.how) return [bx, by + PZ5lSAG * u * u * SC];
  // ② 표적이 죽어서 — **죽은 그 자리**에서 몸 반대쪽으로 튕깁니다.
  //   ⚠️ 죽어 가는 적을 따라가면 **적과 같이 오므라들어** 죽음 연출에 묻힙니다.
  const ox = q.wx - cx, oy = q.wy - cy, d = Math.hypot(ox, oy) || 1;
  return [q.wx + ox / d * PZ5lFLING * u * SC,
          q.wy + oy / d * PZ5lFLING * u * SC - PZ5lFLING * .34 * u * SC];
}

/// 소멸 마디의 **끊긴 몫** — 줄·빨판이 같은 값을 봐야 어긋나지 않습니다.
/// ⚠️ **L3+ 는 더 빨리 끊깁니다**(`×1.35`) — 붙잡고 있던 것이 사라져 **허공에서**
///   끊기는 것이라 「스스로 놓는」 L1·L2 보다 날카로워야 합니다.
const PZ5cutOf = q => (q.die >= 0 ? Math.min(1, q.die * (q.how ? 1.35 : .85)) : 0);

/// L5 곁가지의 **줄** — `drawFoes` **앞**에서 한 번에 답니다.
/// ⚠️ 줄과 빨판을 **한 함수에 안 둡니다** — 그리는 차례가 서로 반대입니다.
function PZ5cords(c, t, cx, cy, st, K, SC, FORK) {
  if (!FORK) return;
  // ⚠️ **한 곁적에 줄이 두 번 그려지던 자리입니다** — 주머니 셋이 같은
  //   이웃을 고르면 같은 줄을 겹쳐 그려 잉크만 두 배가 됩니다.
  const seen = new Set();
  for (const q of st.b) {
    if (!q.sk || q.fly < 1 || q.grow < 1) continue;
    const f = q.f, E = PZ5sacAt(q, cx, cy, SC);
    for (const g of q.sk) {
      if (seen.has(g)) continue; seen.add(g);
      // ⚠️ **곁적 → 주머니** 차례로 넘깁니다 — 흐르는 결의 방향이 그 차례입니다.
      PZ5cord(c, t, cx + g.ox + g.kx, cy + g.oy + g.ky, E[0], E[1],
        K, .34 + .56 * f.dr, SC, g.sd * 23 + q.sd * 7, f.dr, PZ5cutOf(q));
    }
  }
}

/// L5 곁가지의 **빨판** — `drawFoes` **뒤**.
function PZ5cordEnds(c, t, cx, cy, st, K, SC, FORK) {
  if (!FORK) return;
  // ⚠️ **한 곁적에 줄이 두 번 그려지던 자리입니다** — 주머니 셋이 같은
  //   이웃을 고르면 같은 줄을 겹쳐 그려 잉크만 두 배가 됩니다.
  const seen = new Set();
  for (const q of st.b) {
    if (!q.sk || q.fly < 1 || q.grow < 1) continue;
    const E = PZ5sacAt(q, cx, cy, SC), rel = PZ5cutOf(q);
    for (const g of q.sk) {
      if (seen.has(g)) continue; seen.add(g);
      const gx = cx + g.ox + g.kx, gy = cy + g.oy + g.ky;
      const ga = Math.atan2(E[1] - gy, E[0] - gx);
      PZ5cordEnd(c, t, gx + Math.cos(ga) * g.r * .82, gy + Math.sin(ga) * g.r * .82,
        (2.6 + 3.4 * g.dr) * SC, ga, K, .95, SC, g.sd * 29 + 3, g.dr, rel);
    }
  }
}

/// 쭈그러진 몸 — 줄기만 하면 「작아진 적」이고, 눌려야 「말라붙은 적」입니다.
function PZ5shrivel(c, t, x, y, r, K, dr, sd) {
  const T = toneOf(K);
  for (let k = 0; k < 5; k++) {
    const ang = k / 5 * TAU + sd * 2 + t * .05, d = r * (.88 - .10 * dr);
    fillPoly(c, PKrag(x + Math.cos(ang) * d, y + Math.sin(ang) * d, r * (.26 + .18 * dr),
      sd + k * 3.3, 8, .40, ang), A(T[0], .30 + .40 * dr));
  }
}

FX.PZlatch = function (c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  if (!st.F) {
    st.F = PZ5foes(PZ5lFOE, SC);
    for (const f of st.F) {
      f.bx = f.ox; f.by = f.oy; f.r0 = f.r; f.dr = 0; f.sd = PZ5seed(f);
      f.fd = -1; f.rs = 0;             // 죽는 몫(−1 = 살아 있습니다) · 되살아나기까지
    }
    st.b = []; st.fa = 0; st.n = 0; st.scar = [];
  }
  for (const f of st.F) {
    f.ox = f.bx + Math.sin(t * (.55 + f.sd * .50) + f.sd * 9) * 22 * SC;
    f.oy = f.by + Math.cos(t * (.47 + f.sd * .40) + f.sd * 5) * 16 * SC;
    f.on = 0;
  }
  stepFoes(st.F, dt);
  const K = PZ5LT;
  const NB = PZ5lNB[LV - 1], KEEP = atL(3), VEIN = atL(4), FORK = atL(5);
  const RATE = PZ5lDRAIN * (VEIN ? PZ5lFAST : 1), LIFE = KEEP ? 999 : PZ5lLIFE;
  st.fa += dt;
  // ⚠️ **죽었거나 죽고 있는 적은 안 물어요** — 그 자리부터 세어 살아 있는 첫 적을
  //   고릅니다(안 그러면 시체를 물고 시작합니다).
  const pickF = () => {
    for (let k = 0; k < st.F.length; k++) {
      const g = st.F[(st.n + k) % st.F.length];
      if (g.fd < 0) return g;
    }
    return null;
  };
  const tgt = (st.fa > 1.05 && st.b.length < NB) ? pickF() : null;
  if (tgt) {
    st.fa = 0; st.n++;
    st.b.push({
      f: tgt, fly: 0, grow: 0, die: -1,
      a: hash(st.n * 7.7) * TAU, rr: .60 + hash(st.n * 3.1) * .24,
      age: 0, tk: 0, hit: 0, set: -1, sd: hash(st.n * 5.9), sk: null,
      // 소멸 — `how` 0 = 스스로 놓음(L1·L2) · 1 = 표적이 죽어서(L3+) ·
      //   `lag` ≥ 0 이면 **적이 죽은 뒤 세는 중**(−1 = 안 셈) · `wx,wy` 는
      //   끊긴 순간의 **얼어붙은 자리**(죽어 가는 적을 안 따라갑니다).
      how: 0, lag: -1, wx: 0, wy: 0,
    });
  }
  for (let i = st.b.length - 1; i >= 0; i--) {
    const q = st.b[i];
    // ── 마디 ① 시전 ──────────────────────────────────────────────────────
    if (q.fly < 1) { q.fly = Math.min(1, q.fly + dt / .08); if (q.fly >= 1) { q.hit = 1; q.f.hit = 1; } continue; }
    // ── 마디 ④ 소멸 — 두 갈래입니다(위 [PZ5lLAG] 절이 근거) ─────────────
    if (q.die >= 0) {
      q.die += dt / (q.how ? PZ5lSNAP : PZ5lDIE);
      // ⚠️ **①에서만 되돌립니다.** ② 는 표적이 이미 죽었으므로 마름을 되돌릴
      //   몸이 없습니다(되돌리면 죽어 가는 적이 도로 살찝니다).
      if (!q.how) q.f.dr = Math.max(0, q.f.dr - dt * 1.1);
      if (q.die >= 1) {
        st.scar.push({ f: q.f, age: 0, wx: q.wx, wy: q.wy, how: q.how });
        // ⭐ 곁적에도 **물린 자국**이 남습니다 — 빨판이 놓인 자리입니다.
        if (q.sk) for (const g of q.sk) st.scar.push({ f: g, age: 0, wx: 0, wy: 0, how: 0 });
        st.b.splice(i, 1);
      }
      continue;
    }
    // ── 마디 ② 생성 — 주머니가 맺히는 동안은 **안 마릅니다** ──────────────
    if (q.grow < 1) { q.grow = Math.min(1, q.grow + dt / PZ5lGROW); q.f.on = 1; continue; }
    // ── 마디 ③ 발현 ──────────────────────────────────────────────────────
    q.age += dt; q.tk += dt; q.f.on = 1;
    q.hit = Math.max(0, q.hit - dt * 3.2);
    const was = q.f.dr;
    q.f.dr = Math.min(1, q.f.dr + dt * RATE);
    if (KEEP && was < 1 && q.f.dr >= 1) q.set = 0;       // L3+ — 소멸이 「굳음」입니다
    if (q.set >= 0 && q.set < 1) {
      q.set += dt / PZ5lDIE;
      // ⭐⭐ **굳음이 끝나면 표적이 죽습니다** — 「L3+ 는 표적이 죽을 때까지 문다」의
      //   **끝**입니다. 다 빨린 적이 그대로 서 있으면 그 규칙이 화면에 안 보입니다.
      if (q.set >= 1 && q.f.fd < 0) { q.f.fd = 0; q.lag = 0; }
    }
    // ⭐ 기생은 **조금 늦게** 끊깁니다 — 적의 죽음 연출에 안 묻히게.
    if (q.lag >= 0) {
      q.lag += dt;
      if (q.lag > PZ5lLAG) {
        // ⚠️⚠️ **자리를 먼저 얼리고 나서** 갈래를 켭니다. 순서를 뒤집으면
        //   [PZ5sacAt] 이 이미 ② 가지로 들어가 **아직 0 인 `wx,wy`** 를 읽어
        //   주머니가 칸 밖으로 날아갑니다(2026-08-28 실측으로 잡은 자리 —
        //   끊긴 순간의 거리가 **204px** 로 찍혔습니다).
        const S = PZ5sacAt(q, cx, cy, SC); q.wx = S[0]; q.wy = S[1];
        q.how = 1; q.die = 0; q.lag = -1;
      }
    }
    if (FORK) {
      if (!q.sk) q.sk = st.F.filter((g) => g !== q.f)
        .sort((a, b) => Math.hypot(a.ox - q.f.ox, a.oy - q.f.oy) - Math.hypot(b.ox - q.f.ox, b.oy - q.f.oy))
        .slice(0, 2);
      for (const g of q.sk) { g.on = 1; g.dr = Math.min(1, g.dr + dt * RATE * .55); }
    }
    if (q.tk > .5) { q.tk = 0; q.hit = 1; q.f.hit = 1; if (FORK && q.sk) for (const g of q.sk) g.hit = .6; }
    if (q.age > LIFE) q.die = 0;
  }
  // ── 마디 ⑤ 종료 — 바닥 부스러기 자국 ───────────────────────────────────
  for (const s of st.scar) s.age += dt;
  for (let i = st.scar.length - 1; i >= 0; i--) if (st.scar[i].age > PZ5lSCAR) st.scar.splice(i, 1);
  for (const f of st.F) {
    if (!f.on && !KEEP) f.dr = Math.max(0, f.dr - dt * .50);
    f.hit = Math.max(0, f.hit - dt * 2.6);
    // ── 표적의 죽음 — **L3+ 에서만 납니다**(다 빨리면 죽습니다) ─────────────
    if (f.fd >= 0 && f.fd < 1) {
      f.fd = Math.min(1, f.fd + dt / PZ5lFDIE);
      // ⚠️ 같은 적을 문 **다른 주머니**도 같이 끊깁니다 — 안 그러면 죽은 적을
      //   계속 빨고 있는 주머니가 허공에 남습니다.
      for (const q of st.b) if (q.f === f && q.die < 0 && q.lag < 0 && q.fly >= 1) q.lag = 0;
    } else if (f.fd >= 1) {
      // ⚠️ **되살아나는 것은 시안의 사정입니다**(칸이 계속 돌아야 합니다).
      f.rs += dt;
      if (f.rs > PZ5lRESP) { f.fd = -1; f.rs = 0; f.dr = 0; f.hit = 0; }
    }
    // ⭐ **빨린 만큼 몸이 줄어듭니다** — 이 한 줄이 「말라간다」의 축입니다.
    // ⚠️ 죽는 동안은 그 위에 **오므라듦**이 곱해집니다(0 은 안 됩니다 — 반지름이
    //   0 이면 `arc` 가 터집니다).
    f.r = f.r0 * (1 - PZ5lSHRINK * f.dr) * (f.fd >= 0 ? Math.max(.06, 1 - f.fd) : 1);
  }

  // ── 마디 ⑤ 종료 — **물린 자국이 잠깐 남았다 삭습니다**(`fxNoiseGrainy`) ────
  // ⚠️ ② 는 적이 이미 없으므로 **얼어붙은 자리**에 남깁니다(적을 따라가면
  //   되살아난 적의 발밑으로 자국이 순간이동합니다).
  for (const s of st.scar) {
    const u = s.age / PZ5lSCAR;
    const sx = s.how ? s.wx : cx + s.f.ox;
    const sy = s.how ? s.wy : cy + s.f.oy + s.f.r0 * .5;
    PZ5scar(c, t, sx, sy, s.f.r0 * 1.5, K, (1 - u) * .48, SC, s.f.sd * 7, u);
  }
  for (const f of st.F) {
    if (f.fd >= 1) continue;
    if (f.dr <= .05) continue;
    PZ5ring(c, cx + f.ox + f.kx, cy + f.oy + f.ky + f.r0 * .55, f.r0 * (1.15 + .35 * f.dr), .34,
      t * .1, 1.7 * SC, K, .22 * f.dr, 2.4);
    // ㉮ 바닥 잔해 — **빨린 만큼** 부스러기가 쌓입니다(마름의 눈금이기도 합니다).
    PZ5litter(c, cx + f.ox + f.kx, cy + f.oy + f.ky + f.r0 * .55, f.r0 * 2.4, 20, K,
      .30 + .34 * f.dr, SC, f.sd * 47 + 2, .25 + .75 * f.dr);
  }
  // ⭐ **잇는 줄을 여기서 먼저 깝니다** — `drawFoes` 앞이라 줄이 적의
  //   몸 **아래**로 갑니다(빨판만 뒤에서 얹습니다).
  PZ5cords(c, t, cx, cy, st, K, SC, FORK);
  // ⚠️ **다 죽은 적은 안 그립니다** — 되살아나기 전까지 자리가 비어야 「죽었다」가
  //   납니다(반지름만 줄이면 점 하나가 남아 「작아진 적」이 됩니다).
  drawFoes(c, t, cx, cy, st.F.filter((f) => f.fd < 1));
  // ── ⭐⭐ **표적이 무너집니다** — L3+ 의 「죽을 때까지」의 끝입니다 ──────────
  // ⚠️⚠️ **안으로** 오므라듭니다. 기생의 소멸은 **바깥으로** 갑니다([PZ5sacAt]) —
  //   방향이 반대라야 기생이 죽음 연출에 안 묻힙니다.
  for (const f of st.F) {
    if (!(f.fd >= 0) || f.fd >= 1) continue;
    const x = cx + f.ox + f.kx, y = cy + f.oy + f.ky, u = f.fd;
    PZ5ring(c, x, y, Math.max(.6, f.r0 * (1.10 - .92 * u)), .82, t * .5,
      Math.max(.4, (2.4 - 1.7 * u) * SC), K, (1 - u) * .60, 1.2);
    PZ5motes(c, t * 2, x, y, f.r0 * (1.35 - 1.05 * u), 5, f.sd * 61 + 9, K,
      (1 - u) * .70, SC, PZgSQ, 3);
  }

  // ── 빈 껍질 · 쭈그러진 몸 ───────────────────────────────────────────────
  // ⚠️ **부스러지는 것은 ① 뿐입니다.** ② 는 표적이 통째로 무너지므로 껍질이
  //   따로 터지면 사건이 둘이 되어 서로를 지웁니다.
  const burstOf = (f) => { for (const q of st.b) if (q.f === f && q.die >= 0 && !q.how) return q.die; return 0; };
  for (const f of st.F) {
    if (f.fd >= 1) continue;
    if (f.dr <= .05) continue;
    const x = cx + f.ox + f.kx, y = cy + f.oy + f.ky, bu = burstOf(f);
    PZ5shrivel(c, t, x, y, f.r, K, f.dr, f.sd);
    PZ5husk(c, t, x, y, f.r0, f.r, K, (.30 + .48 * f.dr) * (1 - bu * .5), KEEP, SC, f.sd * 9 + 1, bu);
    PZ5taint(c, t, x, y, f.r, K, .30 + .34 * f.dr, SC, f.sd * 13 + 2);
    PZ5motes(c, t, x, y, f.r0 * 1.5, 3, f.sd * 31 + 7, K, .42 * f.dr, SC, PZgSQ, -7);
    // ㉮ 껍질(큰 뼈대) 둘레에 **마른 조각**이 매달립니다.
    {
      const ring = [];
      for (let k = 0; k <= 8; k++) {
        const aa = k / 8 * TAU + t * .08;
        ring.push([x + Math.cos(aa) * f.r0 * 1.06, y + Math.sin(aa) * f.r0 * 1.06]);
      }
      PZ5cling(c, t, ring, 7, f.r0 * .17, K, .34 + .52 * f.dr, SC, f.sd * 41 + 5);
    }
  }

  for (const q of st.b) {
    const f = q.f, fx = cx + f.ox + f.kx, fy = cy + f.oy + f.ky;
    // ⭐ 주머니 자리는 **한 곳에서만** 냅니다 — 소멸의 처짐·튕김이 거기 있습니다.
    const SA = PZ5sacAt(q, cx, cy, SC), tx = SA[0], ty = SA[1];
    if (q.fly < 1) {
      // ㉰ 0.08초짜리라도 **머리·몸통·꼬리**가 갈립니다 — 머리에 삼엽이 찍힙니다.
      PZ5bolt(c, t, cx, cy, tx, ty, 2.8 * SC, K, .92, SC, q.sd * 11 + 3, q.fly);
      continue;
    }
    // ② 생성 — 주머니가 **맺힙니다**(부풀었다 자리를 잡습니다).
    if (q.grow < 1) {
      const g = q.grow;
      // ⭐ 무는 자리에 **작은 진**이 그려집니다 — 무는 순간이 한 프레임이라
      //   안 보이던 자리를 이 마디가 채웁니다(「그림체 변화」의 한 항).
      PZ5sigil(c, t, fx, fy, f.r0 * 2.2, K, .26 + .46 * g, SC, q.sd * 17 + 4, g, .55);
      PZ5mass(c, tx, ty, (1.4 + 3.0 * g) * SC * (1 + .3 * Math.sin(g * 9)), q.sd * 9 + 1, K, .95, .92, t);
      PZ5ring(c, fx, fy, f.r * (1.6 - .5 * g), 1, t * .9, (1.2 + 1.2 * g) * SC, K, .30 + .45 * g);
      continue;
    }
    if (VEIN) for (let k = 0; k < 3; k++) {
      const sp = q.a + (k - 1) * .62, len = f.r0 * (1.35 + 1.15 * f.dr), P = [];
      for (let s = 0; s <= 6; s++) {
        const w = s / 6, aa = sp + Math.sin(w * 3.1 + k) * .55;
        P.push([fx + Math.cos(aa) * len * w, fy + Math.sin(aa) * len * w]);
      }
      PZ5lit(c, P, 3.4 * SC, K, .70 * f.dr * (q.die >= 0 ? 1 - q.die : 1));
      PZ5mass(c, P[6][0], P[6][1], 2.6 * SC * (.6 + .6 * f.dr), k * 4.4 + q.sd * 9, K,
        .8 * f.dr * (q.die >= 0 ? 1 - q.die : 1), .95, t + k);
    }
    // ⭐⭐ **주머니가 쪼그라듭니다** — 그냥 옅어지면 「사라진다」이고, 크기가
    //   줄어야 「놓았다」입니다. ⚠️ ② 는 잡을 것이 없어져 **더 빨리** 쪼그라듭니다.
    const dq = q.die >= 0 ? Math.min(1, q.die) : 0;
    const shrink = q.die >= 0 ? (1 - PZqS3(q.how ? Math.min(1, dq * 1.25) : dq)) : 1;
    const pr = Math.max(.4, (2.4 + 7.6 * f.dr) * SC * (1 + q.hit * .30) * shrink);
    const av = q.die >= 0 ? 1 - dq * .55 : 1;
    // ⭐⭐ 「그림체 변화」의 답이 ㉠ 입니다 — 주머니를 **면 쪼갠 덩어리**로 두면
    //   얼룩이 아니라 **달라붙은 것**으로 읽힙니다. 조각 넷이 서로 다른 각으로
    //   붙고(㉥) 발치에 그림자가 깔립니다(㉧).
    // ⚠️ 발치 그림자는 **놓이면 먼저 사라집니다** — 바닥에 붙어 있던 것이라
    //   떠오르면 그림자가 남을 까닭이 없습니다.
    PZ5foot(c, tx, ty + pr * .5, pr * 1.25, K, .42 * (1 - dq), q.sd * 5);
    PZ5glow(c, tx, ty, pr * 2.3, K, .40 * av, .92);       // 빛 램프 1/문 자리
    PZ5mass(c, tx, ty, pr, q.sd * 9 + 1, K, .95 * av, .92, t * .5);
    // 쪼그라들면 결이 **촘촘해집니다** — 주름입니다.
    PZ5grain(c, tx, ty, pr, q.sd * 17 + 3, K, .85 * av, .92, 6 + ((dq * 5) | 0), t * .4);
    // 결 — **잎맥**(엔진 `fxNoiseVein`). 주머니가 「붙은 얼룩」이 아니라
    //   **「살아 자란 것」**으로 읽히는 마지막 항입니다.
    PZ5vein(c, tx, ty, pr * .80, q.a + t * .10, K, .66 * av, SC, q.sd * 23 + 2, 6);
    for (let k = 0; k < 4; k++) {
      const cs = q.sd * 31 + k * 4.7, ang = k / 4 * TAU + q.a * .5 + t * .12;
      // ⚠️ 조각은 **안으로 말려듭니다**(`.52 → .18`) — 밖으로 흩으면 폭발입니다.
      const dd = pr * (.52 - .34 * dq);
      PZ5shard(c, tx + Math.cos(ang) * dd, ty + Math.sin(ang) * dd,
        pr * (.85 + .55 * hash(cs)), pr * .30, ang, K, .92 * av, SC, cs,
        k > 1 ? .7 : 0, .35);
    }
    // ④ 소멸(L3+) — **굳는 순간.** 부스러기가 한 번 떨어지고 껍질이 멎습니다.
    if (q.set >= 0 && q.set < 1)
      PZ5motes(c, t * 2, fx, fy, f.r0 * 2.0, 7, q.sd * 41 + 11, K, (1 - q.set) * .85, SC, PZgSQ, -12);
    if (q.die >= 0) {
      // ⭐⭐ **끊긴 순간의 섬광** — 「끊어졌다」는 **한 박자의 사건**이라 소리 대신
      //   빛으로 냅니다(가산). ⚠️ 앞 `.22` 안에서만 — 길게 끌면 폭발이 됩니다.
      if (dq < .22) {
        const fl = 1 - dq / .22;
        gAdd(c, gg => gHalo(gg, tx, ty, pr * (1.6 + 2.2 * (1 - fl)), K, .70 * fl * fl));
      }
      // 부스러기는 **떨어지는 방식이 다릅니다** — ① 은 아래로 흘러내리고
      //   ② 는 위로 튑니다(허공에서 끊겨 위로 놓입니다).
      PZ5motes(c, t * 2, tx, ty, f.r0 * (1.5 + 1.3 * dq), 6, q.sd * 53 + 13, K,
        (1 - dq) * .80, SC, PZgSQ, q.how ? -13 : 6);
      // 껍질이 부스러지는 그 순간만 — **낮은** 터짐 하나(기생은 안 솟습니다).
      //   ⚠️ ① 에서만 — ② 는 표적의 붕괴가 이미 그 자리에서 터집니다.
      if (!q.how) PZ5pop(c, t, fx, fy, f.r0 * 1.9, K, .85, SC, q.sd * 23 + 7, dq, .28);
    }
    // ⚠️ **곁가지의 줄과 빨판은 여기서 안 그립니다** — 이 반복문이 통째로
    //   `drawFoes` **뒤**라, 여기서 그리면 잇는 줄이 적의 몸을 덮습니다
    //   (2026-08-28 사용자 판정의 그 자리). 줄은 [PZ5cords] 가 `drawFoes`
    //   **앞**에서, 빨판은 [PZ5cordEnds] 가 **뒤**에서 그립니다.
  }
  PZ5cordEnds(c, t, cx, cy, st, K, SC, FORK);
  hero(c, t, cx, cy, "gold", SC);
};

